RG.HK["26"] = [{"id":"26_heian_daigokuden","n":"平安宮大極殿跡（平安京の中心）","yomi":"へいあんきゅうだいごくでんあと","cat":"遺跡","rank":"S","y":794,"era":["heian"],"sh":"国指定史跡（平安宮跡）","ad":"京都市上京区千本通丸太町上ル 内野児童公園ほか","st":"市バス「千本丸太町」から歩いてすぐ／JR・地下鉄「二条」駅から歩いて約15分","la":35.0205,"lo":135.7428,"hook":"1000年の都の «ど真ん中» は、いま住宅街の小さな公園。石碑ひとつが、天皇の即位した大宮殿の記憶を守っている。","lead":"794年、桓武天皇は都を平安京に移しました。その中心にあったのが、国の大事な儀式を行う «大極殿»。建物は平安時代の終わりに焼けて二度と建て直されず、いまは千本丸太町の公園に «大極殿遺址» の碑が立つ «跡» だけが残ります。","story":["794年、桓武天皇の一行は、長岡京からこの盆地の北のはしへやってきました。北に山、東と西に川、南は広い平地。«山や川が自然の城壁になっている国だ» と考えた天皇は、この国を «山城国» と名づけ、都を «平安京» と呼びました。«平らかで安らかな都であれ» という願いがこもった名前です。","都の北の中央に置かれたのが «大内裏»。東西約1.2km、南北約1.4kmほどの広い区画に、役所や天皇の住まいがぎっしり並びました。その中心、朝堂院のいちばん奥にそびえたのが大極殿です。朱色の柱に緑の窓、屋根には金色の鴟尾（しび）。新しい天皇が即位するとき、元日に家臣のあいさつを受けるとき、天皇はここに座りました。","ところが都の中心は、しだいに «からっぽ» になっていきます。天皇の住まいの内裏はたびたび火事にあい、天皇は貴族の屋敷を借りた «里内裏» で暮らすことが増えました。なぜ建て直さなかったの? と思うでしょう。巨大な宮殿を何度も建て直すには、とてつもないお金と人手がかかったからです。","そして1177年、都を焼いた大火事（安元の大火）で大極殿も焼け落ち、ついに再建されませんでした。かつての宮殿の跡地は «内野（うちの）» とよばれる野原になり、中世には畑や人の住む町に変わっていきます。都そのものは、東へずれるように育っていったのです。","忘れられた大極殿の場所を探したのは、明治の人々でした。1895年、平安遷都1100年を記念して、ここに «大極殿遺址» の碑が建てられます。同じ年、岡崎には大極殿を小さくして再現した平安神宮もつくられました。近年は発掘調査で建物の土台の跡が次々に見つかり、地下に眠る都の姿が少しずつわかってきています。"],"tl":[["794年","桓武天皇が平安京に都を移す"],["9世紀","大極殿で即位式や元日の儀式が行われる"],["876年","大極殿が火災で焼け、のちに再建"],["1177年","安元の大火で焼失。以後は再建されず"],["中世","跡地は «内野» と呼ばれる野原・町に"],["1895年","平安遷都1100年を記念して «大極殿遺址» の碑を建立。平安神宮も創建"]],"who":[["桓武天皇","平安京に都を移した天皇"],["和気清麻呂","平安京への遷都を進言したと伝わる貴族"],["藤原冬嗣・良房ら","大内裏で政治を動かした藤原氏"]],"deep":["平安宮跡の国指定史跡は一か所ではなく、内裏跡・朝堂院跡・豊楽殿跡など点々と指定されています。市街地の下に宮殿が眠っているため、ビルの建て替えのたびに少しずつ発掘されています。","平安神宮の «外拝殿» は大極殿を約8分の5の大きさで再現したものとされます。本物がいかに大きかったか、そこから逆算して想像してみるのも楽しい見方です。","平安京の南北の大通り «朱雀大路» は幅約84m（28丈）と記録されます。いまの千本通がほぼその道筋にあたり、大極殿は朱雀大路の北のつき当たりにありました。","«内裏» は天皇の住まい、«大内裏» は役所まで含んだ宮城全体を指します。いまの京都御所は、里内裏の一つ «土御門東洞院殿» がもとになったもので、場所は平安宮より東にずれています。","碑のある場所の近くには «平安宮跡» の説明板が何か所もあり、たどって歩くと内裏・豊楽殿の位置関係がわかります。京都市平安京創生館（京都アスニー内）では平安京の大きな復元模型が見られます。"],"look":["内野児童公園の «大極殿遺址» 碑","周辺に点在する平安宮跡の説明板（内裏跡・豊楽殿跡など）","千本通＝かつての朱雀大路の道筋","京都アスニーの平安京復元模型"],"q":["大極殿が焼けて再建されなくなったきっかけの火事は？","1177年の «安元の大火»。以後、大極殿は二度と建てられませんでした。"],"koji":[{"w":"鳴くよウグイス平安京","m":"794年の平安遷都を覚える語呂合わせ"}],"myth":"和気清麻呂の進言や遷都の理由（怨霊を避けた等）には諸説があります。","img":["平安京","大極殿","平安神宮","桓武天皇"],"wp":"大内裏","rel":{"ev":["heian","michizane","jokyu","nanboku","haishi","tosanikki"],"grave":[]}},{"id":"26_toji","n":"東寺（教王護国寺・空海の都の寺）","yomi":"とうじ（きょうおうごこくじ）","cat":"寺社","rank":"S","y":796,"era":["heian","edo"],"sh":"国宝（五重塔・金堂ほか）・国指定史跡（教王護国寺境内）・世界遺産","ad":"京都市南区九条町","st":"近鉄「東寺」駅から歩いて約10分／JR京都駅八条口から歩いて約15分","la":34.9807,"lo":135.7478,"hook":"新幹線の窓から見える、日本一高い木の塔。1200年前、空海がこの寺を «仏の世界そのもの» に変えた。","lead":"東寺は平安京ができてすぐ、都の南の入口・羅城門の東に建てられた国の寺です。のちに嵯峨天皇から空海にまかされ、真言密教の中心になりました。高さ約55mの五重塔は、木でできた塔として日本一の高さです。","story":["平安京の南の正門・羅城門をくぐると、左右に二つの大きな寺が向かい合っていました。東に «東寺»、西に «西寺»。都を守るための国の寺です。ところがいま残っているのは東寺だけ。西寺は時代とともに衰え、跡地の公園に土壇が残るばかりです。なぜ東寺だけが生き残ったのでしょう。","答えの鍵をにぎるのが空海です。唐で最新の密教を学んで帰ってきた空海に、823年、嵯峨天皇はこの寺をまかせました。空海はここを密教の道場にしようと考えます。«言葉だけでは伝えきれない教えを、目に見える形で示したい»。そうして講堂に仏像を並べ、立体の曼荼羅（まんだら）をつくりあげました。","講堂に入ると、薄暗い中に21体の仏像がずらりと並び、見る人を取り囲みます。真ん中に大日如来、まわりに如来・菩薩・明王・天部。これは «仏の世界の地図» そのものです。空海の考えを、いまも同じ場所で体で感じられる。これこそ東寺のすごさです。","空海への信仰は、身分を問わず人々に広がりました。空海が亡くなった21日にちなみ、毎月21日には «弘法市» が開かれ、骨董や古着、食べ物の店が境内を埋めつくします。«弘法さん» と親しみをこめて呼ぶ京都の人にとって、東寺は今も暮らしのそばにある寺です。","五重塔は落雷などで4度焼け、そのたびに建て直されました。いまの塔は5代目で、1644年に徳川家光の寄進で完成したものです。地震の多い日本で、木の塔が何百年も倒れないのはなぜ? 塔の中心を通る «心柱» のしくみが揺れを吸収するという説が知られ、研究が続いています。"],"tl":[["796年","平安京の官寺として創建されたと伝わる"],["823年","嵯峨天皇が空海に東寺をまかせる"],["839年","講堂の仏像（立体曼荼羅）が開眼"],["1486年","土一揆による火災で金堂・講堂などが焼ける"],["1603年","豊臣秀頼の寄進で金堂が再建"],["1644年","徳川家光の寄進で現在の五重塔が完成"],["1994年","«古都京都の文化財» として世界遺産に"]],"who":[["空海（弘法大師）","真言宗を開いた僧。東寺を密教の根本道場にした"],["嵯峨天皇","空海に東寺をまかせた天皇"],["豊臣秀頼","金堂を再建"],["徳川家光","現在の五重塔を寄進"]],"deep":["正式名 «教王護国寺» は «王を教え、国を護る寺» の意味。ただし寺の古い文書では «東寺» と書かれることが多く、どちらの名も使われてきました。","五重塔の高さは約55m。現存する木造の塔として日本一とされます。初層内部は特別公開のときに入ることができ、心柱を大日如来に見立てた空間になっています。","講堂の21体の仏像のうち多くが国宝です。平安時代の初めにつくられた像がまとまって、ほぼ当初の配置で残る例はとても貴重です。","金堂は1486年の土一揆による火災で焼け、1603年に豊臣秀頼の寄進で再建されました。本尊の薬師如来像は桃山時代の仏師・康正の作とされます。","東寺には空海が唐から持ち帰ったとされる品や、密教の法具・曼荼羅が伝わり、宝物館で時期を限って公開されます。西寺跡（唐橋西寺公園）もあわせて歩くと、都の «左右対称» がよくわかります。"],"look":["五重塔（池越しの姿が定番の眺め）","講堂の立体曼荼羅21体","金堂の薬師三尊像と十二神将","毎月21日の弘法市","近くの羅城門跡・西寺跡"],"q":["毎月21日に東寺で開かれる市の名前は？","«弘法市»。空海（弘法大師）が亡くなった日にちなむといわれます。"],"koji":[{"w":"弘法も筆の誤り","m":"どんな名人でも失敗することがある、という意味。書の名人だった空海にちなむ"}],"myth":"創建年（796年）は寺の伝えによるもの。心柱が揺れをおさえるしくみには諸説があります。","img":["空海","五重塔","羅城門","西寺"],"wp":"東寺","rel":{"ev":["kukai"],"grave":[]}},{"id":"26_kinkakuji","n":"鹿苑寺 金閣（足利義満の北山殿）","yomi":"ろくおんじ きんかく","cat":"寺社","rank":"S","y":1397,"era":["muromachi","showa"],"sh":"国指定特別史跡・特別名勝（鹿苑寺庭園）・世界遺産","ad":"京都市北区金閣寺町","st":"市バス「金閣寺道」から歩いて約5分","la":35.0394,"lo":135.7292,"hook":"池に映る金色の楼閣は、将軍が «日本国王» として外国の使者をもてなした舞台。そして一度、炎に消えた建物でもある。","lead":"金閣は室町幕府3代将軍・足利義満が建てた山荘 «北山殿» の中心の建物です。義満の死後、寺（鹿苑寺）になりました。いまの金閣は1950年に焼けたあと、1955年に再建されたものです。","story":["1397年、足利義満は京都の北山にあった貴族・西園寺家の山荘を手に入れ、大がかりに造り直しはじめました。このとき義満はもう将軍の位を息子にゆずっていましたが、実際の権力はしっかり握ったまま。北山殿は、いわば «もう一つの政治の中心» でした。","池のほとりに建てられた三階建ての楼閣は、階ごとに建て方がちがいます。一階は貴族の寝殿造風、二階は武家の住まい風、三階は中国風の禅宗様。そして二階と三階は金ぱくで包まれ、屋根には鳳凰。なぜ三つの様式を重ねたのでしょう。«公家も武家も、そして仏の世界も、自分が上に立つ» という義満の気持ちの表れ、と読む人もいます。","義満は明（中国）との貿易を始め、明の皇帝から «日本国王» と呼ばれる手紙を受けとりました。明の使者を北山殿でもてなしたとも伝わります。金色にかがやく楼閣は、海の向こうから来た客に «日本の王の力» を見せる舞台でもあったのかもしれません。","1408年に義満が亡くなると、北山殿の建物の多くは移されたりこわされたりしましたが、金閣は寺の «舎利殿» として残りました。応仁の乱の戦火もくぐりぬけ、500年以上、池の上に立ちつづけます。","ところが1950年7月2日の未明、金閣は寺の若い僧による放火で焼け落ちてしまいました。国宝だった建物と、中にあった義満の像も失われます。人々の募金などで1955年に再建され、1987年には金ぱくをはりかえる大修理も行われました。この事件は三島由紀夫の小説『金閣寺』など、文学の題材にもなっています。"],"tl":[["1397年","足利義満が西園寺家の山荘を譲り受け、北山殿の造営を始める"],["1402年","明の皇帝から義満に «日本国王» あての国書が届く"],["1408年","義満が死去"],["1420年ごろ","北山殿が禅寺・鹿苑寺となる（夢窓疎石を開山とする）"],["1950年","放火により金閣が焼失"],["1955年","金閣が再建される"],["1987年","漆の塗り替えと金ぱくの張り替えを行う大修理"],["1994年","世界遺産に登録"]],"who":[["足利義満","室町幕府3代将軍。北山殿を築いた"],["足利義持","義満の子で4代将軍。父の死後、北山殿を寺にした"],["夢窓疎石","鹿苑寺の開山とされる禅僧（義満より前の人で、名目上の開山）"],["三島由紀夫","焼失事件を題材に小説『金閣寺』を書いた作家"]],"deep":["«金閣» は通称で、正式には «舎利殿»。一階は «法水院»、二階は «潮音洞»、三階は «究竟頂（くっきょうちょう）» と名前がついています。","焼失前の金閣は国宝でしたが、焼けたことで指定は外れ、いまの建物は国宝ではありません。一方、庭園は国の特別史跡・特別名勝に指定されています。","焼ける前の金閣は、一階には金ぱくがなく、上の階の金もかなりはげていたといわれます。再建では古い記録や調査をもとに金ぱくを施しました。","境内の «陸舟の松» は、義満が自ら植えた盆栽を移したと伝わる松で、帆かけ船の形に仕立てられています。京都三松の一つとされます。","文化史では、義満の時代の華やかな文化を «北山文化»、孫の義政の時代の落ち着いた文化を «東山文化» と呼び分けます。金閣と銀閣を見比べるとその違いが体でわかります。"],"look":["鏡湖池に映る金閣（«逆さ金閣»）","三つの階で違う建築様式","屋根の上の鳳凰","陸舟の松","夕佳亭（江戸時代の茶室）"],"q":["金閣の三階はどの国の建築様式？","中国風の «禅宗様（唐様）»。一階は寝殿造風、二階は武家造風です。"],"koji":[],"myth":"三つの様式に義満の «天下観» を読む解釈は一つの見方です。明の使者を北山殿で迎えた点は記録がありますが、詳細は諸説。","img":["足利義満","北山文化","金閣寺 (小説)","夢窓疎石"],"wp":"鹿苑寺","rel":{"ev":["kinkaku"],"grave":[]}},{"id":"26_ginkakuji","n":"慈照寺 銀閣（東山文化）","yomi":"じしょうじ ぎんかく","cat":"寺社","rank":"S","y":1489,"era":["muromachi"],"sh":"国宝（銀閣・東求堂）・国指定特別史跡・特別名勝（慈照寺庭園）・世界遺産","ad":"京都市左京区銀閣寺町","st":"市バス「銀閣寺道」から歩いて約10分","la":35.027,"lo":135.7982,"hook":"銀ぱくはもともと貼られていなかった？ 戦乱に背を向けた将軍が、静けさの中に «日本らしさ» の原型を生んだ。","lead":"銀閣は室町幕府8代将軍・足利義政が、応仁の乱のあと東山に建てた山荘 «東山殿» の建物です。義政の死後、寺（慈照寺）になりました。たたみや床の間のある部屋の原型が、ここに残っています。","story":["京の都は、11年も続いた応仁の乱で焼け野原になりました。争いのきっかけの一つは、将軍・足利義政のあとつぎ問題。けれど義政は争いを止めることができず、やがて将軍の位を息子の義尚にゆずります。そして1482年、東山のふもとで山荘づくりを始めました。","«政治はうまくいかなかった。でも美しいものなら、自分の手でつくれる»。義政がそう思ったかどうかはわかりません。ただ、東山殿にはお金も人手も足りませんでした。戦乱のあとで幕府は貧しく、義政は税を集めて工事を進めたため、人々からは不満も出たといわれます。","1489年、観音殿（いまの銀閣）の建物が上がりました。二階建てで、一階は住まい風、二階は禅宗様の仏堂。金閣のように金色ではなく、黒い漆と木の色が落ち着いた姿です。なぜ «銀閣» なの? 銀ぱくを貼る予定だった、という話が有名ですが、調査では銀ぱくを貼ったあとは見つかっていません。«銀閣» という呼び名は、江戸時代ごろから広まったと考えられています。","義政が特に大事にしたのが «東求堂（とうぐどう）» の一室 «同仁斎»。広さは四畳半、たたみを敷きつめ、作りつけの棚と机があります。ここで義政は書物や茶道具を楽しんだのでしょう。この «書院造» の部屋が、のちの日本の和室のお手本になりました。","義政は1490年、東山殿の完成を見ずに亡くなり、山荘は寺になりました。華やかさより «わび» や «しずけさ» を大切にした義政のまわりの文化は «東山文化» と呼ばれ、茶の湯・生け花・庭づくりなど、いまの日本文化の根っこになっています。"],"tl":[["1467年","応仁の乱が始まる（〜1477年）"],["1473年","義政が将軍職を義尚にゆずる"],["1482年","東山殿の造営を始める"],["1489年","観音殿（銀閣）が上棟"],["1490年","義政死去。のちに寺となり慈照寺と名づけられる"],["江戸時代","銀沙灘・向月台がつくられたと考えられる"],["1994年","世界遺産に登録"]],"who":[["足利義政","室町幕府8代将軍。東山殿を築いた"],["日野富子","義政の妻。応仁の乱のあとつぎ争いに関わった"],["善阿弥","義政に仕えた庭づくりの名人（東山殿との関わりは諸説）"],["村田珠光","わび茶の祖とされ、東山文化の人物"]],"deep":["2007〜2008年の科学調査で、銀閣の外壁から銀ぱくの痕跡は見つからず、黒漆が塗られていたことがわかったと報じられました。«貼る予定だったがお金がなくて貼れなかった» という説明は証拠のない俗説です。","銀閣（観音殿）と東求堂は、ともに室町時代の建物がそのまま残る国宝です。建てられた当時の東山殿の建物で残っているのは、この二つだけです。","同仁斎は、たたみを敷きつめ «付書院» と «違い棚» を備えた現存最古級の書院造の部屋とされます。«四畳半» の茶室の源流とも語られます。","白砂を波の形に盛った «銀沙灘» と円すい形の «向月台» は、義政の時代ではなく江戸時代に形ができたと考えられています。","銀閣寺道から南へのびる疏水ぞいの道は «哲学の道»。哲学者の西田幾多郎らが散歩したことから名づけられ、慈照寺と南禅寺方面をつないでいます。"],"look":["銀閣（観音殿）と錦鏡池","銀沙灘と向月台","東求堂（同仁斎は特別公開時）","展望所から見る銀閣と京都市街","哲学の道"],"q":["義政が東求堂につくった四畳半の書斎の名前は？","«同仁斎»。書院造の現存最古級の部屋とされます。"],"koji":[],"myth":"«銀ぱくを貼る予定だった» 説は俗説。善阿弥の関与は諸説です。","img":["足利義政","東山文化","応仁の乱","哲学の道"],"wp":"慈照寺","rel":{"ev":["higashiyama"],"grave":[]}},{"id":"26_nijojo","n":"二条城（大政奉還の舞台）","yomi":"にじょうじょう","cat":"城","rank":"S","y":1603,"era":["edo"],"sh":"国宝（二の丸御殿）・国指定史跡（旧二条離宮）・世界遺産","ad":"京都市中京区二条通堀川西入二条城町","st":"地下鉄東西線「二条城前」駅からすぐ","la":35.0142,"lo":135.7482,"hook":"江戸幕府の始まりと終わりを、同じ城が見届けた。徳川家康が建て、15代慶喜がここで政権を返した。","lead":"二条城は徳川家康が京都での宿所として建てた城です。1603年、将軍になった家康はここでお祝いの儀式を行いました。そして1867年、15代将軍・徳川慶喜はこの城で «大政奉還» を諸藩に伝えました。","story":["1603年、征夷大将軍になった徳川家康は、完成したばかりの二条城から御所へ向かい、天皇にお礼を申し上げる行列を行いました。京都に城を置くことには意味がありました。天皇のいる都で «いまの天下の主は徳川だ» と目に見える形で示すためです。","1611年、この城である対面が行われます。家康と、豊臣秀吉の子・秀頼。成長した秀頼の姿を見た家康が «これは油断できない» と感じた、という話が伝わります。真実はわかりませんが、この数年後、大坂の陣で豊臣家は滅びました。","3代将軍・家光のころ、後水尾天皇を城に迎えるため、城は大きく広げられました。二の丸御殿には狩野探幽ら狩野派の画家が豪華なふすま絵を描きます。大広間の松、黒書院の桜。部屋の奥へ行くほど、身分の高い人しか入れないしくみでした。","時は流れて1867年10月。15代将軍・徳川慶喜は、二の丸御殿の大広間に諸藩の重臣を集め、政権を朝廷に返す考えを伝えました。«このまま戦えば国が割れる。ならば自分から返そう»。慶喜はそう考えたとも、政権を返したあとも力を保てると見ていたともいわれます。翌日、朝廷に申し出て、265年続いた江戸幕府の政治は幕を閉じました。","明治になると城は皇室の «二条離宮» となり、のちに京都市のものになりました。廊下を歩くとキュッキュッと鳴る «うぐいす張り» の床は、忍び込む者を知らせるためともいわれますが、床板の留め金がこすれて鳴るしくみだという説明もあります。"],"tl":[["1601年","家康が築城を始める"],["1603年","完成。将軍宣下を受けた家康が拝賀の礼を行う"],["1611年","家康と豊臣秀頼が会見"],["1626年","家光が城を拡張し、後水尾天皇を迎える"],["1750年","天守が落雷で焼失"],["1867年","徳川慶喜が大広間で大政奉還の意向を伝える"],["1884年","皇室の二条離宮となる"],["1939年","京都市に下賜され «元離宮二条城» に"],["1994年","世界遺産に登録"]],"who":[["徳川家康","二条城を築いた初代将軍"],["豊臣秀頼","1611年に家康と会見"],["徳川家光","城を拡張し後水尾天皇を迎えた3代将軍"],["後水尾天皇","1626年に二条城へ行幸"],["徳川慶喜","大政奉還を行った15代将軍"],["狩野探幽","二の丸御殿の障壁画を描いた絵師"]],"deep":["二の丸御殿は6棟が雁行（ななめに連なる）して並ぶ大建築で、武家風書院造の代表として国宝に指定されています。ふすま絵などの障壁画も多くが重要文化財です。","大政奉還をめぐる日付は、10月13日に大広間で諸藩重臣に諮問、14日に朝廷へ上表、15日に勅許、という流れで説明されます（いずれも旧暦）。","天守は後水尾天皇の行幸のころに伏見城から移したものといわれ、1750年の落雷で焼けたあと再建されませんでした。いまは天守台だけが残ります。","本丸御殿は、もとの建物が失われたあと、明治時代に京都御苑にあった旧桂宮家の御殿を移したものです。","障壁画の本物の多くは劣化を防ぐため収蔵館で保管され、御殿の中は模写に置きかえられています。原画は展示収蔵館で順番に公開されます。"],"look":["東大手門と唐門","二の丸御殿の大広間（大政奉還の場面の人形展示）","うぐいす張りの廊下","天守台からの眺め","二の丸庭園"],"q":["二の丸御殿の廊下が鳴るしくみの名前は？","«うぐいす張り»。歩くと鳥の声のように鳴ることから。"],"koji":[{"w":"大政奉還","m":"将軍が政治を行う権利を天皇（朝廷）に返すこと"}],"myth":"家康が秀頼を見て警戒したという話や、うぐいす張りが防犯目的だったという話は伝承・俗説です。","img":["大政奉還","徳川慶喜","徳川家康","狩野探幽"],"wp":"二条城","rel":{"ev":["taisei"],"grave":[]}},{"id":"26_kyoto_gosho","n":"京都御所（王政復古の大号令）","yomi":"きょうとごしょ","cat":"大名屋敷","rank":"S","y":1867,"era":["muromachi","edo","meiji"],"sh":"","ad":"京都市上京区京都御苑","st":"地下鉄烏丸線「今出川」駅または「丸太町」駅から歩いて約5〜10分","la":35.0254,"lo":135.7621,"hook":"500年以上、天皇が暮らした場所。1867年の冬の夜、ここで «幕府はもういらない» という宣言が出された。","lead":"京都御所は、明治のはじめに天皇が東京へ移るまで、およそ500年にわたって天皇の住まいだった場所です。幕末には、王政復古の大号令が出され、その夜の小御所会議で新しい政府の方針が話し合われました。いまは申し込みなしで見学できます。","story":["平安京の内裏は火事が続き、天皇は貴族の屋敷を借りて暮らすようになりました。その一つ «土御門東洞院殿» が、14世紀なかばから天皇の決まった住まいになります。これがいまの京都御所のはじまりです。平安宮の跡より東にずれているのはそのためです。","御所は何度も火事で焼けました。江戸時代、老中・松平定信のころの再建では、学者の裏松固禅が平安時代の内裏を調べあげ、紫宸殿や清涼殿を古い姿に近づけて建て直しました。そのあと1854年に焼け、翌年に同じ形で再建されたのが、いま見られる建物です。","1867年12月9日（旧暦）。大政奉還から2か月、薩摩や土佐などの兵が御所の門を固める中、«王政復古の大号令» が出されました。«幕府も摂政・関白もやめ、天皇のもとで新しい政治を始める»。その夜、御所の «小御所» で会議が開かれます。","会議では、土佐の山内容堂が «徳川慶喜をこの場に呼ばないのはおかしい» と強く反対しました。対する岩倉具視は «慶喜はまず官位と領地を返すべきだ» と迫ります。休憩のとき、西郷隆盛が «短刀一本あれば片がつく» と言ったという話が伝わり、会議の空気は一変したといわれます。こうして慶喜に辞官・納地を求めることが決まりました。","この決定に反発した旧幕府側と新政府軍は、翌月、鳥羽・伏見でぶつかります。その後天皇は東京へ移り、御所は «主のいない宮殿» になりました。それでも大正天皇と昭和天皇の即位の礼は、ここ紫宸殿で行われています。"],"tl":[["1331年","光厳天皇が土御門東洞院殿で即位したと伝わる。以後、内裏となる"],["1790年","松平定信のもと、平安の様式にならって再建"],["1854年","火災で焼失し、翌1855年に再建（現在の建物）"],["1864年","蛤御門の変（禁門の変）。御所の門の周辺で戦闘"],["1867年","王政復古の大号令。小御所会議"],["1869年","明治天皇が東京へ（事実上の遷都）"],["1915年・1928年","大正・昭和天皇の即位の礼が紫宸殿で行われる"],["2016年","通年一般公開が始まる"]],"who":[["明治天皇","王政復古のとき満15歳の天皇"],["岩倉具視","公家。王政復古を進めた中心人物"],["山内容堂","土佐藩前藩主。小御所会議で慶喜を擁護"],["西郷隆盛","薩摩藩士。御所の警備を指揮"],["松平定信","寛政の御所再建を指揮した老中"]],"deep":["御所の建物の周りの公園は «京都御苑» で環境省が管理し、御所そのものは宮内庁が管理しています。江戸時代、御苑の場所には公家屋敷が200ほど並んでいました。","紫宸殿の前の «左近の桜・右近の橘» は、平安時代の内裏のならわしを受けつぐものです。ひな人形の飾りにもこの二本の木が出てきます。","«蛤御門» は、ふだん閉じていた門が大火のときに初めて開いたことから «焼けて口を開く蛤» にたとえられた、という名前の由来が伝わります。1864年の戦いの弾のあととされるくぼみが門に残っています。","寛政の再建で裏松固禅がまとめた考証書『大内裏図考証』は、平安宮の研究でもいまも重要な史料とされています。","西郷の «短刀一本» の話は後年の回想などで伝わるもので、言葉どおりに言ったかはわかりません。小御所会議の記録は立場によって書き方が違います。"],"look":["建礼門と承明門越しの紫宸殿","清涼殿","小御所（王政復古の夜の会議場）","御池庭","京都御苑の蛤御門"],"q":["王政復古の大号令が出た日の夜、御所のどの建物で会議が開かれた？","«小御所»。そのため «小御所会議» と呼ばれます。"],"koji":[{"w":"王政復古","m":"武家の政治を終わらせ、天皇中心の政治にもどすこと"}],"myth":"西郷隆盛の «短刀一本» 発言は伝聞。蛤御門の名の由来も伝承です。","img":["王政復古 (日本)","小御所会議","京都御苑","禁門の変"],"wp":"京都御所","rel":{"ev":["michinaga","genji","taisei","gokajo","tokyo_sento"],"grave":[]}},{"id":"26_honnoji","n":"本能寺跡（本能寺の変）","yomi":"ほんのうじあと","cat":"事件","rank":"S","y":1582,"era":["azuchi"],"sh":"","ad":"京都市中京区小川通蛸薬師 元本能寺南町付近","st":"地下鉄烏丸線「四条」駅・阪急「烏丸」駅から歩いて約10分","la":35.0063,"lo":135.7542,"hook":"天下統一まであと一歩。明け方の寺を取り囲んだのは、いちばん信頼していた家臣の軍勢だった。","lead":"1582年6月2日の明け方、織田信長が泊まっていた本能寺を、家臣の明智光秀が大軍で襲いました。信長はここで命を落とします。いまの本能寺は後に移された場所にあり、事件の現場には «本能寺址» の石碑が立つだけです。","story":["1582年の初夏、織田信長はわずかな供を連れて京都の本能寺に泊まっていました。中国地方で毛利氏と戦う羽柴秀吉を助けに行く途中です。本能寺は町の中の寺でしたが、堀や土塁で囲まれ、信長の京都での宿所として使われていました。","同じころ、明智光秀は1万を超える兵をひきいて丹波の亀山城を出ました。行き先は秀吉の応援のはず。ところが軍勢は西ではなく東へ、京都へと向かいます。«敵は本能寺にあり» というせりふが有名ですが、これは後の時代の本や物語でふくらんだ言葉だと考えられています。","6月2日の夜明け前、本能寺のまわりで物音が上がりました。信長は最初、家来どうしのけんかかと思ったといいます。しかし旗印を見た家来が «明智の軍勢です» と告げると、信長は «是非に及ばず（しかたがない）» とだけ言ったと『信長公記』は記します。信長は自ら弓や槍で戦ったのち、奥へ入り、寺に火がかけられました。","信長の遺体は見つからなかったといわれます。近くの二条新御所にいた長男の信忠も、明智軍に囲まれて自害しました。天下の主が、たった一日で消えたのです。なぜ光秀は主君を討ったのか? 恨み説、天下を取りたかった説、黒幕がいた説…。400年以上たったいまも答えは出ていません。","光秀の天下は長く続きませんでした。知らせを聞いた秀吉は急いで軍を引き返し（«中国大返し»）、11日後の山崎の戦いで光秀を破ります。本能寺は焼けたあと、秀吉の都市づくりで寺町御池へ移されました。いまの本能寺の境内には信長の供養塔があり、かつての現場は、ビルと住宅の並ぶ静かな町の一角になっています。"],"tl":[["1415年","日隆が «本応寺» を開く（のちの本能寺）"],["1582年6月2日","本能寺の変。織田信長、信忠が死去"],["1582年6月13日","山崎の戦いで明智光秀が敗れる"],["1591年ごろ","豊臣秀吉の命で寺町御池へ移転"],["2007年","旧境内の発掘調査で堀の跡や焼けた瓦が見つかる"]],"who":[["織田信長","本能寺で最期をむかえた戦国大名"],["明智光秀","信長を襲った家臣。変の11日後に敗れる"],["織田信忠","信長の長男。二条新御所で自害"],["森蘭丸（成利）","信長のそばに仕えた小姓。本能寺で討ち死に"],["太田牛一","『信長公記』の作者"]],"deep":["«是非に及ばず» は太田牛一『信長公記』の記述です。«もうどうにもならない» とも «良い悪いを言っている場合ではない» とも読め、解釈が分かれます。","2007年の発掘では、本能寺の変のころの堀の跡や、焼けた瓦がまとまって見つかったと報告されています。«寺» といっても防御をそなえた «城のような宿所» だった可能性が指摘されています。","光秀の動機は «怨恨説»«野望説»«四国政策をめぐる対立説»«朝廷・足利義昭などの黒幕説» などがあり、決め手はありません。","«敵は本能寺にあり» は江戸時代以降の読み物や頼山陽の詩などで広まった表現とされ、同時代の史料にはありません。","本能寺の瓦や寺名の «能» の字は、火事をきらって «ヒ（火）» を «去» にかえた異体字を使っています。度重なる焼失の歴史を物語る話として知られます。"],"look":["«此附近 本能寺址» の石碑（跡地）","碑の周辺の地形（堀のあった場所を想像して歩く）","移転後の本能寺（寺町御池）の信長公廟","本能寺の «能» の字の異体字"],"q":["光秀の軍勢に気づいた信長が言ったと記録される言葉は？","«是非に及ばず»。『信長公記』に書かれています。"],"koji":[{"w":"敵は本能寺にあり","m":"本当の目的はほかにある、という意味で使われる。ただし光秀の実際の言葉とは確かめられない"},{"w":"三日天下","m":"ごく短い間しか権力を持てないこと。光秀の天下の短さから"}],"myth":"«敵は本能寺にあり» は後世の創作的表現。信長最期のようすや光秀の動機は諸説あり、遺体の行方もわかっていません。","img":["本能寺","織田信長","明智光秀","山崎の戦い"],"wp":"本能寺の変","rel":{"ev":["honnoji"],"grave":[]}},{"id":"26_byodoin","n":"平等院 鳳凰堂","yomi":"びょうどういん ほうおうどう","cat":"寺社","rank":"S","y":1053,"era":["heian"],"sh":"国宝（鳳凰堂・阿弥陀如来坐像ほか）・国指定史跡・名勝（平等院庭園）・世界遺産","ad":"宇治市宇治蓮華","st":"JR奈良線・京阪宇治線「宇治」駅から歩いて約10分","la":34.8893,"lo":135.8077,"hook":"«この世の終わりが来る»。そう信じられた年、藤原頼通はこの世に極楽をつくった。10円玉のあの建物だ。","lead":"平等院は、藤原道長の子・頼通が父の別荘を寺にしたものです。池に浮かぶように建つ «鳳凰堂» は、極楽浄土の宮殿を思いえがいてつくられました。10円玉の表の絵柄、1万円札のうらの鳳凰でもおなじみです。","story":["平安時代の人々は、ある年から «末法» の世が始まると恐れていました。お釈迦さまの教えが力を失い、世の中が乱れるという考えです。その始まりの年とされたのが1052年。ちょうどその年、藤原頼通は宇治にあった父・道長の別荘を寺に改め、«平等院» としました。","翌1053年、池の中島に阿弥陀堂が完成します。中には仏師・定朝がつくった金色の阿弥陀如来。まわりの壁には、雲に乗って楽器を奏でたり舞ったりする «雲中供養菩薩» が52体。«せめて死ぬときは、阿弥陀さまに極楽へ迎えてほしい»。人々の願いを形にした建物でした。","なぜ «鳳凰堂» と呼ばれるの? 屋根の上に一対の鳳凰が飾られていることに加え、建物全体が羽を広げた鳥のように見えるからだといわれます。これは江戸時代ごろから広まった呼び名です。池の東側に立って見ると、水面に映る姿もふくめて、まさに «極楽の宮殿» です。","平等院は、戦いの舞台にもなりました。1180年、平家をたおそうと立ち上がった以仁王と源頼政は、宇治川で平家の軍に追いつかれます。頼政は平等院で自害したと伝わり、境内には «扇の芝» と呼ばれる場所が残っています。","その後の戦乱で多くの建物は失われましたが、鳳凰堂は奇跡的に残りました。2012年から2014年の修理では、柱や扉を当初に近い朱色（丹土）で塗り直し、屋根の鳳凰も金色にかがやく姿で戻されています。"],"tl":[["998年","藤原道長が宇治の別荘を手に入れる（のちの宇治殿）"],["1052年","頼通が別荘を寺に改め、平等院とする（末法元年とされた年）"],["1053年","阿弥陀堂（鳳凰堂）が完成"],["1180年","源頼政が平等院で自害したと伝わる"],["1951年","10円硬貨のデザインに鳳凰堂が採用される"],["1994年","世界遺産に登録"],["2014年","平成の大修理が完了"]],"who":[["藤原頼通","道長の子。平等院を開いた"],["藤原道長","宇治の別荘の持ち主だった頼通の父"],["定朝","本尊・阿弥陀如来坐像をつくった仏師"],["源頼政","以仁王の挙兵に加わり、平等院で最期をとげたと伝わる武将"]],"deep":["本尊の阿弥陀如来坐像は、定朝の作と確実にわかる唯一の像とされます。«寄木造» の技法を完成させた定朝の仏像は «仏の本様» と呼ばれ、以後の仏像の手本になりました。","雲中供養菩薩52体はすべて国宝。一部は境内の博物館 «鳳翔館» に移して展示されています。屋根の鳳凰の本物も鳳翔館にあり、屋根の上のものは複製です。","平安時代には «極楽いぶかしくば宇治の御寺をうやまへ（極楽が疑わしければ宇治の寺を拝みなさい）» という歌がはやったと伝わります。","庭園は、阿弥陀堂を池に浮かべて見せる «浄土式庭園» の代表例です。発掘調査で、当初の州浜（小石を敷きつめた岸辺）がよみがえりました。","1万円札（2004年発行のシリーズ）のうらに描かれた鳳凰は、鳳凰堂の屋根の鳳凰がモデルです。お金の表と裏、両方に登場する珍しい建物です。"],"look":["池の東岸から見る鳳凰堂の正面","鳳凰堂内の阿弥陀如来坐像（内部拝観は別受付）","鳳翔館の雲中供養菩薩と鳳凰","扇の芝","宇治川と宇治橋"],"q":["鳳凰堂の壁にかけられた、雲に乗る菩薩像は全部で何体？","52体。«雲中供養菩薩» と呼ばれ、すべて国宝です。"],"koji":[{"w":"末法思想","m":"仏の教えが衰え、世が乱れるという考え。日本では1052年が末法の始まりとされた"}],"myth":"頼政が平等院で自害したことや扇の芝の由来は伝承です。流行歌の文句は伝えによります。","img":["藤原頼通","定朝","末法思想","宇治川"],"wp":"平等院","rel":{"ev":["byodoin","genji"],"grave":[]}},{"id":"26_toba_fushimi","n":"鳥羽・伏見の戦い 古戦場（小枝橋・御香宮）","yomi":"とば・ふしみのたたかい こせんじょう","cat":"古戦場","rank":"S","y":1868,"era":["edo","meiji"],"sh":"","ad":"京都市伏見区御香宮門前町（御香宮神社）・伏見区中島（小枝橋付近）","st":"御香宮：近鉄「桃山御陵前」駅・京阪「伏見桃山」駅から歩いて約5分／小枝橋：地下鉄・近鉄「竹田」駅から歩いて約20分","la":34.9357,"lo":135.7707,"hook":"一発の大砲が、日本を二つに割った。1868年正月、京都の南の町から «戊辰戦争» が始まった。","lead":"1868年1月3日（旧暦）、京都の南の鳥羽と伏見で、旧幕府軍と薩摩・長州を中心とする新政府軍が戦いました。数では旧幕府軍が多かったのに、4日ほどで敗れます。この戦いから、1年半におよぶ戊辰戦争が始まりました。","story":["王政復古のあと、徳川慶喜は大坂城に下がっていました。«薩摩の横暴を朝廷に訴えよう»。旧幕府側の兵は京都へ向かって北上します。鳥羽街道と伏見街道、二つの道です。待ちかまえていたのは、薩摩と長州の兵でした。","1月3日の夕方、鳥羽街道の小枝橋のあたりで «通せ»«通さぬ» の押し問答が続いたあと、薩摩の大砲が火をふきました。その音を合図のように、伏見でも戦いが始まります。伏見では、旧幕府方の会津藩兵や新選組が伏見奉行所に、薩摩が高台の御香宮神社に陣取り、にらみ合っていました。","高いところから撃ちおろす薩摩の砲撃で、伏見奉行所は燃え上がり、町も炎に包まれました。新選組は刀を抜いて斬り込みますが、銃と大砲の前に次々と倒れます。のちに土方歳三が «これからの戦いは銃砲でなければだめだ。刀や槍では役に立たない» と語ったと伝わります。","なぜ数で勝る旧幕府軍が負けたのでしょう。武器や指揮のちがいに加え、大きかったのが «錦の御旗» です。新政府軍に天皇の軍を示す旗がかかげられると、旧幕府軍は «朝敵（天皇の敵）» になってしまいました。淀藩は城に入れてくれず、津藩は味方から撃ってくる側にまわりました。","1月6日の夜、慶喜はひそかに大坂城を抜け出し、船で江戸へ帰ってしまいます。残された兵たちは大坂から散っていきました。戦場となった伏見や淀のまちには、いまも戦死者の墓や慰霊碑が残り、両軍の人々をしのんでいます。"],"tl":[["1867年12月","王政復古の大号令。慶喜は大坂城へ"],["1868年1月3日","鳥羽の小枝橋付近で戦闘開始。伏見でも交戦"],["1868年1月4日","新政府軍に錦の御旗が与えられる"],["1868年1月5日","淀の千両松などで激戦。淀藩が旧幕府軍の入城を拒む"],["1868年1月6日","橋本で津藩が新政府側につき砲撃。慶喜が大坂城を脱出"],["1869年5月","箱館戦争が終わり、戊辰戦争が終結"]],"who":[["徳川慶喜","前将軍。戦いの最中に大坂から江戸へ去った"],["西郷隆盛","薩摩藩の指導者。新政府軍を指揮"],["土方歳三","新選組副長。伏見で戦った"],["井上源三郎","新選組の古参隊士。淀千両松付近で戦死"],["仁和寺宮嘉彰親王","征討大将軍に任じられ、錦の御旗をかかげた"]],"deep":["兵力は旧幕府軍が約1万5千、新政府軍が約5千と説明されることが多いですが、数え方によって差があります。","御香宮神社の表門は、伏見城の大手門を移したものと伝わり、国の重要文化財です。境内には «伏見の戦跡» の碑があり、薩摩がここに陣を置いたことが記されています。","錦の御旗は、岩倉具視の周辺で事前に用意されていたとされ、それまで実物を見た人がほとんどいない旗でした。«旗一枚で戦局が変わった» ことは、この戦いの特徴としてよく語られます。","伏見奉行所跡は、のちに陸軍の工兵隊の敷地となり、いまは住宅地（桃陵団地）の一角に碑が立ちます。","土方の言葉は、のちに依田学海が書きとめた談話として伝わるもので、原文は漢文調です。言葉どおりかは確かめられません。"],"look":["御香宮神社の表門と «伏見の戦跡» 碑","小枝橋と «鳥羽伏見戦跡» の碑","伏見奉行所跡の碑","淀・千両松付近の慰霊碑","寺田屋など伏見の幕末史跡（別の事件）"],"q":["新政府軍を «天皇の軍» と示し、旧幕府軍の士気をくじいた旗の名前は？","«錦の御旗»。これにより旧幕府軍は朝敵とされました。"],"koji":[{"w":"勝てば官軍","m":"勝った方が正義とされる、という意味。この戦いから生まれたことばといわれる"}],"myth":"兵力の数、土方の言葉、御香宮表門の由来などは伝承・諸説を含みます。","img":["戊辰戦争","御香宮神社","伏見奉行所","錦の御旗"],"wp":"鳥羽・伏見の戦い","rel":{"ev":[],"grave":[]}},{"id":"26_ikedaya","n":"池田屋跡（池田屋事件）","yomi":"いけだやあと","cat":"幕末","rank":"S","y":1864,"era":["edo"],"sh":"","ad":"京都市中京区三条通河原町東入ル中島町","st":"京阪「三条」駅・地下鉄東西線「京都市役所前」駅から歩いて約5分","la":35.0089,"lo":135.7715,"hook":"祇園祭の宵の夜、三条の宿屋の階段を新選組が駆け上がった。この一夜で «新選組» の名は京都中にとどろいた。","lead":"1864年6月5日（旧暦）の夜、京都三条の旅館 «池田屋» に集まっていた尊王攘夷派の志士たちを、新選組が襲いました。多くの志士が亡くなり、新選組は一躍有名になります。建物は残っておらず、跡地には石碑が立っています。","story":["幕末の京都は、«外国を追い払え»«天皇中心の世に» と叫ぶ志士たちと、それを取りしまる幕府側が、にらみ合う町でした。前の年、長州藩は政変で京都から追い出されていました。長州や土佐などの志士たちは、なんとか京都へ戻ろうと、ひそかに計画を練っていました。","6月5日の朝、新選組は志士たちに道具を用意していた古高俊太郎を捕まえ、きびしく取り調べます。新選組側の記録によれば、古高は «強い風の日に御所に火を放ち、そのすきに…» という計画を話したとされます。«今夜、どこかで志士たちが集まる»。新選組は町じゅうをしらみつぶしに探しはじめました。","その夜は祇園祭の宵山のころ。人通りの多い中、近藤勇がひきいる数人の隊は、三条小橋の池田屋にたどり着きます。«御用改めである!»。近藤は数人だけで中へ踏み込みました。暗い二階、せまい階段。刀と刀がぶつかる、激しい斬り合いが始まりました。","やがて土方歳三の隊や、会津藩などの兵もかけつけ、宿のまわりは囲まれます。熊本の宮部鼎蔵、長州の吉田稔麿らが命を落としました。新選組でも藤堂平助が額を斬られるなど、けが人や死者が出ています。長州の桂小五郎（のちの木戸孝允）は、その場にいなかったため助かったと伝わります。","この事件は、長州藩を怒らせ、翌月の «禁門の変» へとつながりました。«池田屋事件がなければ明治維新はもっと早かった» とも «かえって早まった» とも言われ、評価はさまざまです。いまの跡地には飲食店が建ち、店の前の石碑が、この夜に亡くなった人々をしのぶ場所になっています。"],"tl":[["1863年8月","八月十八日の政変。長州藩が京都から追われる"],["1864年6月5日朝","古高俊太郎が新選組に捕らえられる"],["1864年6月5日夜","池田屋事件"],["1864年7月","禁門の変（蛤御門の変）"],["明治以降","池田屋は廃業。跡地に «池田屋騒動之址» の碑が立つ"]],"who":[["近藤勇","新選組局長。池田屋に最初に踏み込んだ"],["土方歳三","新選組副長。別働隊をひきいて駆けつけた"],["沖田総司","新選組一番隊組長。池田屋で戦った"],["宮部鼎蔵","熊本藩出身の志士。池田屋で死去"],["吉田稔麿","長州藩士で松下村塾の門下生。事件で死去"],["桂小五郎","長州藩士。事件の難を逃れたと伝わる"]],"deep":["«御所に火を放つ» という計画は、古高の自白として新選組側の記録などに見えるものです。どこまで具体的な計画だったかについては議論があります。","沖田総司が池田屋で血を吐いて倒れた、という有名な場面は、後の小説などが広めた話で、同時代の確かな史料では確かめられていません。","近藤勇が故郷に送った手紙には、踏み込んだ人数の少なさや激闘のようすが書かれ、事件を知る重要な史料になっています。","事件後、新選組は幕府や会津藩からほうびを受け、隊士の数もふえました。«新選組» の名が広く知られるきっかけになった事件です。","跡地の石碑は三条通の歩道ぞいにあり、すぐ西が三条小橋です。三条大橋のたもとには、池田屋事件の刀傷と伝わる擬宝珠（ぎぼし）があります。"],"look":["«池田屋騒動之址» の石碑","三条小橋と高瀬川","三条大橋の擬宝珠の刀傷（伝承）","近くの «古高俊太郎邸跡» の碑"],"q":["池田屋事件のあと、翌月に長州藩が京都で起こした戦いは？","«禁門の変（蛤御門の変）»。池田屋事件が長州の出兵を後押ししました。"],"koji":[],"myth":"計画の中身、沖田の喀血、桂小五郎が助かった理由、三条大橋の刀傷などには諸説・創作が含まれます。","img":["新選組","近藤勇","禁門の変","三条大橋"],"wp":"池田屋事件","rel":{"ev":["kenmu","ikedaya","ryoma","k_tokaido","k_nakasendo"],"grave":[]}},{"id":"26_nagaokakyu","n":"長岡宮跡（向日市・長岡京）","yomi":"ながおかきゅうあと","cat":"遺跡","rank":"S","y":784,"era":["nara","heian"],"sh":"国指定史跡（長岡宮跡）","ad":"向日市鶏冠井町大極殿（大極殿公園）","st":"阪急京都線「西向日」駅から歩いて約5分","la":34.9433,"lo":135.7042,"hook":"平城京と平安京のあいだ、わずか10年だけの都があった。その短さのうらに、一つの暗殺事件がひそむ。","lead":"784年、桓武天皇は奈良の平城京から、いまの向日市・長岡京市のあたりに都を移しました。これが長岡京です。ところが都は10年で捨てられ、平安京へ移ります。大極殿の跡は公園になり、基壇が復元されています。","story":["奈良の平城京では、大きな寺の力が強くなりすぎていました。即位したばかりの桓武天皇は «新しい都で、新しい政治を» と考えます。選んだのは、桂川・宇治川・木津川が集まる長岡の地。川を使えば、荷物を船で運びこむことができました。","工事は急ピッチで進みました。難波宮の建物を解体して運び、長岡宮で建て直したとも考えられています。784年の暮れ、天皇は新しい宮に移りました。ところが翌785年9月、工事の責任者だった藤原種継が、夜の見回り中に矢で射られて亡くなります。","犯人として捕らえられた者の中には、天皇の弟で皇太子の早良親王に仕える人々がいました。早良親王は «自分は無実だ» と食事をとらず、淡路へ送られる途中で亡くなったと伝わります。そのあと、天皇の身内に不幸が続き、洪水や病気も起こりました。«早良親王のたたりではないか»。人々はそうささやきました。","なぜ都はたった10年で捨てられたのでしょう。«たたりを恐れたから» という説明が有名ですが、洪水が多かったこと、もっと広く計画的な都をつくりたかったこと、なども理由に挙げられます。794年、桓武天皇は北東の平安京へ移り、長岡京は田畑にもどっていきました。","長いあいだ «幻の都» とされた長岡京ですが、1950年代から地元の研究者・中山修一らが発掘を始め、宮殿の跡がつぎつぎと見つかりました。いまでは大極殿や朝堂院の位置がわかり、市街地の地下から毎年のように新しい発見が報告されています。"],"tl":[["784年","桓武天皇が平城京から長岡京へ遷都"],["785年","藤原種継が暗殺される。早良親王が廃され死去"],["789年ごろ","宮の中心部の建て替え（東宮の移転など）が進む"],["792年","大雨による洪水の被害が記録される"],["794年","平安京へ遷都"],["1950年代","中山修一らによる発掘で宮跡が確認される"],["1964年","長岡宮跡が国の史跡に指定"]],"who":[["桓武天皇","長岡京、そして平安京をつくった天皇"],["藤原種継","長岡京造営の責任者。建設中に暗殺された"],["早良親王","桓武天皇の弟。事件に連座して亡くなり、のち «崇道天皇» とされた"],["中山修一","長岡京の発掘に生涯をかけた地元の研究者"]],"deep":["長岡宮の建物の一部は、後期難波宮から移したと考えられています。出土する瓦に難波宮と同じ型のものがあることが根拠の一つです。","早良親王はのちに «崇道天皇» の名を贈られ、怨霊をしずめるまつりが行われました。京都の上御霊神社・下御霊神社にもまつられています。","長岡京は、それまでの都にはなかった «水運の都» だったと評価されます。淀川を通じて瀬戸内海とつながり、物資を運ぶのに便利でした。","遷都の理由は «怨霊説»«洪水説»«計画のやり直し説» などが挙げられ、ひとつに決めることはできません。短期間にもかかわらず、発掘成果から都市としてかなり整備されていたことがわかっています。","大極殿公園には大極殿の基壇が復元され、隣接して後殿跡もあります。近くの «向日市文化資料館» では長岡京の模型や出土品を見ることができます。"],"look":["大極殿公園の復元基壇と説明板","朝堂院跡の史跡公園（朝堂院西第四堂跡など）","向日市文化資料館","向日神社と周辺の丘陵"],"q":["長岡京の造営中に暗殺された責任者はだれ？","藤原種継。事件は早良親王の悲劇へとつながりました。"],"koji":[],"myth":"遷都の理由（怨霊など）は諸説あり、早良親王の死のようすも伝承を含みます。","img":["桓武天皇","藤原種継","早良親王","平安京"],"wp":"長岡京","rel":{"ev":[],"grave":[]}},{"id":"26_kunikyo","n":"恭仁宮跡（聖武天皇の都・木津川市）","yomi":"くにきゅうあと","cat":"遺跡","rank":"S","y":740,"era":["nara"],"sh":"国指定史跡（恭仁宮跡〈山城国分寺跡〉）","ad":"木津川市加茂町例幣","st":"JR関西本線「加茂」駅から歩いて約30分（コミュニティバスもあり）","la":34.7556,"lo":135.8633,"hook":"«国分寺をつくれ» ——あの有名な命令は、奈良の都ではなく、木津川のほとりの小さな都で出された。","lead":"740年、聖武天皇は平城京をはなれて旅を続け、いまの木津川市に «恭仁京（くにきょう）» をつくりました。国分寺建立の詔はここで出されています。都はわずか数年で終わり、大極殿はのちに山城国分寺の金堂になりました。","story":["740年秋、九州で藤原広嗣が反乱を起こしました。その知らせのさなか、聖武天皇は突然平城京を出て、伊勢・美濃・近江をめぐる旅に出ます。«なぜ都を出たのか?» 反乱への不安、政治の立て直し、仏教への思い。はっきりした答えは、いまも見つかっていません。","その年の暮れ、天皇がたどりついたのが、木津川のほとりの «恭仁» の地でした。右大臣・橘諸兄の別荘があったところです。天皇はここに新しい宮をかまえ、平城京から大極殿を運ばせました。山と川に囲まれた小さな盆地に、都がつくられていきます。","741年、天皇はここで大きな命令を出します。«国ごとに寺をつくり、国の平和を祈れ»。全国に国分寺・国分尼寺をおく «国分寺建立の詔» です。743年には、開墾した土地を永久に自分のものにしてよいという «墾田永年私財法» も、この都の時代に出されました。","けれど、恭仁京が完成することはありませんでした。天皇は近江の紫香楽宮へたびたび出かけ、743年にはそこで大仏をつくる詔を出します。744年には難波宮を都とし、745年、結局平城京へもどりました。都は5年ほどで捨てられたのです。","残された大極殿は、746年に山城国の国分寺にあたえられ、その金堂になりました。天皇が国分寺をつくれと命じた場所が、最後には国分寺そのものになったのです。いま、田畑の中に残る大きな礎石が、都と寺の二つの時代を静かに伝えています。"],"tl":[["740年","藤原広嗣の乱。聖武天皇が平城京を出て、年末に恭仁京へ"],["741年","国分寺建立の詔が出される"],["743年","墾田永年私財法。紫香楽宮で大仏造立の詔"],["744年","難波宮を都とする"],["745年","平城京へもどる"],["746年","恭仁宮の大極殿が山城国分寺に施入される"],["1957年","恭仁宮跡（山城国分寺跡）が国の史跡に指定"]],"who":[["聖武天皇","恭仁京をつくった天皇。大仏造立でも知られる"],["橘諸兄","右大臣。恭仁の地に別荘があり、遷都を進めたとされる"],["藤原広嗣","九州で反乱を起こした官人"],["大伴家持","恭仁京をほめたたえる歌を『万葉集』に残した歌人"]],"deep":["恭仁京は正式に «大養徳恭仁大宮（やまとのくにのおおみや）» と名づけられたと『続日本紀』に記されています。","都は木津川をまたいでつくられ、川の北側と南側で左京・右京を分けるという、ほかの都にない形だったと考えられています。","大極殿の跡には、国分寺金堂として使われた時代の礎石が残っています。発掘で、大極殿の基壇の大きさは平城宮の大極殿（第一次）とほぼ同じとわかりました。","国分寺跡には七重塔の基壇と礎石も残ります。国分寺の塔は多くが七重塔だったとされ、ここはその規模を体で感じられる数少ない場所です。","聖武天皇の «彷徨五年» と呼ばれる時期（740〜745年）は、恭仁京・紫香楽宮・難波宮と都がめまぐるしく動き、奈良時代史のなぞの一つとされます。"],"look":["大極殿跡（国分寺金堂跡）の礎石","七重塔跡の基壇と礎石","木津川市恭仁宮跡の説明板・案内施設","周辺の田園風景と木津川"],"q":["恭仁京の時代に出された、国ごとに寺をつくるよう命じた詔は？","«国分寺建立の詔»（741年）。"],"koji":[],"myth":"聖武天皇が平城京を離れた理由は諸説あります。左京・右京の配置も研究途上です。","img":["聖武天皇","国分寺","紫香楽宮","橘諸兄"],"wp":"恭仁京","rel":{"ev":[],"grave":[]}},{"id":"26_kamigamo","n":"賀茂別雷神社（上賀茂神社・山城国一之宮）","yomi":"かもわけいかづちじんじゃ（かみがもじんじゃ）","cat":"寺社","rank":"S","y":677,"era":["asuka","heian"],"sh":"国宝（本殿・権殿）・世界遺産","ad":"京都市北区上賀茂本山","st":"市バス「上賀茂神社前」からすぐ／地下鉄烏丸線「北山」駅から歩いて約20分","la":35.0602,"lo":135.7527,"hook":"天から落ちた雷の子が、屋根を突きやぶって帰っていった。京都でいちばん古い神話をもつ神社の一つ。","lead":"上賀茂神社は、平安京ができるよりずっと前から、この地に住んだ賀茂氏がまつってきた神社です。京都三大祭の一つ «葵祭» は、下鴨神社とこの神社のお祭りです。山城国の一宮として都を守ってきました。","story":["むかし、賀茂の土地に住む玉依日売（たまよりひめ）が川で遊んでいると、朱色の矢が流れてきました。持ち帰って床のそばに置くと、やがて玉依日売は男の子を産みます。父親はだれなのか、だれにもわかりません。","男の子が大きくなったお祝いの宴で、祖父がさかずきを渡して言いました。«おまえの父だと思う人に、この酒を飲ませなさい»。すると男の子はさかずきを天に向けてささげ、屋根を突き破って空へ昇っていったといいます。この子こそ、上賀茂神社の神 «賀茂別雷大神（かもわけいかづちのおおかみ）» です。","神社の北にある神山（こうやま）は、神が最初に降り立った山と伝わります。本殿の前の «細殿» のまえに盛られた二つの円すい形の砂山 «立砂（たてずな）» は、その神山をかたどったもの。鬼門や裏鬼門に «清めの砂» をまく風習の起こりともいわれます。","平安京ができると、賀茂の神は都を守る神としてあつく敬われました。嵯峨天皇は、自分の娘を神に仕える «斎王» として送ります。これが賀茂斎院のはじまりで、以後およそ400年、皇女が神に仕えました。いまの葵祭で十二単を着て行列する «斎王代» は、その姿を再現したものです。","本殿は21年ごとに建て替えや修理をする «式年遷宮» で守られてきました。いまの本殿と権殿は江戸時代末の1863年に建てられたもので、国宝です。境内を流れる «ならの小川» のせせらぎは、小倉百人一首の歌にもよまれています。"],"tl":[["677年","天武天皇の命で社殿が造営されたと伝わる"],["794年","平安遷都。都の守り神として重んじられる"],["810年ごろ","嵯峨天皇の皇女が初代の賀茂斎院となる"],["1093年","賀茂競馬（くらべうま）が始まったと伝わる"],["1863年","現在の本殿・権殿が造営される"],["1994年","世界遺産に登録"]],"who":[["賀茂別雷大神","上賀茂神社の祭神"],["玉依日売","祭神の母とされる女神"],["嵯峨天皇","賀茂斎院の制度を始めた天皇"],["有智子内親王","嵯峨天皇の皇女。初代賀茂斎院"]],"deep":["神話は『山城国風土記』の逸文（ほかの本に引用されて残った文）に記されています。下鴨神社の祭神・玉依日売と賀茂建角身命は、上賀茂の神の母と祖父にあたります。","本殿と権殿はどちらも «流造（ながれづくり）» で、前の屋根が長く流れるように伸びる形です。日本の神社で最も多い形式の代表例とされます。","葵祭では、社殿や行列の人々がフタバアオイの葉で飾られます。フタバアオイは両社の神紋でもあり、境内で育てる取り組みも行われています。","5月5日の «賀茂競馬» は、左右二頭の馬が走りの速さを競う神事で、京都市の無形民俗文化財です。徒然草にも見物の話が出てきます。","«風そよぐ ならの小川の夕暮れは みそぎぞ夏のしるしなりける»（藤原家隆）の歌は、境内の «ならの小川» をよんだものとされます。"],"look":["細殿前の立砂","楼門と玉橋","ならの小川と渉渓園","境内の «片岡社»（紫式部も参ったと伝わる）","周辺の社家町の町並み"],"q":["上賀茂神社の細殿の前にある、二つの円すい形の砂山の名前は？","«立砂»。神が降りた神山をかたどったものといわれます。"],"koji":[],"myth":"創建は神話・伝承による。社殿造営の年や競馬の始まりの年は社伝です。","img":["葵祭","賀茂御祖神社","斎院","賀茂氏"],"wp":"賀茂別雷神社","rel":{"ev":[],"grave":[]}},{"id":"26_kiyomizu","n":"清水寺","yomi":"きよみずでら","cat":"寺社","rank":"S","y":778,"era":["heian","edo"],"sh":"国宝（本堂）・世界遺産","ad":"京都市東山区清水1丁目","st":"市バス「五条坂」「清水道」から歩いて約10分／京阪「清水五条」駅から歩いて約25分","la":34.9949,"lo":135.785,"hook":"くぎを一本も使わない «舞台» は、清らかな滝の上に建つ。征夷大将軍・坂上田村麻呂とのゆかりが伝わる寺。","lead":"清水寺は、音羽山のふもとに湧く清らかな滝を中心に開かれた寺です。坂上田村麻呂が仏堂を建てたと伝わります。崖にせり出した «清水の舞台» は、江戸時代に徳川家光の寄進で再建された本堂の一部です。","story":["寺の伝えによると、778年、大和の僧・延鎮（賢心）は夢のお告げにみちびかれて、音羽山にやってきました。そこには金色の水が流れ落ちる滝があり、一人の老人が修行していました。老人は «この地をたのむ» と言い残して姿を消した、と伝わります。","2年後、鹿を追って山に入った坂上田村麻呂が、延鎮と出会います。«殺生をやめ、観音さまを信じなさい»。延鎮の話に心を動かされた田村麻呂は、妻とともに仏堂を建てました。これが清水寺のはじまりと伝わります。のちに田村麻呂は征夷大将軍として東北へ向かい、蝦夷のリーダー・阿弖流為（アテルイ）と戦いました。","清水寺は何度も火事で焼けました。いまの本堂は1633年、3代将軍・徳川家光の寄進で建て直されたものです。本堂の前にせり出した «舞台» は、長さ十数メートルのケヤキの柱で支えられ、組み合わせの工夫でくぎを使わずに組まれています。«懸造（かけづくり）» と呼ばれる建て方です。","«清水の舞台から飛び降りる» ということわざを知っていますか? 思い切って大きな決断をすることのたとえです。江戸時代には、願いをかなえるため実際に飛ぶ人がいたと寺の記録に残り、明治時代に禁止されました。舞台の高さは約13m、ビルの4階ほどです。","舞台の下には、寺の名のもとになった «音羽の滝» が三筋に分かれて流れています。いまは修学旅行生や世界中の観光客でにぎわう清水寺ですが、千年以上、人々がここで祈りをささげてきたことに変わりはありません。"],"tl":[["778年","延鎮が音羽の滝のほとりで修行を始めたと伝わる"],["780年ごろ","坂上田村麻呂が仏堂を建てたと伝わる"],["802年","阿弖流為が田村麻呂に降伏"],["1633年","徳川家光の寄進で本堂が再建される"],["1994年","世界遺産に登録"],["1994年","境内に «阿弖流為・母禮之碑» が建立される"],["2020年","本堂の屋根のふき替えなど平成・令和の大修理が完了"]],"who":[["延鎮（賢心）","清水寺を開いたと伝わる僧"],["坂上田村麻呂","征夷大将軍。清水寺の建立に関わったと伝わる"],["阿弖流為（アテルイ）","蝦夷のリーダー。境内に慰霊碑がある"],["徳川家光","現在の本堂を寄進した3代将軍"]],"deep":["本堂の本尊は十一面千手観音で、ふだんは見られない秘仏です。33年に一度などの機会に公開されてきました。","舞台の床下を支える柱の組み方 «地獄止め» は、柱と貫（ぬき）を組み合わせてくぎなしで固定するしくみです。雨にぬれても腐りにくいよう、舞台の床板はわずかに傾いているとされます。","寺の «成就院日記» などには、江戸時代に舞台から飛び降りた人の記録が残るとされます。明治時代の1872年に京都府が禁止しました。","清水寺はもと法相宗の寺で、1965年に «北法相宗» として独立しました。毎年12月、その年の世相を表す «今年の漢字» がここで発表され、貫主が大きな紙に書き上げます。","境内の «阿弖流為・母禮之碑» は、田村麻呂と戦い処刑された二人をしのんで、東北の人々などの手で建てられました。敵味方をこえて祈る場所です。"],"look":["清水の舞台と本堂","音羽の滝","仁王門と三重塔","奥の院から見る舞台の全景","阿弖流為・母禮之碑"],"q":["清水の舞台のような、崖に柱を立ててせり出させる建て方を何という？","«懸造（かけづくり）»。くぎを使わず柱と貫で組んでいます。"],"koji":[{"w":"清水の舞台から飛び降りる","m":"思い切って大きな決断をすること"}],"myth":"延鎮や坂上田村麻呂による創建の話は寺の縁起（伝承）です。","img":["坂上田村麻呂","阿弖流為","懸造","今年の漢字"],"wp":"清水寺","rel":{"ev":[],"grave":[]}},{"id":"26_fushimijo","n":"伏見城（秀吉終焉の城）","yomi":"ふしみじょう","cat":"城","rank":"S","y":1592,"era":["azuchi","edo"],"sh":"","ad":"京都市伏見区桃山町（伏見桃山城運動公園ほか）","st":"近鉄・京阪「丹波橋」駅から歩いて約20分／JR奈良線「桃山」駅から歩いて約20分","la":34.9404,"lo":135.7822,"hook":"天下人・豊臣秀吉が最期の息をひきとった城。地震で崩れ、戦で焼け、最後は «桃の山» になった。","lead":"伏見城は、豊臣秀吉が晩年に築いた城です。1598年、秀吉はここで亡くなりました。その後は徳川家康の城となり、やがて取りこわされます。城の中心部はいま明治天皇陵などになって立ち入れず、見られる天守は昭和につくられた «模擬天守» です。","story":["関白の位をおいの秀次にゆずった秀吉は、1592年、宇治川を見下ろす伏見の «指月（しげつ）» の丘に隠居の屋敷をつくりはじめました。ところが屋敷はどんどん大きくなり、やがて本格的な城になります。伏見は、京都と大坂を結ぶ水の道の要でした。","1596年閏7月、大地震が京都を襲います。完成間もない指月の伏見城は天守が崩れ、多くの人が亡くなりました。秀吉はすぐに、北東の木幡山（こはたやま）に城を建て直させます。«ただちに城を建てよ»。この再建の早さに、天下人の力が表れています。","1598年8月18日、秀吉は伏見城で62年の生涯を閉じました。まだ幼い息子・秀頼を、五大老・五奉行にくりかえし頼んだといいます。辞世の句として «露と落ち 露と消えにし 我が身かな 浪速のことは 夢のまた夢» が伝わります。","2年後の1600年、関ヶ原の戦いの直前。家康が東へ向かったあと、伏見城には家康の家臣・鳥居元忠が残りました。石田三成方の大軍に囲まれても降伏せず、城は落ちて元忠は討ち死にします。このときの血のついた床板が、京都のいくつかの寺の天井に «血天井» として残っていると伝わります。","家康は城を建て直し、1603年にはここで将軍の宣下を受けました。しかし江戸幕府の基礎が固まると城は不要になり、1620年代に取りこわされます。建物は各地の寺や城に移されたと伝わり、跡地には桃の木が植えられて «桃山» と呼ばれるようになりました。«安土桃山時代» の «桃山» は、ここから来ています。"],"tl":[["1592年","秀吉が指月に隠居屋敷の造営を始める"],["1596年","慶長伏見地震で指月の城が倒壊"],["1597年","木幡山に城を再建"],["1598年","秀吉が伏見城で死去"],["1600年","鳥居元忠が籠城し、伏見城が落城"],["1603年","家康が伏見城で将軍宣下を受ける"],["1620年代","廃城となる"],["1912年","城跡に明治天皇の伏見桃山陵が営まれる"],["1964年","模擬天守（伏見桃山城）が建てられる"]],"who":[["豊臣秀吉","伏見城を築き、ここで亡くなった"],["鳥居元忠","家康の家臣。関ヶ原前夜に伏見城で討ち死に"],["徳川家康","城を再建し、将軍宣下を受けた"],["石田三成","伏見城を攻めた西軍の中心人物"]],"deep":["伏見城は、指月城（第1期）・木幡山城（第2期・豊臣期）・家康の再建城（第3期）と、同じ «伏見城» の名で複数の城があったと整理されます。2015年には指月の城のものとみられる石垣が発掘されました。","城の中心部（本丸など）は明治天皇陵・昭憲皇太后陵の区域で、宮内庁の管理地として立入禁止です。模擬天守は遊園地の施設として1964年に建てられ、いまは外から見学するのみです。","«血天井» は養源院・宝泉院・源光庵など京都の複数の寺に伝わります。伏見城の床板を供養のため天井にしたと伝わりますが、伝承の部分もあります。","伏見城の遺構と伝わる建物は、御香宮神社表門のほか、各地の寺社にあります。ただ «伏見城から移した» という話には確かめられないものも多く、慎重な検討が必要です。","秀吉の辞世の句は多くの本で紹介されますが、本人の作かどうかには議論もあります。"],"look":["伏見桃山城運動公園の模擬天守（外観）","明治天皇伏見桃山陵の参道と石段（陵への参拝は可能）","周辺の大名屋敷の名残の地名（毛利長門・筒井伊賀など）","御香宮神社の表門（伏見城大手門と伝わる）"],"q":["伏見城の跡が桃の木の山になったことから生まれた時代の名前は？","«安土桃山時代» の «桃山»。伏見城跡の «桃山» からきています。"],"koji":[{"w":"夢のまた夢","m":"はかないこと、とても実現しそうにないことのたとえ。秀吉の辞世と伝わる句から"}],"myth":"血天井、各地の «伏見城遺構»、秀吉の辞世には伝承・諸説を含みます。","img":["豊臣秀吉","鳥居元忠","伏見桃山陵","慶長伏見地震"],"wp":"伏見城","rel":{"ev":[],"grave":[]}},{"id":"26_shimogamo","n":"賀茂御祖神社（下鴨神社・糺の森）","yomi":"かもみおやじんじゃ（しもがもじんじゃ）・ただすのもり","cat":"寺社","rank":"A","y":794,"era":["heian","kamakura"],"sh":"国宝（東本殿・西本殿）・国指定史跡（糺の森を含む境内）・世界遺産","ad":"京都市左京区下鴨泉川町","st":"京阪「出町柳」駅から歩いて約10分／市バス「下鴨神社前」からすぐ","la":35.0389,"lo":135.7728,"hook":"都の真ん中に残る原生の森。『方丈記』の鴨長明は、この神社の神職の家に生まれた。","lead":"下鴨神社は、賀茂川と高野川が合わさる三角地帯にある神社です。参道をつつむ «糺の森» は、平安京ができる前からの植物が残るといわれる森で、国の史跡です。上賀茂神社とともに葵祭を行います。","story":["京都の町を北から流れてくる賀茂川と高野川。二つの川が出会ってひとつの鴨川になる場所に、こんもりとした森があります。«糺（ただす）の森»。夏でもひんやりとして、ケヤキやエノキの大木が空をおおいます。この森の奥に、下鴨神社はあります。","まつられているのは、賀茂建角身命（かもたけつぬみのみこと）と、その娘・玉依媛命（たまよりひめのみこと）。玉依媛命は、上賀茂神社の神・賀茂別雷大神の母です。つまり二つの神社は «親子・祖父» の関係。«賀茂御祖（みおや）神社» という正式名には、«上賀茂の神の祖先をまつる» という意味がこめられています。","平安時代の終わり、この神社の神職の家に一人の男の子が生まれました。鴨長明です。父は下鴨神社の摂社・河合社の禰宜（ねぎ）でした。長明も同じ道を望みましたが、その願いはかないませんでした。«なぜ自分ではないのか»。失意の長明は出家し、やがて日野の山奥の小さな庵で暮らしはじめます。","そこで書かれたのが『方丈記』です。«ゆく河の流れは絶えずして、しかももとの水にあらず»。大火事、竜巻、飢饉、地震。都をおそった災害を見つめた長明は、この世の «うつろいやすさ» をつづりました。長明が暮らした方丈（約3m四方）の庵は、河合神社の境内に復元されています。","下鴨神社の社殿は、上賀茂神社と同じく定期的に建て替えられてきました。いまの東本殿・西本殿は1863年のもので、国宝です。夏の土用の «御手洗祭（みたらしまつり）» では、足を池の水にひたして無病息災を祈ります。«みたらし団子» の名前は、この祭りや御手洗池の泡に由来するともいわれます。"],"tl":[["古代","賀茂氏が祖神をまつる"],["794年","平安遷都。都の守り神として朝廷に重んじられる"],["1155年ごろ","鴨長明が生まれる"],["1212年","鴨長明『方丈記』成立"],["1863年","現在の東本殿・西本殿が造営される"],["1983年","糺の森を含む境内が国の史跡に"],["1994年","世界遺産に登録"]],"who":[["賀茂建角身命","祭神。賀茂氏の祖とされる"],["玉依媛命","祭神。上賀茂神社の神の母"],["鴨長明","下鴨神社の神職の家に生まれた随筆家。『方丈記』の作者"]],"deep":["糺の森の面積は約12万㎡。発掘調査で、縄文時代から人が暮らした跡や平安時代の流路が見つかっています。«糺» の名の由来は «ただす（正す）» «只洲（ただす）» など諸説あります。","本殿の «流造» は上賀茂神社と同じ形式で、東西に同じ形の本殿が二つ並びます。東本殿に玉依媛命、西本殿に賀茂建角身命がまつられています。","境内の «相生社» のそばにある «連理の賢木（さかき）» は、二本の木が途中で一つに結ばれた神木で、縁結びの象徴とされます。","『方丈記』の成立は1212年とされ、日本三大随筆の一つです。記録された «安元の大火»«治承の辻風»«養和の飢饉»«元暦の地震» は、当時の災害史の史料としても読まれています。","長明が禰宜になれなかったいきさつは、『源家長日記』などに記されるものの、細かい事情には諸説あります。"],"look":["糺の森の参道と小川（瀬見の小川など）","楼門と舞殿","河合神社と方丈の庵の復元","御手洗池と井上社","相生社の連理の賢木"],"q":["鴨長明が書いた、«ゆく河の流れは絶えずして» で始まる随筆は？","『方丈記』。長明が暮らした方丈の庵が河合神社に復元されています。"],"koji":[{"w":"ゆく河の流れは絶えずして、しかももとの水にあらず","m":"世の中のものは形を保っているように見えても、たえず移り変わっている、ということ"}],"myth":"«糺» の名の由来、みたらし団子の由来は諸説です。","img":["糺の森","鴨長明","方丈記","葵祭"],"wp":"賀茂御祖神社","rel":{"ev":[],"grave":[]}},{"id":"26_ryoanji","n":"龍安寺（石庭）","yomi":"りょうあんじ","cat":"寺社","rank":"A","y":1450,"era":["muromachi","edo"],"sh":"国指定史跡・特別名勝（龍安寺方丈庭園）・世界遺産","ad":"京都市右京区龍安寺御陵下町","st":"京福電鉄北野線「龍安寺」駅から歩いて約7分／市バス「竜安寺前」からすぐ","la":35.0345,"lo":135.7182,"hook":"石は15個。なのに、どこから見ても14個しか見えない。作者も意味もわからない、世界一有名な «なぞの庭»。","lead":"龍安寺は、室町幕府の管領・細川勝元がひらいた禅寺です。方丈の前の石庭は、白い砂に15個の石を置いただけの «枯山水»。だれが、何を表そうとしてつくったのか、いまもわかっていません。","story":["1450年、室町幕府の重臣・細川勝元は、貴族の徳大寺家の山荘をゆずり受け、禅寺を建てました。これが龍安寺です。のちに勝元は応仁の乱で東軍の大将となり、寺は戦火で焼けてしまいます。勝元の子・政元が寺を立て直しました。","方丈の前に広がる石庭は、東西約25m、南北約10m。白い砂をほうきで筋目をつけ、大小15個の石を5つのまとまりに分けて置いています。木も水もありません。ところが、縁側のどこに座っても、石はいつも14個しか見えないのです。«なぜ全部見えないの?»。15は «完全» を表す数で、それが見えないことに意味がある、と語られることもあります。","では、この庭は何を表しているのでしょう。«虎の子渡し»、«大海に浮かぶ島々»、«雲の上に出た山の頂»…。答えはどこにも書かれていません。見る人がそれぞれ考えるための庭だ、と言う人もいます。","作った人もわかりません。石の一つには «小太郎» «□二郎（清二郎とも）» という名前が刻まれていて、庭づくりにたずさわった人たちの名前と考えられています。いまの形になったのは、江戸時代の火事で方丈が焼け、別の寺から移したあとだという説もあります。","1975年、イギリスのエリザベス女王が龍安寺を訪れ、石庭をたたえたことが世界に報じられ、«ロック・ガーデン» として一気に有名になりました。方丈の裏には «吾唯足知（われ、ただ足るを知る）» と読める «つくばい» があり、中央の四角い水穴を «口» の字として使った、ことば遊びのデザインになっています。"],"tl":[["1450年","細川勝元が龍安寺を創建"],["1467年","応仁の乱が始まり、のちに寺は焼失"],["1488年","細川政元が再興"],["1797年","火災で方丈などが焼け、塔頭西源院の方丈を移築"],["1975年","エリザベス女王が訪れる"],["1994年","世界遺産に登録"]],"who":[["細川勝元","龍安寺を開いた管領。応仁の乱の東軍大将"],["細川政元","勝元の子。寺を再興した"],["義天玄承","龍安寺の開山とされる禅僧"],["エリザベス2世","1975年に訪れた英国女王"]],"deep":["石庭の石は、東から «5・2・3・2・3» の5群に分けて置かれています。«七五三の庭»（7・5・3と数える見方）ともいわれますが、数え方は一つではありません。","庭の土塀は、菜種油を練りこんだ土でつくられたといわれ、年月とともに油がしみ出して独特の模様が浮かんでいます。塀は奥へ行くほど低くなっていて、庭を実際より広く見せる工夫とする説があります。","石庭がいつ、だれの手でいまの形になったかは、室町時代説・江戸時代説があり決着していません。相阿弥の作とする古い説明もありますが、根拠は弱いとされます。","«吾唯足知» のつくばいは、水戸光圀が寄進したと伝わるもので、見学できるものは複製とされます。","境内の大きな «鏡容池（きょうようち）» は、徳大寺家の山荘時代からの池と伝わり、石庭とは対照的な回遊式の庭を楽しめます。"],"look":["方丈前の石庭（縁側からいろいろな位置で数えてみる）","油土塀","蹲踞（吾唯足知）","鏡容池","方丈のふすま絵"],"q":["龍安寺の石庭に置かれた石は全部で何個？","15個。ただし一度に全部を見ることはできないといわれます。"],"koji":[{"w":"吾唯足知（われただたるをしる）","m":"自分がすでに持っているもので満足することを知る、という禅のことば"}],"myth":"石庭の作者・作庭時期・意味は不明で諸説あります。つくばいの由来も伝承です。","img":["枯山水","細川勝元","つくばい","応仁の乱"],"wp":"龍安寺","rel":{"ev":["higashiyama"],"grave":[]}},{"id":"26_nishihonganji","n":"西本願寺（本願寺）","yomi":"にしほんがんじ（ほんがんじ）","cat":"寺社","rank":"A","y":1591,"era":["azuchi","edo"],"sh":"国宝（御影堂・阿弥陀堂・唐門・飛雲閣・書院ほか）・世界遺産","ad":"京都市下京区堀川通花屋町下ル本願寺門前町","st":"JR京都駅から歩いて約15分／市バス「西本願寺前」からすぐ","la":34.9918,"lo":135.7514,"hook":"織田信長と10年戦いぬいた教団が、豊臣秀吉からもらった土地。巨大な御影堂は、たたみ441畳の広さ。","lead":"西本願寺は、浄土真宗本願寺派の本山です。親鸞の教えを受けつぎ、戦国時代には信長と戦った «本願寺» が、1591年に秀吉から土地を寄進されてこの地に移りました。のちに本願寺は東と西に分かれます。","story":["鎌倉時代、親鸞は «阿弥陀仏を信じ、念仏をとなえればだれでも救われる» と説きました。親鸞が亡くなったあと、娘の覚信尼が京都・東山の大谷に墓所のお堂を建てます。これが本願寺のはじまりです。やがて室町時代、蓮如が教えを広め、本願寺は全国に信者をもつ大きな教団になりました。","戦国時代、本願寺は大坂の «石山» に本拠をおいていました。天下統一を進める織田信長は、そこを明けわたすよう求めます。1570年、本願寺の顕如は «仏法を守れ» と全国の門徒に呼びかけ、戦いが始まりました。石山合戦です。10年におよぶ戦いのすえ、1580年に顕如は石山を退きます。","信長が亡くなったあと、豊臣秀吉は本願寺と手を結び、1591年、京都の堀川六条に広い土地をあたえました。本願寺はここに新しい伽藍を建てます。ところが、顕如の死後、あとつぎをめぐって長男の教如と三男の准如の間で対立が起こりました。","1602年、徳川家康は教如に土地を寄進し、少し東に新しい寺を建てさせます。こうして «西本願寺» と «東本願寺» が並び立つことになりました。«なぜ家康は分けたのか?»。巨大な教団の力を弱めるためだった、という説が有名ですが、教団の中の対立を利用しただけだという見方もあります。","いまの御影堂は1636年、阿弥陀堂は1760年に建てられた大建築で、どちらも国宝です。幕末には新選組が一時この境内を屯所にしており、太鼓楼のあたりがその名残の場所として知られています。"],"tl":[["1272年","覚信尼が東山大谷に親鸞の廟堂を建てる"],["1570年","石山合戦が始まる"],["1580年","顕如が石山本願寺を退去"],["1591年","秀吉の寄進で堀川六条に移る"],["1602年","家康が教如に土地を与え、東西に分立"],["1636年","御影堂が完成"],["1760年","阿弥陀堂が完成"],["1865年","新選組が境内に屯所を置く"],["1994年","世界遺産に登録"]],"who":[["親鸞","浄土真宗の宗祖。御影堂に像がまつられる"],["蓮如","室町時代に本願寺を大きく発展させた"],["顕如","石山合戦で信長と戦った本願寺の宗主"],["准如","西本願寺を継いだ顕如の三男"],["豊臣秀吉","本願寺に現在の地を寄進"]],"deep":["御影堂は東西約48m・南北約62m・高さ約29mの巨大な木造建築で、内部の畳は441畳といわれます。","唐門は «日暮門» とも呼ばれ、一日じゅう見ていても飽きないほど彫刻が豪華だという意味です。伏見城の遺構と伝わりますが、確証はありません。","飛雲閣は金閣・銀閣とならぶ «京の三名閣» の一つとされ、聚楽第の遺構と伝わります（これも諸説）。ふだんは非公開です。","北能舞台は、現存する最古の能舞台とされ国宝です。書院（対面所・白書院）とともに、ふだんは非公開で特別公開のときに見られます。","新選組の屯所だった時期、境内で大砲の訓練などを行い寺が困っていたという話も伝わります。新選組はのちに不動堂村へ移りました。"],"look":["御影堂と阿弥陀堂（自由に参拝できる）","唐門（日暮門）","大イチョウ（«水ふきイチョウ» の伝承）","太鼓楼（新選組屯所のゆかり）","龍谷ミュージアム（向かい側）"],"q":["一日じゅう見ていても見飽きないほど豪華だといわれる、西本願寺の門の別名は？","«日暮門»。正式には唐門で、国宝です。"],"koji":[],"myth":"唐門・飛雲閣の伏見城・聚楽第遺構説、東西分立の理由は諸説です。","img":["親鸞","顕如","石山合戦","東本願寺"],"wp":"西本願寺","rel":{"ev":["jodo"],"grave":[]}},{"id":"26_daigoji","n":"醍醐寺（醍醐の花見）","yomi":"だいごじ","cat":"寺社","rank":"A","y":874,"era":["heian","azuchi"],"sh":"国宝（五重塔・金堂・三宝院表書院ほか）・国指定特別史跡・特別名勝（三宝院庭園）・世界遺産","ad":"京都市伏見区醍醐東大路町","st":"地下鉄東西線「醍醐」駅から歩いて約15分","la":34.951,"lo":135.8196,"hook":"死の5か月前、秀吉は700本の桜の下で一世一代の宴を開いた。京都最古の木造建築、五重塔が見守る寺。","lead":"醍醐寺は、平安時代のはじめに僧・聖宝が山の上に開いた真言宗の寺です。京都府でいちばん古い木造建築の五重塔があります。1598年には、豊臣秀吉がここで盛大な «醍醐の花見» を開きました。","story":["874年、修行僧の聖宝（しょうぼう）は、笠取山の頂にわく清らかな水を見つけました。水をすくって飲んだ一人の老人が «ああ、醍醐味だ» と言って姿を消した、という伝説が残ります。«醍醐» とは、牛乳から作る最上の味のこと。こうしてこの地に寺がひらかれ、«醍醐寺» と名づけられたと伝わります。","聖宝は醍醐天皇にあつく信頼され、寺は天皇の祈りの寺として大きくなりました。山の上の «上醍醐»、ふもとの «下醍醐» に建物が広がります。951年に完成した五重塔は、応仁の乱の戦火をくぐりぬけ、京都府に残るいちばん古い木造建築になりました。","戦国時代、醍醐寺は荒れはてていました。立て直しを願った座主の義演は、天下人・豊臣秀吉とつながりを持ちます。秀吉は寺の再興を約束し、そして1598年3月15日、ここで大きな花見を開くと決めました。","その日のため、秀吉は近くの国から桜の木を700本も植えさせたと伝わります。花見に集まったのは、秀吉の妻・北政所（ねね）や淀殿、息子の秀頼をはじめ、女性たちを中心に約1300人。女性たちは一日に二度着がえたとも伝わり、境内には茶屋が並びました。«なんと見事な桜じゃ»。秀吉の笑顔が目にうかぶようです。","けれど、秀吉はその5か月後、伏見城で亡くなりました。醍醐の花見は、天下人の最後の大きな楽しみになったのです。秀吉が設計にかかわったといわれる三宝院の庭園は、秀頼の時代に完成しました。いまも毎年4月には «豊太閤花見行列» が行われ、当時の華やかさをしのんでいます。"],"tl":[["874年","聖宝が上醍醐に草庵を結んだと伝わる"],["907年","醍醐天皇の勅願寺となる"],["951年","五重塔が完成"],["応仁の乱のころ","下醍醐の多くの建物が焼失（五重塔は残る）"],["1598年3月","豊臣秀吉が «醍醐の花見» を開く"],["1598年8月","秀吉死去"],["1600年","金堂が紀伊から移築され再建"],["1994年","世界遺産に登録"]],"who":[["聖宝（理源大師）","醍醐寺を開いた僧"],["醍醐天皇","寺を勅願寺とした天皇"],["豊臣秀吉","醍醐の花見を開き、寺の再興を進めた"],["義演","秀吉の支援で寺を立て直した座主。日記を残した"],["北政所・淀殿","花見に加わった秀吉の妻たち"]],"deep":["五重塔の初層内部には、両界曼荼羅や真言八祖を描いた壁画が残り、平安時代の絵画として別に国宝に指定されています。","金堂は、秀吉の命で紀伊国湯浅の満願寺から移されたと伝わり、平安時代後期の建物を基礎に桃山時代に再建された姿です。","三宝院の庭にある «藤戸石» は «天下の名石» と呼ばれ、足利将軍家から信長・秀吉へと受けつがれ、聚楽第からここへ運ばれたと伝わります。","座主・義演の日記『義演准后日記』は、花見の準備や当時の社会を知る第一級の史料です。花見の人数や桜の本数の数字は、この種の記録や後世の書物によります。","上醍醐へは、下醍醐から山道を歩いて約1時間。准胝堂・薬師堂（国宝）・清瀧宮拝殿（国宝）など、開山のころの信仰の場が山上に残っています。"],"look":["五重塔（京都府最古の木造建築）","金堂と伽藍の参道","三宝院の庭園と表書院","霊宝館のしだれ桜と寺宝","上醍醐（健脚向け）"],"q":["豊臣秀吉が醍醐の花見を開いたのは何年？","1598年。秀吉はその年の8月に亡くなりました。"],"koji":[{"w":"醍醐味","m":"物事の本当のおもしろさ。もとは乳から作る最上の味のことで、寺名の伝説にも登場する"}],"myth":"寺名の由来の老人の話、花見の桜700本・人数約1300人、藤戸石の来歴は伝承・記録による数字です。","img":["醍醐の花見","聖宝","三宝院","藤戸石"],"wp":"醍醐寺","rel":{"ev":["daigo"],"grave":[]}},{"id":"26_kitano","n":"北野天満宮（北野大茶湯）","yomi":"きたのてんまんぐう","cat":"寺社","rank":"A","y":947,"era":["heian","azuchi"],"sh":"国宝（本殿・石の間・拝殿・楽の間）・国指定史跡（御土居）","ad":"京都市上京区馬喰町","st":"市バス「北野天満宮前」からすぐ／京福北野線「北野白梅町」駅から歩いて約5分","la":35.0312,"lo":135.7353,"hook":"怨霊として恐れられた男は、学問の神さまになった。そしてこの境内で、秀吉は «誰でも来い» の大茶会を開いた。","lead":"北野天満宮は、菅原道真をまつる神社で、全国の天満宮・天神社の総本社の一つです。1587年には豊臣秀吉が境内で «北野大茶湯» を開きました。境内には秀吉がきずいた «御土居» の跡も残っています。","story":["菅原道真は、平安時代の学者で政治家でした。右大臣にまで出世しましたが、901年、藤原時平らの計略で九州の大宰府に左遷され、2年後にその地で亡くなります。都を出るとき、庭の梅に向けて «東風吹かば にほひおこせよ 梅の花 あるじなしとて 春な忘れそ» とよんだと伝わります。","道真が亡くなったあと、都ではおそろしいことが続きました。時平が若くして亡くなり、930年には天皇のいる清涼殿に雷が落ちて、多くの貴族がけがをしたり亡くなったりしました。«これは道真の怨霊のしわざだ»。人々は震え上がり、道真を神としてまつり、その怒りをしずめようとしました。","947年、道真をまつる社殿が北野の地に建てられます。やがて道真は、怨霊から «天神さま» へ、そして学問・和歌の神さまへと姿を変えていきました。いまでは受験の季節になると、合格を願う人たちで境内がいっぱいになります。","1587年10月1日、この境内で、天下人・豊臣秀吉が大きな茶会を開きました。«北野大茶湯» です。«茶の湯が好きな者なら、身分に関係なく、茶碗一つ持って来ればよい» というおふれが出され、千利休ら茶人も腕をふるいました。10日間の予定でしたが、実際には1日で終わってしまいます。なぜ? 九州で一揆が起きたから、などの説がありますが、はっきりしません。","秀吉はまた、京都の町を囲む土の壁 «御土居» を築きました。その一部が北野天満宮の西側にいまも残り、秋には «もみじ苑» として公開されます。本殿は1607年に豊臣秀頼が建てたもので、国宝。梅のころには約1500本の梅が咲きほこります。"],"tl":[["901年","菅原道真が大宰府に左遷される"],["903年","道真が大宰府で死去"],["930年","清涼殿に落雷。道真の怨霊と恐れられる"],["947年","北野に社殿が建てられる"],["1587年","豊臣秀吉が北野大茶湯を開く"],["1591年","秀吉が御土居を築く"],["1607年","豊臣秀頼が現在の本殿などを造営"]],"who":[["菅原道真","祭神。学問の神さま"],["藤原時平","道真を左遷に追いこんだとされる左大臣"],["豊臣秀吉","北野大茶湯を開き、御土居を築いた"],["千利休","北野大茶湯を取り仕切った茶人の一人"],["豊臣秀頼","現在の本殿を造営した"]],"deep":["本殿と拝殿を «石の間» でつなぐ «八棟造（権現造）» は、日光東照宮など後の霊廟建築の原型の一つとされます。本殿・石の間・拝殿・楽の間が一体で国宝です。","北野大茶湯では、秀吉自慢の «黄金の茶室» が持ち込まれ公開されたと伝わります。茶席の数は800を超えたともいわれますが、数字には幅があります。","御土居は1591年に秀吉が築いた、京都を囲む全長約22.5kmの土塁と堀です。北野天満宮の西側に残る部分は国の史跡 «御土居» の一部として指定されています。","境内には牛の像がたくさんあります。道真が丑年生まれだった、遺体を運ぶ牛が動かなくなった場所に墓を建てた、など理由には諸説があります。","毎月25日の «天神さん» の縁日は、道真の誕生日と命日がどちらも25日と伝わることにちなみます。東寺の «弘法さん» とならぶ京都の二大縁日です。"],"look":["三光門（中門）","本殿・拝殿（国宝）","御土居（もみじ苑、季節公開）","梅苑（2〜3月）","境内の撫で牛"],"q":["豊臣秀吉が1587年に北野天満宮で開いた大茶会の名前は？","«北野大茶湯»。身分を問わず参加できるとされました。"],"koji":[{"w":"東風吹かば にほひおこせよ 梅の花","m":"道真が都を去るときによんだと伝わる歌。主人がいなくても春を忘れずに咲いてほしい、という思い"}],"myth":"道真の怨霊の話、大茶湯が1日で終わった理由、牛との関係は伝承・諸説です。","img":["菅原道真","北野大茶湯","御土居","千利休"],"wp":"北野天満宮","rel":{"ev":["rikyu"],"grave":[]}},{"id":"26_hokoji","n":"方広寺（大仏と鐘銘事件）","yomi":"ほうこうじ","cat":"寺社","rank":"A","y":1595,"era":["azuchi","edo"],"sh":"国指定史跡（方広寺大仏殿跡及び石塁・石塔）・国の重要文化財（梵鐘）","ad":"京都市東山区大和大路通正面茶屋町","st":"京阪「七条」駅から歩いて約10分／市バス「博物館三十三間堂前」から歩いて約5分","la":34.99,"lo":135.7712,"hook":"«国家安康»——鐘に刻まれたたった4文字が、豊臣家を滅ぼす戦いの引き金になった。","lead":"方広寺は、豊臣秀吉が奈良の大仏より大きな大仏をつくろうとして建てた寺です。大仏は地震や火事で何度も失われ、いまは残っていません。秀頼がつくった鐘の文字を徳川家康が問題にしたことが、大坂の陣のきっかけになりました。","story":["天下統一を進める豊臣秀吉は、京都に «奈良をしのぐ大仏» をつくると決めました。1588年に出した刀狩令では、«集めた刀は大仏づくりのくぎなどに使う。そうすれば百姓はこの世でもあの世でも救われる» と説いています。人々から武器を取り上げる理由にも、大仏が使われたのです。","1595年ごろ、高さ約19mともいわれる木造の大仏と、巨大な大仏殿がほぼ完成しました。ところが翌1596年、大地震が京都をおそい、大仏は壊れてしまいます。«自分の身も守れない仏か» と秀吉が怒ったという話も伝わります。秀吉は信濃の善光寺から如来像を迎えるなどしましたが、1598年に亡くなりました。","父の遺志をつぎ、秀頼は金属製の大仏の再建に取りかかります。途中の火事で一度焼けてしまいますが、1612年ごろに大仏が完成し、1614年には大きな鐘も鋳造されました。そして、その鐘の銘文が問題になったのです。","銘文には «国家安康» «君臣豊楽» という句がありました。家康の側は «家康の名を «家» と «康» に切り分けて呪い、豊臣を君として栄えさせようとしている» と言いたてます。豊臣方は «そんなつもりはない» と弁明しましたが、話はこじれ、その年の冬、大坂冬の陣が始まりました。翌年の夏の陣で豊臣家は滅びます。«言いがかり» だったのか、それとも本当に問題のある文だったのか。いまも議論は続いています。","大仏はその後も地震と落雷で失われ、江戸時代後期に建てられた上半身だけの像も、1973年の火事で焼けました。いまは問題の鐘と、豊国神社のまわりに残る巨大な石垣、大仏殿の跡地の公園が、秀吉の夢の大きさを伝えています。"],"tl":[["1586年","秀吉が大仏造立を始める"],["1588年","刀狩令。刀を大仏の材料にすると説く"],["1595年","大仏と大仏殿がほぼ完成し、千僧供養が行われる"],["1596年","慶長伏見地震で大仏が損壊"],["1612年","秀頼による大仏・大仏殿が完成"],["1614年","梵鐘の銘文が問題となり、大坂冬の陣へ"],["1798年","落雷で大仏殿・大仏が焼失"],["1973年","江戸後期に造られた半身の大仏が火災で焼失"]],"who":[["豊臣秀吉","大仏と方広寺をつくった天下人"],["豊臣秀頼","大仏を再建し、梵鐘を鋳造させた"],["徳川家康","鐘銘を問題にした"],["文英清韓","鐘の銘文を書いた僧"],["片桐且元","豊臣家の家臣。鐘銘事件の交渉役"]],"deep":["梵鐘は高さ約4.2m、重さ約82tとされ、国の重要文化財です。銘文の «国家安康»«君臣豊楽» の部分は白く囲まれて示されており、いまも実物を見ることができます。","銘文を書いた清韓は、家康の名を句に入れたのは «かくし題» の技法で、祝う意図だったと説明したとされます。名前を分けて書くことを失礼と見る習慣が当時あったかについても議論があります。","大仏殿跡は発掘調査で基壇や須弥壇の位置が確認され、2000年代に国の史跡範囲が広げられました。跡地は «大仏殿跡緑地» として整備されています。","豊国神社の西側に残る石垣は、大仏殿の境内を囲んだ «石塁» で、ひとつひとつの石の大きさに圧倒されます。","近くの «耳塚» は、朝鮮出兵のとき持ち帰られた人々の耳や鼻を供養したと伝わる塚です。戦争の犠牲者を悼む場所として訪れたいところです。"],"look":["鐘楼の梵鐘と «国家安康» の銘文","豊国神社の周りの大仏殿の石塁","大仏殿跡緑地","耳塚","近くの三十三間堂・京都国立博物館"],"q":["方広寺の鐘の銘文で、家康の名を分けたと問題にされた4文字は？","«国家安康»。«君臣豊楽» とあわせて問題にされました。"],"koji":[],"myth":"秀吉が大仏に怒った話は伝承。鐘銘事件が家康の «言いがかり» だったかどうかは諸説あります。","img":["方広寺鐘銘事件","京の大仏","大坂の陣","耳塚"],"wp":"方広寺","rel":{"ev":["kenchi"],"grave":[]}},{"id":"26_chionin","n":"知恩院（法然の御廟）","yomi":"ちおんいん","cat":"寺社","rank":"A","y":1212,"era":["kamakura","edo"],"sh":"国宝（三門・御影堂）","ad":"京都市東山区林下町","st":"地下鉄東西線「東山」駅から歩いて約8分／京阪「祇園四条」駅から歩いて約15分","la":35.0053,"lo":135.7832,"hook":"«ただ念仏をとなえればいい»。法然の教えが広まった場所に、大みそかには17人で突く巨大な鐘が響く。","lead":"知恩院は、浄土宗を開いた法然が念仏の教えを広め、亡くなった場所に建つ浄土宗の総本山です。江戸時代には徳川家の厚い保護を受け、日本最大級の木造の門 «三門» や大きな御影堂が建てられました。","story":["平安時代の終わり、戦や飢饉で人々は苦しんでいました。比叡山で学んだ僧・法然は、長いあいだ考え続けた末、一つの答えにたどりつきます。«南無阿弥陀仏ととなえれば、だれでも極楽に生まれることができる»。1175年、法然は比叡山を下り、東山の吉水に庵をむすんで、この教えを説きはじめました。","むずかしい修行も、お金のかかる寄進もいらない。この教えは、武士や貴族だけでなく、町の人々にも広まりました。しかし、ほかの宗派からは強い反発を受け、法然は一時四国へ流されます。都にもどった法然は1212年、吉水の近く、いまの知恩院の場所で80歳の生涯を閉じました。","法然の墓所には、弟子たちがお堂を建てて守りました。これが知恩院のはじまりです。大きく変わったのは江戸時代。浄土宗を信仰していた徳川家康は、知恩院を大切にし、境内を大きく広げました。2代秀忠は三門を、3代家光は御影堂を建てます。","«なぜ徳川家はここまで力を入れたの?»。家康が浄土宗の信者だったことに加え、知恩院が京都の東山の高台にあり、二条城とともに徳川の力を京都に示す場所だった、とも考えられています。","三門の高さは約24m。見上げると首が痛くなるほどです。大鐘楼の鐘は高さ約3.3m、重さ約70t。大みそかには17人の僧が «えーい、ひとーつ» と声を合わせ、全身で綱を引いて鐘を突きます。その姿は、京都の年越しの名物になっています。"],"tl":[["1175年","法然が浄土宗を開き、吉水で教えを広める"],["1207年","法然が四国へ流される（建永の法難）"],["1212年","法然が死去"],["1234年","弟子の源智が堂舎を整え、知恩院の基礎を築く"],["1621年","徳川秀忠の寄進で三門が完成"],["1636年","大鐘が鋳造される"],["1639年","徳川家光の寄進で御影堂が再建"],["2019年","御影堂の平成の大修理が完了"]],"who":[["法然","浄土宗の開祖。知恩院の地で亡くなった"],["源智","法然の弟子。知恩院の基礎を整えた"],["徳川家康","知恩院を保護し、境内を拡張"],["徳川秀忠","三門を寄進"],["徳川家光","御影堂を再建"]],"deep":["三門は、現存する木造の門として日本最大級とされ、国宝です。楼上には釈迦如来や十六羅漢の像がまつられ、特別公開のときに上がることができます。","御影堂は1639年に家光が建てたもので国宝。2019年まで約9年かけた修理が行われました。","知恩院には «七不思議» と呼ばれる言い伝えがあり、御影堂の軒下に置かれた «忘れ傘» は、名工・左甚五郎が魔除けのために置いたとも、火事よけのためともいわれます。","大鐘は1636年の鋳造。除夜の鐘は1人が撞木の親綱を引き、16人が子綱を持って勢いをつける、計17人のチームで突きます。","境内の奥には法然の御廟があり、知恩院の名の由来とされる場所です。法然の時代の吉水の草庵跡とされる場所も、近くの安養寺などに伝わります。"],"look":["三門（国宝）","御影堂（国宝）","大鐘楼","法然上人御廟","方丈庭園と «七不思議»"],"q":["知恩院の除夜の鐘は、何人の僧が力を合わせて突く？","17人。親綱1人と子綱16人で突きます。"],"koji":[{"w":"南無阿弥陀仏","m":"«阿弥陀仏に身も心もおまかせします» という意味の念仏"}],"myth":"七不思議、忘れ傘の由来は伝承です。","img":["法然","浄土宗","徳川秀忠","除夜の鐘"],"wp":"知恩院","rel":{"ev":["jodo"],"grave":[["honen","法然"]]}},{"id":"26_kenninji","n":"建仁寺（栄西の禅寺）","yomi":"けんにんじ","cat":"寺社","rank":"A","y":1202,"era":["kamakura"],"sh":"国宝（風神雷神図屏風〈京都国立博物館に寄託〉）・国の重要文化財（方丈ほか）","ad":"京都市東山区大和大路通四条下ル小松町","st":"京阪「祇園四条」駅から歩いて約7分／阪急「京都河原町」駅から歩いて約10分","la":35.0003,"lo":135.7738,"hook":"禅と «お茶» を日本に広めた栄西の寺。二日酔いの将軍に、茶を差し出した話も伝わる。","lead":"建仁寺は、1202年に栄西がひらいた、京都でいちばん古い禅寺です。鎌倉幕府2代将軍・源頼家の支援で建てられました。俵屋宗達の «風神雷神図屏風» を伝える寺としても知られます。","story":["平安時代の終わり、比叡山で学んだ僧・栄西は、二度にわたって中国の宋へわたりました。そこで出会ったのが «禅»。すわって心を静め、自分の心をみつめる修行です。1191年に帰国した栄西は、禅を日本に広めようとしましたが、京都では古い寺々から反発を受けました。","栄西が頼ったのは鎌倉の武士たちでした。1202年、2代将軍・源頼家の寄進を受け、京都の鴨川の東に寺を開きます。年号から «建仁寺» と名づけられました。はじめは禅だけでなく、天台・真言の教えもあわせて学ぶ寺にしました。«なぜ?»。京都の古い寺々とぶつからないよう、工夫したのだといわれます。","栄西は、宋から茶の種を持ち帰ったとも伝わります。お茶は体によい薬だと考えた栄西は、1211年に『喫茶養生記』を書きました。『吾妻鏡』には、3代将軍・源実朝が二日酔いで苦しんでいたとき、栄西がお茶とこの本を差し出したという話が記されています。","時代がくだって、江戸時代のはじめ、絵師の俵屋宗達が描いた «風神雷神図屏風» が、この寺に伝わりました。金色の空をかけまわる、緑の風神と白い雷神。どこかユーモラスな二人の神は、のちの尾形光琳らが写し、日本美術を代表する絵になりました。","2002年、創建800年を記念して、法堂の天井に日本画家・小泉淳作による大きな «双龍図» が描かれました。見上げると二匹の龍がからみあい、いまにも動き出しそうです。祇園の花街のすぐそばにありながら、境内は静かな禅の空気につつまれています。"],"tl":[["1191年","栄西が宋から帰国"],["1202年","源頼家の寄進で建仁寺を創建"],["1211年","栄西が『喫茶養生記』を著す"],["1214年","栄西が源実朝に茶を献じたと『吾妻鏡』に記される"],["1215年","栄西死去"],["1599年","安国寺恵瓊が方丈を移築"],["2002年","創建800年を記念し法堂に «双龍図» が描かれる"]],"who":[["栄西","臨済宗を伝えた僧。建仁寺の開山"],["源頼家","鎌倉幕府2代将軍。建仁寺の開基"],["源実朝","3代将軍。栄西から茶を献じられた"],["俵屋宗達","«風神雷神図屏風» を描いた絵師"],["安国寺恵瓊","方丈を移した戦国時代の僧"]],"deep":["建仁寺は京都五山の第3位に位置づけられました。寺の名はそのころの年号 «建仁» からで、年号を寺名にするのは延暦寺などと同じ特別な扱いです。","«風神雷神図屏風» の本物は京都国立博物館に寄託されていて、寺ではデジタル技術でつくった高精細の複製を見ることができます。","方丈は1599年、安国寺恵瓊が安芸国（広島県）の安国寺から移したもので、国の重要文化財です。","栄西の読み方は «えいさい» と «ようさい» の二通りがあります。建仁寺では «ようさい» と読むことが多いとされます。","境内の «○△□乃庭» は、禅の考えで宇宙の基本の形を表したものとされ、«潮音庭» とともに方丈・書院から楽しめます。"],"look":["法堂の天井画 «双龍図»","風神雷神図屏風（複製）","方丈と大雄苑（枯山水）","潮音庭・○△□乃庭","栄西の茶にちなむ «平成の茶苑»"],"q":["栄西がお茶の効き目を書いた本の名前は？","『喫茶養生記』。«茶は養生の仙薬なり» で始まります。"],"koji":[{"w":"茶は養生の仙薬なり","m":"お茶は体を健やかに保つ特別な薬である、という栄西のことば"}],"myth":"栄西が茶の種を持ち帰った話は伝承を含みます。","img":["栄西","風神雷神図","喫茶養生記","俵屋宗達"],"wp":"建仁寺","rel":{"ev":["kuya","kiyomori","zen"],"grave":[]}},{"id":"26_rokuharamitsuji","n":"六波羅蜜寺（空也と六波羅）","yomi":"ろくはらみつじ","cat":"寺社","rank":"A","y":951,"era":["heian","kamakura"],"sh":"国宝（十一面観音立像）・国の重要文化財（本堂・空也上人立像ほか）","ad":"京都市東山区五条通大和大路上ル東","st":"京阪「清水五条」駅から歩いて約7分／市バス「清水道」から歩いて約7分","la":34.9966,"lo":135.773,"hook":"口から6体の小さな仏さまが飛び出す像。念仏を町に広めた «市の聖» と、平家の本拠地の記憶が眠る寺。","lead":"六波羅蜜寺は、951年に僧・空也が、都で流行した病気をしずめるためにひらいた寺です。のちにこのあたり «六波羅» には平家の屋敷が並び、鎌倉時代には幕府の «六波羅探題» が置かれました。","story":["951年、京の都では疫病が広がっていました。道ばたには倒れた人々。そのとき一人の僧が、自ら十一面観音の像をきざみ、車に乗せて町をまわりました。僧は «南無阿弥陀仏» ととなえながら、病人に茶をふるまったと伝わります。これが空也です。","空也は、貴族の寺ではなく、町の中で念仏を広めました。道をなおし、井戸を掘り、身寄りのない人をとむらいました。人々は親しみをこめて空也を «市聖（いちのひじり）» と呼びました。空也が開いた寺は、はじめ «西光寺» といい、のちに «六波羅蜜寺» と名を改めます。","寺の宝物館に立つ «空也上人立像» は、一度見たら忘れられません。やせた体にわらじばき、胸に鉦（かね）をかけ、口からは針金に通された6体の小さな仏さまが並んでいます。«南・無・阿・弥・陀・仏» の6文字が、声にしたとたん阿弥陀仏の姿になった、という表現です。つくったのは鎌倉時代の仏師・康勝、運慶の子です。","平安時代の終わり、このあたりには平清盛ら平家一門の屋敷が建ちならび、«六波羅» は平家の本拠地になりました。«平家にあらずんば人にあらず» といわれたほどの栄えぶり。寺には清盛の姿と伝わる像も残っています。平家が滅んだあとは、鎌倉幕府がここに «六波羅探題» を置き、朝廷や西国を見張りました。","寺はその後の戦乱でいくつもの堂を失いましたが、いまの本堂は1363年に建てられたもので、重要文化財です。正月には、空也が病人にふるまった茶にちなむ «皇服茶（おうぶくちゃ）» が授与され、1000年以上前の祈りがいまも続いています。"],"tl":[["951年","空也が十一面観音像をつくり、疫病退散を祈る"],["963年","空也が鴨川のほとりで大般若経の供養を行い、西光寺を建てたと伝わる"],["977年","中信が寺名を六波羅蜜寺と改めたと伝わる"],["平安時代末","周辺に平家一門の屋敷（六波羅殿）が建つ"],["1221年","承久の乱のあと、六波羅探題が置かれる"],["1333年","六波羅探題が足利尊氏らに攻められ滅ぶ"],["1363年","現在の本堂が建てられる"]],"who":[["空也","念仏を町に広めた «市聖»。寺の開祖"],["康勝","空也上人立像をつくった仏師。運慶の四男"],["平清盛","六波羅に屋敷を構えた平家の棟梁"],["北条泰時","承久の乱のあと初代の六波羅探題の一人となった"]],"deep":["本尊の十一面観音立像は空也の時代の作とされ、国宝です。12年に一度、辰年に開帳される秘仏です。","«平清盛坐像» は清盛の姿と伝わる像で、重要文化財。経巻を手にした僧形の姿で、«おごる平家» のイメージとは違う落ち着いた表情です。","寺には «運慶坐像» «湛慶坐像» と伝わる像もあります。運慶の像と確定できれば、日本の仏師の肖像として非常に珍しい例です（伝承を含む）。","«皇服茶» は、村上天皇が病気のときにこの茶を飲んで治ったという言い伝えから名づけられたとされます。梅干しと結び昆布を入れた茶です。","六波羅探題は、北方・南方の二人の長官がいて、どちらも北条氏の一族がつとめました。1333年に滅んだとき、北条仲時らは東国へ逃げる途中、近江で最期をとげています。"],"look":["宝物館の空也上人立像","平清盛坐像（伝）","本堂（1363年建立）","境内の «平清盛公之塚»","近くの六道珍皇寺・«六道の辻»"],"q":["空也上人立像の口から出ている6体の仏は、何を表している？","«南無阿弥陀仏» の6文字。念仏が仏の姿になったことを表しています。"],"koji":[{"w":"平家にあらずんば人にあらず","m":"平家一門でなければ人ではない、というほど平家が栄えたことを表すことば（『平家物語』より）"}],"myth":"寺名の改称年、皇服茶の由来、運慶・湛慶・清盛像の像主には伝承・諸説を含みます。","img":["空也","六波羅探題","平清盛","康勝"],"wp":"六波羅蜜寺","rel":{"ev":["kuya","kiyomori","zen"],"grave":[]}},{"id":"26_kamigoryo","n":"上御霊神社（応仁の乱 開戦の地）","yomi":"かみごりょうじんじゃ","cat":"古戦場","rank":"A","y":1467,"era":["heian","muromachi"],"sh":"","ad":"京都市上京区上御霊前通烏丸東入上御霊竪町","st":"地下鉄烏丸線「鞍馬口」駅から歩いて約3分","la":35.0366,"lo":135.7597,"hook":"11年続いた大乱は、この静かな森での小さな戦いから始まった。まつられているのは、怨霊とおそれられた人々。","lead":"上御霊神社は、非業の死をとげて «怨霊» とおそれられた人々の霊をしずめるためにまつった神社です。1467年、境内の森で畠山氏どうしが戦った «御霊合戦» が、応仁の乱の始まりとされています。","story":["平安時代、都の人々がいちばんおそれたのは «怨霊» でした。無実の罪で亡くなった人の霊が、病気や災害を起こすと信じられていたのです。長岡京の事件で亡くなった早良親王をはじめ、そうした人々の霊を «御霊» としてまつり、心をしずめようとしました。上御霊神社は、その «御霊信仰» の中心の一つです。","時代はくだって室町時代。将軍の力が弱まり、有力な大名たちが対立していました。管領の家柄・畠山家では、畠山政長と畠山義就のいとこどうしが、家の跡つぎをめぐって激しく争っていました。そこに、幕府の実力者・細川勝元と山名宗全の対立がからみあいます。","1467年1月、都を追われそうになった政長は、兵をひきいて上御霊神社の森に陣を構えました。そこへ、山名宗全の支援を受けた義就の軍勢がおそいかかります。«御霊の森» での戦いは一日で決着がつき、政長は敗れて逃げました。これが «御霊合戦» です。","なぜこの小さな戦いが大乱の始まりなの? それは、政長を支えるはずの細川勝元がこのとき動かず、両陣営の不満が一気に高まったからです。5月、勝元の東軍と宗全の西軍が京都で本格的にぶつかり、戦いは全国の大名を巻きこんで11年も続きました。都の大部分が焼け、多くの人の命が失われます。","いま、上御霊神社の境内は木々にかこまれた静かな場所です。鳥居のわきには «応仁の乱勃発地» の石碑が立ち、ここから戦国時代への扉が開いたことを伝えています。毎年5月には «御霊祭» が行われ、華やかな神輿が町をめぐります。"],"tl":[["794年","桓武天皇が早良親王の霊をまつったのが始まりと伝わる（社伝）"],["863年","神泉苑で朝廷による御霊会が行われる"],["1467年1月","御霊合戦。畠山政長が義就に敗れる"],["1467年5月","東軍・西軍が本格的に衝突し応仁の乱が広がる"],["1477年","応仁の乱が終わる"]],"who":[["早良親王（崇道天皇）","御霊としてまつられる祭神の一人"],["畠山政長","御霊の森に陣を構え、敗れた武将"],["畠山義就","政長を攻めた武将"],["山名宗全","義就を支援した西軍の大将"],["細川勝元","東軍の大将。御霊合戦では政長を助けなかった"]],"deep":["正式名は «御霊神社»。下京区の «下御霊神社» と区別して «上御霊» と呼ばれます。祭神は早良親王（崇道天皇）・井上内親王・他戸親王・藤原吉子など、政争で亡くなった人々です。","863年の神泉苑の御霊会は、朝廷が公式に行った御霊会として『日本三代実録』に記されています。祇園祭の起源も御霊会と関係が深いとされます。","御霊合戦の日付は文正2年1月18日（旧暦）。その直後に年号が «応仁» に改められたため、この大乱は «応仁の乱»（のちに «応仁・文明の乱»）と呼ばれます。","応仁の乱の «西陣» は、山名宗全の西軍が陣を置いたことから生まれた地名で、のちに «西陣織» の名になりました。上御霊神社からも近い場所です。","御霊合戦のとき、政長方が社に火をかけて退いたとも伝わります。戦いの細かな経過は、『応仁記』など後の軍記物によるところもあり、慎重に読む必要があります。"],"look":["鳥居わきの «応仁の乱勃発地» 碑","御霊の森の面影を残す境内の木々","本殿と拝殿","近くの相国寺・西陣の町並み"],"q":["応仁の乱の始まりとされる、上御霊神社での戦いを何という？","«御霊合戦»（1467年）。畠山政長と義就の戦いです。"],"koji":[{"w":"応仁の乱","m":"1467年から1477年まで京都を中心に続いた大乱。戦国時代の始まりとされる"}],"myth":"創祀の年は社伝。合戦の細部は軍記物による部分があります。","img":["応仁の乱","御霊信仰","畠山政長","畠山義就"],"wp":"上御霊神社","rel":{"ev":["onin"],"grave":[]}},{"id":"26_hananogosho","n":"花の御所（室町第）跡","yomi":"はなのごしょ（むろまちてい）あと","cat":"遺跡","rank":"A","y":1378,"era":["muromachi"],"sh":"","ad":"京都市上京区 室町通今出川上ル付近","st":"地下鉄烏丸線 今出川駅から歩いて約3分","la":35.0303,"lo":135.7584,"hook":"«室町幕府» の «室町» は、ここの通りの名前。将軍が花に囲まれて暮らした御殿は、いまは石碑と地下の遺構だけ。","lead":"3代将軍・足利義満が、室町通に面した広い土地に建てた将軍の御殿が «室町第»。庭に各地の名花を集めたので «花の御所» と呼ばれました。ここで政治が行われたことから、この時代を «室町時代» と呼びます。建物は残っておらず、今は «跡» を示す石碑が立つだけです。","story":["南北朝の争いがまだ続いていた1378年ごろ、若い将軍・足利義満は、御所（天皇の住まい）のすぐ北西に新しい屋敷をつくり始めました。«将軍の家は、天皇の御所に負けない立派なものにしたい»。そんな思いがあったのかもしれません。敷地は東西およそ1町・南北2町ほどといわれ、公家の屋敷をしのぐ広さでした。","庭には鴨川の水を引いた池がつくられ、全国の大名や公家から、桜や梅などの名木が贈られたと伝わります。春になると御殿は花でいっぱい。人びとは «花の御所» と呼びました。«なぜ将軍は花を集めたの?» ――美しい庭は、将軍の力と教養を見せる «舞台» でもあったのです。","1381年には後円融天皇がこの御殿を訪れ、義満は盛大にもてなしました。天皇を自分の家に迎えることは、«将軍は天皇にも一目おかれる存在だ» と世に示すことでした。やがて義満は1392年に南北朝をひとつにまとめ、幕府の力は頂点に向かいます。","その後、4代義持は別の場所（三条坊門）に移りましたが、6代義教がふたたび室町に戻ります。8代義政のころ、1467年に «応仁の乱» が始まると、将軍を擁する東軍の本陣となり、御所の近くは戦場になりました。そして戦乱のなかで建物は焼け、将軍の «花の御所» は二度と元の姿には戻りませんでした。","いま、この場所には大学の校舎や寺、住宅が並んでいます。発掘調査では池の跡や庭石と考えられるものが見つかり、ここに大きな庭園があったことが確かめられています。通りに立つ石碑の前で目を閉じると、花見の宴のざわめきが聞こえてきそうです。"],"tl":[["1378年","足利義満が室町に新しい将軍御殿の造営を始める"],["1381年","後円融天皇が室町第を訪れる"],["1392年","義満のもとで南北朝が合一"],["1467年","応仁の乱が始まり、周辺が戦場になる"],["応仁の乱のころ","戦乱の中で建物が焼け、失われる"],["近代以降","跡地に大学・寺・住宅が建ち、石碑が置かれる"]],"who":[["足利義満","3代将軍。花の御所をつくった"],["後円融天皇","室町第に行幸し、義満のもてなしを受けた"],["足利義教","6代将軍。ふたたび室町を将軍の本拠にした"],["足利義政","8代将軍。応仁の乱の時代の主"]],"deep":["«室町幕府» という呼び名は、同時代の正式な名前ではなく、将軍の御殿がこの室町通にあったことから後世に使われるようになった呼び方です。","室町第の土地には、義満以前にも上皇の御所や公家の屋敷があったとされ、義満はそれを引き継いで大きく広げたといわれます。","義満はのちに北山に «北山殿»（今の金閣のある場所）を建てて移ります。花の御所と金閣は、ともに義満の «見せる政治» の舞台でした。","応仁の乱の最初の戦いとされる «御霊合戦» の上御霊神社は、ここから北東へ歩いて行ける距離。乱が «将軍の家の目と鼻の先» で始まったことがわかります。","跡地の一部は同志社大学の敷地になっていて、建物の建設にともなう発掘で室町第に関係する遺構が見つかったと報告されています。","近くの大聖寺は、室町第ゆかりの尼寺と伝わります。尼門跡寺院で、ふだんは非公開です。"],"look":["室町通今出川付近に立つ «室町幕府跡» を示す石碑","南に広がる京都御苑（天皇の御所との近さを体感）","北東の上御霊神社（応仁の乱の始まりの地）","今出川通を歩いて、当時の敷地の広さを想像する"],"q":["«花の御所» をつくった将軍はだれ?","3代将軍の足利義満。各地の名花を庭に集めたので «花の御所» と呼ばれました。"],"koji":[],"myth":"正確な敷地の範囲や、庭の花が贈られた話の細部には諸説がある。","img":["足利義満","室町幕府","応仁の乱"],"wp":"花の御所","rel":{"ev":["muromachi_bakufu"],"grave":[]}},{"id":"26_jurakudai","n":"聚楽第跡","yomi":"じゅらくだいあと","cat":"城","rank":"A","y":1587,"era":["azuchi"],"sh":"","ad":"京都市上京区 中立売通大宮〜智恵光院付近","st":"市バス «堀川中立売» または «千本中立売» から歩いて約5〜10分","la":35.0265,"lo":135.7465,"hook":"金箔の瓦がかがやく、秀吉の «夢の城»。わずか8年ほどで跡形もなく壊された幻の城は、町名の中に生きている。","lead":"聚楽第は、関白になった豊臣秀吉が、平安京の大内裏の跡地につくった城のような御殿です。天皇を迎えるほどの豪華さでしたが、完成から8年ほどで取り壊されました。いまは «跡» を示す石碑と、発掘で見つかった石垣や金箔瓦の記録が残るだけです。","story":["1586年、関白となった豊臣秀吉は、京都の中心に新しい本拠地をつくり始めました。場所は、かつて平安京の天皇の宮殿があったあたり。«聚楽» とは «長生不老の楽しみを聚（あつ）める» という意味だとされます。翌1587年、九州を平定して帰った秀吉は、この豪華な御殿に移りました。","堀と石垣に囲まれ、天守のような高い建物もあったとされる聚楽第。屋根には金箔を押した瓦がのり、日の光を受けてきらきらと光っていたことでしょう。まわりには大名たちの屋敷が並び、京都の町は秀吉の城下町のように姿を変えていきました。","1588年、秀吉は後陽成天皇をこの聚楽第に迎えます。行列は華やかで、天皇は数日間ここにとどまりました。このとき秀吉は、集まった大名たちに «天皇の命令にそむかない» という誓いを書かせます。«天皇を立てることで、自分の天下を正しいものに見せたい»――それが秀吉のねらいでした。","1591年、秀吉は関白の位と聚楽第を、おいの豊臣秀次にゆずります。ところが1593年に実の子・秀頼が生まれると、ふたりの関係はこじれていきました。1595年、秀次は謀反の疑いをかけられて高野山で切腹。すると秀吉は、秀次の住んだ聚楽第を徹底的に壊させてしまいます。","«なぜそこまで?» ――秀次の記憶ごと消し去りたかったのだともいわれます。建物の一部は伏見城などに移されたと伝わり、城の跡は町になりました。いま、この一帯には «如水町»（黒田如水）など、大名屋敷の名残とされる町名が残り、地面の下から幻の城が顔をのぞかせています。"],"tl":[["1586年","秀吉が聚楽第の建設を始める"],["1587年","完成し、秀吉が大坂から移る"],["1588年","後陽成天皇が聚楽第に行幸"],["1591年","秀吉が関白職とともに聚楽第を豊臣秀次にゆずる"],["1595年","秀次が切腹。聚楽第は取り壊される"],["2012年","発掘で本丸の堀にともなう石垣が見つかる"]],"who":[["豊臣秀吉","聚楽第をつくった関白"],["後陽成天皇","聚楽第に行幸した天皇"],["豊臣秀次","秀吉のおい。聚楽第をゆずられたが、のち切腹"],["黒田如水（官兵衛）","近くに屋敷があったとされ、«如水町» の名の由来と伝わる"]],"deep":["聚楽第の遺構と伝わる建物に、西本願寺の飛雲閣や大徳寺の唐門などがありますが、いずれも «伝» であり、確かな証拠はなく諸説あります。","2012年の発掘では、本丸の南側の堀に沿った石垣が数十メートルにわたって見つかり、大きなニュースになりました。調査のあと石垣は埋め戻されています。","周辺からは金箔瓦が多く出土しています。金箔瓦は秀吉と、その一族や重臣の城に限られる傾向があり、豊臣の権力の象徴とされます。","行幸のようすは『聚楽行幸記』という記録に残されています。大名の誓紙はここで天皇への忠誠を誓う形をとりながら、実際には秀吉への服従を示すものでした。","聚楽第を描いた «聚楽第図屏風»（三井記念美術館所蔵）は、失われた姿を知るための重要な手がかりです。","上京区の «松林寺» の境内は周囲より低く、聚楽第の堀の跡と考えられています。"],"look":["«聚楽第址» や «本丸西濠跡» などの石碑","松林寺の境内の低い土地（堀の名残とされる）","如水町・弾正町などの町名表示","近くの西陣の町並み"],"q":["聚楽第が完成から8年ほどで壊された理由は?","聚楽第をゆずられた豊臣秀次が切腹したあと、秀吉が徹底的に取り壊させたためです。"],"koji":[{"w":"聚楽","m":"«長生不老の楽しみを聚める» という意味とされ、今も «聚楽» の名は地名や土壁（聚楽壁）に残る"}],"myth":"飛雲閣・大徳寺唐門などを聚楽第の遺構とする説は伝承の域を出ない。天守の有無や規模にも諸説。","img":["豊臣秀吉","豊臣秀次","後陽成天皇"],"wp":"聚楽第","rel":{"ev":[],"grave":[]}},{"id":"26_mibu","n":"壬生寺と新選組屯所（八木邸・前川邸）","yomi":"みぶでら・しんせんぐみとんしょ（やぎてい・まえかわてい）","cat":"幕末","rank":"A","y":1863,"era":["edo","heian"],"sh":"","ad":"京都市中京区壬生梛ノ宮町","st":"阪急大宮駅・京福四条大宮駅から歩いて約10分","la":35.0021,"lo":135.743,"hook":"«壬生狼（みぶろ）»――新選組が最初に暮らしたのは、お寺の門前ののどかな郷士の家だった。","lead":"壬生寺は平安時代に始まったと伝わる地蔵信仰の寺で、«壬生狂言» で知られています。幕末、その近くの八木家と前川家の屋敷に浪士たちが住みつき、ここから «新選組» が生まれました。八木邸は見学でき、壬生寺には近藤勇の像や隊士の墓があります。","story":["1863年春、江戸から «浪士組» と呼ばれる200人あまりの男たちが京都にやってきました。将軍・徳川家茂が京都へ行くのを守る、という名目でした。ところが中心人物の清河八郎が «本当の目的は尊王攘夷だ» と言い出し、浪士組は江戸へ引き返すことになります。«それでは約束が違う»――京都に残ったのが、近藤勇・土方歳三・芹沢鴨たちでした。","彼らが宿にしたのは、壬生村の郷士・八木源之丞の屋敷や、前川家の屋敷でした。会津藩の «預かり» となった一団は、村の人から «壬生浪（みぶろ）» と呼ばれます。壬生寺の境内では、剣術や大砲の訓練も行われたと伝わります。お寺にとっては、ちょっと迷惑なお客さんだったかもしれません。","1863年8月の政変のあと、一団は «新選組» の名を与えられます。しかし組の中では争いが続きました。乱暴なふるまいが目立った筆頭局長・芹沢鴨は、その年の秋、八木邸で暗殺されます。今も八木邸には、そのときのものと伝わる刀傷が残っています。","1864年6月、前川邸の蔵では、捕らえた古高俊太郎への取り調べが行われたといわれます。そこで聞き出した情報から、新選組は池田屋へ踏み込み、その名は一気に知られるようになりました。1865年には総長・山南敬助が前川邸で切腹。ここは «誠» の旗の光と影が交差した場所です。","やがて隊士が増えると、新選組は西本願寺へと屯所を移します。壬生寺そのものは、991年に快賢という僧が開いたと伝わる古い寺で、鎌倉時代に円覚上人が始めたとされる無言劇 «壬生狂言» は今も春と秋、節分に演じられます。地蔵さんに見守られた町で、若者たちは何を夢見ていたのでしょう。"],"tl":[["991年","快賢が壬生寺を開いたと伝わる"],["1300年","円覚上人が壬生狂言を始めたと伝わる"],["1863年2月","浪士組が京都に入り、壬生村に宿をとる"],["1863年8〜9月","«新選組» の名が与えられ、芹沢鴨が八木邸で暗殺される"],["1864年6月","池田屋事件"],["1865年","山南敬助が前川邸で切腹。屯所を西本願寺へ移す"],["1962年","壬生寺本堂が火災で焼失（のちに再建）"]],"who":[["近藤勇","新選組局長。壬生寺に胸像がある"],["土方歳三","副長。«鬼の副長» と呼ばれた"],["芹沢鴨","初期の筆頭局長。八木邸で暗殺された"],["山南敬助","総長。前川邸で切腹した"],["八木源之丞","屋敷を屯所として提供した壬生村の郷士"],["円覚上人","壬生狂言を始めたと伝わる僧"]],"deep":["«新選組» の «選» は «撰» と書かれることもあり、当時の史料でも両方が使われています。","芹沢鴨の暗殺は長く «長州の仕業» とされましたが、実際には近藤・土方らが関わったとする見方が一般的です。ただし実行者の顔ぶれには諸説あります。","壬生寺の «壬生塚» には、芹沢鴨・平山五郎らの墓や近藤勇の遺髪塔とされる塔があります。","八木邸は現在も八木家が管理し、見学（有料）できます。前川邸は個人の住宅で、ふだんは非公開です。","壬生狂言は国の重要無形民俗文化財。せりふを使わず、身ぶりと «ガンデンデン» という鉦・太鼓の音だけで演じる念仏狂言です。","近くの光縁寺には山南敬助らの墓があると伝わります。"],"look":["八木邸の刀傷と伝わる鴨居","壬生寺の壬生塚（近藤勇像・隊士の墓）","壬生狂言が演じられる大念仏堂","前川邸の外観（非公開・外から見るだけ）","坊城通の古い町並み"],"q":["新選組が最初に屯所にした屋敷は?","壬生村の郷士の八木家・前川家の屋敷です。八木邸は今も見学できます。"],"koji":[{"w":"誠","m":"新選組の隊旗に書かれた文字。うそのない心を表す"}],"myth":"壬生寺の創建年・壬生狂言の起こりは伝承。芹沢暗殺の実行者、古高の取り調べの細部には諸説。刀傷の由来も伝承。","img":["新選組","近藤勇","芹沢鴨","壬生狂言"],"wp":"壬生寺","rel":{"ev":["ikedaya"],"grave":[]}},{"id":"26_ryozen","n":"京都霊山護国神社（龍馬・慎太郎・木戸の墓）","yomi":"きょうとりょうぜんごこくじんじゃ","cat":"墓所","rank":"A","y":1868,"era":["edo","meiji"],"sh":"","ad":"京都市東山区清閑寺霊山町","st":"市バス «東山安井» から歩いて約10分（坂道）","la":34.9969,"lo":135.7825,"hook":"京の町を見下ろす丘の上で、坂本龍馬と中岡慎太郎は今も並んで眠っている。","lead":"京都霊山護国神社は、明治のはじめに、幕末に国のために命を落とした人びとをまつるためにつくられた神社です。東山の中腹にある墓地には、坂本龍馬・中岡慎太郎・木戸孝允など、幕末の志士たちの墓がならびます。墓地に入るには拝観料が必要です。","story":["1867年11月、京都の近江屋で坂本龍馬と中岡慎太郎が襲われました。龍馬はその夜のうちに、慎太郎も2日後に亡くなります。仲間たちはふたりのなきがらを、東山の霊山に運びました。葬列には多くの人が加わったと伝わります。«ここなら京の町がよく見える»――そんな思いで選ばれた場所だったのかもしれません。","霊山にはそれ以前から、神道式のお葬式をする霊明神社があり、幕末の志士たちがここに葬られるようになっていました。明治時代が始まった1868年、明治天皇の意向により、国のために命を落とした人びとの霊をまつる «招魂社» がこの地につくられます。これが今の京都霊山護国神社の始まりです。","墓地の石段をのぼると、龍馬と慎太郎の墓が並んで立っています。そばには、ふたりと一緒に斬られた龍馬の従者・藤吉の墓もあります。墓の前には全国から来た人が手紙や花を置いていきます。«日本の夜明けは近いぜよ»――ドラマや小説で有名なこのせりふは創作ですが、そのことばに励まされてここに来る人も多いのです。","さらにのぼると、長州の木戸孝允と、その妻・幾松（松子）の墓があります。祇園の芸妓だった幾松は、新選組などに追われた木戸をかくまったと伝わります。明治の新政府で活躍した木戸は、1877年に京都で亡くなり、遺言によりここに葬られました。","このほか、禁門の変で亡くなった長州藩士や、天誅組の人びとなど、多くの志士の墓や碑が山の斜面をうめています。立場は違っても、それぞれが «この国をどうするか» に命をかけた人たちでした。静かな墓地で手を合わせると、幕末という時代の重さが伝わってきます。"],"tl":[["江戸時代後期","霊山に神葬祭をおこなう霊明神社ができる"],["1867年11月","坂本龍馬・中岡慎太郎が近江屋で襲われ、霊山に葬られる"],["1868年","明治天皇の意向で霊山に招魂社がつくられる"],["1877年","木戸孝允が京都で亡くなり、霊山に葬られる"],["1939年","«京都霊山護国神社» と名を改める"],["1970年","向かいに霊山歴史館が開館"]],"who":[["坂本龍馬","土佐出身。海援隊を率いた。ここに眠る"],["中岡慎太郎","土佐出身。陸援隊隊長。龍馬と並んで眠る"],["木戸孝允","長州出身。維新三傑の一人。妻と並んで眠る"],["幾松（木戸松子）","木戸の妻。祇園の芸妓だった"],["藤吉","龍馬の従者。近江屋で斬られた"]],"deep":["ここは «官祭招魂社» として、国が関わってまつった招魂社の中でも早い時期のものとされ、のちの各地の護国神社のさきがけの一つです。","龍馬の墓碑の文字は木戸孝允が書いたと伝わります。長州と土佐の志士のつながりを感じさせるエピソードです。","命日にあたる11月15日には «龍馬祭» が行われ、全国からファンが集まります。","向かいの霊山歴史館は、幕末・明治維新を専門にした博物館で、近江屋事件に関する資料なども展示されています。","霊山の墓域には、禁門の変で自害した久坂玄瑞らの墓や碑もあり、長州・土佐・肥後など、多くの藩の志士がともにまつられています。","霊山への坂は «維新の道» と呼ばれ、坂の上から京都の町並みを見下ろせます。"],"look":["坂本龍馬・中岡慎太郎の墓（京都市内を見下ろす）","龍馬の従者・藤吉の墓","木戸孝允と幾松の墓","長州藩士ら多くの志士の墓碑群","向かいの霊山歴史館"],"q":["坂本龍馬と並んで眠っているのはだれ?","中岡慎太郎です。近江屋でいっしょに襲われ、2日後に亡くなりました。"],"koji":[],"myth":"«日本の夜明けは近いぜよ» は小説・ドラマ由来の創作。龍馬の墓碑の揮毫者や幾松の逸話には伝承を含む。","img":["坂本龍馬","中岡慎太郎","木戸孝允","霊山歴史館"],"wp":"京都霊山護国神社","rel":{"ev":[],"grave":[["kido","木戸孝允"],["ryoma","坂本龍馬"],["nakaoka","中岡慎太郎"]]}},{"id":"26_hokokubyo","n":"豊国廟（阿弥陀ヶ峰の秀吉の墓）","yomi":"ほうこくびょう","cat":"墓所","rank":"A","y":1598,"era":["azuchi","meiji"],"sh":"","ad":"京都市東山区今熊野北日吉町（阿弥陀ヶ峰）","st":"京阪七条駅から歩いて約20分、さらに石段を約30分のぼる","la":34.9892,"lo":135.7853,"hook":"500段近い石段の先、山頂に立つ巨大な五輪塔。天下人は、死んでからも «消されかけた»。","lead":"豊国廟は、豊臣秀吉が葬られた阿弥陀ヶ峰の山頂の墓所です。秀吉は神としてまつられましたが、豊臣家がほろびると、徳川幕府によってまつりは禁じられ、墓は荒れはてました。今の大きな五輪塔は、明治時代に建て直されたものです。","story":["1598年8月、豊臣秀吉は伏見城で亡くなりました。幼い秀頼を残して。«露と落ち 露と消えにし 我が身かな 浪速のことは 夢のまた夢»――秀吉の辞世と伝わる歌です。その死はしばらく秘密にされ、なきがらはひそかに東山の阿弥陀ヶ峰に運ばれたといわれます。","翌年、山のふもとには大きな神社 «豊国社» が建てられ、秀吉は «豊国大明神» という神になりました。«自分を神としてまつれ» というのは、秀吉自身の望みだったともいわれます。豊国社の祭りはとても華やかで、そのにぎわいは屏風絵にも描かれています。","ところが1615年、大坂の陣で豊臣家がほろびると、徳川家康は豊国社を取りつぶしました。神の名も取り上げられ、山頂へ続く参道はふさがれ、墓はしだいに草にうもれていきます。«秀吉の記憶を人びとの心から消したい»――天下を取った者の、きびしい決断でした。","時代はめぐり、明治時代。新しい政府は、朝廷を大切にした人物として秀吉を高く評価しました。1880年には方広寺の大仏殿跡に豊国神社が再建され、1898年の秀吉の三百年祭にあわせて、山頂の墓所も整えられます。このとき建てられたのが、今も山頂にそびえる巨大な五輪塔です。","いま、ふもとから山頂までは長い石段が続きます。息を切らしてのぼりきると、そこは静かな山の上。天下人の墓としてはひっそりとした場所です。死んだあとまで «消されかけ»、また «よみがえった» 秀吉。その墓は、歴史が時代によって書きかえられることを教えてくれます。"],"tl":[["1598年8月","秀吉が伏見城で亡くなり、阿弥陀ヶ峰に葬られる"],["1599年","ふもとに豊国社が建てられ、«豊国大明神» の神号がおくられる"],["1604年","秀吉の七回忌に盛大な豊国祭が行われる"],["1615年","豊臣家滅亡後、徳川家康が豊国社を廃絶"],["1880年","方広寺大仏殿跡に豊国神社が再建される"],["1898年","三百年祭にあわせて山頂の墓所が整えられ、五輪塔が建つ"]],"who":[["豊臣秀吉","天下を統一した人物。ここに眠る"],["豊臣秀頼","秀吉の子。大坂の陣で亡くなった"],["徳川家康","豊国社を取りつぶした"],["伊東忠太","明治の建築家。山頂の墓所の整備に関わったとされる"]],"deep":["秀吉の神号は «豊国大明神»。«大明神» の号をめぐっては、«大権現» にしたかった側との間で議論があったともいわれ、のちに家康は «東照大権現» となりました。","1604年の豊国祭のにぎわいを描いた «豊国祭礼図屏風» は、豊国神社や徳川美術館などに伝わり、当時の京都の人びとの熱気を今に伝えます。","山頂の五輪塔は高さ約10mといわれる大きなもので、明治の整備の際に建てられました。","明治の墓所整備の工事中に、遺骸をおさめたとみられる甕が見つかったという話が伝わっていますが、確かな記録は限られます。","ふもとの参道のとちゅうにある平らな場所 «太閤坦（たいこうだいら）» は、かつての豊国社の社殿があったあたりとされます。","豊国神社の唐門（国宝）は、伏見城の遺構と伝わるものです。"],"look":["山頂の巨大な五輪塔","長い石段と途中の拝殿","太閤坦（豊国社の跡とされる平地）","ふもとの豊国神社と方広寺の大鐘（«国家安康» の鐘）"],"q":["豊臣家がほろびたあと、豊国社を取りつぶしたのはだれ?","徳川家康です。そのため墓は明治時代に再び整えられるまで荒れていました。"],"koji":[{"w":"夢のまた夢","m":"秀吉の辞世と伝わる歌の一節。この世の栄華もはかないものだということ"}],"myth":"辞世の歌が本人作かどうか、遺骸がひそかに葬られた経緯、明治の甕の発見談には伝承・諸説を含む。","img":["豊臣秀吉","豊国神社 (京都市)","方広寺","阿弥陀ヶ峰"],"wp":"豊国廟","rel":{"ev":[],"grave":[["hideyoshi","豊臣秀吉"]]}},{"id":"26_daitokuji","n":"大徳寺（利休・三成の墓所）","yomi":"だいとくじ","cat":"寺社","rank":"A","y":1325,"era":["kamakura","muromachi","azuchi"],"sh":"方丈・唐門は国宝、方丈庭園は国の史跡・特別名勝","ad":"京都市北区紫野大徳寺町","st":"市バス «大徳寺前» からすぐ","la":35.0441,"lo":135.7461,"hook":"山門の2階に置かれた、わらじ姿の木像ひとつ。それが千利休の命を奪った――と伝わる。","lead":"大徳寺は鎌倉時代の終わりに開かれた禅寺で、一休さん、織田信長、豊臣秀吉、千利休など、たくさんの有名人とつながりがあります。広い境内には20あまりの塔頭（小さな寺）が並び、利休や石田三成の墓もあります（墓のある塔頭はふだん非公開）。","story":["大徳寺を開いたのは宗峰妙超（大燈国師）という禅僧です。鎌倉時代の終わりごろ、紫野の地に小さな庵を結んだのが始まりでした。やがて花園上皇や後醍醐天皇があつく信仰し、大徳寺は京都でも指おりの禅寺になります。","しかし応仁の乱で、寺は焼けてしまいます。立て直しに力をつくしたのが、あの «一休さん»、一休宗純でした。81歳で大徳寺の住職となった一休は、堺の商人たちの力を借りて寺を復興します。こうして大徳寺は、商人や茶人たちと深く結びついていきました。","1582年、本能寺の変で織田信長が亡くなると、豊臣秀吉はこの大徳寺で信長の盛大な葬儀を行いました。«信長さまの後を継ぐのはこの秀吉だ» と天下に示すための葬儀です。その後、信長の菩提をとむらう塔頭 «総見院» が建てられ、戦国大名たちも競うように塔頭を建てました。","1589年、茶人・千利休は寄付をして、未完成だった山門に2階を増築しました。これが朱色の «金毛閣» です。お礼として、寺は利休の木像を門の上に置きました。ところが «天下人の自分が、利休の足の下をくぐるのか»――これに秀吉が怒ったといわれます。1591年、利休は切腹を命じられました。","本当の理由は何だったのか、今もはっきりしません。利休の墓は塔頭の聚光院にあり、関ケ原で敗れた石田三成の墓は三玄院にあるといわれます。静かな石畳の参道を歩けば、戦国の人びとの祈りと争いが、ひっそりと重なっているのを感じられます。"],"tl":[["1315年ごろ","宗峰妙超が紫野に庵を結んだとされる"],["1325年","後醍醐天皇が大徳寺を祈願所とする"],["1474年","一休宗純が住職となり、応仁の乱後の復興を進める"],["1582年","秀吉が信長の葬儀を行い、総見院が建てられる"],["1589年","千利休の寄進で山門の上層（金毛閣）が完成"],["1591年","利休が切腹を命じられる"]],"who":[["宗峰妙超（大燈国師）","大徳寺を開いた禅僧"],["一休宗純","応仁の乱で焼けた大徳寺を復興した"],["豊臣秀吉","信長の葬儀を大徳寺で行った"],["千利休","山門の上層を寄進。のちに切腹を命じられた"],["石田三成","塔頭の三玄院に墓があるとされる"]],"deep":["利休の切腹の理由は、山門の木像のほかにも、茶道具の売買での不正の疑い、秀吉との政治上の対立など多くの説があり、決め手はありません。","唐門（国宝）は聚楽第の遺構と伝えられますが、確かな証拠はなく、諸説あります。","常に公開されている塔頭は龍源院・瑞峯院・大仙院など一部で、聚光院や三玄院などは特別公開のときなどを除いて非公開です。","大仙院の枯山水庭園は、石と砂だけで山から流れる水が大河となり海に注ぐようすを表したとされる名庭です。","大徳寺には «大徳寺納豆» と呼ばれる、塩辛い味の寺納豆が伝わっています。一休が広めたともいわれますが伝承です。","大徳寺は茶の湯と深く結びつき、«大徳寺の茶面» という古い言い回しが伝わるほど、多くの茶人がここで禅を学びました。"],"look":["朱色の山門（金毛閣）――利休の木像が置かれた門","国宝の唐門","秀吉が建てた信長の菩提所・総見院（公開時）","公開中の塔頭の枯山水庭園","石畳の参道と塔頭の土塀"],"q":["大徳寺の山門の2階を寄付した茶人はだれ?","千利休です。門の上に置かれた利休の木像が、秀吉の怒りを招いたと伝わります。"],"koji":[{"w":"一期一会","m":"一生に一度の出会いと思って心をつくすこと。茶の湯の心得として知られる"}],"myth":"利休切腹の理由、唐門の聚楽第遺構説、大徳寺納豆と一休の関係は諸説・伝承。創建年は諸説。","img":["千利休","一休宗純","金毛閣","大仙院"],"wp":"大徳寺","rel":{"ev":[],"grave":[["rikyu","千利休"],["mitsunari","石田三成"]]}},{"id":"26_sanjo_ohashi","n":"三条大橋（東海道・中山道の終点）","yomi":"さんじょうおおはし","cat":"街道","rank":"A","y":1590,"era":["azuchi","edo"],"sh":"","ad":"京都市中京区・東山区（鴨川にかかる三条通の橋）","st":"京阪三条駅・地下鉄三条京阪駅からすぐ","la":35.0093,"lo":135.7722,"hook":"江戸・日本橋から約500km。«東海道五十三次» の旅人がたどり着くゴールが、この橋だった。","lead":"三条大橋は鴨川にかかる橋で、江戸時代には東海道と中山道の終点（京都側の起点）でした。1590年に豊臣秀吉の命令で石の柱を使った本格的な橋になり、今もその時代の石柱や擬宝珠が伝わっています。","story":["1590年、豊臣秀吉は家臣の増田長盛に命じて、三条通の鴨川に大きな橋をかけさせました。橋脚には、それまでの木ではなく丈夫な石の柱が使われました。橋の手すりにつけられた擬宝珠（ぎぼし）には «天正十八年» の年号が刻まれ、今もその一部が使われています。","江戸時代になると、この橋は江戸の日本橋から続く東海道の終点になりました。中山道も草津で東海道と合流するので、どちらの旅人もこの橋を渡って京都に入ります。«やっと京に着いた!»――長い旅を終えた人たちの喜びが目に浮かびます。","十返舎一九の『東海道中膝栗毛』の主人公、弥次さん・喜多さんも、旅の終わりに京都を訪れます。橋のたもとには、二人の像が立っています。また東のたもとには、京都御所の方角を拝む勤王家・高山彦九郎の像があり、待ち合わせの目印になっています。","一方、橋の下の三条河原は、罪人の首がさらされる場所でもありました。関ケ原の戦いで敗れた石田三成も、処刑ののちここで首をさらされたと伝わります。幕末には、橋のすぐ近くの池田屋で新選組による襲撃事件が起こりました。擬宝珠の一つには、そのときの刀傷とされる傷があります。","今の橋は1950年にかけかえられたものですが、欄干には昔ながらの擬宝珠がならび、木の手すりが残されています。橋のたもとには、かつての石の橋脚も展示されています。鴨川の風に吹かれながら橋を渡ると、何百年もの旅人たちの足音が重なって聞こえるようです。"],"tl":[["室町時代","三条通の鴨川に橋がかけられていたことが記録に見える"],["1590年","秀吉の命で増田長盛が石柱の橋にかけかえる"],["1600年","石田三成の首が三条河原にさらされたと伝わる"],["江戸時代","東海道・中山道の終点として旅人でにぎわう"],["1864年","近くの池田屋で池田屋事件が起こる"],["1950年","現在の橋にかけかえられる"]],"who":[["豊臣秀吉","石柱の橋にかけかえさせた"],["増田長盛","秀吉の命で工事を担当した奉行"],["十返舎一九","『東海道中膝栗毛』の作者"],["高山彦九郎","江戸中期の勤王家。東詰に像がある"],["石田三成","処刑後、三条河原で首をさらされたと伝わる"]],"deep":["擬宝珠の銘には、«日本で初めての石柱の橋» という意味の文があるといわれ、秀吉の自信が感じられます。","擬宝珠の刀傷を池田屋事件のものとする話は伝承で、確かな根拠はありません。","東海道五十三次は江戸・日本橋から数えて53の宿場を通り、京都・三条大橋に至ります。","高山彦九郎は、三条大橋を通るたびに御所の方角に向かって拝んだと伝わり、その姿が像になっています。","三条河原は中世から処刑やさらし首の場となり、豊臣秀次の妻子たちが処刑された悲しい場所でもあります。近くの瑞泉寺でとむらわれています。","近年の補修で、古い擬宝珠や木の欄干の手入れが行われています。"],"look":["«天正十八年» の銘のある擬宝珠","刀傷と伝わる擬宝珠（西から2番目付近とされる）","西詰の弥次喜多像","東詰の高山彦九郎像","旧橋脚の石柱の展示"],"q":["東海道の起点は江戸・日本橋。では京都側の終点は?","三条大橋です。中山道も草津で東海道と合流して、この橋に至りました。"],"koji":[],"myth":"刀傷の由来、石田三成の首のさらし場所の細部は伝承を含む。","img":["東海道","東海道中膝栗毛","高山彦九郎","池田屋事件"],"wp":"三条大橋","rel":{"ev":["kenmu","ikedaya","k_tokaido","k_nakasendo"],"grave":[]}},{"id":"26_teradaya","n":"寺田屋（寺田屋事件・伏見）","yomi":"てらだや","cat":"幕末","rank":"A","y":1862,"era":["edo"],"sh":"","ad":"京都市伏見区南浜町","st":"京阪中書島駅から歩いて約5分","la":34.9323,"lo":135.7627,"hook":"同じ宿で二度の血の事件。一度目は薩摩の仲間どうしの斬り合い、二度目は坂本龍馬の襲撃だった。","lead":"寺田屋は、伏見の港町にあった船宿です。1862年には薩摩藩士どうしが斬り合う «寺田屋事件» が起こり、1866年には坂本龍馬がここで伏見奉行所の役人に襲われました。今の建物は、のちに建て直されたものと考えられています。","story":["江戸時代の伏見は、京都と大坂を結ぶ淀川の船の港でした。寺田屋は、大坂へ向かう «三十石船» の客が泊まる船宿です。1862年春、ここに薩摩藩の過激な尊王攘夷派の藩士たちが集まりました。«幕府寄りの役人を討ち、天皇のもとで攘夷の兵をあげよう»――そんな計画だったといわれます。","ところが、薩摩の実力者・島津久光は、この動きを許しませんでした。久光は自分の家来を送り、思いとどまるよう説得させます。話し合いは決裂し、同じ薩摩の仲間どうしで斬り合いが始まりました。中心人物の有馬新七らが命を落とし、事件は «寺田屋騒動» とも呼ばれます。仲間を斬らなければならなかった人たちの気持ちは、どれほどつらかったでしょう。","4年後の1866年1月、今度は坂本龍馬がここに泊まっていました。薩長同盟の話し合いが進むなか、幕府は龍馬を危険人物として追っていたのです。夜ふけ、伏見奉行所の役人たちが宿を取り囲みました。","そのとき、風呂に入っていたお龍（のちの龍馬の妻）が異変に気づき、急いで2階の龍馬に知らせたと伝わります。龍馬はピストルで応戦し、長州藩士の三吉慎蔵とともに脱出しますが、手に深い傷を負いました。ふたりは材木小屋に隠れ、やがて伏見の薩摩藩邸に助け出されます。","この事件のあと、龍馬はお龍と薩摩へ旅に出ます。これが «日本初の新婚旅行» ともいわれる旅です。寺田屋の建物は1868年の鳥羽・伏見の戦いで焼けたと考えられ、今の建物はそのあとに建てられたものです。それでも館内には龍馬ゆかりの品々が並び、多くのファンが訪れます。"],"tl":[["江戸時代","伏見の港の船宿としてにぎわう"],["1862年4月","寺田屋事件（薩摩藩士どうしの斬り合い）"],["1866年1月","伏見奉行所の役人が坂本龍馬を襲撃"],["1868年1月","鳥羽・伏見の戦いで周辺が焼ける"],["2008年","京都市が、現在の建物は事件後の再建とみられるとの見解を示す"]],"who":[["有馬新七","薩摩藩士。寺田屋事件で命を落とした"],["島津久光","薩摩藩の実力者。藩士たちの計画をおさえた"],["坂本龍馬","1866年、ここで襲われ負傷した"],["お龍","龍馬に危険を知らせたと伝わる"],["三吉慎蔵","長州藩士。龍馬とともに戦い脱出した"],["お登勢","寺田屋の女将。龍馬を助けた"]],"deep":["1862年の寺田屋事件は、島津久光が兵をひきいて京都に入り、朝廷と幕府の間に立とうとしていた時期に起こりました。久光は過激な動きを抑えることで、朝廷の信頼を得ました。","龍馬襲撃は «寺田屋遭難» とも呼ばれ、同じ «寺田屋事件» の名でよばれることもあるので注意が必要です。","龍馬が使ったピストルは、高杉晋作から贈られたものと伝わります。","京都市は2008年、現在の建物は鳥羽・伏見の戦いのあとに再建されたものとの見解を示しました。館内の «刀傷» や «弾痕» とされるものの由来には注意が必要です。","お龍が風呂から裸同然で2階へ駆け上がった、という話は有名ですが、細部はのちの回想による部分があります。","寺田屋は現在も営業していて、見学料を払うと館内を見られます。"],"look":["寺田屋の建物と、龍馬が泊まったとされる部屋","寺田屋事件の殉難者の碑","近くの濠川と十石舟（季節運航）","伏見の酒蔵の町並み"],"q":["1866年、寺田屋で龍馬に危険を知らせたと伝わる女性は?","お龍です。のちに龍馬の妻となりました。"],"koji":[],"myth":"現在の建物は再建とされ、館内の刀傷・弾痕の真偽には疑問がある。お龍の逸話の細部は伝承。","img":["坂本龍馬","楢崎龍","島津久光","伏見港"],"wp":"寺田屋事件","rel":{"ev":["ryoma"],"grave":[]}},{"id":"26_omiya","n":"近江屋跡（坂本龍馬暗殺の地）","yomi":"おうみやあと","cat":"幕末","rank":"A","y":1867,"era":["edo"],"sh":"","ad":"京都市中京区 河原町通蛸薬師下ル","st":"阪急京都河原町駅から歩いて約5分","la":35.0056,"lo":135.7689,"hook":"大政奉還からわずか1か月。新しい国の形を描いていた龍馬の夢は、醤油屋の2階で断ち切られた。","lead":"近江屋は、坂本龍馬が隠れ住んでいた醤油屋です。1867年11月15日、龍馬と中岡慎太郎はここで何者かに襲われ、命を落としました。今は建物はなく、通りの一角に石碑が立つだけです。","story":["1867年10月、将軍・徳川慶喜は政権を朝廷に返す «大政奉還» を行いました。この流れをつくった一人が坂本龍馬です。けれども龍馬は、幕府の側からも倒幕派の一部からも、命をねらわれる立場にありました。そこで龍馬は、土佐藩邸の近くにあった醤油屋・近江屋にひそんでいたのです。","11月15日の夜。龍馬は風邪ぎみで、2階の部屋にいたといわれます。そこへ陸援隊の隊長・中岡慎太郎がたずねてきました。ふたりが話しこんでいると、«十津川郷士» を名乗る男たちが訪ねてきます。取り次いだ従者の藤吉は、階段で斬られました。","刺客たちは2階へかけ上がり、ふたりに斬りつけます。額を深く斬られた龍馬は、その場で、あるいはまもなく息を引き取ったとされます。慎太郎は重い傷を負いながら、襲われたときのようすを語り残し、2日後に亡くなりました。この日は龍馬の誕生日だったともいわれています。","«いったいだれが?» ――犯人は長いあいだ謎でした。明治になって、元京都見廻組の今井信郎が関わりを認める証言をしたことから、今では見廻組が実行したという説が有力です。それでも、新選組説や、薩摩藩が裏で動いたという説など、さまざまな推理が今も語られています。","近江屋の建物は今はなく、跡地にはお店が建ち、歩道の脇に «坂本龍馬 中岡慎太郎 遭難之地» の石碑が立っています。にぎやかな繁華街の中で、手を合わせていく人の姿が絶えません。ここで亡くなった三人の命を思いながら、そっと立ち止まってみてください。"],"tl":[["1867年10月","大政奉還"],["1867年11月15日","近江屋で龍馬・慎太郎・藤吉が襲われる"],["1867年11月16日","従者の藤吉が亡くなる"],["1867年11月17日","中岡慎太郎が亡くなる。三人は霊山に葬られる"],["1870年","元見廻組の今井信郎が取り調べで関与を述べる"],["現在","跡地に石碑が立つ"]],"who":[["坂本龍馬","土佐出身の志士。ここで命を落とした"],["中岡慎太郎","陸援隊隊長。ともに襲われ2日後に死去"],["藤吉","龍馬の従者。最初に斬られた"],["井口新助","近江屋の主人。龍馬をかくまった"],["今井信郎","元京都見廻組。事件への関与を証言した"]],"deep":["今井信郎の証言では、見廻組の佐々木只三郎らが実行したとされます。ただし、だれが実際に斬りつけたかについては証言によって食い違いがあります。","現場に残された刀の鞘や下駄をもとに、当初は新選組の原田左之助が疑われましたが、これは誤りとする見方が一般的です。","«薩摩黒幕説» など陰謀論に近い説も多くありますが、確かな史料による裏づけはありません。","龍馬の誕生日は天保6年11月15日とされ、命日と同じ日だという話が広く知られていますが、誕生日については異説もあります。","事件の現場に残されたとされる血染めの掛け軸や屏風は、京都国立博物館などに伝わり、公開されることがあります。","石碑があるのは跡地の一角で、建物の中は店舗です。見学は石碑のみで、店舗や周囲の迷惑にならないようにしましょう。"],"look":["«坂本龍馬 中岡慎太郎 遭難之地» の石碑","近くの土佐藩邸跡の碑（高瀬川沿い）","龍馬が通ったとされる河原町・木屋町の通り"],"q":["龍馬と慎太郎を襲ったのはだれとする説が有力?","京都見廻組です。明治になって元隊士の今井信郎が関与を証言しました。"],"koji":[],"myth":"犯人・黒幕、龍馬の即死かどうか、誕生日と命日の一致などには諸説がある。","img":["坂本龍馬","中岡慎太郎","京都見廻組","今井信郎"],"wp":"近江屋事件","rel":{"ev":["ikedaya","ryoma"],"grave":[]}},{"id":"26_kinmon","n":"蛤御門（禁門の変）","yomi":"はまぐりごもん（きんもんのへん）","cat":"幕末","rank":"A","y":1864,"era":["edo"],"sh":"","ad":"京都市上京区 京都御苑（烏丸通沿い）","st":"地下鉄烏丸線 丸太町駅または今出川駅から歩いて約7分","la":35.0211,"lo":135.7592,"hook":"«開かずの門» が火事で開いた――その門は60年あまり後、御所をめぐる激しい戦いの舞台になった。","lead":"蛤御門は、京都御苑の西側にある門です。1864年、京都から追い出されていた長州藩が兵をひきいて御所に攻め込み、この門の周りで会津藩・薩摩藩などと激しく戦いました。これが «禁門の変»（蛤御門の変）です。門には今も弾のあとが残るといわれます。","story":["この門はもともと «新在家御門» と呼ばれ、ふだんは閉じられたままの «開かずの門» でした。ところが1788年の天明の大火のとき、初めて門が開かれたといわれます。«焼けて口を開く蛤のようだ»――そこから «蛤御門» と呼ばれるようになった、と伝わります。","1863年、朝廷で強い力をもっていた長州藩は、«八月十八日の政変» で京都から追い出されました。翌年6月には池田屋事件で多くの仲間を失います。«このままでは終われない» と、長州藩は兵をひきいて京都に向かいました。","1864年7月19日、戦いが始まりました。来島又兵衛の部隊が蛤御門に攻めかかり、門を守る会津藩と激しく撃ち合います。そこへ西郷隆盛らの薩摩藩が駆けつけ、来島は銃弾に倒れました。久坂玄瑞は近くの鷹司家の屋敷で戦ったのち自害。«御所に向けて弓を引いた» 長州藩は、«朝敵» とされてしまいます。","戦いの火は町に燃え広がり、京都の町は3日ほど燃え続けました。«どんどん焼け» と呼ばれたこの大火で、とても多くの家が焼け、町の人びとの暮らしがうばわれました。戦のかげで、罪のない人びとが大きな犠牲を受けたのです。","この戦いのあと、幕府は長州を攻め（長州征討）、長州藩は一度は屈服します。しかしやがて薩摩と手を結び、幕府をたおす側にまわっていきました。今、門の前はのどかな御苑の散歩道。けれども門の柱をよく見ると、弾のあとと伝わるくぼみが残っています。"],"tl":[["1788年","天明の大火で «開かずの門» が開かれたと伝わる"],["1863年8月","八月十八日の政変で長州藩が京都を追われる"],["1864年6月","池田屋事件"],["1864年7月19日","禁門の変。蛤御門周辺で激戦"],["1864年7月","«どんどん焼け» で京都の町が広く焼ける"],["1864年","第一次長州征討"]],"who":[["来島又兵衛","長州藩士。蛤御門を攻め、戦死した"],["久坂玄瑞","長州藩士。鷹司邸で自害した"],["真木和泉","久留米の志士。敗戦後、天王山で自刃した"],["松平容保","会津藩主・京都守護職。御所を守った"],["西郷隆盛","薩摩藩の指揮官として戦った"]],"deep":["«禁門» とは御所の門のこと。蛤御門だけでなく、堺町御門や中立売御門など複数の門の周りで戦いがありました。","«蛤御門» の名の由来は天明の大火にまつわる話として広く伝わっていますが、確かな史料で裏づけられたものではありません。","«どんどん焼け» では、町家約2万8千戸が焼けたとされます（数には諸説）。«鉄砲焼け» とも呼ばれました。","門の柱や梁に残るくぼみは、禁門の変の弾痕と伝えられています。","真木和泉らは敗戦後、天王山にのぼって自刃しました。天王山には «十七烈士の墓» があります。","この戦いで長州は朝敵とされましたが、数年後の鳥羽・伏見の戦いでは、逆に «官軍» として幕府軍と戦うことになります。"],"look":["蛤御門の柱や梁（弾痕と伝わるくぼみ）","門の前の説明板","御苑内の鷹司邸跡・九條邸跡など","御所の築地塀"],"q":["«蛤御門» の名前の由来として伝わる話は?","天明の大火で «開かずの門» が初めて開いたので、«焼けて口を開く蛤» にたとえた、と伝わります。"],"koji":[],"myth":"名の由来、弾痕の真偽、焼失戸数には諸説・伝承を含む。","img":["京都御苑","久坂玄瑞","来島又兵衛"],"wp":"禁門の変","rel":{"ev":[],"grave":[]}},{"id":"26_sosui","n":"琵琶湖疏水と水路閣・インクライン","yomi":"びわこそすい","cat":"近代","rank":"A","y":1890,"era":["meiji"],"sh":"国指定史跡","ad":"京都市左京区南禅寺草川町（蹴上インクライン）ほか","st":"地下鉄東西線 蹴上駅から歩いてすぐ","la":35.0112,"lo":135.7887,"hook":"天皇が東京へ去り、元気をなくした京都。町を救ったのは、山をくりぬいて琵琶湖の水を引く、21歳の技師の大工事だった。","lead":"琵琶湖疏水は、明治時代に琵琶湖の水を京都まで引いた水路です。飲み水や田畑の水だけでなく、船の運送や水力発電にも使われ、京都の近代化を支えました。南禅寺の水路閣や、船を台車にのせて坂を運んだ蹴上インクラインが今も残っています。","story":["1869年ごろ、天皇が東京に移ると、京都からは多くの公家や商人が去っていきました。人口は減り、町には元気がありません。«このままでは京都がさびれてしまう»――そう考えた京都府知事・北垣国道は、昔からの夢だった «琵琶湖の水を京都へ引く» 大工事を決意します。","工事の責任者に選ばれたのは、工部大学校を卒業したばかりの田辺朔郎でした。まだ20代はじめの若者です。外国人技師にたよらず、日本人の手でやりとげる――それは大きな挑戦でした。1885年、工事が始まります。","一番の難関は、大津と京都の間にそびえる長等山をくりぬく長いトンネルでした。田辺たちは、山の上から縦穴（竪坑）を掘り下げ、そこから左右に掘り進める方法も取り入れて工期を縮めました。レンガも現地の工場で焼き、たくさんの人びとが力を合わせました。そして1890年、第1疏水が完成します。","疏水の水は、京都の町を大きく変えました。蹴上には、日本で最初の営業用の水力発電所がつくられ、その電気で1895年には京都で日本初の路面電車が走り出します。高低差のある場所では、船を台車にのせてレールで運ぶ «インクライン» が活躍しました。«水が町を生き返らせた» のです。","南禅寺の境内を通る赤レンガの «水路閣» は、アーチがつらなる美しい水道橋で、今では人気の撮影スポットです。1912年には第2疏水も完成し、今も京都の水道水の多くは琵琶湖から疏水で運ばれています。明治の人びとの挑戦は、今もこの町の暮らしを支え続けています。"],"tl":[["1881年","北垣国道が京都府知事になり、疏水計画を進める"],["1885年","第1疏水の工事が始まる"],["1888年","南禅寺の水路閣が完成したとされる"],["1890年","第1疏水が完成"],["1891年","蹴上発電所が運転を始める"],["1895年","疏水の電気で日本初の路面電車が京都で走る"],["1912年","第2疏水が完成"],["1996年","疏水の主な施設が国の史跡に指定される"]],"who":[["北垣国道","第3代京都府知事。疏水建設を決断した"],["田辺朔郎","若き技師。工事の中心となって設計・監督した"],["琵琶湖疏水の工事に関わった人びと","多くの作業員が工事に加わり、殉職者も出た"]],"deep":["田辺朔郎は工部大学校の卒業論文で疏水の計画をまとめ、その内容が評価されて工事の主任に抜てきされたといわれます。","蹴上インクラインは長さ約580m・高低差約36mで、運転されていた時期のものとしては世界でも有数の長さだったとされます。今はレールが保存され、桜並木の散歩道になっています。","当初は水車で工場を動かす計画でしたが、田辺らがアメリカで水力発電を視察し、発電所をつくる計画に変えたとされます。","トンネルの出入り口には、伊藤博文・山県有朋ら明治の元勲の揮毫による額（扁額）がかかげられています。","工事では殉職者も出ており、蹴上には工事で亡くなった人びとをしのぶ碑があります。","疏水のそばの «琵琶湖疏水記念館» では、工事の図面や模型、田辺朔郎の資料が見られます。"],"look":["蹴上インクラインのレールと台車（復元展示）","南禅寺境内の赤レンガの水路閣","蹴上発電所の外観","ねじりまんぽ（インクライン下のねじれたレンガのトンネル）","琵琶湖疏水記念館"],"q":["琵琶湖疏水の電気で、1895年に京都で日本で初めて走ったものは?","路面電車です。蹴上の水力発電所の電気が使われました。"],"koji":[],"myth":"インクラインの «世界最長» などの表現には比較の条件により諸説。","img":["蹴上インクライン","水路閣","田辺朔郎","北垣国道"],"wp":"琵琶湖疏水","rel":{"ev":[],"grave":[]}},{"id":"26_katsura","n":"桂離宮","yomi":"かつらりきゅう","cat":"大名屋敷","rank":"A","y":1615,"era":["edo"],"sh":"","ad":"京都市西京区桂御園","st":"阪急桂駅から歩いて約20分／市バス «桂離宮前» から歩いて約8分","la":34.9838,"lo":135.7094,"hook":"ドイツの建築家が «泣きたくなるほど美しい» と言った――月を愛でるために建てられた、皇族の別荘。","lead":"桂離宮は、江戸時代のはじめに皇族の八条宮家がつくった別荘です。池のまわりに書院や茶屋が配置され、日本の庭園と建築の最高傑作の一つとされます。宮内庁が管理しており、見学には申し込みが必要です。","story":["桂離宮をつくったのは、後陽成天皇の弟で八条宮家を開いた智仁親王です。智仁親王は一時、豊臣秀吉の養子になっていましたが、秀吉に実の子が生まれると、その縁は解かれてしまいました。やがて親王は、桂川のほとりに山荘をつくり始めます。1615年ごろのことといわれます。","桂の地は、平安時代から月の名所として知られ、『源氏物語』に登場する光源氏の別荘 «桂殿» のモデルともいわれます。智仁親王は、和歌や古典を深く学んだ文化人でした。«源氏物語の世界を、この庭に描きたい»。そんな思いがあったのかもしれません。","親王が亡くなったあと、しばらく荒れていた山荘を大きく整えたのが、息子の智忠親王です。中書院や新御殿が建て増しされ、池のまわりには松琴亭・賞花亭・笑意軒などの茶屋が配置されました。古書院には、月をながめるための «月見台» が池に向かってつくられています。","庭を歩くと、道が曲がるたびに景色ががらりと変わります。石の橋、灯籠、飛び石、そして水面に映る建物。«どこから見ても絵になる» ように、すみずみまで計算されているのです。松琴亭の青と白の市松模様のふすまは、今見てもモダンでおしゃれです。","1933年、日本を訪れたドイツの建築家ブルーノ・タウトは、桂離宮を見て深く感動し、その簡素な美しさを世界に紹介しました。明治時代に宮内省の管理となり «桂離宮» と呼ばれるようになってから、今も大切に守られています。"],"tl":[["1615年ごろ","智仁親王が桂の地に山荘をつくり始める"],["1629年","智仁親王が亡くなる"],["1640年代","智忠親王が中書院などを増築し、整備を進める"],["1660年代","後水尾上皇が桂の山荘を訪れたとされる"],["1883年","宮内省の管理となり «桂離宮» となる"],["1933年","ブルーノ・タウトが訪れ、世界に紹介する"]],"who":[["智仁親王","八条宮家の初代。桂離宮を創始した"],["智忠親王","智仁親王の子。増築し整備した"],["後水尾上皇","桂の山荘を訪れたとされる"],["ブルーノ・タウト","ドイツの建築家。桂離宮の美を世界に伝えた"],["細川幽斎","智仁親王に «古今伝授» を授けた歌人・武将"]],"deep":["智仁親王は細川幽斎から、古今和歌集の秘伝 «古今伝授» を受けました。1600年、幽斎が関ヶ原の戦いの前に丹後の田辺城で籠城したとき、秘伝がとだえるのを心配した朝廷が、戦いをやめさせたといわれます。","書院の建物は «数寄屋風書院造» の代表とされ、古書院・中書院・新御殿が雁が飛ぶように斜めに連なる «雁行形» に並んでいます。","八条宮家はのちに常磐井宮・京極宮と名を変え、江戸後期に «桂宮» となりました。桂宮家は明治時代に絶え、この山荘が宮内省のものになりました。","よく知られる «小堀遠州がつくった» という話は、確かな証拠がなく、今は否定的な見方が多いです。","参観は宮内庁への事前申し込みや当日の受付で行い、ガイドの案内で決められたコースを歩きます（有料）。","タウトの評価は、日本人自身が «日本の美» を見直すきっかけにもなりました。"],"look":["古書院の月見台","松琴亭の市松模様のふすま","池を巡る回遊式庭園と «天橋立» を模した景色","笑意軒の丸い下地窓","外から見られる «桂垣»（竹の生垣）"],"q":["桂離宮の美しさを世界に紹介したドイツの建築家は?","ブルーノ・タウトです。1933年に訪れ、その簡素な美しさを高く評価しました。"],"koji":[],"myth":"小堀遠州作とする説は根拠が弱い。後水尾上皇の訪問時期や、源氏物語の桂殿との関係は諸説。","img":["智仁親王","ブルーノ・タウト","八条宮","数寄屋造"],"wp":"桂離宮","rel":{"ev":[],"grave":[]}},{"id":"26_sanjusangendo","n":"三十三間堂（蓮華王院）","yomi":"さんじゅうさんげんどう（れんげおういん）","cat":"寺社","rank":"A","y":1164,"era":["heian","kamakura","edo"],"sh":"国宝（本堂・千手観音坐像・千手観音立像ほか）","ad":"京都市東山区三十三間堂廻町","st":"京阪七条駅から歩いて約7分／市バス «博物館三十三間堂前» からすぐ","la":34.9879,"lo":135.7717,"hook":"お堂の中にずらりと並ぶ1001体の観音さま。その中に、会いたい人に似た顔がきっとある――と伝わる。","lead":"三十三間堂は、後白河上皇が平清盛に建てさせたお寺で、正式には «蓮華王院» の本堂です。長さ約120mの細長いお堂に、千手観音の像がなんと1001体も並んでいます。江戸時代には、お堂の縁で矢を射る «通し矢» でも有名でした。","story":["平安時代の終わり、政治の中心にいた後白河上皇は、仏の力で国を守ってもらおうと考えました。1164年、上皇の命を受けて、平清盛がこの大きなお堂を建てます。«千体の観音さまを並べれば、きっと大きなご利益があるはずだ»。それは、上皇と清盛の力を見せつける大事業でもありました。","けれども1249年、お堂は火事で焼けてしまいます。人びとは必死に観音像を運び出したといわれ、平安時代の像も一部が残りました。鎌倉時代の1266年、お堂は建て直され、それが今の本堂です。仏師・湛慶が中央の大きな千手観音坐像を完成させ、多くの仏師たちが残りの像をつくりました。","お堂に入ると、ずらりと並ぶ金色の観音像に圧倒されます。«どうしてこんなにたくさん?»――千手観音は、たくさんの手と目で、すべての人を救ってくれる仏さま。その数を千にすることで、救いの力もいっそう大きくなると考えられたのです。1001体の中には、会いたい人に似た顔が必ずあると言い伝えられています。","お堂の両端には、風神・雷神の像や、観音さまを守る二十八部衆の像も並んでいます。どれも筋肉や表情が生き生きとして、鎌倉時代の彫刻の力強さを感じさせます。","江戸時代には、お堂の西側の縁側を使って、南から北の端まで約120mを矢で射通す «通し矢» が大流行しました。武士たちは記録を競い合い、一昼夜で何千本もの矢を射通す者もいたといいます。今も1月には、成人を迎えた人たちが弓を引く «大的大会» が行われます。"],"tl":[["1164年","後白河上皇の命で平清盛が蓮華王院を建てる"],["1249年","火災で焼ける"],["1254年","湛慶が中尊の千手観音坐像を完成させる"],["1266年","本堂が再建される（現在の本堂）"],["江戸時代","西縁での «通し矢» がさかんになる"],["2018年","千体の千手観音立像がすべて国宝に指定される"]],"who":[["後白河上皇","三十三間堂の建立を命じた"],["平清盛","上皇の命で造営した"],["湛慶","運慶の子。中尊の千手観音坐像をつくった仏師"],["和佐大八郎","江戸時代の紀州藩士。通し矢で大記録を残したと伝わる"]],"deep":["«三十三間» は、お堂の正面の柱と柱の間の数が33あることに由来します。33は観音さまが33の姿に変わって人を救うという教えにもつながります。","1001体の内訳は、中央の大きな坐像1体と、その左右に並ぶ等身大の立像1000体です。","千体の立像のうち、約120体は平安時代の創建時のもので、残りの多くは鎌倉時代の再興時のものとされます。","通し矢では、1686年に和佐大八郎が1万本余りのうち8千本余りを射通したという記録が伝わります。","お堂は長くて大きいため、地震対策として、地面の下に砂と粘土を交互に固めた地盤があるといわれ、昔の免震の工夫と考える説もあります。","三十三間堂は天台宗の妙法院が管理しています。"],"look":["1001体の千手観音像がならぶ内陣","中尊の千手観音坐像（湛慶作）","風神・雷神像と二十八部衆像","お堂の西側の縁（通し矢の舞台）","南大門と太閤塀（秀吉ゆかり）"],"q":["三十三間堂の名前の «三十三» は何の数?","お堂の正面の柱と柱の間の数です。"],"koji":[],"myth":"«会いたい人に似た顔がある» は言い伝え。通し矢の記録数や地盤の免震構造については諸説。","img":["蓮華王院","後白河天皇","湛慶","通し矢"],"wp":"三十三間堂","rel":{"ev":["kenchi"],"grave":[]}},{"id":"26_kurama","n":"鞍馬寺（牛若丸の修行伝説）","yomi":"くらまでら","cat":"伝承","rank":"A","y":1160,"era":["nara","heian"],"sh":"","ad":"京都市左京区鞍馬本町","st":"叡山電鉄 鞍馬駅から仁王門まで歩いて約3分（本殿へはケーブルと徒歩）","la":35.1167,"lo":135.771,"hook":"夜の山で天狗に剣を習った少年――牛若丸の伝説が、杉の巨木の根に今も息づいている。","lead":"鞍馬寺は京都の北の山の中にある古いお寺です。源義経が子どものころ «牛若丸» としてここに預けられ、天狗から剣術を習ったという伝説で有名です。山の中には、義経ゆかりとされる石や水の跡が点々と残っています。","story":["鞍馬寺の始まりは、奈良時代の770年、鑑真の弟子の鑑禎という僧が、夢のお告げでこの山に毘沙門天をまつったことだと伝わります。都の北を守るお寺として、平安時代には多くの人びとがお参りしました。","1159年の平治の乱で、源義朝は平清盛に敗れ、命を落とします。義朝の子・牛若丸は、まだ幼い子どもでした。命を助けられた牛若丸は、やがて鞍馬寺に預けられ、«遮那王（しゃなおう）» と呼ばれて修行の日々を送ったといわれます。","夜になると、牛若丸はこっそりお寺を抜け出し、奥の «僧正ガ谷» で剣の稽古をした――そんな伝説が生まれました。相手は、山に住む大天狗・鞍馬山僧正坊。«強くなって、いつか父のかたきを討つのだ»。杉の根がむき出しになった «木の根道» は、牛若丸が修行した場所と伝わります。","やがて牛若丸は、奥州（東北）の藤原秀衡をたよって鞍馬を去りました。山には、旅立つ前に背比べをしたという «背比べ石» や、のどをうるおしたという «息つぎの水» など、名残を伝える場所が残されています。のちに義経は平家をほろぼす大活躍をし、悲劇の英雄となりました。","ただし、天狗の話はもちろん伝説です。けれども、深い杉の森と、木の根がうねる山道に立つと、«ここなら天狗が出てきても不思議じゃない» と思えてきます。鞍馬寺は戦後に独立して «鞍馬弘教» の総本山となり、今も多くの参拝者が山道をのぼります。"],"tl":[["770年","鑑禎が毘沙門天をまつったのが始まりと伝わる"],["796年","藤原伊勢人が伽藍を整えたと伝わる"],["1159年","平治の乱で源義朝が敗れる"],["1160年代","牛若丸（義経）が鞍馬寺に預けられたと伝わる"],["1174年ごろ","義経が奥州へ向かったと伝わる"],["1949年","天台宗から独立し、鞍馬弘教の総本山となる"]],"who":[["源義経（牛若丸）","少年時代を鞍馬寺で過ごしたと伝わる"],["鞍馬山僧正坊","牛若丸に剣を教えたとされる伝説の大天狗"],["鑑禎","鞍馬寺を開いたと伝わる僧"],["源義朝","義経の父。平治の乱で敗れた"],["藤原秀衡","奥州藤原氏。鞍馬を出た義経をかくまった"]],"deep":["義経が鞍馬寺にいたことは『平治物語』や『義経記』などに記されますが、年齢や修行の中身、天狗の話は物語や伝説の要素が強いとされます。","寺の霊宝殿には、平安時代の毘沙門天立像（国宝）が安置されています。","«魔王殿» には、650万年前に金星から降り立ったとされる «護法魔王尊» がまつられているという独自の信仰があります。","山門近くの由岐神社では、毎年10月22日に «鞍馬の火祭» が行われ、京都三大奇祭の一つに数えられます。","«木の根道» は、岩盤が硬く、杉の根が地中にもぐれずに地表をはっているため生まれた景色だとされます。","鞍馬山から尾根を越えて貴船神社へ歩く道は、昔から人気の参詣ルートです。"],"look":["仁王門と由岐神社","本殿金堂前の «金剛床»","木の根道と背比べ石","僧正ガ谷不動堂と奥の院魔王殿","霊宝殿の毘沙門天像"],"q":["牛若丸に剣術を教えたと伝わるのはだれ?","鞍馬山に住む大天狗・僧正坊です。もちろん伝説です。"],"koji":[],"myth":"天狗との修行、背比べ石などの由来はすべて伝説。創建年・義経の在寺年代も伝承。","img":["源義経","鞍馬天狗","鞍馬の火祭","貴船神社"],"wp":"鞍馬寺","rel":{"ev":[],"grave":[]}},{"id":"26_yasaka","n":"八坂神社（祇園祭）","yomi":"やさかじんじゃ（ぎおんまつり）","cat":"寺社","rank":"A","y":869,"era":["heian","muromachi","edo"],"sh":"国宝（本殿）","ad":"京都市東山区祇園町北側","st":"京阪祇園四条駅から歩いて約5分","la":35.0037,"lo":135.7785,"hook":"1100年以上前の疫病退散の祈りが、日本一華やかな夏祭り «祇園祭» になった。","lead":"八坂神社は、京都の人に «祇園さん» と呼ばれて親しまれている神社です。7月の «祇園祭» は、平安時代に疫病をしずめるために始まったといわれ、豪華な山鉾が町を進みます。本殿は国宝に指定されています。","story":["平安時代、京都ではたびたび疫病がはやりました。人びとは、その原因を怨霊や疫病神のしわざだと考えました。869年、疫病をしずめるため、国の数にあわせて66本の鉾を立て、神泉苑で祈りをささげたといわれます。これが祇園祭の始まりと伝えられています。","八坂神社は、明治時代までは «祇園社» や «感神院» と呼ばれ、神さまと仏さまをいっしょにまつっていました。祭られていたのは «牛頭天王»。疫病をはらう力のある神さまで、のちに素戔嗚尊（スサノオノミコト）と同じ神とされました。","祇園祭の山鉾は、町の人びとがお金を出しあって守ってきたものです。«うちの町の鉾が一番きれいだ!» と、町ごとに飾りを競い合いました。応仁の乱で祭りはとだえますが、1500年、町衆の力で見事に復活します。戦乱の中でも祭りを守りたいという、京都の人びとの強い思いがあったのです。","山鉾には、ペルシャやヨーロッパから伝わったじゅうたんなどの布も飾られていて、«動く美術館» と呼ばれます。はるばる海を越えてきた品が、京都の祭りをいろどっているのです。","今の本殿は1654年に建てられたもので、本殿と拝殿を一つの大きな屋根でおおった «祇園造» という珍しい形です。2020年に国宝に指定されました。祇園祭は7月1日から1か月間続き、町中がお囃子の音「コンチキチン」に包まれます。"],"tl":[["656年","創建年として伝わる説の一つ（ほかに諸説）"],["869年","疫病をしずめる御霊会が行われ、祇園祭の起源とされる"],["応仁の乱のころ","祇園祭がとだえる"],["1500年","町衆によって祇園祭が再興される"],["1654年","現在の本殿が建てられる"],["1868年","神仏分離により «八坂神社» と名を改める"],["2009年","祇園祭の山鉾行事がユネスコ無形文化遺産に登録される"],["2020年","本殿が国宝に指定される"]],"who":[["素戔嗚尊","八坂神社の主祭神"],["牛頭天王","疫病をはらう神。素戔嗚尊と同じ神とされた"],["京都の町衆","山鉾を守り、祇園祭を再興した町の人びと"]],"deep":["創建については、656年に朝鮮半島からの使者がまつったという説や、平安時代の初めとする説など諸説があり、はっきりしません。","祇園祭では、«蘇民将来子孫也» と書いたお札のついた «ちまき» が授けられます。スサノオをもてなした蘇民将来の子孫は疫病からのがれられる、という伝説にもとづきます。","山鉾巡行は、7月17日の «前祭» と24日の «後祭» の2回に分かれています。","長刀鉾には、昔からのしきたりにより «生稚児» が乗り、しめ縄を切って巡行が始まります。","西楼門（重要文化財）は四条通の突き当たりにあり、朱色の門が祇園のシンボルになっています。","境内の «美御前社» は美容の神さまとして知られ、湧き水の «美容水» が人気です。"],"look":["四条通の突き当たりの朱色の西楼門","祇園造の本殿（国宝）","夜にちょうちんがともる舞殿","境内の美御前社","7月の祇園祭の山鉾（前祭・後祭）"],"q":["祇園祭は、もともと何を願って始まった祭り?","疫病をしずめることです。平安時代の869年に行われた御霊会が起源とされます。"],"koji":[],"myth":"創建年、869年の66本の鉾の話は伝承・諸説。","img":["祇園祭","牛頭天王","素戔嗚尊","蘇民将来"],"wp":"八坂神社","rel":{"ev":[],"grave":[]}},{"id":"26_koryuji","n":"広隆寺（秦氏と弥勒菩薩）","yomi":"こうりゅうじ","cat":"寺社","rank":"A","y":603,"era":["asuka","heian"],"sh":"国宝（弥勒菩薩半跏思惟像・桂宮院本堂ほか）","ad":"京都市右京区太秦蜂岡町","st":"京福電鉄 太秦広隆寺駅からすぐ","la":35.0153,"lo":135.7066,"hook":"ほおに指をそえて、そっとほほえむ仏さま。京都でいちばん古いお寺で、1400年の時をこえて考えごとを続けている。","lead":"広隆寺は、飛鳥時代に渡来系の豪族・秦河勝が聖徳太子から仏像をさずかって建てたと伝わる、京都最古のお寺です。有名な «弥勒菩薩半跏思惟像» は、国宝の第1号に選ばれた仏像の一つです。","story":["今から1400年ほど前、京都盆地の西、太秦のあたりには «秦氏» という一族が住んでいました。海の向こうの朝鮮半島から渡ってきたと伝わる人びとで、機織りや土木の技術にすぐれ、川をせき止めて田畑を開いていきました。","『日本書紀』によると、603年、聖徳太子が «だれかこの仏像をまつる者はいないか» とたずねると、秦河勝が進み出て仏像をいただき、寺を建てたといいます。これが広隆寺の始まりとされ、昔は «蜂岡寺» などとも呼ばれていました。","霊宝殿に入ると、うす暗い中に、ほっそりとした仏さまが座っています。右足を左のひざにのせ、右手の指をほおにそえて、何かを考えているような姿。«半跏思惟» と呼ばれるポーズです。弥勒菩薩は、遠い未来にこの世に現れて人びとを救う仏さま。«どうやってみんなを救おうか» と考えているのだといわれます。","この像は赤松の一木で彫られていて、日本の飛鳥時代の仏像の多くがクスノキでつくられているのとは違います。そのため、朝鮮半島でつくられて日本に運ばれたのではないか、という説があります。韓国の国立中央博物館にある金銅の弥勒菩薩像とよく似ていることも知られています。","平安時代には火事にあいましたが、再建されて、今の講堂は平安時代の建物です。昭和の1951年、弥勒菩薩像は «新しい国宝» の第1号として指定された仏像の一つになりました。京都の町なかで、1400年前の渡来の人びとの息づかいを感じられる、特別な場所です。"],"tl":[["603年","秦河勝が聖徳太子から仏像をさずかり寺を建てたと『日本書紀』に記される"],["818年","火災にあったとされる"],["1165年","講堂が建てられる（現存）"],["1251年","桂宮院本堂が建てられたとされる（国宝）"],["1951年","弥勒菩薩半跏思惟像が新国宝の第1号の一つとして指定される"]],"who":[["秦河勝","秦氏の長。広隆寺を建てた"],["聖徳太子","秦河勝に仏像をさずけたと伝わる"],["秦氏","渡来系の一族。太秦や嵯峨野を開いた"]],"deep":["«宝冠弥勒» と呼ばれる有名な像のほかに、泣いているような表情の «泣き弥勒»（宝髻弥勒）もあり、こちらも国宝です。","宝冠弥勒像の材が赤松であることは、日本製か朝鮮半島製かという論争の大きな根拠になっています。ただし日本でつくられたとする説もあり、決着していません。","«太秦（うずまさ）» の名は、『日本書紀』で秦氏が絹を «うず高く» 積んで献上したことに由来するとする説があります。","秦氏は桂川に «葛野大堰» と呼ばれる堰をつくったと伝わり、今の嵐山の渡月橋付近の «一の井堰» にその名残があるともいわれます。","桂宮院本堂は八角形の珍しいお堂で、聖徳太子をまつります。ふだんは非公開です。","1960年に学生が像の指を折ってしまう事故がありましたが、修復されました。"],"look":["霊宝殿の弥勒菩薩半跏思惟像（宝冠弥勒・泣き弥勒）","平安時代の講堂","楼門（南大門）","近くの蚕ノ社（木嶋坐天照御魂神社）の三柱鳥居"],"q":["広隆寺の宝冠弥勒像は、何の木でつくられている?","赤松です。日本の飛鳥仏にはクスノキが多いので、朝鮮半島製とする説の根拠になっています。"],"koji":[],"myth":"日本製か朝鮮半島製か、蜂岡寺の場所、寺の当初の位置には諸説。","img":["秦河勝","秦氏","弥勒菩薩","太秦"],"wp":"広隆寺","rel":{"ev":[],"grave":[]}},{"id":"26_tennozan","n":"天王山（山崎の戦い）","yomi":"てんのうざん（やまざきのたたかい）","cat":"古戦場","rank":"A","y":1582,"era":["azuchi"],"sh":"","ad":"京都府乙訓郡大山崎町","st":"JR山崎駅・阪急大山崎駅から山頂まで歩いて約1時間","la":34.9003,"lo":135.6785,"hook":"«ここが天王山だ» ――勝負どころを意味するこのことばは、本能寺の変のわずか11日後の戦いから生まれた。","lead":"天王山は、京都と大阪の境にある標高270mほどの山です。1582年、本能寺の変で織田信長を討った明智光秀と、急いで引き返してきた羽柴（豊臣）秀吉が、この山のふもとで戦いました。これが «山崎の戦い» です。","story":["1582年6月2日、明智光秀は京都の本能寺で主君・織田信長を討ちました。そのころ羽柴秀吉は、備中（岡山県）で毛利氏の高松城を攻めていました。知らせを聞いた秀吉は、すぐに毛利と和睦し、大軍をひきいて京都へ引き返します。これが «中国大返し» です。","«なぜそんなに急いだの?»――光秀より先に «主君のかたき討ち» をした者が、次の天下を手にできると秀吉は考えたのでしょう。光秀も、まさか秀吉がこんなに早く戻ってくるとは思っていなかったといわれます。","6月13日、両軍は山崎でぶつかりました。山崎は、天王山と淀川にはさまれた細い土地で、京都への入り口にあたる大切な場所です。天王山を先に押さえた方が有利になる――後の軍記物は、両軍が天王山を取り合ったように描いています。戦いは夕方に始まり、秀吉軍が数でまさって勝利しました。","敗れた光秀は、勝竜寺城に逃げこみ、夜のうちに近江の坂本城をめざしました。しかし、その途中の小栗栖（京都市伏見区）で、落ち武者狩りの農民におそわれて命を落としたと伝わります。本能寺の変から、わずか11日後のことでした。","この勝利で、秀吉は信長の後継者として一気に名乗りをあげます。«天下分け目の天王山» ということばは、やがて «勝負を決める大事なところ» という意味で使われるようになりました。いま山頂までの道には、戦いの流れを説明する陶板の絵が並び、山頂には秀吉が築いた山崎城の跡があります。"],"tl":[["1582年6月2日","本能寺の変"],["1582年6月上旬","秀吉が毛利と和睦し、中国大返しを始める"],["1582年6月13日","山崎の戦い。秀吉軍が勝利"],["1582年6月13日夜〜14日","光秀が小栗栖で落命したと伝わる"],["1582年","秀吉が天王山に山崎城を築き始める"],["1583年","秀吉が大坂城の築城を始め、山崎城はまもなく使われなくなる"]],"who":[["羽柴秀吉","中国大返しで引き返し、光秀を破った"],["明智光秀","本能寺の変で信長を討ったが、この戦いで敗れた"],["織田信長","本能寺の変で亡くなった"],["黒田官兵衛","秀吉の軍師。大返しを支えたと伝わる"]],"deep":["«天王山の奪い合いが勝敗を分けた» という話は、後の軍記物による脚色が大きいとされます。実際の主戦場は、円明寺川（今の小泉川）付近の平地だったと考えられています。","両軍の兵の数は、秀吉軍が約4万、光秀軍が約1万数千とする見方が多いですが、史料によって差があり、諸説あります。","中国大返しでは、高松城から姫路まで、大軍が短い日数で移動しました。その速さについては、あらかじめ準備していたのではないかという説もあります。","天王山の中腹にある宝積寺（宝寺）は、秀吉が本陣を置いたと伝わる寺で、«秀吉の一夜の城» の伝説もあります。","山頂には、禁門の変で敗れた真木和泉ら «十七烈士» の墓もあります。","天王山のふもとの大山崎は、中世には荏胡麻油の商売で栄えた町でした。"],"look":["山頂の山崎城跡（曲輪や石垣の名残）","中腹の «旗立松» 展望台","登山道の山崎合戦の陶板絵","宝積寺（宝寺）","十七烈士の墓"],"q":["«天下分け目の天王山» のもとになった戦いは?","1582年の山崎の戦いです。羽柴秀吉が明智光秀を破りました。"],"koji":[{"w":"天下分け目の天王山","m":"勝負を決める大事な場面のたとえ"},{"w":"三日天下","m":"ほんの短い間だけ権力をにぎること。光秀の天下が短かったことから（実際は十数日）"}],"myth":"天王山の争奪戦は軍記物の脚色とされる。兵数・光秀の最期の場所と時刻には諸説。","img":["明智光秀","中国大返し","山崎城"],"wp":"山崎の戦い","rel":{"ev":[],"grave":[]}},{"id":"26_myokian","n":"妙喜庵 待庵（利休の国宝茶室）","yomi":"みょうきあん（たいあん）","cat":"寺社","rank":"A","y":1582,"era":["azuchi"],"sh":"国宝（待庵）","ad":"京都府乙訓郡大山崎町竜光","st":"JR山崎駅から歩いてすぐ（見学は事前申し込み制）","la":34.8919,"lo":135.6773,"hook":"たった2畳。天下人・秀吉も頭を下げないと入れない、世界でいちばん小さな «宇宙»。","lead":"妙喜庵は山崎駅の目の前にある小さなお寺です。境内の茶室 «待庵» は、千利休がつくったと伝わる茶室の中で、今に残る唯一のものとされ、国宝に指定されています。見学は往復はがきでの事前申し込みが必要で、茶室には入らず外からのぞく形になります。","story":["1582年、山崎の戦いのころ、秀吉はこの近くに陣を置いていました。そこに呼ばれた茶人・千利休が、陣中につくった茶室が待庵のもとになった――そう伝えられています。その後、茶室は妙喜庵に移されたといわれます。","待庵の広さは、たった2畳。«どうしてこんなに狭いの?» 利休は、茶の湯を豪華な道具を見せびらかす場ではなく、主人と客が心を向き合わせる場にしたいと考えました。狭い空間では、身分の上下も意味を失います。","茶室の入り口は、ひざをついてはい入るほど小さな «にじり口»。武士も刀を外に置かなければ入れません。«天下人でも頭を下げて入る»――その約束ごとが、茶室の中を特別な世界にしました。","中に入ると、床の間の壁は土で四すみまで丸く塗りこめられ（«室床»）、天井は低く、竹や土の窓から、やわらかな光がさしこみます。狭いのに、なぜか広く感じる。利休の工夫がつまった空間です。","山崎は、京都と大坂を結ぶ交通の要所で、名水の地としても知られていました。のちに近くにはウイスキーの蒸留所もつくられています。«よい水のある所には、よい茶がある»。利休がこの地で茶の湯に向き合ったと伝わるのも、うなずける話です。戦いの直後のあわただしい時期に、秀吉と利休はどんな会話をかわしながら茶をたてたのでしょうか。","金ぴかの茶室をつくらせた秀吉と、わびしさの中に美を見つけた利休。やがてふたりの考えはすれ違い、利休は切腹を命じられます。駅前の静かな庵で、小さな茶室は今も、利休の «わび» の心を伝えています。"],"tl":[["室町時代","妙喜庵が開かれたと伝わる"],["1582年","山崎の戦いのころ、利休が秀吉の陣中に茶室をつくったと伝わる"],["その後","茶室が妙喜庵に移されたと伝わる"],["1591年","千利休が切腹"],["1951年","待庵が国宝に指定される"]],"who":[["千利休","わび茶を大成した茶人。待庵をつくったと伝わる"],["豊臣秀吉","山崎の戦いの勝者。利休を茶頭として重用した"],["功叔","妙喜庵の住職で、利休と親しかったと伝わる"]],"deep":["現存する国宝の茶室は、待庵（妙喜庵）、如庵（愛知県犬山市）、密庵（大徳寺龍光院）の3つです。","待庵を利休の作とする確かな同時代史料はなく、利休の作と «伝わる» 茶室とされます。つくられた時期や移築の経緯にも諸説があります。","にじり口の発想は、川舟の小さな出入口から得た、という話が伝わっていますが、伝承です。","床の間の «室床» は、四すみの柱を塗りこめて見せないことで、狭い空間の奥行きを感じさせる工夫とされます。","見学は往復はがきでの事前申し込み制で、人数や日程に限りがあります（内部には入れず、外からの拝観）。","妙喜庵の書院（重要文化財）もあわせて見学できます。","待庵の中は、茶をたてる主人の畳と客の畳の2畳に、板の間などが付いた構成とされます。天井は場所によって高さや仕上げを変え、狭い空間に変化をもたせています。"],"look":["待庵のにじり口","室床の床の間（外からのぞく）","下地窓・連子窓からの光","書院（重要文化財）","山崎駅前の立地（天王山のふもと、山崎の戦いの舞台）"],"q":["待庵の広さは何畳?","2畳です。利休の «わび» の考えを表す、とても小さな茶室です。"],"koji":[{"w":"わび","m":"質素で静かなものの中に深い美しさを見出す心"}],"myth":"待庵の利休作、陣中からの移築の話は伝承。にじり口の由来も伝承。","img":["待庵","千利休","茶室","わび茶"],"wp":"妙喜庵","rel":{"ev":["ogaeshi"],"grave":[]}},{"id":"26_ujigami","n":"宇治上神社（現存最古の神社建築）","yomi":"うじがみじんじゃ","cat":"寺社","rank":"A","y":1060,"era":["heian","kamakura"],"sh":"国宝（本殿・拝殿）、世界遺産","ad":"京都府宇治市宇治山田","st":"京阪宇治駅から歩いて約10分","la":34.8901,"lo":135.8113,"hook":"木の年輪が答えを出した――平安時代に切られた木でできた、日本でいちばん古い神社の本殿。","lead":"宇治上神社は、宇治川の東岸にある小さな神社です。本殿は平安時代後期の建物で、今残る神社の建物としては日本最古とされ、国宝に指定されています。1994年には «古都京都の文化財» の一つとして世界遺産に登録されました。","story":["宇治川をはさんで向かい側には、平等院鳳凰堂があります。宇治上神社は、平等院の鎮守（守り神）として大切にされたと伝わる神社です。まつられているのは、応神天皇とその子の菟道稚郎子（うじのわきいらつこ）、そして仁徳天皇です。","菟道稚郎子には、こんな話が伝わっています。父の応神天皇は、弟の菟道稚郎子に位をゆずるつもりでした。けれども彼は «兄さんこそふさわしい» とゆずり合い、なかなか決まりません。とうとう彼は自ら命を絶ち、兄が仁徳天皇になった――『日本書紀』はそう記しています。","本殿は、大きな覆屋（おおいや）の中に、小さなお社が3つ並ぶ珍しいつくりです。«この建物はいつ建てられたの?» 長いあいだ、はっきりとはわかりませんでした。そこで、奈良文化財研究所が木の年輪を調べる «年輪年代法» で調査したところ、使われた木が1060年ごろに切られたものだとわかりました。","1060年ごろといえば、藤原頼通が平等院を建てたすぐあと。宇治が貴族の別荘地としてにぎわっていた時代です。本殿の前の拝殿も鎌倉時代はじめの建物で、貴族の住まいである «寝殿造» の雰囲気を伝えています。","境内には、宇治七名水の一つ «桐原水» がわき出ています。昔は七つあった名水のうち、今もわき出ているのはここだけといわれます。静かな境内で、平安の空気をそのまま吸いこんでみてください。"],"tl":[["古代","菟道稚郎子の伝承が『日本書紀』に記される"],["1052年","対岸で藤原頼通が平等院を開く"],["1060年ごろ","本殿に使われた木が伐採される（年輪年代法による）"],["鎌倉時代前期","拝殿が建てられる"],["1994年","«古都京都の文化財» の一つとして世界遺産に登録"],["2004年","年輪年代調査の結果が発表される"]],"who":[["菟道稚郎子","応神天皇の子。宇治にゆかりの皇子"],["応神天皇","まつられている神"],["仁徳天皇","まつられている神。菟道稚郎子の兄"],["藤原頼通","対岸に平等院を建てた"]],"deep":["年輪年代法は、木の年輪のパターンを基準のデータと比べて、木が切られた年を知る方法です。宇治上神社の本殿では、1060年ごろという結果が出ました。","本殿の3つのお社は、それぞれ一間社流造で、中央のお社だけ少し小さく、左右の2つと形が少しちがいます。","拝殿は、屋根の形や蔀戸（しとみど）などに、貴族の住まいの要素がみられ、神社の建物としては珍しいものです。","平等院とともに宇治の信仰の中心で、平安時代には «離宮明神» と呼ばれ、近くの宇治神社と一対の神社でした。","本殿の奥には、ふだん入れない場所もあるので、案内に従って参拝しましょう。","«宇治七名水» はかつて宇治にあった7つの名水のことで、今残るのは桐原水だけとされます。"],"look":["覆屋の中に並ぶ3棟の本殿（国宝）","寝殿造風の拝殿（国宝）","桐原水","近くの宇治神社・さわらびの道","対岸の平等院"],"q":["宇治上神社の本殿の年代は、どうやって調べられた?","年輪年代法です。木が1060年ごろに切られたものだとわかりました。"],"koji":[],"myth":"菟道稚郎子の話は『日本書紀』などの伝承。平等院の鎮守とされる関係も伝承を含む。","img":["菟道稚郎子","平等院","宇治神社"],"wp":"宇治上神社","rel":{"ev":["byodoin","genji"],"grave":[]}},{"id":"26_ujigawa","n":"宇治川の先陣争い（宇治橋・橋寺放生院）","yomi":"うじがわのせんじんあらそい（うじばし・はしでらほうじょういん）","cat":"古戦場","rank":"A","y":1184,"era":["heian","kamakura","asuka"],"sh":"宇治橋断碑は国の重要文化財","ad":"京都府宇治市宇治東内（宇治橋・橋寺放生院）","st":"京阪宇治駅からすぐ（宇治橋）","la":34.8931,"lo":135.8093,"hook":"«われこそが一番乗り!» ――名馬にまたがった二人の武者が、宇治川の急流に飛びこんだ。","lead":"宇治川は、京都の南の入り口を守る大切な川で、何度も戦いの舞台になりました。1184年の戦いでは、源義経の軍の佐々木高綱と梶原景季が «先陣争い» をしたことが『平家物語』に描かれています。宇治橋の東のたもとの橋寺放生院には、宇治橋の由来を記した古い石碑が伝わります。","story":["宇治橋は、日本でもとても古い橋の一つです。橋寺放生院にある «宇治橋断碑» には、646年に道登という僧がこの橋をかけたと記されています。京都と奈良を結ぶ道の要所だったため、宇治川は何度も戦いの舞台になりました。","1184年、源頼朝は、京都にいた木曽義仲を討つため、弟の義経らを送りました。義仲の軍は宇治橋の板をはずし、川には太い綱をはって待ちかまえます。冬の雪どけで水かさが増し、川は白い波を立てて流れていました。","そこへ、頼朝から名馬 «生唼（いけずき）» をもらった佐々木高綱と、名馬 «磨墨（するすみ）» に乗った梶原景季がかけつけます。先に川に入ったのは景季でした。高綱は «馬の腹帯がゆるんでいるぞ» と声をかけ、景季が帯をしめなおしているすきに、一気に追いぬきます。","高綱は水の中の綱を刀で切りはらい、向こう岸に一番乗りしました。«宇多天皇より九代の後胤、佐々木四郎高綱、宇治川の先陣ぞや!»――『平家物語』は、高らかな名乗りを伝えています。義経の軍は宇治川をわたり、義仲はまもなく近江の粟津で最期をとげました。","宇治川は、1180年に以仁王と源頼政が平家と戦った場所でもあり、1221年の承久の乱でも激戦がありました。今、宇治川の中の島には «宇治川先陣之碑» が立っています。おだやかに見える川の流れの中に、武者たちのさけび声がとけこんでいるようです。"],"tl":[["646年","道登が宇治橋をかけたと宇治橋断碑に記される"],["1180年","以仁王・源頼政が宇治で平家と戦う（第1次宇治川の戦い）"],["1184年","源義経らが木曽義仲の軍を破る。佐々木・梶原の先陣争い"],["1221年","承久の乱で宇治川が戦場になる"],["1286年","叡尊が宇治川の中の島に十三重石塔を建てる"],["1791年","宇治橋断碑の上部が放生院の境内で見つかったとされる"]],"who":[["佐々木高綱","名馬・生唼に乗り先陣を果たした"],["梶原景季","名馬・磨墨に乗り先陣を争った"],["源義経","義仲追討軍をひきいた"],["木曽義仲","宇治川で義経軍をふせごうとした"],["道登","宇治橋をかけたと伝わる僧"]],"deep":["宇治橋断碑は、上部だけが江戸時代に見つかり、失われた下部は『帝王編年記』に残る碑文をもとに補われたとされます。橋をかけたのは道昭とする別の記録もあり、諸説があります。","宇治橋は、瀬田の唐橋・山崎橋とともに «日本三古橋» と呼ばれます。","宇治橋の上流側には、橋を守る神をまつった «三の間» と呼ばれる張り出しがあり、秀吉がここから茶の水をくませたという話が伝わります。","先陣争いの話は『平家物語』による描写で、細部は物語としての脚色を含みます。","中の島（塔の島）の十三重石塔は、鎌倉時代に叡尊が宇治川の魚の供養と殺生禁断を願って建てたとされ、国の重要文化財です。","放生院の名は、捕らえた生き物を川に放して命を救う «放生» の法会に由来します。"],"look":["宇治橋と «三の間»","橋寺放生院の宇治橋断碑（拝観は有料）","中の島の宇治川先陣之碑","塔の島の十三重石塔","宇治橋西詰の紫式部像"],"q":["宇治川の先陣争いで、一番乗りを果たした武将は?","佐々木高綱です。名馬・生唼に乗り、梶原景季を追いぬいたと『平家物語』は描きます。"],"koji":[{"w":"先陣争い","m":"一番乗りを争うこと。宇治川の佐々木・梶原の話が有名"}],"myth":"先陣争いの細部は『平家物語』の描写。宇治橋の架橋者は道登説と道昭説がある。","img":["宇治橋","佐々木高綱","梶原景季","宇治橋断碑"],"wp":"宇治川の戦い","rel":{"ev":["byodoin","genji"],"grave":[]}},{"id":"26_manpukuji","n":"萬福寺（隠元と黄檗宗）","yomi":"まんぷくじ","cat":"寺社","rank":"A","y":1661,"era":["edo"],"sh":"国宝（大雄宝殿・法堂・天王殿ほか）","ad":"京都府宇治市五ケ庄三番割","st":"JR・京阪 黄檗駅から歩いて約5分","la":34.914,"lo":135.8067,"hook":"門をくぐると、そこは江戸時代の «中国»。インゲン豆も、明朝体の文字も、ここから広まったといわれる。","lead":"萬福寺は、中国・明の僧、隠元隆琦が開いた黄檗宗の大本山です。建物もお経の読み方も、食事も中国風で、境内を歩くと外国に来たような気分になります。江戸時代の日本に、多くの新しい文化を伝えたお寺です。","story":["1654年、中国から一人の老僧が長崎に到着しました。名前は隠元隆琦。63歳でした。当時の中国は、明の王朝がほろび、清が力をのばしていた激動の時代です。長崎の中国人たちの熱心な招きに応じて、隠元は海を渡ってきたのでした。","«本場の禅を学びたい» ――多くの日本の僧たちが、隠元のもとに集まりました。隠元はやがて江戸で将軍・徳川家綱に会い、宇治の土地を与えられます。1661年、隠元はふるさとの寺と同じ «黄檗山萬福寺» という名前で、新しい寺を開きました。","萬福寺の建物は、明の時代の中国の様式でつくられています。丸い窓、卍を組み合わせた手すり、チーク材の柱。本堂の «大雄宝殿» の前に立つと、屋根の形も日本の寺とどこか違うことに気づきます。お経も中国の発音で読まれ、時を知らせるのは魚の形をした木の «開梆（かいぱん）» です。","隠元は、仏教だけでなく、たくさんのものを日本に伝えたといわれます。«インゲン豆» の名は隠元にちなむといわれ、ほかにも煎茶の文化や、中国風の精進料理 «普茶料理» などが広まりました。«食べることも修行の一つ»――萬福寺では今も普茶料理を味わうことができます。","隠元の弟子の鉄眼道光は、お経をすべて木の板に彫って印刷する «一切経» の出版に生涯をささげました。そのとき使われた文字の形が、今の «明朝体» のもとになったとする説もあります。何万枚もの版木は今も境内の宝蔵院に守られ、刷られ続けています。"],"tl":[["1592年","隠元が中国の福建で生まれる"],["1654年","隠元が長崎に来日"],["1658年","江戸で将軍・徳川家綱に会う"],["1661年","宇治に萬福寺を開く"],["1673年","隠元が亡くなる"],["1681年","鉄眼道光の一切経（鉄眼版）が完成したとされる"],["2014年","大雄宝殿・法堂・天王殿などが国宝に指定される"]],"who":[["隠元隆琦","萬福寺を開いた明の僧"],["徳川家綱","4代将軍。萬福寺の土地を与えた"],["鉄眼道光","隠元の弟子。一切経を出版した"],["後水尾上皇","隠元に帰依したと伝わる"]],"deep":["天王殿には、お腹を突き出して笑う布袋さまの像が弥勒菩薩としてまつられています。中国では布袋が弥勒の化身と考えられています。","«インゲン豆» を実際に隠元が持ってきたかは確かではなく、別の豆だったという説もあります。","鉄眼の一切経の版木は約6万枚ともいわれ、国の重要文化財に指定されています。","明朝体と鉄眼版のつながりについては、«日本の明朝体に影響を与えた» という見方がありますが、詳しくは諸説があります。","黄檗宗は江戸時代に日本の禅宗の一つとして広まり、臨済宗・曹洞宗とともに日本の三つの禅宗に数えられます。","萬福寺の建物は、回廊で結ばれた左右対称の伽藍配置で、中国の寺院の形をよく伝えています。"],"look":["大雄宝殿（チーク材の建物）","天王殿の布袋像","魚の形の «開梆»","卍くずしの勾欄と丸窓","宝蔵院の一切経版木"],"q":["«インゲン豆» の名前のもとになったといわれる人物は?","萬福寺を開いた中国の僧・隠元です（持ってきた豆の種類には諸説）。"],"koji":[],"myth":"インゲン豆の伝来、明朝体との関係、後水尾上皇の帰依の程度には諸説。","img":["隠元隆琦","黄檗宗","鉄眼道光","普茶料理"],"wp":"萬福寺","rel":{"ev":[],"grave":[]}},{"id":"26_joruriji","n":"浄瑠璃寺（当尾の九体阿弥陀）","yomi":"じょうるりじ","cat":"寺社","rank":"A","y":1107,"era":["heian"],"sh":"国宝（本堂・三重塔・九体阿弥陀如来像）、庭園は国の特別名勝・史跡","ad":"京都府木津川市加茂町西小","st":"JR加茂駅から木津川市コミュニティバスで約20分 «浄瑠璃寺前» 下車／奈良駅からもバスあり","la":34.7168,"lo":135.8726,"hook":"池の東に薬師さま、西に阿弥陀さま。この世とあの世を池で分けた、平安貴族の «極楽» が山里に残る。","lead":"浄瑠璃寺は、京都と奈良の境の山里 «当尾（とうの）» にあるお寺です。9体の阿弥陀如来がずらりと並ぶ本堂は、平安時代にたくさんつくられた «九体阿弥陀堂» の中で、ただ一つ残るものです。池を中心にした庭園は、極楽浄土を表しているといわれます。","story":["平安時代の後半、人びとは «末法» の世が来ると恐れていました。仏の教えがおとろえ、世の中が乱れる時代です。«せめて死んだあとは、阿弥陀さまの極楽浄土に生まれたい»――そんな願いから、貴族たちは阿弥陀如来をまつるお堂を競うように建てました。","浄瑠璃寺は、1047年に義明上人が開いたと寺の記録に伝わります。1107年には、9体の阿弥陀如来をまつる本堂が建てられたとされます。«なぜ9体なの?» ――人は生きている間の行いによって、極楽への生まれ方が9通りある、という «九品往生» の考えにもとづくといわれます。","寺の中心には «宝池» と呼ばれる池があります。池の東には、この世の苦しみを救う薬師如来をまつる三重塔、西には、あの世の極楽へ導く阿弥陀如来の本堂。朝日の昇る東から、夕日の沈む西の極楽を池ごしに拝む――庭全体が、この世からあの世への道をあらわしているのです。","三重塔は、平安時代の終わりに京都の一条大宮から移されたと伝わります。本堂の中に入ると、金色の阿弥陀さまが横一列に並び、中央の1体だけが大きく、ほかの8体をしたがえています。うす暗いお堂の中でその姿を見上げると、平安の人びとが思いえがいた極楽が目の前に広がるようです。","寺のまわりの当尾の里には、鎌倉時代などの石仏が山道のあちこちに残り、«当尾の石仏めぐり» として歩く人が絶えません。ふだんは秘仏の吉祥天女像も、決まった時期には公開され、その美しさで人びとを魅了しています。"],"tl":[["1047年","義明上人が寺を開いたと寺の記録に伝わる"],["1107年","九体阿弥陀の本堂が建てられたとされる"],["1157年","本堂が現在の位置に移されたとする説がある"],["1178年","三重塔が京都から移されたと伝わる"],["鎌倉時代","吉祥天女像がつくられる"],["明治時代","興福寺の末寺から真言律宗の寺となる"]],"who":[["義明上人","浄瑠璃寺を開いたと伝わる僧"],["阿弥陀如来","本堂に9体まつられる仏"],["薬師如来","三重塔にまつられる仏"],["吉祥天","秘仏として知られる美しい像の女神"]],"deep":["平安時代には、藤原道長の法成寺など、九体阿弥陀堂が多く建てられましたが、今も残るのは浄瑠璃寺の本堂だけです。","寺の名は、薬師如来の住む東方の «浄瑠璃浄土» に由来します。","本堂の建立年と、今の位置への移築については、寺の記録『浄瑠璃寺流記事』をもとに1107年建立・1157年移築とする見方がありますが、諸説があります。","9体の阿弥陀像は、中尊が約2.2mの丈六像、ほかの8体は半丈六ほどの大きさです。","吉祥天女像（重要文化財）は鎌倉時代の彩色像で、正月・春・秋の決まった期間だけ公開されます。","当尾の石仏群には、«わらい仏» や «あたご灯籠» など親しみやすいものが多く、岩船寺との間を歩く人が多いです。"],"look":["九体阿弥陀如来がならぶ本堂","宝池ごしに見る三重塔","東から西へ池を拝む配置","吉祥天女像（公開期間のみ）","当尾の石仏めぐりの山道"],"q":["浄瑠璃寺の本堂に、阿弥陀如来が9体もあるのはなぜ?","極楽への生まれ方が9通りあるという «九品往生» の考えにもとづくといわれます。"],"koji":[{"w":"末法","m":"仏の教えがおとろえ世が乱れるとされた時代。平安後期の浄土信仰の背景"}],"myth":"本堂の建立・移築年、三重塔の移築の経緯には諸説。九体の意味づけにも解釈の違いがある。","img":["九品往生","当尾","吉祥天","岩船寺"],"wp":"浄瑠璃寺","rel":{"ev":[],"grave":[]}},{"id":"26_kasagi","n":"笠置寺（元弘の乱・後醍醐天皇の行在所）","yomi":"かさぎでら（げんこうのらん・あんざいしょ）","cat":"古戦場","rank":"A","y":1331,"era":["nara","kamakura"],"sh":"国指定史跡・名勝（笠置山）","ad":"京都府相楽郡笠置町笠置山","st":"JR笠置駅から山道を歩いて約45分（車なら山上の駐車場まで行ける）","la":34.7535,"lo":135.9421,"hook":"巨大な岩に刻まれた仏と、天皇の «夢»。鎌倉幕府をゆるがした戦いは、この山から始まった。","lead":"笠置寺は、木津川を見下ろす笠置山の上にあるお寺です。山には巨大な岩がいくつもあり、岩に仏を刻んだ «磨崖仏» が信仰を集めてきました。1331年、後醍醐天皇が鎌倉幕府をたおそうとして、この山に立てこもりました。","story":["笠置山の頂上近くには、見上げるような巨大な岩があります。そこには、高さ15mほどの弥勒菩薩が刻まれていたといわれます。奈良時代ころからこの岩は信仰を集め、多くの人がはるばる山をのぼって拝みに来ました。«この岩の仏さまに会えば、救われる»――そんな思いで。","1331年、後醍醐天皇は、鎌倉幕府をたおす計画を進めていましたが、それが幕府に知られてしまいます。天皇はひそかに京都を抜け出し、けわしい岩山の笠置山に立てこもりました。これが «元弘の乱» の始まりです。","『太平記』には、こんな話があります。笠置山で天皇が夢を見ると、南の方に大きな木があり、その下に «ここに座りなさい» と席が用意されていた。«木の南――つまり «楠»。» 目覚めた天皇は、河内の武士・楠木正成を呼び寄せた、というのです。夢の話はもちろん物語ですが、正成はこのころ天皇方として立ち上がりました。","幕府の大軍が山を取りかこみ、激しい戦いが続きました。やがて、夜の風雨にまぎれて幕府軍が山に攻め入り、寺に火が放たれたと伝わります。天皇は山を逃れましたが捕らえられ、翌年、隠岐（島根県）に流されました。この戦いの火で、磨崖仏の多くも焼けてしまったといわれます。","けれども、物語はここで終わりません。後醍醐天皇はやがて隠岐を抜け出し、1333年、ついに鎌倉幕府はほろびます。今、笠置山には «行在所跡» の碑や、焼けた跡がのこる磨崖仏の岩が静かにたたずみ、岩のすき間をくぐる修行の道が続いています。"],"tl":[["奈良時代ごろ","笠置山の巨岩に磨崖仏が刻まれたとされる"],["1193年","貞慶（解脱上人）が笠置寺に入り、寺を栄えさせる"],["1331年8月","後醍醐天皇が笠置山に入る（元弘の乱）"],["1331年9月","笠置山が落ち、寺が焼ける。天皇は捕らえられる"],["1332年","後醍醐天皇が隠岐に流される"],["1333年","鎌倉幕府がほろびる"]],"who":[["後醍醐天皇","幕府をたおすため笠置山に立てこもった"],["楠木正成","天皇の夢の話で知られる河内の武士"],["貞慶（解脱上人）","鎌倉時代に笠置寺を栄えさせた僧"],["北条高時","当時の幕府の実力者（得宗）"]],"deep":["弥勒磨崖仏は火災で表面が焼け、今は仏の姿がほとんど見えず、光背の形などが残るだけです。一方、虚空蔵磨崖仏は線で刻まれた姿が今もよく見えます。","笠置山の磨崖仏は、奈良の東大寺の大仏づくりとのつながりを伝える話もありますが、伝承です。","«楠の夢» の話は『太平記』によるもので、史実かどうかは確かではありません。","境内の «胎内くぐり» や «ゆるぎ石» など、岩をめぐる修行の道が続き、山全体が信仰の場になっています。","笠置山は国の史跡・名勝に指定されており、春の桜や秋の紅葉の名所でもあります。","後醍醐天皇が笠置に逃れた理由の一つは、山が木津川ぞいの交通の要所で、けわしい岩山で守りやすかったことだと考えられています。"],"look":["弥勒磨崖仏の巨岩（焼けた跡）","線刻の虚空蔵磨崖仏","行在所跡の碑","胎内くぐり・ゆるぎ石などの修行場","山上から見下ろす木津川"],"q":["1331年、後醍醐天皇が笠置山に立てこもったことで始まった戦いは?","元弘の乱です。この戦いがきっかけとなり、1333年に鎌倉幕府はほろびました。"],"koji":[],"myth":"楠の夢の話は『太平記』の物語。磨崖仏の制作時期・東大寺との関係、落城の細部には伝承を含む。","img":["後醍醐天皇","元弘の乱","楠木正成","笠置山"],"wp":"笠置寺","rel":{"ev":[],"grave":[]}},{"id":"26_tsubai","n":"椿井大塚山古墳（三角縁神獣鏡）","yomi":"つばいおおつかやまこふん","cat":"遺跡","rank":"A","y":280,"era":["kofun"],"sh":"国指定史跡","ad":"京都府木津川市山城町椿井","st":"JR奈良線 上狛駅または棚倉駅から歩いて約15分","la":34.7627,"lo":135.8184,"hook":"線路工事のスコップが、卑弥呼の謎につながる鏡を30面以上も掘り当てた。","lead":"椿井大塚山古墳は、古墳時代のはじめごろにつくられた大きな前方後円墳です。1953年、線路の工事中に石室が見つかり、«三角縁神獣鏡» という鏡が30面以上も出てきました。邪馬台国やヤマト王権の成り立ちを考えるうえで、とても大切な古墳です。","story":["1953年、国鉄の線路を広げる工事をしていたとき、作業員のスコップが古墳の中の石室をつきあてました。中から出てきたのは、たくさんの鏡や鉄の武器・よろい。«これは大変なものが出たぞ»――調査が始まると、鏡は30面をこえ、そのほとんどが «三角縁神獣鏡» という特別な鏡でした。","三角縁神獣鏡は、ふちの断面が三角形で、神仙や霊獣の模様がある銅の鏡です。中国の歴史書『魏志倭人伝』には、邪馬台国の女王・卑弥呼が魏の皇帝から «銅鏡百枚» をもらったと書かれています。«この鏡こそ、卑弥呼の鏡ではないか?»――そう考える学者もいて、今も議論が続いています。","考古学者の小林行雄は、同じ型でつくられた «兄弟の鏡»（同笵鏡）が、各地の古墳から見つかっていることに注目しました。«ヤマトの王が鏡を地方の豪族に配り、仲間の証にしたのではないか»。椿井大塚山古墳の鏡は、その配布の中心にあった、と考えたのです。","古墳の長さは約175m。木津川を見下ろす丘の上にあり、ここに眠る人物は、川の交通をおさえた有力な首長だったと考えられています。ヤマトの王とどんな関係だったのか、想像がふくらみます。","いまも古墳の後円部の近くをJR奈良線の線路が通り、古墳の形を切るように走っています。出土した鏡は国の重要文化財に指定されています。近くの京都府立山城郷土資料館では、古墳について学ぶことができます。"],"tl":[["3世紀後半ごろ","古墳がつくられたと考えられる"],["1953年","国鉄の線路工事で石室が見つかり、三角縁神獣鏡などが出土"],["1950年代","小林行雄が同笵鏡の分析からヤマト王権の鏡の配布を論じる"],["2000年","国の史跡に指定される"]],"who":[["卑弥呼","邪馬台国の女王。魏から銅鏡をもらったと記される"],["小林行雄","考古学者。同笵鏡の研究で知られる"],["古墳の被葬者","木津川流域の有力な首長と考えられる（名は不明）"]],"deep":["出土した鏡の数は、三角縁神獣鏡が32面以上とされ、ほかの種類の鏡も含めると30数面になります（破片の数え方により諸説）。","三角縁神獣鏡は日本各地で数百面見つかっていて、«魏でつくられた» とする説と «日本でつくられた» とする説があり、決着していません。","«卑弥呼の鏡» の銅鏡百枚が三角縁神獣鏡だとすると、見つかっている数が多すぎるという反論もあります。","見つかったときの状況は急な工事の中だったため、鏡の置かれていた正確な位置などがわからない部分もあります。","古墳の築造時期は、奈良県の箸墓古墳などとともに、最も古い段階の前方後円墳の一つとする見方があります。","出土品は京都大学が保管しています。"],"look":["丘の上の墳丘（後円部）","古墳を横切るJR奈良線の線路","説明板と古墳からのながめ","近くの京都府立山城郷土資料館"],"q":["椿井大塚山古墳から30面以上見つかった鏡は何という鏡?","三角縁神獣鏡です。«卑弥呼の鏡» とする説もあり、議論が続いています。"],"koji":[],"myth":"三角縁神獣鏡と卑弥呼の鏡の関係は諸説。古墳の年代、鏡の正確な面数にも諸説。","img":["三角縁神獣鏡","卑弥呼","小林行雄","前方後円墳"],"wp":"椿井大塚山古墳","rel":{"ev":[],"grave":[]}},{"id":"26_iwashimizu","n":"石清水八幡宮（男山）","yomi":"いわしみずはちまんぐう","cat":"寺社","rank":"A","y":860,"era":["heian","edo"],"sh":"国宝（本殿など）、境内は国指定史跡","ad":"京都府八幡市八幡高坊","st":"京阪 石清水八幡宮駅からケーブルで «ケーブル八幡宮山上» へ、歩いて約5分","la":34.8797,"lo":135.7,"hook":"ふもとだけ拝んで帰ってしまったお坊さんの話は、『徒然草』の名場面。本当のお社は山の上にある。","lead":"石清水八幡宮は、京都の南、男山の上にある神社です。平安時代のはじめに九州の宇佐八幡宮から神さまを迎えたのが始まりで、都を守る神社として、また武士の神として信仰されました。本殿は国宝です。","story":["859年、奈良の大安寺の僧・行教は、九州の宇佐八幡宮にこもって祈っていました。すると «都の近くに移ってまつられたい» という八幡神のお告げを受けたといわれます。行教が男山に神さまを迎え、翌860年に社殿が建てられました。これが石清水八幡宮の始まりです。","男山は、都の南西にあたる場所。都を守る «裏鬼門» の守りとして、朝廷はこの神社をとても大切にしました。天皇や上皇のお参りもたびたびあり、伊勢神宮とならぶほどの格の高い神社とされました。","八幡神は、武士にとっても大切な神さまでした。源義家は、この社の前で元服したことから «八幡太郎» と呼ばれたといわれます。源氏が八幡神を守り神にしたことで、全国の武士の間に八幡信仰が広がりました。","鎌倉時代の『徒然草』には、おもしろい話があります。仁和寺のお坊さんが、年をとってはじめて石清水にお参りしました。ところが、山のふもとの寺や社だけを拝んで、«思っていたより立派だった» と満足して帰ってしまいます。«みんな山に登っていたけれど、何があるのだろう»――じつは本当のお社は山の上にあったのです。兼好法師は «少しのことにも、先達（案内する人）はあらまほしきことなり» としめくくっています。","今の本殿は、1634年に徳川家光によって建てられたものです。二つの建物を前後につなげた «八幡造» と呼ばれる形で、2016年に国宝に指定されました。境内には、発明王エジソンが電球のフィラメントにこのあたりの竹を使ったことを記念する碑もあります。"],"tl":[["859年","行教が宇佐八幡宮で神託を受けたと伝わる"],["860年","男山に社殿が建てられる"],["1063年ごろ","源頼義が鎌倉に八幡神を勧請（のちの鶴岡八幡宮）"],["鎌倉時代","『徒然草』に仁和寺の法師の話が書かれる"],["1634年","徳川家光が現在の本殿を造営"],["1868年","鳥羽・伏見の戦いで、ふもとの橋本などが戦場になる"],["2016年","本殿など10棟が国宝に指定される"]],"who":[["行教","宇佐から八幡神を迎えた僧"],["源義家（八幡太郎）","石清水で元服したといわれる武将"],["兼好法師","『徒然草』で石清水の話を書いた"],["徳川家光","現在の本殿を造営した"],["トーマス・エジソン","八幡の竹を電球のフィラメントに使ったとされる"]],"deep":["石清水八幡宮は、宇佐神宮・筥崎宮（または鶴岡八幡宮）とともに «日本三大八幡宮» に数えられることがあります。","毎年9月15日の «石清水祭» は、天皇の使いが参向する勅祭で、日本三大勅祭の一つとされます。","本殿の «黄金の雨樋» は、織田信長が寄進したものと伝わります。","エジソンは白熱電球の改良で、世界中の植物を調べたすえ、八幡周辺の真竹を使ったと伝わり、境内に記念碑が立っています。","«石清水» の名は、山の中腹にわく清水に由来し、今も «石清水社» にその井戸があります。","明治の神仏分離まで、山上には多くの寺院があり、神と仏をいっしょにまつる «宮寺» でした。"],"look":["八幡造の本殿と楼門（国宝）","信長寄進と伝わる黄金の雨樋","エジソン記念碑","石清水社の井戸","展望台から見る京都盆地と三川合流"],"q":["『徒然草』で、仁和寺のお坊さんがしてしまった失敗とは?","ふもとの寺社だけを拝んで、山の上の本社に行かずに帰ってしまったことです。"],"koji":[{"w":"先達はあらまほしきことなり","m":"どんな小さなことでも、案内してくれる人がいてほしいものだ（『徒然草』）"}],"myth":"義家の元服の場所、黄金の雨樋の信長寄進、エジソンと八幡の竹の話には伝承を含む。","img":["男山 (京都府)","行教","徒然草","源義家"],"wp":"石清水八幡宮","rel":{"ev":[],"grave":[]}},{"id":"26_kameyamajo","n":"丹波亀山城（明智光秀の居城）","yomi":"たんばかめやまじょう","cat":"城","rank":"A","y":1582,"era":["azuchi","edo","taisho"],"sh":"","ad":"亀岡市荒塚町","st":"JR嵯峨野線 亀岡駅から歩いて約10分","la":35.0156,"lo":135.5748,"hook":"1582年6月、明智光秀はこの城から1万余の兵を率いて夜の山道へ出た。行き先は、京都の本能寺だった。","lead":"丹波亀山城は、明智光秀が丹波（今の京都府中部）を治めるために築いた城です。本能寺の変のとき、光秀の軍勢はここから出発しました。江戸時代には大きな天守がそびえましたが、今は石垣などが残る «城跡» で、宗教法人 «大本» の敷地になっています。","story":["天正のはじめ、織田信長は明智光秀に «丹波を攻め取れ» と命じました。丹波は山が深く、地元の武士たちが城にこもって強く抵抗する土地です。光秀は何年もかけて一つずつ城を落としていきました。その拠点として保津川（大堰川）のほとりの丘に築いたのが、この亀山城です。京都へは老ノ坂を越えればすぐ。丹波と京都をつなぐ «のど元» のような場所でした。","1582年6月1日の夕方、光秀は «中国地方で戦う羽柴秀吉を助けに行く» という名目で兵を集め、亀山城を出発しました。ふつうなら西へ向かうはず。ところが軍勢は東の老ノ坂へ進みます。«なぜ京都へ?» 兵の多くは理由を知らなかったといわれます。夜明け前、桂川を渡ったところで目的が告げられたと伝わり、有名な «敵は本能寺にあり» という言葉は、後の時代の書物で広まったものです。","本能寺の変のわずか11日後、光秀は山崎の戦いで敗れ、亀山城に戻ることはありませんでした。城はその後、信長の四男で秀吉の養子になった羽柴秀勝らが城主となります。関ヶ原の戦いのあと、1610年ごろには徳川家康が西国の大名に命じて城を大きく作り直させました（天下普請）。石垣の設計は、築城の名手として知られる藤堂高虎が担当したといわれます。","江戸時代の亀山城には五重の天守がそびえ、城下町は山陰道の宿場としてにぎわいました。1869年、伊勢国（三重県）の亀山と区別するため、地名は «亀岡» に改められます。明治のはじめに城は払い下げられ、建物はとりこわされ、石垣も多くが運び出されて、荒れ果てていきました。","1919年、この荒れた城跡を買い取ったのが、出口王仁三郎が率いた宗教団体 «大本» です。信者たちが石垣を積み直し、ここを «天恩郷» と呼んで本部の一つにしました。しかし1935年の第二次大本事件で、国は大本の施設をダイナマイトで壊してしまいます。戦後、大本は再びこの地で活動を続け、光秀の城の記憶と、近代の宗教弾圧の記憶が、同じ石垣に重なることになりました。"],"tl":[["1577年ごろ","明智光秀が丹波攻めの拠点として築城を始めたとされる"],["1579年","光秀が丹波をほぼ平定"],["1582年6月1日","光秀の軍勢が亀山城から出陣。翌2日未明、本能寺の変"],["1582年6月13日","山崎の戦いで光秀が敗れる"],["1610年ごろ","天下普請で城が大改修される"],["1869年","地名が «亀山» から «亀岡» に変わる"],["1877年ごろ","明治政府の方針で建物がとりこわされる"],["1919年","大本が城跡を買い取る"],["1935年","第二次大本事件で大本の施設が破壊される"]],"who":[["明智光秀","築城者。丹波平定の拠点とし、本能寺の変ではここから出陣した"],["羽柴秀勝","信長の四男で秀吉の養子。光秀のあとの城主の一人"],["藤堂高虎","江戸初期の大改修で縄張り（設計）を担当したといわれる"],["出口王仁三郎","大本の指導者。荒れた城跡を買い取り、石垣を積み直させた"]],"deep":["光秀の出陣ルートには «老ノ坂越え» のほか、«唐櫃越（からとごえ）»«明智越» などの山道を使ったという説もあり、軍勢を分けて進んだ可能性も議論されています。","天下普請の石垣には、工事を分担した大名が目印として刻んだ «刻印石» が見られるといわれ、どの大名が担当したかを探る手がかりになります。","江戸時代初めの五重天守は、藤堂高虎が今治城（愛媛県）から移したものだという言い伝えがあります。ただし確かな史料による裏付けは十分でなく、諸説の一つです。","城主は江戸時代に何度も入れ替わり、最後は形原松平家が明治まで治めました。城下町の南郷池は、かつての外堀の名残とされています。","大本が積み直した石垣は、江戸時代の石と近代に積んだ部分が混ざっています。どこが古いか見比べるのも、城好きの楽しみ方です。","1935年の第二次大本事件は、治安維持法などを理由にした大規模な宗教弾圧でした。戦後の裁判で治安維持法違反は無罪となっています。"],"look":["大本の受付で申し込んで見学できる本丸付近の石垣（見学のきまりに従うこと）","城の外堀の名残とされる南郷池と南郷公園","亀岡駅から城跡へ向かう道の、城下町らしい町割り","光秀の銅像がある南郷公園"],"q":["亀山城のあった «亀山» が «亀岡» に名前を変えたのはなぜ？","1869年、伊勢国（三重県）の亀山と区別するためです。"],"koji":[{"w":"敵は本能寺にあり","m":"本当のねらいは別のところにある、という意味で使われる。光秀が言ったという確かな記録はなく、後世の書物で広まった"}],"myth":"«敵は本能寺にあり» の言葉、天守の今治城からの移築、出陣ルートには諸説がある。","img":["明智光秀","本能寺の変","藤堂高虎","大本"],"wp":"亀山城 (丹波国)","rel":{"ev":[],"grave":[]}},{"id":"26_shinomura","n":"篠村八幡宮（足利尊氏挙兵の地）","yomi":"しのむらはちまんぐう","cat":"寺社","rank":"A","y":1333,"era":["kamakura","heian"],"sh":"","ad":"亀岡市篠町篠","st":"JR嵯峨野線 馬堀駅から歩いて約20〜25分","la":35.0003,"lo":135.6012,"hook":"鎌倉幕府を倒す «裏切り» の合図は、丹波の小さな八幡宮で上がった。","lead":"篠村八幡宮は、足利高氏（のちの尊氏）が鎌倉幕府に反旗をひるがえした場所です。1333年、幕府の命令で後醍醐天皇の軍と戦うはずだった高氏は、ここで逆に天皇の味方になると宣言し、京都の六波羅探題を攻め落としました。","story":["1333年の春、鎌倉幕府は大あわてでした。隠岐の島に流したはずの後醍醐天皇が島を抜け出し、各地の武士が天皇のもとに集まり始めていたからです。幕府は有力な御家人・足利高氏に大軍を預けて西へ向かわせました。«天皇方をたたけ» というわけです。ところが高氏の心の中には、別の考えがありました。","京都を出た高氏の軍は、老ノ坂を越えて丹波の篠村に入りました。ここは足利家の領地があったといわれる場所です。高氏は八幡宮の神前で願文をささげ、«幕府を倒し、天皇に味方する» と宣言しました。«源氏の氏神・八幡さまの前で、源氏の子孫として立ち上がる» ― それが、いちばん心を動かす演出だったのでしょう。","境内には «旗立楊（はたたてやなぎ）» と呼ばれる柳があります。高氏がこの木に源氏の白旗を掲げたと伝わる場所です。旗を見た近くの武士たちは続々と集まり、軍勢はみるみるふくらんだといいます。また兵たちが一本ずつ矢を奉納し、それを埋めたと伝わる «矢塚» も残っています。","高氏の軍は再び老ノ坂を越えて京都へ攻め入り、5月7日、幕府の西の拠点・六波羅探題を攻め落としました。逃げ出した北条仲時らは近江の番場で追いつめられ、多くの人が自害しました。同じころ関東では新田義貞が鎌倉を攻め、5月22日、鎌倉幕府は滅びます。高氏はその後、天皇から «尊» の字をもらい、«尊氏» と名乗りました。","八幡宮そのものの歴史はもっと古く、平安時代の1071年に源頼義が河内国（大阪府）の誉田八幡宮から神さまを迎えたのが始まりと伝わります。源氏とのつながりが深い神社だったからこそ、尊氏はここを旗揚げの舞台に選んだのでしょう。今は静かな住宅地の中の神社ですが、日本の歴史の大きな曲がり角がここにありました。"],"tl":[["1071年","源頼義が誉田八幡宮から神を迎えて創建したと伝わる"],["1331年","後醍醐天皇が倒幕の兵を挙げる（元弘の変）"],["1332年","後醍醐天皇が隠岐に流される"],["1333年4月下旬","足利高氏が篠村八幡宮で願文をささげ、倒幕に立つ"],["1333年5月7日","高氏の軍が六波羅探題を攻め落とす"],["1333年5月22日","新田義貞が鎌倉を攻め、鎌倉幕府が滅亡"],["1338年","尊氏が征夷大将軍になる"]],"who":[["足利尊氏（高氏）","ここで倒幕の兵を挙げた。のちの室町幕府初代将軍"],["後醍醐天皇","倒幕を目指した天皇。高氏はこの天皇の側についた"],["足利直義","尊氏の弟。兄とともに行動した"],["源頼義","平安時代の武将。この八幡宮を開いたと伝わる"]],"deep":["尊氏が奉納したとされる願文が神社に伝わっています。倒幕を神に誓う内容で、挙兵の日付を知る手がかりとされますが、細かな日付の読み方には議論もあります。","尊氏がなぜ幕府を裏切ったのかは諸説あります。北条氏への不満、父の喪中に出陣させられた恨み、源氏の棟梁として天下を狙った、などさまざまに語られます。","«旗立楊» は代々植えつがれてきた柳とされ、今の木が当時のものではありません。場所の記憶を伝える目印と考えるとよいでしょう。","篠村は京都から山陰道で丹波に入った最初の平地で、軍勢を集めるのに向いていました。のちの明智光秀の出陣路（老ノ坂）とも重なり、京都攻めの «入り口» だったことがわかります。","尊氏は挙兵後、この地を大切にし、所領を寄進したと伝わります。足利家にとって、ここは «運命が開けた場所» でした。"],"look":["尊氏が白旗を掲げたと伝わる «旗立楊»","兵たちの矢を埋めたと伝わる «矢塚»","本殿と境内に立つ «足利高氏旗揚げの地» の案内","近くの国道9号・老ノ坂方面の地形（京都への近さを実感できる）"],"q":["足利高氏が篠村八幡宮を旗揚げの場に選んだ理由の一つは？","八幡神が源氏の氏神だったから。源氏の子孫として兵を集めるのにふさわしい場所でした。"],"myth":"旗立楊・矢塚の話は伝承。挙兵の正確な日付や裏切りの動機には諸説がある。","img":["足利尊氏","六波羅探題","元弘の乱","後醍醐天皇"],"wp":"篠村八幡宮","rel":{"ev":[],"grave":[]}},{"id":"26_fukuchiyamajo","n":"福知山城（光秀の城）","yomi":"ふくちやまじょう","cat":"城","rank":"A","y":1579,"era":["azuchi","edo","showa"],"sh":"","ad":"福知山市字内記","st":"JR福知山駅から歩いて約15分","la":35.2968,"lo":135.1223,"hook":"石垣をよく見ると、お墓の石や石仏がはめこまれている。光秀の城は、ふしぎな石でできていた。","lead":"福知山城は、明智光秀が丹波を治めるために築いた城です。今の天守は1986年に市民の協力で再建されたもの。でも石垣には光秀の時代の «転用石»（墓石や石塔を使った石）がたくさん残り、光秀の城の姿を今に伝えています。","story":["1579年、丹波をほぼ平定した明智光秀は、由良川と土師川が合流する小高い丘に新しい城を築きました。北の丹後、西の但馬へ通じる交通の要所です。城代には一族の明智秀満（左馬助）を置いたといわれます。ここは «福知山» と呼ばれるようになりますが、光秀が地名を改めたと伝わるものの、はっきりした記録は残っていません。","城の石垣を近くで見ると、ちょっと驚きます。五輪塔や宝篋印塔、石仏、墓石が、積み石の中にたくさん混ざっているのです。«なぜ、そんな石を?» 短い期間で城を築くために近くの寺などから石を集めたという説、古い権威を打ち破る意味があったという説などがあり、はっきりした答えはありません。","光秀は城下町づくりにも力を入れたと伝わります。暴れ川だった由良川の流れを変え、堤防を築いた話や、町の人の税（地子銭）を免除した話が語られ、地元では今も «光秀さん» として親しまれています。光秀をまつる御霊神社があり、夏の «福知山踊り» にも光秀をたたえる歌詞があります。","しかし1582年、本能寺の変のあと光秀は山崎で敗れ、城の主は次々と入れ替わりました。江戸時代の1669年からは朽木家が城主となり、明治まで福知山藩を治めます。明治の廃城で、建物のほとんどはとりこわされ、城跡は長く石垣だけの丘になりました。","昭和の終わり、«もう一度天守を» という声が高まり、市民が瓦を一枚ずつ寄付する «瓦一枚運動» が広がりました。そして1986年、古い絵図などをもとに三層四階の天守が再建されます。天守の中は郷土資料館。光秀の築いた石垣の上に、市民の思いがこもった天守が立っているのです。"],"tl":[["1579年","光秀が丹波をほぼ平定し、築城を始めたとされる"],["1582年6月","本能寺の変。13日の山崎の戦いで光秀が敗れる"],["1600年","関ヶ原の戦いのあと有馬豊氏が入り、城と町を整える"],["1669年","朽木稙昌が入り、以後幕末まで朽木家が治める"],["1873年","廃城令により、建物の多くがとりこわされる"],["1986年","市民の寄付をもとに天守が再建される"]],"who":[["明智光秀","築城者。治水や町づくりの伝承が残り、地元で慕われる"],["明智秀満","光秀の一族。城代として福知山城を預かったといわれる"],["有馬豊氏","関ヶ原のあとの城主。城と城下町を整備した"],["朽木稙昌","朽木家初代の福知山藩主。以後200年ほど朽木家が治めた"]],"deep":["石垣に使われた転用石は数百点にのぼるとされ、年号が刻まれた石もあります。その年号は、城ができる前の石だという証拠になります。","天守台の石垣は、自然の石をほとんど加工せずに積む «野面積み» で、光秀の時代の古い積み方をよく残すと評価されています。","本丸には «豊磐井（とよいわのい）» と呼ばれる深い井戸があり、城の井戸としてはとても深いものとして知られています。","再建天守は、大天守と小天守が並ぶ形で、古い絵図や写真などを参考にした «復興» です。完全に昔と同じかどうかは史料の限界があります。","城内に残る «銅門番所» は、本来は二の丸の門の番所で、明治以後に移されて今の場所に建っています。","光秀が «福智山» を «福知山» に改めたという話は伝承で、確かな一次史料は見つかっていません。"],"look":["天守台の野面積みの石垣と、その中の転用石（石仏・墓石）","再建天守の最上階からの由良川と城下町のながめ","本丸の深い井戸 «豊磐井»","移築された銅門番所","城下の御霊神社（光秀をまつる）"],"q":["福知山城の石垣に多く使われている、ふつうとちがう石とは？","墓石や五輪塔、石仏などを使った «転用石» です。"],"myth":"地名を光秀が改めた話、治水や税免除の話は伝承。転用石を使った理由も諸説ある。","img":["明智光秀","転用石","由良川","福知山藩"],"wp":"福知山城","rel":{"ev":[],"grave":[]}},{"id":"26_oeyama","n":"大江山（酒呑童子伝説）","yomi":"おおえやま","cat":"伝承","rank":"A","y":990,"era":["heian","muromachi"],"sh":"","ad":"福知山市大江町・与謝野町・宮津市の境","st":"京都丹後鉄道 大江駅から車で約20分（«日本の鬼の交流博物館» まで。バスは本数が少ない）","la":35.443,"lo":135.112,"hook":"都から姫たちをさらった鬼の王・酒呑童子。そのすみかとされた山は、いまも雲の海に浮かんでいる。","lead":"大江山は、京都府北部にある連山で、鬼の «酒呑童子» が住んでいたという伝説で知られます。源頼光と四天王が山伏に化けて鬼を退治した話は、絵巻や能、子どもの絵本にもなりました。ふもとには鬼をテーマにした博物館があります。","story":["むかし、一条天皇のころ（10世紀の終わり）。都では若い娘や姫が次々と姿を消す事件が起きていました。陰陽師・安倍晴明が占うと、«丹波の大江山に住む鬼のしわざ» と出ます。鬼の頭は «酒呑童子»。その名のとおり大酒のみで、手下の鬼たちと山奥の岩屋で宴を開いているというのです。","帝の命令を受けたのは源頼光。渡辺綱、坂田金時（金太郎）、碓井貞光、卜部季武の «四天王» と藤原保昌を連れて、山伏の姿に化けて山に入りました。途中で出会ったふしぎな老人たちから «神便鬼毒酒» という酒をもらいます。人が飲めば力が出るのに、鬼が飲むと力が抜けてしまう、魔法の酒です。","鬼の館にたどり着いた一行は、«道に迷った山伏です» と一夜の宿を頼みました。酒呑童子は疑いながらも宴に招き入れます。頼光たちが差し出した酒を飲んだ鬼は、上機嫌で身の上を語りはじめ、やがて眠りこけてしまいました。その時、頼光は刀を抜きます。はねられた首は宙に舞い、頼光のかぶとにかみついたといいます。«鬼に横道（おうどう）なきものを!» ― だましうちをなじる鬼の叫びだったと語られます。","この物語は室町時代に絵巻『大江山絵詞』や能『大江山』として広まりました。でも «なぜ鬼は大江山に?» 大江山には古くから鉱物がとれたことから、鬼の正体は鉱山で働く人びとや、都に従わない地方の勢力だったのでは、という説もあります。また、京都と丹波の境にある «大枝山（老ノ坂）» こそ本当の舞台だという説もあり、答えは一つではありません。","大江山にはもう一つ、飛鳥時代に麻呂子親王（聖徳太子の弟とされる）が鬼を退治したという伝説もあります。今、ふもとの «日本の鬼の交流博物館» には、世界中の鬼の面や資料が集められています。秋から冬の朝には、山の上から «雲海» が見られることもあり、鬼の伝説にふさわしい幻想的な景色が広がります。"],"tl":[["飛鳥時代（伝承）","麻呂子親王が大江山の鬼を退治したと伝わる"],["990年ごろ（伝承）","一条天皇の時代、源頼光らが酒呑童子を退治したとされる"],["14世紀","絵巻『大江山絵詞』が作られる"],["室町時代","能『大江山』や御伽草子で物語が広まる"],["1993年","ふもとに «日本の鬼の交流博物館» が開館"],["2007年","丹後天橋立大江山国定公園に指定される"]],"who":[["源頼光","鬼退治の大将。平安時代に実在した武士"],["渡辺綱・坂田金時","頼光四天王。金時は «金太郎» のモデルとされる"],["酒呑童子","大江山に住んだとされる鬼の頭"],["藤原保昌","頼光に同行したとされる武人。和泉式部の夫"],["麻呂子親王","もう一つの鬼退治伝説の主人公"]],"deep":["源頼光や藤原保昌は実在の人物ですが、鬼退治は物語です。実在の武士を主人公にすることで、話に «本当らしさ» が加わりました。","最古級の絵巻とされる『大江山絵詞』（逸翁美術館蔵）は重要文化財です。物語の古い形を知る大事な手がかりです。","«大江山» がどの山かについては、丹後・丹波の大江山連峰とする説と、京都市西京区と亀岡市の境の «大枝山（老ノ坂）» とする説があります。","酒呑童子の生まれについても、越後（新潟県）生まれ説、近江（滋賀県）の伊吹山出身説など、地域ごとにさまざまな伝承があります。","大江山ではかつてニッケルなどが採掘されました。第二次世界大戦中の鉱山では、連合軍の捕虜や、中国・朝鮮半島から連れてこられた人びとが働かされたことも、忘れてはならない歴史です。","百人一首の «大江山いく野の道の遠ければ» の «大江山» は、老ノ坂付近の大枝山を指すとする説が有力です。"],"look":["«日本の鬼の交流博物館» の鬼の面と大きな鬼瓦","鬼嶽稲荷神社付近から見る雲海（秋〜冬の早朝）","登山道の «鬼の足跡» «頼光の腰掛岩» など伝説の場所","ふもとの元伊勢内宮・皇大神社（あわせて参拝する人が多い）"],"q":["頼光たちが鬼を眠らせるために使った酒の名前は？","«神便鬼毒酒»。人が飲むと力が出て、鬼が飲むと力が抜ける酒とされます。"],"koji":[{"w":"鬼に横道なし","m":"鬼はうそをつかない、という意味。だまし討ちにされた酒呑童子が言ったとされる"}],"myth":"酒呑童子の話は伝説。舞台の山、鬼の正体、出生地には諸説がある。","img":["酒呑童子","源頼光","坂田金時","大江山絵詞"],"wp":"大江山","rel":{"ev":[],"grave":[]}},{"id":"26_hikiage","n":"舞鶴引揚記念館（引揚の岸壁）","yomi":"まいづるひきあげきねんかん","cat":"昭和","rank":"A","y":1945,"era":["showa"],"sh":"","ad":"舞鶴市字平（舞鶴引揚記念公園）","st":"JR東舞鶴駅からバスで約20分 «引揚記念館前» 下車","la":35.4777,"lo":135.3657,"hook":"«いつかこの岸壁に、息子が帰ってくる» ― 母はそう信じて、何年も船を待ち続けた。","lead":"第二次世界大戦のあと、海外に取り残された日本人が船で帰ってきた «引揚げ»。舞鶴港には13年間で約66万人が帰り着きました。記念館では、シベリア抑留の記録や、家族を待った人びとの思いを伝えています。","story":["1945年8月、戦争が終わったとき、中国東北部（旧満州）や朝鮮半島、樺太、南の島々などには、兵士や一般の人をあわせて600万人以上の日本人がいたといわれます。国を失ったような状態で、人びとは «どうやって帰ればいいのか» と途方に暮れました。こうした人びとを迎える港の一つに選ばれたのが、日本海に面した舞鶴でした。","とくにつらかったのが «シベリア抑留» です。ソ連軍は多くの日本兵や民間人をシベリアなどへ連れて行き、極寒の中で木の切り出しや鉄道づくりなどの重労働をさせました。食べ物は少なく、寒さと病気で多くの人が亡くなりました。舞鶴は、こうした抑留者が帰ってくる港として、最後まで役目を果たしました。","引揚船が着く日、岸壁には家族を捜す人たちが集まりました。名前を書いたのぼりを掲げ、«〇〇はいませんか» と声をかける。その中に、東京から何度も通い、息子の帰りを待ち続けた母がいました。この姿は歌謡曲 «岸壁の母» に歌われ、多くの人の涙をさそいました。息子さんはついに帰らず、母は亡くなるまで待ち続けたといわれます。","記念館の中で、ひときわ目をひくのが «白樺日誌» です。紙もない収容所で、白樺の木の皮に、空き缶で作ったペンと煤のインクで和歌などを書きとめたもの。«なぜ、そこまでして書いたのか?» 見つかれば取り上げられる危険の中で、生きた証を残したかったのでしょう。","引揚げは1958年まで続きました。記念館は1988年に開館し、2015年には舞鶴への引揚げに関する資料がユネスコの «世界の記憶»（世界記憶遺産）に登録されました。近くの岸壁跡には «引揚桟橋» が復元され、海をながめることができます。ここは、戦争が終わった後にも続いた苦しみと、家族の絆を静かに語りかける場所です。"],"tl":[["1945年8月","第二次世界大戦が終わる。海外に多くの日本人が残される"],["1945年10月","舞鶴港に最初の引揚船が入る"],["1950年ごろ","多くの引揚港が閉じる中、舞鶴が中心的な港となる"],["1954年","歌謡曲 «岸壁の母» が発表される"],["1958年9月","最後の引揚船が舞鶴に入る"],["1988年","舞鶴引揚記念館が開館"],["1994年","引揚桟橋が復元される"],["2015年","引揚げ関連資料がユネスコ «世界の記憶» に登録"]],"who":[["端野いせ","«岸壁の母» のモデル。息子の帰りを舞鶴で待ち続けた"],["引揚者たち","13年間で約66万人が舞鶴に帰り着いた"],["舞鶴の市民","湯茶の接待などで引揚者を温かく迎えた"],["シベリア抑留者","極寒の地で強制労働を強いられ、多くが亡くなった"]],"deep":["舞鶴への引揚者は約66万人、遺骨は約1万6千柱とされます。引揚港は各地にありましたが、舞鶴は最も長く、1958年まで役目を果たしました。","ソ連による抑留者は約57万人以上とされ、そのうち5万人以上が亡くなったといわれます。数字には調査により幅があります。","ユネスコ «世界の記憶» に登録された資料は570点で、日記、手紙、絵、白樺日誌などが含まれます。","«岸壁の母» は1954年に菊池章子が歌い、1970年代に二葉百合子の歌でふたたび大ヒットしました。","舞鶴の人びとは引揚者にお茶やふかし芋をふるまったといわれ、その «ふるさとの味» は多くの引揚者の記憶に残りました。"],"look":["展示室の白樺日誌（複製が展示されることもある）","シベリアの収容所を再現した展示","丘の上から見下ろす舞鶴湾","海辺に復元された «引揚桟橋»","«岸壁の母» の歌碑"],"q":["舞鶴港への引揚げが終わったのは何年？","1958年。最後の引揚船が舞鶴に入り、13年間の引揚げが終わりました。"],"myth":"","img":["シベリア抑留","岸壁の母","引揚げ","舞鶴港"],"wp":"舞鶴引揚記念館","rel":{"ev":[],"grave":[]}},{"id":"26_akarenga","n":"舞鶴赤れんが倉庫群（旧海軍）","yomi":"まいづるあかれんがそうこぐん","cat":"近代","rank":"A","y":1903,"era":["meiji","showa"],"sh":"国の重要文化財","ad":"舞鶴市北吸","st":"JR東舞鶴駅から歩いて約15分","la":35.4745,"lo":135.395,"hook":"海軍が魚雷や兵器をしまった赤れんがの倉庫。100年以上たった今、若者が写真を撮りに集まる。","lead":"舞鶴は明治時代、日本海を守る海軍の大きな基地 «舞鶴鎮守府» がおかれた町です。赤れんが倉庫群は、その海軍が兵器や物資をしまった倉庫。今は博物館やイベント会場として使われ、8棟が国の重要文化財になっています。","story":["明治の日本は、ロシアなど大国の動きを心配していました。«日本海側にも海軍の拠点が必要だ»。そこで選ばれたのが、入り口が狭く奥が広い、天然の良港・舞鶴湾でした。1901年、舞鶴鎮守府が開かれ、初代司令長官には、のちに日本海海戦で名を上げる東郷平八郎が着任しました。","基地には、魚雷や砲弾、食料や衣類など、さまざまな物をしまう倉庫が必要です。そこで明治30年代から大正時代にかけて、れんが造りの倉庫が次々に建てられました。当時のれんがは、近くの工場で焼かれたものも使われたといわれます。火事や湿気に強く、がっしりとした倉庫は、海軍の力の象徴でもありました。","なかでも古い一棟が、今の «舞鶴市立赤れんが博物館» です。もとは魚形水雷（魚雷）をしまう倉庫で、1903年ごろの建物。鉄骨とれんがを組み合わせた造りで、この種類の建物としては日本でもとても古いものといわれます。博物館には、世界各地のれんがが集められ、«れんがの歴史» を知ることができます。","戦争が終わると海軍はなくなり、倉庫は海上自衛隊や民間の会社の倉庫として使われました。やがて使われない建物も増え、«取り壊すか、残すか» が話し合われました。市民は、町の歴史を語る建物を残そうと声を上げ、2008年には8棟が国の重要文化財に指定されます。","2012年、倉庫群は «赤れんがパーク» として生まれ変わりました。イベントホールやカフェ、展示室ができ、映画やドラマのロケ地としても人気です。すぐ近くの岸壁には今も海上自衛隊の艦艇が停泊し、明治から続く «軍港の町» の姿を感じることができます。"],"tl":[["1901年","舞鶴鎮守府が開かれる。初代司令長官は東郷平八郎"],["1903年ごろ","魚形水雷庫（今の赤れんが博物館）が完成"],["1921年ごろ","この頃までに倉庫群がほぼ出そろう"],["1945年","終戦。海軍が解体される"],["1993年","旧魚形水雷庫が «赤れんが博物館» として開館"],["2008年","8棟が国の重要文化財に指定"],["2012年","«舞鶴赤れんがパーク» がオープン"]],"who":[["東郷平八郎","舞鶴鎮守府の初代司令長官"],["海軍の技術者たち","倉庫の設計・建設にあたった"],["舞鶴の市民","倉庫の保存運動を進め、まちづくりに生かした"]],"deep":["れんがの積み方には、一段ごとに長い面と短い面を交互に見せる «イギリス積み» などがあり、建物ごとに見比べると違いがわかります。","旧魚形水雷庫は、鉄骨の骨組みにれんがの壁を組み合わせた構造で、近代建築の技術史の上でも貴重とされています。","«肉じゃが» の発祥地を名乗る町の一つが舞鶴です。東郷平八郎が英国で食べたビーフシチューをもとに作らせたという話がありますが、確かな記録はなく、広島県呉市も発祥を名乗っています。","倉庫の一部は今も海上自衛隊などが使っており、立ち入れない建物もあります。見学は公開されているエリアで楽しみましょう。","舞鶴には «赤れんが» のほか、旧鎮守府の司令長官官舎（東郷邸）など、明治の海軍の建物が点々と残っています。"],"look":["赤れんが博物館（旧魚形水雷庫）の鉄骨の骨組み","倉庫の外壁のれんがの積み方の違い","倉庫の間を通る引き込み線の跡","近くの岸壁から見る海上自衛隊の艦艇"],"q":["赤れんが博物館になっている建物は、もともと何をしまう倉庫だった？","魚雷（魚形水雷）をしまう倉庫でした。"],"myth":"肉じゃが発祥の話は伝承で、呉市も発祥を名乗っている。","img":["舞鶴鎮守府","舞鶴市立赤れんが博物館","東郷平八郎","煉瓦"],"wp":"舞鶴赤レンガ倉庫群","rel":{"ev":[],"grave":[]}},{"id":"26_amanohashidate","n":"天橋立","yomi":"あまのはしだて","cat":"伝承","rank":"A","y":1643,"era":["nara","muromachi","edo"],"sh":"国の特別名勝","ad":"宮津市文珠〜宮津市府中","st":"京都丹後鉄道 天橋立駅から歩いて約5分（南の入口）","la":35.57,"lo":135.1915,"hook":"神さまが天に通うための «はしご» が倒れてできた ― 昔の人は、この細長い松の道をそう説明した。","lead":"天橋立は、宮津湾に細長くのびる砂の道（砂州）で、長さは約3.6km。道には松がずらりと並びます。松島・宮島とともに «日本三景» の一つで、昔から歌や絵に描かれてきました。","story":["奈良時代にまとめられた『丹後国風土記』（その一部が残る）には、ふしぎな話が書かれています。国を生んだ神イザナギが、天と地を行き来するために長いはしごを立てていました。ところがある晩、イザナギが眠っているあいだに、はしごは倒れて海に横たわってしまった。それが «天の橋立» なのだ、と。","実際には、天橋立は川が運んだ砂が、海の流れで少しずつ積もってできたものです。何千年もかけて、海の中に細い道がのびていきました。«なぜまっすぐ伸びたのか?» 湾の外と内の海の流れがぶつかり合う場所に、砂がたまりやすかったからだと考えられています。","平安時代の歌人・小式部内侍は、母の和泉式部が丹後に住んでいたころ、«歌は母に代作してもらっているのでは» とからかわれ、«大江山いく野の道の遠ければ まだふみもみず天の橋立» と即座に返しました。«母のいる丹後は遠くて、天橋立を踏んだことも、母からの文（ふみ）を見たこともない» という見事な歌で、百人一首にも入っています。","室町時代、画僧の雪舟は、天橋立を空から見下ろしたような大きな絵を描きました。«天橋立図» は国宝です。江戸時代の初め、儒学者の林春斎（鵞峰）が、松島・宮島とともに天橋立を «三処の奇観» と書いたことが、«日本三景» の始まりといわれます。","今の楽しみ方の定番は «股のぞき»。展望台で後ろ向きになり、股の間から天橋立をのぞくと、空と海が逆さになって、橋が天に架かっているように見えるのです。ふもとの智恩寺は «三人寄れば文殊の知恵» の文殊菩薩をまつる寺。歩いて、自転車で、船で ― 神話と絶景を味わう旅ができます。"],"tl":[["奈良時代","『丹後国風土記』に、イザナギのはしごが倒れたという話が記される"],["平安時代","小式部内侍が «大江山いく野の道» の歌を詠む"],["1500年ごろ","雪舟が «天橋立図» を描いたとされる"],["1643年","林春斎が松島・宮島・天橋立を «三処の奇観» と記す"],["1952年","国の特別名勝に指定される"],["2007年","丹後天橋立大江山国定公園に含まれる"]],"who":[["イザナギ","日本を生んだとされる神。天橋立は、この神のはしごだったと伝わる"],["小式部内侍","和泉式部の娘。天橋立を詠んだ歌で知られる"],["雪舟","室町時代の画僧。国宝 «天橋立図» を描いた"],["林春斎（鵞峰）","江戸時代の儒学者。«日本三景» の元になる言葉を記した"]],"deep":["砂州には数千本の松があり、中には «磯清水» という、海に囲まれているのに塩からくない井戸もあります。名水として知られます。","近年、川から運ばれる砂が減り、砂州がやせる問題が起きました。そこで小さな突堤を並べたり、砂を運び入れたりして、形を守る工夫がされています。","雪舟の «天橋立図» は、実際には見られない高さから描かれた «鳥の目» の構図です。現地を歩き回って組み立てたと考えられ、京都国立博物館に収められています。","«日本三景» の三つがそろったのは江戸時代の書物からで、そのとき «三景» と言ったわけではなく、後に言葉が定着しました。","北側の籠神社は丹後国一宮で、天橋立はもともとこの神社の参道のような存在だったともいわれます。"],"look":["傘松公園や天橋立ビューランドからの «股のぞき»","砂州の松並木と «磯清水»","船が通るときに回転する «小天橋» の廻旋橋","ふもとの智恩寺（文殊堂）"],"q":["天橋立を逆さに見る有名な見方を何という？","«股のぞき»。股の間からのぞくと、橋が天に架かっているように見えます。"],"koji":[{"w":"三人寄れば文殊の知恵","m":"ふつうの人でも三人集まって考えればよい知恵が出る。天橋立の智恩寺は文殊菩薩をまつる"}],"myth":"イザナギのはしごの話は神話。雪舟の «天橋立図» の制作年は推定。","img":["天橋立図","日本三景","智恩寺","小式部内侍"],"wp":"天橋立","rel":{"ev":[],"grave":[]}},{"id":"26_kono","n":"籠神社（丹後国一之宮・海部氏系図）","yomi":"このじんじゃ","cat":"寺社","rank":"A","y":719,"era":["kofun","nara","heian"],"sh":"","ad":"宮津市字大垣","st":"京都丹後鉄道 天橋立駅から観光船で約12分、一の宮桟橋から歩いて約5分（バスもある）","la":35.5905,"lo":135.1862,"hook":"日本でいちばん古い系図が、この神社に守られてきた。そこには千年以上つづく一族の名が並ぶ。","lead":"籠神社は、天橋立の北のたもとにある丹後国の一宮（その国でいちばん格の高い神社）です。伊勢神宮の神さまが、もとはここにまつられていたという «元伊勢» の伝承があります。また、国宝の «海部氏系図» は、現存する日本最古の系図として知られます。","story":["天橋立を渡りきると、静かな森の中に大きな神社が見えてきます。籠神社（この じんじゃ）です。まつられているのは彦火明命（ひこほあかりのみこと）。神社の言い伝えでは、ここはもと «吉佐宮（よさのみや）» と呼ばれ、天照大神と豊受大神がいっしょにまつられていたといいます。","«なぜ伊勢の神さまが丹後に?» 『日本書紀』などには、天照大神をまつる場所を探して各地をめぐった話があります。その途中の場所を «元伊勢» と呼び、籠神社もその一つとされます。さらに、伊勢神宮の外宮にまつられる豊受大神は、丹後から迎えられたと伝わります。丹後は、伊勢と深いつながりをもつ土地なのです。","この神社に代々仕えてきたのが海部（あまべ）氏です。その家に伝わった «海部氏系図» は、平安時代の初めごろに書かれたとされ、1976年に国宝になりました。系図には祖先の名前が縦に並び、一族が古い時代からこの土地を治めていたことを伝えます。宮司は今も海部家の方がつとめています。","1987年、神社はもう一つの秘宝を公表しました。«息津鏡（おきつかがみ）» と «辺津鏡（へつかがみ）»。土の中から掘り出されたのではなく、代々手渡しで伝えられてきた «伝世鏡» だといいます。中国の後漢・前漢の時代の鏡と考えられ、日本に伝わった時期をめぐって大きな話題になりました。","本殿の奥、山の中には奥宮の «真名井神社» があります。古い磐座（いわくら＝神が宿る岩）がまつられ、清らかな湧き水が流れる場所です。本殿前には、鎌倉時代の作とされる石の狛犬が座っています。天橋立の景色だけでなく、日本の神話と古代の一族の物語を味わえる神社です。"],"tl":[["神代（伝承）","彦火明命が降り立ったと伝わる"],["崇神天皇のころ（伝承）","天照大神が一時この地にまつられた «元伊勢» とされる"],["719年（社伝）","奥宮から今の場所に移され、«籠宮» と改めたと伝わる"],["平安時代初め","«海部氏系図» が書かれたとされる"],["1976年","海部氏系図が国宝に指定される"],["1987年","伝世鏡 «息津鏡»«辺津鏡» が公表される"]],"who":[["彦火明命","主祭神。海部氏の祖先とされる"],["豊受大神","食物の神。のちに伊勢の外宮にまつられたと伝わる"],["海部氏","代々の宮司家。国宝の系図を伝えた"],["雪舟","国宝 «天橋立図» に籠神社周辺も描いた"]],"deep":["«海部氏系図» は、本系図と «勘注系図» の二つが伝わり、国宝は本系図の方です。勘注系図は江戸時代の写しとされ、内容の扱いには慎重な検討が必要です。","本系図には、平安時代の丹後国の印（丹後国印）が押されていると言われ、公的な文書としての性格があったと考えられています。","息津鏡・辺津鏡は、2000年近く伝世されたという神社の伝えがあり、事実なら非常に珍しい例です。ただし伝来の経緯には学術的な議論があります。","本殿は伊勢神宮と同じ «神明造» で、屋根の上には五色の «座玉（すえたま）» が飾られています。これは伊勢神宮の正殿などごく一部にしか見られない特別な飾りです。","石造の狛犬には、剣豪・岩見重太郎が夜な夜な暴れる狛犬を斬ったという伝説があり、«天下一の狛犬» とも呼ばれます。"],"look":["本殿（神明造）と屋根の五色の座玉","鎌倉時代の作とされる石造狛犬","奥宮・真名井神社と «天の真名井» の湧き水","神社から眺める天橋立の北側"],"q":["籠神社に伝わる国宝の «海部氏系図» は、どんな点で有名？","現存する日本最古の系図とされる点です。"],"myth":"«元伊勢» の由来、社伝の創建年、伝世鏡の伝来、狛犬の岩見重太郎伝説は伝承・諸説を含む。","img":["海部氏系図","元伊勢","天橋立","真名井神社"],"wp":"籠神社","rel":{"ev":[],"grave":[]}},{"id":"26_amino_choshiyama","n":"網野銚子山古墳（日本海側最大の前方後円墳）","yomi":"あみのちょうしやまこふん","cat":"遺跡","rank":"A","y":400,"era":["kofun"],"sh":"国指定史跡","ad":"京丹後市網野町網野","st":"京都丹後鉄道 網野駅から歩いて約15分","la":35.6838,"lo":135.0317,"hook":"日本海をのぞむ丘に、長さ約200mの巨大な墓。丹後にはかつて «海の王国» があった。","lead":"網野銚子山古墳は、古墳時代の中ごろ（4世紀の終わりごろ）に造られた前方後円墳で、長さは約200m。日本海側では最大の古墳です。こんなに大きな墓を造れた丹後の王は、海を通じて大陸や各地とつながる強い力をもっていたと考えられます。","story":["京丹後市の網野の町に、こんもりとした丘のような森があります。近づくと、それが人の手で造られた巨大な墓だとわかります。前が四角、後ろが丸い «前方後円墳»。全体の長さは約200m、後円部の高さは約16mほど。丹後の古い王が眠る墓です。","«なぜ日本海側の丹後に、こんな大きな古墳が?» 当時、丹後は日本海を行き来する船の拠点でした。朝鮮半島や北陸、山陰とつながり、鉄や玉（ガラスや石の飾り）などをつくる工房もあったことが、周辺の遺跡からわかっています。海の交易で富を集めた王がいた ― そう考える研究者は «丹後王国» という言葉で呼んでいます。","古墳は、造られた当時、斜面に石がびっしり敷きつめられていました。«葺石» です。そして墳丘のまわりには、筒の形をした埴輪がずらりと並べられていました。丹後の古墳では、独特の形をした «丹後型円筒埴輪» が見つかっています。遠くの海から見ると、白く光る石の山に見えたかもしれません。","丹後には、網野銚子山古墳のほかにも、与謝野町の蛭子山古墳、京丹後市丹後町の神明山古墳という大きな前方後円墳があり、あわせて «丹後三大古墳» と呼ばれます。いずれも海や川を見わたす場所にあり、王たちが海とともに生きていたことを物語ります。","古墳のそばには、小さな古墳（陪塚）も寄りそっています。一つは平安時代の宇多天皇（寛平法皇）の墓だという伝説から «寛平法皇陵» と呼ばれてきましたが、実際には古墳時代のものです。大きな墓は、時代ごとにさまざまな物語を生んできました。今は公園として整備が進み、墳丘を歩いて王の目線で町を見わたせます。"],"tl":[["4世紀の終わりごろ","網野銚子山古墳が造られたと考えられる"],["4〜5世紀","丹後に神明山古墳・蛭子山古墳などの大型古墳が造られる"],["1922年","国の史跡に指定される"],["平成時代以降","京丹後市による発掘調査で墳丘の形や埴輪の様子が明らかに"],["近年","史跡公園としての整備が進む"]],"who":[["丹後の王（名前は不明）","この古墳に葬られた人物。海の交易で力をもったと考えられる"],["宇多天皇（寛平法皇）","陪塚の一つがこの天皇の墓だという伝説がある"],["古墳を造った人びと","土を運び、葺石を敷き、埴輪を並べた大勢の人たち"]],"deep":["全長は約198mとされてきましたが、調査の進展で約201mとする見方もあります。いずれにしても日本海側で最大です。","丹後型円筒埴輪は、下の方がふくらむなど独特の形をもち、丹後の地域色を示すものとして注目されています。","網野銚子山・神明山・蛭子山の三大古墳は、いずれも古墳時代前期末から中期にかけてと考えられ、同じ時期に丹後が栄えたことを示します。","古墳のそばの潟湖（浅い湖）は、船を停める港の役割を果たしたという説があり、古墳と港の関係が研究されています。","墳丘は三段に造られていたと考えられ、段ごとに埴輪が並ぶ壮大な姿だったと推定されています。"],"look":["前方部から後円部へ歩いて感じる古墳の大きさ","斜面に残る葺石","陪塚の小銚子古墳と «寛平法皇陵» の伝説地","墳丘から見る網野の町と日本海方面"],"q":["網野銚子山古墳は、どの地域で最大の古墳？","日本海側で最大の前方後円墳です。"],"myth":"«丹後王国» は研究者による呼び方。全長は調査により約198mとも約201mとも。陪塚を寛平法皇陵とするのは伝説。","img":["前方後円墳","神明山古墳","蛭子山古墳","丹後国"],"wp":"網野銚子山古墳","rel":{"ev":[],"grave":[]}},{"id":"26_tanabejo","n":"田辺城（細川幽斎の籠城と古今伝授）","yomi":"たなべじょう","cat":"城","rank":"A","y":1600,"era":["azuchi","edo"],"sh":"","ad":"舞鶴市南田辺（舞鶴公園）","st":"JR西舞鶴駅から歩いて約10分","la":35.4426,"lo":135.3297,"hook":"«この老人を死なせてはならない» ― 天皇が戦を止めさせたのは、和歌の «秘伝» のためだった。","lead":"田辺城は、戦国武将で歌人でもあった細川幽斎（藤孝）が築いた城です。1600年、関ヶ原の戦いの直前、幽斎は約500の兵で1万を超える大軍を相手に2か月近く籠城しました。この戦いを終わらせたのは、なんと天皇の命令でした。","story":["1579年ごろ、細川藤孝（のちの幽斎）は、織田信長から丹後をまかされ、舞鶴湾の奥に城を築きました。これが田辺城です。藤孝は武将としてだけでなく、和歌や茶の湯、礼法にも通じた大教養人でした。本能寺の変のとき、親戚だった明智光秀の誘いを断り、頭を丸めて «幽斎» と名乗ったことでも知られます。","1600年7月、石田三成らの西軍が挙兵します。幽斎の息子・忠興は徳川家康に従って東へ出陣しており、田辺城には隠居の身の幽斎と、わずか500ほどの兵しか残っていませんでした。そこへ西軍の大軍、1万5千ともいわれる兵が押し寄せます。«どう考えても勝ち目はない»。それでも幽斎は城を開きませんでした。","この時、京都の宮中はあわてました。幽斎は «古今伝授» を受けた、ただ一人の人物だったからです。古今伝授とは、『古今和歌集』の読み方や解釈の秘密を、師から弟子へ一対一で伝えるもの。«幽斎が死ねば、この伝統が途絶えてしまう»。幽斎の弟子だった八条宮智仁親王らが働きかけ、後陽成天皇は勅使を送り、戦をやめるよう命じました。","9月、幽斎は天皇の命令に従って城を明け渡しました。籠城はおよそ2か月。その数日後、関ヶ原で東軍が勝利します。田辺城を囲んでいた西軍の兵は、関ヶ原に間に合わなかったともいわれます。«和歌が戦を止め、天下分け目の戦いにも影響した» ― 田辺城の籠城は、そんなふうに語り継がれています。","江戸時代、田辺城は京極家、のちに牧野家の城となりました。明治のはじめ、紀州の田辺と区別するため町の名は «舞鶴» に改められます。これは田辺城の別名 «舞鶴城» から取られた名前です。城跡は舞鶴公園となり、再建された城門の中の資料館で、幽斎と籠城の歴史を学ぶことができます。"],"tl":[["1579年ごろ","細川藤孝が丹後に入り、田辺城の築城を始めたとされる"],["1582年","本能寺の変。藤孝は剃髪して «幽斎» と名乗る"],["1600年7月","西軍が田辺城を包囲。籠城戦が始まる"],["1600年9月","天皇の勅使が遣わされ、幽斎が城を明け渡す"],["1600年9月15日","関ヶ原の戦い"],["1668年","牧野家が入り、明治まで田辺藩を治める"],["1869年","町の名が «田辺» から «舞鶴» に改められる"],["1940年","城門（模擬の櫓門）が建てられる"]],"who":[["細川幽斎（藤孝）","築城者。古今伝授の継承者で、籠城戦を指揮した"],["細川忠興","幽斎の息子。関ヶ原では東軍として戦った"],["後陽成天皇","勅使を送り、籠城戦をやめさせた"],["八条宮智仁親王","幽斎から古今伝授を受けた皇族。幽斎を救おうと動いた"]],"deep":["古今伝授は、東常縁から宗祇へ伝わった流れが有名で、幽斎は三条西実枝からこれを受けました。幽斎は籠城中にも、伝授の証である書物などを朝廷に届けようとしたと伝わります。","勅使として田辺城に来たのは、公家の三条西実条・中院通勝・烏丸光広らとされます。","西軍の包囲軍の中には幽斎の和歌の弟子もいて、本気で攻めなかったという話も伝わりますが、はっきりした記録は乏しいです。","関ヶ原の戦いの後、細川家は豊前（福岡県・大分県）に移り、田辺城には京極高知が入りました。","«舞鶴» という市の名前の由来は、田辺城の別名 «舞鶴城» です。城の形が鶴が舞うように見えたからともいわれます。"],"look":["舞鶴公園に残る天守台の石垣","再建された城門（中は資料館）","城跡に残る幽斎ゆかりの碑や説明板","城下町の名残をとどめる西舞鶴の町並み"],"q":["細川幽斎が田辺城で籠城したとき、天皇が戦をやめさせたのはなぜ？","幽斎が «古今伝授» を受けたただ一人の人物で、死ねば和歌の秘伝が途絶えるおそれがあったからです。"],"koji":[{"w":"古今伝授","m":"『古今和歌集』の解釈の秘伝を、師から弟子へ特別に伝えること"}],"myth":"西軍に手加減があった話、関ヶ原への影響の大きさには諸説がある。兵力の数字も史料により異なる。","img":["細川幽斎","古今伝授","関ヶ原の戦い","細川忠興"],"wp":"田辺城","rel":{"ev":[],"grave":[]}},{"id":"26_shugakuin","n":"修学院離宮","yomi":"しゅうがくいんりきゅう","cat":"大名屋敷","rank":"B","y":1659,"era":["edo"],"sh":"","ad":"京都市左京区修学院藪添","st":"叡山電鉄 修学院駅から歩いて約20分（見学は宮内庁への申し込みが必要）","la":35.0546,"lo":135.8006,"hook":"幕府に押さえつけられた天皇が、山と田んぼと池をまるごと «庭» にした。","lead":"修学院離宮は、江戸時代の初めに後水尾上皇がつくった山荘です。比叡山のふもとに、上・中・下の三つの «お茶屋» があり、あいだを松並木と田んぼの道が結びます。今は宮内庁が管理していて、申し込めば案内付きで見学できます。","story":["後水尾天皇は、徳川家康や秀忠の時代に即位した天皇です。幕府は «禁中並公家諸法度» というきまりで、天皇や公家の行動を細かくしばりました。1627年の «紫衣事件» では、天皇が高僧に与えた紫の衣の許しを幕府が取り消します。«天皇の決めたことが、幕府にひっくり返されるのか»。怒った天皇は1629年、突然位をゆずってしまいました。","上皇になった後水尾は、学問や和歌、そして庭づくりに情熱を注ぎます。1650年代、比叡山のふもとの修学院村に山荘の造営を始め、1659年ごろに完成しました。上皇自ら、模型を作らせて設計を考えたとも伝わります。«なぜここに?» 山すそから京都の町と北山・西山まで見わたせる、すばらしい景色があったからです。","いちばんの見どころは上離宮です。谷をせき止めて造った大きな池 «浴龍池» と、丘の上の «隣雲亭»。石段を登りきって振り返ると、池と森、その向こうに京都の町と山々が一気に広がります。遠くの景色を庭の一部として取り込む «借景» の見本のような眺めで、訪れた人はみな息をのみます。","三つのお茶屋のあいだには、今も田んぼや畑が広がっています。これはわざと残された風景で、農村ののどかな景色も庭の一部なのです。明治時代に、田んぼの中に松並木の道がつくられ、今の姿になりました。宮殿のきらびやかさではなく、自然と暮らしの景色を楽しむ ― そこに上皇の美意識が表れています。","中離宮は、もとは上皇の娘・光子内親王のための御所で、のちに林丘寺という尼寺になりました。明治時代にその一部が離宮に加えられ、宮内省（今の宮内庁）の管理となりました。見学ルートは約3km、一時間あまり。幕府と対立した天皇が最後にたどりついた «心のふるさと» を、ゆっくり歩いて味わえます。"],"tl":[["1611年","後水尾天皇が即位"],["1615年","幕府が «禁中並公家諸法度» を定める"],["1627年","紫衣事件が起きる"],["1629年","後水尾天皇が明正天皇に位をゆずる"],["1655〜1659年ごろ","修学院離宮の造営"],["1680年","後水尾法皇が亡くなる"],["明治時代","宮内省の管理となり、林丘寺の一部が中離宮として加えられる"]],"who":[["後水尾天皇（上皇）","修学院離宮をつくった。幕府と対立し、退位後は文化に力を注いだ"],["東福門院和子","後水尾天皇の中宮。徳川秀忠の娘"],["光子内親王","後水尾上皇の娘。中離宮はもとこの人の御所だった"],["徳川秀忠","2代将軍。朝廷への統制を強めた"]],"deep":["上離宮の «窮邃亭（きゅうすいてい）» は、造営当時から残るとされる貴重な建物で、上皇好みの簡素な意匠が見られます。","浴龍池は、谷川をせき止める大きな堤を築いて造られました。堤の斜面は «大刈込» という生け垣で覆われ、堤であることを感じさせない工夫がされています。","中離宮の客殿には、«霞棚» と呼ばれる違い棚があり、桂離宮の «桂棚»、醍醐寺三宝院の «醍醐棚» とともに «天下三棚» といわれます。","修学院離宮は皇室の施設のため、文化財の指定を受けていません。それでも日本庭園の最高傑作の一つと評価されています。","造営の費用は幕府が出したといわれ、朝廷と幕府の関係が、対立から協調へと変わっていった時代を映しています。"],"look":["上離宮・隣雲亭からの借景の大パノラマ","浴龍池と中島にかかる千歳橋","お茶屋をつなぐ松並木と田んぼの道","中離宮客殿の霞棚"],"q":["後水尾天皇が突然位をゆずるきっかけの一つになった事件は？","«紫衣事件»。天皇が与えた紫衣の許しを幕府が取り消した事件です。"],"myth":"上皇が模型を作らせて設計したという話は伝承。造営費用の負担には諸説がある。","img":["後水尾天皇","紫衣事件","桂離宮","借景"],"wp":"修学院離宮","rel":{"ev":[],"grave":[]}},{"id":"26_akechi_kubizuka","n":"明智光秀首塚（東山・白川）","yomi":"あけちみつひでくびづか","cat":"墓所","rank":"B","y":1582,"era":["azuchi","edo"],"sh":"","ad":"京都市東山区梅宮町（白川のほとり）","st":"京都市営地下鉄東西線 東山駅から歩いて約3分","la":35.0088,"lo":135.7778,"hook":"天下を取ってわずか11日。光秀の首は、京都の町かどの小さな祠に眠るといわれる。","lead":"京都・東山の白川のほとり、和菓子屋さんの裏手のような細い路地に、明智光秀の首塚と伝わる小さな祠があります。本能寺の変で信長を倒した光秀は、山崎の戦いに敗れて命を落としました。その首がここに葬られたといわれます。","story":["1582年6月2日、明智光秀は本能寺の織田信長を討ちました。しかし «天下人» の座は長く続きません。中国地方から大急ぎで戻ってきた羽柴秀吉と、13日に山崎で戦い、光秀は敗れます。わずかな家来と近江の坂本城をめざして落ちのびる途中、京都の小栗栖（おぐるす）の竹やぶで、農民の落ち武者狩りにあい、深い傷を負いました。","«もはやこれまで»。光秀は自ら命を絶ち、家来が首を持ち去って隠したといわれます。しかし首は見つかり、信長が討たれた本能寺などでさらされたと伝わります。その後、首と胴は粟田口（京都の東の入口）に葬られたともいわれますが、はっきりしたことはわかっていません。","この首塚は、江戸時代の中ごろ、光秀の子孫と称する人などによって、今の白川のほとりに移されたと伝わります。小さな祠の中には光秀の木像がまつられ、そばには «長存寺殿明窓玄智大禅定門» という戒名を刻んだ石碑が立っています。近所の人たちが代々守ってきた、町の中のお墓です。","«なぜ光秀の首塚は各地にあるの?» 京都府亀岡市の谷性寺、光秀の城があった福知山など、首塚や供養の塚は一つではありません。天下を取りそこねた «謀反人» として語られる一方、城下の人たちには慕われた光秀。人びとの複雑な思いが、たくさんの塚を生んだのかもしれません。","首塚の前にはいつも花がそなえられ、«首から上の病気に効く» とお参りする人もいるそうです。すぐ近くには、三条通や知恩院、青蓮院があり、観光客でにぎわう場所。そのすぐ裏に、戦国の大事件の主人公が静かに眠っていると思うと、町の中の歴史の深さに驚かされます。"],"tl":[["1582年6月2日","本能寺の変。光秀が信長を討つ"],["1582年6月13日","山崎の戦いで光秀が敗れる"],["1582年6月13日夜〜14日","小栗栖で襲われ、光秀が命を落としたとされる"],["1582年6月","光秀の首がさらされたと伝わる"],["江戸時代中ごろ","首塚が現在地（白川のほとり）に移されたと伝わる"]],"who":[["明智光秀","本能寺の変の首謀者。この塚に首が葬られたと伝わる"],["羽柴秀吉","山崎の戦いで光秀を破った"],["織田信長","本能寺で光秀に討たれた主君"],["近所の人びと","代々首塚を守り、花や線香を絶やさない"]],"deep":["光秀が最期を迎えた小栗栖（伏見区）には «明智藪» と呼ばれる竹やぶがあり、光秀が討たれた場所と伝わります。","光秀の首については、家来が近江や丹波に運んで葬ったとする話も多く、亀岡市の谷性寺の首塚はその一つです。","光秀は «天下を取ったのは3日だけ» という意味で «三日天下» と呼ばれますが、実際には本能寺の変から死まで約11日です。","光秀の生年や出身地は諸説があり、岐阜県可児市、岐阜県恵那市などが «光秀ゆかりの地» を名乗っています。","2020年の大河ドラマ «麒麟がくる» で光秀への関心が高まり、この首塚を訪れる人も増えました。"],"look":["祠の中の光秀の木像（のぞき窓から）","戒名 «長存寺殿明窓玄智大禅定門» の石碑","そばを流れる白川と、祇園方面へ続く石畳","近くの青蓮院・知恩院など、東山の名所"],"q":["光秀が本能寺の変から死ぬまでの短い天下を、何という？","«三日天下»。実際には約11日間でした。"],"koji":[{"w":"三日天下","m":"権力を握っても、ごく短い間しか続かないこと。光秀の短い天下から生まれた言葉"}],"myth":"首がここに葬られたこと、移された時期と経緯は伝承で、確かな史料はない。","img":["山崎の戦い","本能寺の変","三日天下"],"wp":"明智光秀","rel":{"ev":[],"grave":[["mitsuhide","明智光秀"]]}},{"id":"26_mimizuka","n":"耳塚（文禄・慶長の役）","yomi":"みみづか","cat":"墓所","rank":"B","y":1597,"era":["azuchi"],"sh":"国指定史跡","ad":"京都市東山区茶屋町（正面通大和大路西入ル）","st":"京阪本線 七条駅から歩いて約10分","la":34.9906,"lo":135.77,"hook":"京都の真ん中に、海の向こうで命を落とした人びとの «耳と鼻» を埋めた塚がある。","lead":"耳塚は、豊臣秀吉が朝鮮半島に兵を送った «文禄・慶長の役» のとき、日本の武将たちが戦功の証として持ち帰った、朝鮮・明の人びとの鼻や耳を埋めた塚です。1597年に造られ、国の史跡になっています。戦争の悲しい歴史を伝える場所として、静かに手を合わせたい場所です。","story":["豊臣秀吉は全国を統一すると、次に «明（中国）を征服する» という大きすぎる野望をいだきました。1592年、その通り道として朝鮮半島に大軍を送ります（文禄の役）。いったん休戦しましたが話し合いはまとまらず、1597年、秀吉はふたたび兵を送りました（慶長の役）。","戦国時代の日本では、手がらの証として、討ち取った敵の首を持ち帰る習わしがありました。しかし海を越えた戦では首を運ぶのは難しい。そこで武将たちは、代わりに鼻（のちに «耳» とも言われるようになる）を切り取り、塩や酒につけて日本に送ったのです。兵士だけでなく、ふつうの人びとも犠牲になったといわれます。","1597年、それらを埋めて造られたのがこの塚です。秀吉の命令で、相国寺の僧・西笑承兌らを招き、供養の法要が行われました。«なぜ供養を?» 秀吉の «慈悲» を示すためとも、戦の成果を見せるためともいわれます。塚の上には大きな五輪塔が立ち、すぐ近くには秀吉をまつる豊国神社や、秀吉が建てた方広寺の大仏殿の跡があります。","はじめは «鼻塚» と呼ばれていましたが、«鼻» ではむごすぎるとして、江戸時代のはじめごろ、儒学者の林羅山らが «耳塚» と呼んだことから、この名が広まったといわれます。朝鮮半島の人びとにとって、ここは先祖が受けた深い傷を思い起こさせる場所であり、今も韓国からの訪問者が花をたむけています。","戦争は1598年、秀吉の死によって終わりました。その後、徳川家康は朝鮮との国交を回復させ、江戸時代には «朝鮮通信使» が日本を訪れるようになります。耳塚は、戦争がどれほど多くの人を苦しめるかを語りかける場所。見学するときは、敬意をもって静かに訪れましょう。"],"tl":[["1592年","文禄の役。秀吉の軍が朝鮮半島に渡る"],["1593年","休戦し、明との講和交渉が始まる"],["1597年","慶長の役。再び出兵"],["1597年9月","塚が造られ、供養の法要が行われる"],["1598年","秀吉の死により、日本軍が撤退"],["1607年","朝鮮からの使節が来日し、国交回復へ"],["1969年","国の史跡に指定される"]],"who":[["豊臣秀吉","朝鮮出兵を命じ、塚を造らせた"],["西笑承兌","相国寺の僧。供養の法要を行った"],["朝鮮・明の人びと","この戦で命を落とし、塚に埋められた"],["林羅山","江戸時代の儒学者。«耳塚» の名を広めたといわれる"]],"deep":["塚に埋められた人の数は史料や研究により大きく異なり、はっきりした数はわかっていません。数万人とする説もあります。","塚の高さは約9m（五輪塔を含む）ともいわれ、町の中の史跡としてはとても大きなものです。","実際には «鼻» が多かったと考えられ、戦功の証として鼻の数を記録した «鼻請取状» という文書も残っています。","耳塚は、秀吉をまつる豊国神社の門前にあります。秀吉の神社のすぐ前に犠牲になった人びとの塚があるという配置そのものが、見る人に多くのことを考えさせます。","朝鮮半島では、この戦いを «壬辰倭乱（じんしんわらん）»«丁酉再乱» と呼びます。"],"look":["塚の上に立つ五輪塔","塚の説明板（日本語・韓国語など）","近くの豊国神社と方広寺の鐘（«国家安康» の鐘）","方広寺大仏殿跡の大きな石垣"],"q":["耳塚はもともと何と呼ばれていた？","«鼻塚»。むごい名だとして、のちに «耳塚» と呼ばれるようになったといわれます。"],"myth":"埋められた人数、名称が変わった経緯には諸説がある。","img":["文禄・慶長の役","豊臣秀吉","豊国神社 (京都市)","方広寺"],"wp":"耳塚","rel":{"ev":["kenchi"],"grave":[]}},{"id":"26_nishijin","n":"西陣（応仁の乱の西軍本陣跡）","yomi":"にしじん","cat":"産業","rank":"B","y":1467,"era":["muromachi","edo","meiji"],"sh":"","ad":"京都市上京区堀川今出川上ル山名町ほか","st":"京都市営地下鉄烏丸線 今出川駅から歩いて約15分／市バス «堀川今出川» すぐ","la":35.0305,"lo":135.75,"hook":"11年つづいた大戦乱の «西の陣地»。そこで生まれた地名が、日本一の織物のブランドになった。","lead":"西陣は京都市の北西部、上京区から北区にかけての地域の呼び名です。応仁の乱で西軍の大将・山名宗全が陣を置いたことから «西陣» と呼ばれるようになりました。戦乱のあと織物職人が戻ってきて、高級な絹織物 «西陣織» の町として栄えました。","story":["1467年、京都で大きな戦いが始まりました。将軍・足利義政のあとつぎ争いや、有力な大名家の争いが重なり、全国の大名が東軍と西軍に分かれて戦ったのです。東軍の大将は細川勝元、西軍の大将は山名宗全。京都の町が戦場になりました。","山名宗全は、自分の屋敷があった堀川今出川の北あたりに本陣を置きました。一方、細川勝元の東軍は、将軍の御所（花の御所）の近くに陣を置きます。宗全の陣が西にあったから «西陣»。«地名の由来が戦争の陣地?» と驚くかもしれませんが、この名前が500年以上たった今も使われています。","戦いは11年もつづき、京都の町は焼け野原になりました。寺や貴族の屋敷、町家の多くが失われます。戦いを避けて堺などに逃げていた織物職人たちは、乱が終わると、西陣の陣地のあたりに戻ってきて機織りを再開しました。もともと平安時代から都には朝廷の織物職人がいて、その技を受けつぐ人びとでした。","江戸時代、西陣の織物は «西陣織» として全国に知られ、帯や着物、能装束など、豪華な絹織物がつくられました。しかし明治になって都が東京に移ると、お客さんが減ってしまいます。«このままでは西陣がすたれる»。1872年、職人3人がフランスのリヨンへ派遣され、最新の «ジャカード» という織機を持ち帰りました。","ジャカードは、穴をあけた紙（紋紙）で複雑な模様を自動的に織り出せる機械で、コンピューターの先祖ともいわれます。これで西陣織は生まれ変わりました。今、西陣を歩くと、町家の中から «カシャン、カシャン» と機の音が聞こえることがあります。堀川今出川の近くには «山名宗全旧跡» の碑が立ち、戦国の始まりと織物の町の歴史を伝えています。"],"tl":[["1467年1月","上御霊神社の戦い（御霊合戦）で応仁の乱が始まる"],["1467年","山名宗全が自邸の周辺に西軍の本陣を置く"],["1473年","山名宗全・細川勝元があいついで亡くなる"],["1477年","応仁の乱が終わる"],["乱の後","織物職人が戻り、西陣で機織りを再開"],["1872年","職人3人がフランス・リヨンへ派遣される"],["1976年","西陣織会館が開館"]],"who":[["山名宗全（持豊）","西軍の大将。その本陣が «西陣» の名の由来"],["細川勝元","東軍の大将"],["足利義政","8代将軍。あとつぎ問題が乱の原因の一つとなった"],["佐倉常七・井上伊兵衛・吉田忠七","リヨンに派遣された西陣の職人"]],"deep":["«西陣» は正式な町名ではなく、地域の呼び名です。範囲ははっきり決まっていませんが、上京区の北西部を中心に北区の一部まで含みます。","山名宗全は顔が赤かったので «赤入道» と呼ばれたと伝わります。","平安時代、朝廷には «織部司» という織物を担当する役所があり、その職人の流れが西陣織のもとになったといわれます。","リヨンに派遣された3人のうち吉田忠七は、帰国の途中で船の事故にあい亡くなりました。","ジャカード織機の紋紙の «穴のある・なし» で模様を決めるしくみは、のちのパンチカードやコンピューターの考え方につながったといわれます。"],"look":["堀川今出川の北、山名町にある «山名宗全旧跡» の碑","西陣織会館（手織りの実演や資料展示）","路地に残る織屋建ての町家","応仁の乱の始まりの地・上御霊神社（少し東）"],"q":["«西陣» という地名は、何に由来する？","応仁の乱で、西軍の大将・山名宗全が陣を置いたことに由来します。"],"myth":"西陣の範囲には決まった境界がない。山名宗全の «赤入道» の話は伝承。","img":["応仁の乱","山名宗全","西陣織","ジャカード織機"],"wp":"西陣","rel":{"ev":[],"grave":[]}},{"id":"26_tobadono","n":"鳥羽殿跡（院政の離宮）","yomi":"とばどのあと","cat":"遺跡","rank":"B","y":1086,"era":["heian"],"sh":"","ad":"京都市伏見区中島・竹田","st":"京都市営地下鉄烏丸線・近鉄 竹田駅から歩いて約15分（鳥羽離宮跡公園まで）","la":34.9492,"lo":135.7428,"hook":"上皇たちが «もう一つの都» を造った水辺の離宮。今は小さな築山だけが、その名残をとどめる。","lead":"鳥羽殿（鳥羽離宮）は、平安時代の終わりに白河上皇が造らせた大きな離宮（天皇や上皇の別荘）です。上皇が政治を動かす «院政» の中心の一つで、御所や寺がいくつも建ち並びました。建物は残っておらず «跡» ですが、公園や寺、陵にその記憶が残ります。","story":["1086年、白河天皇は幼い息子に位をゆずり、上皇になりました。けれども政治から離れたわけではありません。«天皇の父» として、上皇が実際の政治を動かす «院政» の始まりです。その白河上皇が、都の南、鴨川と桂川が合流するあたりに造らせたのが鳥羽殿でした。","«なぜ都の南に?» ここは川の港 «鳥羽の津» があり、西国から船で運ばれた物資が集まる場所でした。広い池と水辺の景色も美しく、上皇たちは船遊びや和歌の会を楽しみました。離宮の広さは東西約1.5km、南北約1kmにおよんだといわれ、南殿・北殿・泉殿・東殿・田中殿などの御所と寺が次々と建てられました。","白河上皇のあと、鳥羽上皇もここを愛し、離宮はさらに広がりました。鳥羽上皇は安楽寿院を建て、自分の墓所も定めます。貴族たちは離宮のまわりに屋敷を構え、«まるで都が引っ越してきたようだ» といわれるほどのにぎわいでした。","しかし、ここは政治の暗い舞台にもなりました。1179年、平清盛は兵をひきいて後白河法皇の院政を止め、法皇をこの鳥羽殿に閉じ込めてしまいます（治承三年の政変）。上皇たちの華やかな離宮は、武士の力が朝廷を上回る時代の到来を示す場所にもなったのです。","その後、離宮はしだいに荒れ、室町時代の戦乱などでほとんど失われました。今、鳥羽離宮跡公園には、南殿の庭の築山だったとされる «秋の山» が残ります。近くには城南宮、安楽寿院、鳥羽天皇陵、近衛天皇陵などがあり、発掘調査では池や建物の跡が見つかっています。そして幕末の1868年、この近くで鳥羽・伏見の戦いが始まりました。"],"tl":[["1086年","白河上皇が院政を始め、鳥羽殿の造営が始まる"],["1100年代前半","鳥羽上皇のもとで離宮が広がる"],["1137年","鳥羽上皇が安楽寿院を建てる"],["1156年","鳥羽法皇が亡くなり、保元の乱が起こる"],["1179年","平清盛が後白河法皇を鳥羽殿に閉じ込める"],["1868年","離宮跡の近くで鳥羽・伏見の戦いが始まる"],["1960年代以降","発掘調査が進み、池や建物跡が見つかる"]],"who":[["白河上皇","鳥羽殿を造らせ、院政を始めた"],["鳥羽上皇","離宮をさらに広げ、安楽寿院を建てた"],["後白河法皇","平清盛によってここに閉じ込められた"],["平清盛","治承三年の政変で院政を止めた"]],"deep":["鳥羽殿は、平安京の南の出入口・羅城門から南へのびる «鳥羽作道» で都と結ばれていました。","安楽寿院の近くには鳥羽天皇陵、少し離れて近衛天皇陵があり、近衛天皇陵には多宝塔が建っています。天皇陵に塔があるのは珍しい例です。","城南宮は、鳥羽殿ができる前からあった神社とされ、離宮の鎮守として崇められました。今は «方除けの神» として知られます。","発掘調査では、大きな池の跡や、庭園の石組み、建物の礎石などが見つかり、離宮の規模が少しずつ明らかになっています。","«秋の山» は南殿の庭園の築山と考えられ、離宮の地上に残るほぼ唯一の目に見える遺構です。"],"look":["鳥羽離宮跡公園の築山 «秋の山»","安楽寿院と鳥羽天皇陵","多宝塔の建つ近衛天皇陵","城南宮の庭園（平安の庭の雰囲気）","鳥羽・伏見の戦いの碑（小枝橋付近）"],"q":["上皇が天皇にかわって政治を動かすしくみを何という？","«院政»。白河上皇が始めました。"],"myth":"離宮の範囲や規模は発掘と史料からの推定。","img":["白河天皇","院政","城南宮"],"wp":"鳥羽離宮","rel":{"ev":[],"grave":[]}},{"id":"26_shishigatani","n":"鹿ケ谷（俊寛山荘・鹿ケ谷の陰謀）","yomi":"ししがたに","cat":"事件","rank":"B","y":1177,"era":["heian"],"sh":"","ad":"京都市左京区鹿ケ谷","st":"市バス «錦林車庫前» または «真如堂前» から歩いて約10分（山荘跡の碑は山道を約1時間登る）","la":35.0195,"lo":135.801,"hook":"«平氏（へいし）が倒れた!» ― 酒の席の冗談が、流罪と処刑の嵐を呼んだ。","lead":"鹿ケ谷は、東山のふもとの静かな谷です。1177年、ここの山荘で、後白河法皇の近臣たちが平家を倒す相談をしたとされる事件が «鹿ケ谷の陰謀» です。計画はもれ、関わった人たちは処刑や流罪になりました。俊寛の山荘跡とされる場所は、山中に碑が立っています。","story":["平安時代の終わり、平清盛とその一族は朝廷の高い位を独占し、«平家にあらずんば人にあらず» とまで言われるほどの勢いでした。これをおもしろく思わない人たちがいました。後白河法皇のそばに仕える藤原成親、西光、そして法勝寺の僧・俊寛らです。","『平家物語』によると、彼らは東山の鹿ケ谷にある俊寛の山荘に集まり、平家を倒す相談をしました。その席で、成親がふとした拍子に «瓶子（へいじ＝酒のとっくり）» を倒してしまいます。«平氏（へいじ）が倒れたぞ!» 一同は大笑い。西光は «首を取るにしかず» と、とっくりの首を折ってみせたといいます。","ところが、仲間の一人だった多田行綱が清盛に計画を知らせてしまいます。清盛の怒りはすさまじく、西光は捕らえられて処刑され、成親は備前（岡山県）に流されたのち命を落としました。俊寛・藤原成経・平康頼の三人は、はるか南の «鬼界ヶ島» に流されました。","翌年、中宮・徳子（清盛の娘）の安産を祈って大赦が行われ、成経と康頼は許されます。ところが赦免状に俊寛の名前だけがありませんでした。«なぜ私だけが?» 迎えの船にすがりつき、遠ざかる船に向かって足ずりして泣き叫ぶ俊寛の姿は、『平家物語』の名場面として、能や歌舞伎『俊寛』にも描かれました。俊寛はその島で亡くなったと伝わります。","近年の研究では、この事件は本当に陰謀があったのか、それとも清盛が反対派を一掃するための口実だったのか、疑問も出されています。また、集会の場所を『愚管抄』は静賢という僧の山荘と記しており、史料によって話が違います。今、如意ヶ岳へ向かう山中に «俊寛僧都忠誠之碑» が立ち、谷の静けさの中に、平安の終わりの緊張を感じることができます。"],"tl":[["1167年","平清盛が太政大臣になる"],["1177年6月","鹿ケ谷の陰謀が発覚。西光が処刑される"],["1177年","俊寛・成経・康頼が鬼界ヶ島へ流される"],["1178年","大赦で成経と康頼が許されるが、俊寛は残される"],["1179年","清盛が後白河法皇の院政を止める（治承三年の政変）"],["1180年","以仁王の挙兵。源平の争乱が始まる"]],"who":[["俊寛","法勝寺の僧。山荘が密議の場とされ、鬼界ヶ島に流された"],["藤原成親","後白河法皇の近臣。流罪の後に殺された"],["西光","後白河法皇の近臣。捕らえられ処刑された"],["平清盛","計画を知って関係者を厳しく処罰した"],["後白河法皇","近臣たちの主君。関与の度合いは不明"],["多田行綱","計画を清盛に知らせたとされる武士"]],"deep":["«瓶子が倒れた» の話は『平家物語』の描写で、実際にあったかどうかは確かめられません。物語をおもしろくする工夫とも考えられます。","慈円の『愚管抄』は、密議の場所を静賢法印の山荘としています。『平家物語』の俊寛の山荘とは食い違い、どちらが正しいかは決まっていません。","«鬼界ヶ島» がどこかは、鹿児島県の硫黄島など諸説があります。","同じ頃、清盛は延暦寺との対立も抱えており、陰謀事件の発覚にはその政治的な事情が関係したとみる説があります。","俊寛の最期について、『平家物語』では、召し使いの有王が島を訪ね、その最期を看取ったと語られます。"],"look":["山中の «俊寛僧都忠誠之碑»（楼門の滝から山道を登る。登山装備で）","鹿ケ谷の山すその静かな寺町（法然院・安楽寺など）","哲学の道から見上げる如意ヶ岳（大文字山）"],"q":["『平家物語』で、酒のとっくり «瓶子» が倒れたとき、人びとは何とかけてしゃれを言った？","«平氏（へいじ）が倒れた»。瓶子（へいじ）と平氏をかけました。"],"koji":[{"w":"平家にあらずんば人にあらず","m":"平家一門でなければ人ではない、というほど平家が栄えたこと。平時忠の言葉として『平家物語』に出てくる"}],"myth":"密議の場所、陰謀の実態、«瓶子» の話には諸説がある。『平家物語』は文学作品で、史実と異なる部分を含む。","img":["俊寛","平家物語","後白河天皇"],"wp":"鹿ケ谷の陰謀","rel":{"ev":["shunkan"],"grave":[]}},{"id":"26_rajomon","n":"羅城門跡","yomi":"らじょうもんあと","cat":"遺跡","rank":"B","y":794,"era":["heian"],"sh":"","ad":"京都市南区唐橋羅城門町（花園児童公園）","st":"近鉄京都線 東寺駅から歩いて約15分／市バス «羅城門» すぐ","la":34.9806,"lo":135.7422,"hook":"平安京の «正門» は、今は小さな公園の石碑だけ。でも物語の中では、鬼と盗人がうごめいていた。","lead":"羅城門は、794年に始まった平安京の南の正門です。都のまん中を南北に走る朱雀大路の南の端に建っていました。やがて壊れて再建されず、今は公園に «羅城門遺址» の碑が立つだけですが、芥川龍之介の『羅生門』の舞台として有名です。","story":["794年、桓武天皇は都を長岡京から新しい平安京へ移しました。都は碁盤の目のように道が区切られ、真ん中を幅80m以上もある朱雀大路が南北に走ります。その南の入口に建てられたのが羅城門。外国からの使者も、この門をくぐって都に入りました。«これが日本の都か» と感じさせる、国の顔でした。","門は二階建ての大きな建物で、両側には東寺と西寺という二つの国の寺が並んでいました。門の上には、都を守る毘沙門天がまつられていたとも伝わります。しかし門は風に弱く、816年の大風で倒れ、いったん再建されました。そして980年の暴風雨で再び倒れると、もう二度と建て直されることはありませんでした。","«なぜ建て直さなかったの?» 平安京の西側（右京）は湿地が多く、しだいにさびれていきました。都の中心は東へ、北へと移り、南の正門の必要が薄れたのかもしれません。やがて門の跡は荒れ果て、あやしい話の舞台になっていきます。","平安時代の終わりにまとめられた『今昔物語集』には、羅城門の上の階に上がった盗人が、死体の髪を抜いてかつらにしようとする老婆に出会う話があります。1915年、芥川龍之介はこの話をもとに短編小説『羅生門』を書きました。«生きるためなら悪をしてもよいのか» ― 下人の心の動きを描いたこの作品は、教科書でもおなじみです。","また、渡辺綱が羅城門で鬼の腕を切り落としたという伝説も、能『羅生門』などで語られました。今、門の跡とされる場所は住宅街の中の小さな公園で、«羅城門遺址» の石碑が立っています。京都駅前には、門を10分の1で再現した模型も置かれています。華やかな都の入口が、物語の中で鬼の住む場所に変わっていった ― その変化に、都の栄枯盛衰が映っています。"],"tl":[["794年","平安京に都が移り、羅城門が建てられる"],["816年","大風で倒れ、のちに再建される"],["980年","暴風雨で倒壊。以後再建されず"],["12世紀前半","『今昔物語集』に羅城門の話が記される"],["1915年","芥川龍之介が『羅生門』を発表"],["1950年","黒澤明の映画 «羅生門» 公開（内容は芥川の『藪の中』が中心）"]],"who":[["桓武天皇","平安京をつくった天皇"],["渡辺綱","源頼光の四天王。羅城門で鬼の腕を切った伝説がある"],["芥川龍之介","小説『羅生門』の作者"],["黒澤明","映画 «羅生門» の監督。世界に名を知られるきっかけとなった"]],"deep":["«羅城» とは都を囲む城壁のことです。しかし平安京には、中国の都のような周囲の城壁はほとんど造られず、門だけが立っていたと考えられています。","«羅生門» という書き方は、中世以降に広まったもので、能や芥川の小説はこちらの表記を使っています。","東寺に伝わる国宝の兜跋毘沙門天像は、羅城門の上に安置されていたものが、門が倒れた後に東寺へ移されたと伝わります。","門の正確な位置や規模は、地下の遺構がはっきり確認されていないため、推定の部分が残ります。","朱雀大路をはさんで東寺・西寺が並ぶ配置は、都の守りと仏教による国家鎮護の考えを表しています。今、東寺は残り、西寺は跡地になっています。"],"look":["花園児童公園の «羅城門遺址» の碑","近くの «矢取地蔵»（空海と守敏の伝説）","東寺の五重塔と兜跋毘沙門天像（宝物館の公開時）","京都駅前の羅城門の10分の1模型"],"q":["羅城門を舞台にした芥川龍之介の小説の題名は？","『羅生門』。『今昔物語集』の話をもとにしています。"],"myth":"門上に毘沙門天があった話、渡辺綱の鬼退治は伝承。門の正確な位置・規模は推定。","img":["平安京","朱雀大路","羅生門 (小説)","教王護国寺"],"wp":"羅城門","rel":{"ev":[],"grave":[]}},{"id":"26_yamashina_honganji","n":"山科本願寺跡（土塁の寺内町）","yomi":"やましなほんがんじあと","cat":"城","rank":"B","y":1478,"era":["muromachi"],"sh":"国指定史跡","ad":"京都市山科区西野・音羽","st":"京都市営地下鉄東西線 山科駅・JR山科駅から歩いて約15分（山科中央公園の土塁まで）","la":34.979,"lo":135.8105,"hook":"寺なのに、まわりを高い土の壁と堀で囲んだ。そこは «仏の国» であり、同時に要塞だった。","lead":"山科本願寺は、浄土真宗の蓮如が1478年から建てた大きな寺です。まわりに土塁（土の壁）と堀をめぐらせ、中には門徒の町が広がる «寺内町» でした。1532年に焼き討ちされて失われましたが、公園などに土塁が残り、国の史跡になっています。","story":["室町時代の中ごろ、浄土真宗の本願寺はまだ小さな教団でした。そこに現れたのが8代目の蓮如です。«南無阿弥陀仏ととなえれば、だれでも救われる» という教えを、ひらがなまじりのわかりやすい手紙（御文）で広め、農民や商人たちの心をつかみました。門徒は各地で爆発的にふえていきます。","比叡山延暦寺からの圧力で京都の大谷の寺を壊され、北陸の吉崎などで布教した蓮如は、1478年、京都の東の山科に新しい本願寺を建て始めました。1480年ごろには御影堂が完成し、各地から門徒が集まります。«なぜ山科に?» 京都に近く、東国や近江へ通じる交通の要所で、広い土地もあったからです。","山科本願寺は、中心の «御本寺»、僧や一族が住む «内寺内»、商人や職人が住む «外寺内» からなり、それぞれを土塁と堀で囲んでいました。町には門徒がくらし、市が立ち、«まるで仏の国のようだ» とたたえられるほどのにぎわいだったといいます。寺でありながら城のような守りを備えていたのは、戦乱の時代を生きぬくためでした。","しかし本願寺の力が強くなると、周りの大名や他の宗派との争いも激しくなります。1532年、近江の六角定頼と、京都の法華宗の門徒（法華一揆）などが山科本願寺を攻め、寺と町は焼きつくされてしまいました。本願寺は大坂の石山に拠点を移し、のちの石山本願寺（大坂本願寺）となって、織田信長と10年におよぶ戦いをくり広げます。","今、山科中央公園や周辺の住宅地には、高さ数mの土塁の一部が残っています。発掘調査では堀の跡や、御本寺の建物の跡、焼けた土なども見つかりました。近くには蓮如の墓所もあります。団地や道路の間に突然現れる土の壁 ― それが、戦国の «宗教都市» の名残なのです。"],"tl":[["1465年","延暦寺の衆徒によって京都・大谷の本願寺が破壊される"],["1471年","蓮如が越前の吉崎に拠点を築く"],["1478年","蓮如が山科に本願寺の建設を始める"],["1480年ごろ","御影堂が完成"],["1499年","蓮如が山科で亡くなる"],["1532年","六角定頼・法華一揆らの攻撃で焼失"],["2002年","山科本願寺南殿跡とあわせて国の史跡に指定される"]],"who":[["蓮如","本願寺8代。山科本願寺を建て、教団を大きく発展させた"],["実如","蓮如の子で本願寺9代。山科時代の本願寺を率いた"],["証如","本願寺10代。焼き討ち後、石山に移った"],["六角定頼","近江の大名。山科本願寺を攻めた"]],"deep":["山科本願寺は、中心部から外側へ三重の囲みをもつ構造と考えられ、寺内町の典型例、さらには後の城下町の先駆けともいわれます。","土塁の一部は、住宅地の間や山科中央公園内などに残り、場所によっては高さ数mにもなります。","蓮如が晩年に住んだ «南殿» の跡も発掘され、庭園の遺構などが見つかっています。南殿跡と土塁跡があわせて国の史跡になっています。","焼き討ちの背景には、一向一揆と大名との対立、法華宗と浄土真宗の対立など、いくつもの争いが重なっていました（天文の錯乱）。","蓮如の «御文（御文章）» は、今も浄土真宗の法要で読まれています。«白骨の御文» は特に有名です。"],"look":["山科中央公園に残る土塁と説明板","住宅地の間に残る土塁（私有地には立ち入らない）","近くの蓮如上人御廟","山科別院（西本願寺・東本願寺の山科別院）"],"q":["山科本願寺のように、寺を中心に土塁や堀で囲まれた町を何という？","«寺内町（じないまち）» といいます。"],"myth":"«仏の国のよう» と称えられた話は当時の記録に基づくとされるが、町の規模・構造は発掘からの推定を含む。","img":["蓮如","一向一揆","石山本願寺","寺内町"],"wp":"山科本願寺","rel":{"ev":[],"grave":[]}},{"id":"26_otani_honbyo","n":"大谷本廟（親鸞の墓所）","yomi":"おおたにほんびょう","cat":"墓所","rank":"B","y":1262,"era":["kamakura","edo"],"sh":"","ad":"京都市東山区五条橋東","st":"市バス «五条坂» から歩いて約3分／京阪 清水五条駅から歩いて約15分","la":34.9945,"lo":135.774,"hook":"親鸞の小さなお墓を守った娘の思いが、やがて大本山 «本願寺» に育っていった。","lead":"大谷本廟は、浄土真宗の開祖・親鸞の墓所で、浄土真宗本願寺派（西本願寺）が守っています。«西大谷» とも呼ばれます。親鸞の末娘・覚信尼が建てた小さな «廟堂» が、のちの本願寺の始まりになりました。","story":["1262年の冬、親鸞は京都で90年の生涯を閉じました。«南無阿弥陀仏» ととなえる念仏の教えを、身分の低い人びとにも広めた僧です。遺体は東山の鳥辺野で火葬され、遺骨は大谷の地に納められました。はじめは、石の塔を建てて柵で囲んだだけの、とても質素なお墓だったといいます。","親鸞の末娘・覚信尼は、父を慕う門徒たちとともに、1272年、墓を少し北の吉水のあたりに移して六角形のお堂を建て、親鸞の像を安置しました。これが «大谷廟堂» です。覚信尼は «留守職» として廟堂を守り、その役目は子孫へ受けつがれていきます。","«どうして小さなお墓が、大教団の本山になったの?» 廟堂を守る家は、やがて親鸞の教えを受けつぐ中心となり、ひ孫の覚如のころ «本願寺» と名のるようになりました。お墓を守る場所が、教団をまとめる寺へと変わっていったのです。本願寺はその後、山科、石山（大坂）と移り、豊臣秀吉から土地をもらって今の西本願寺の地に落ち着きました。","一方、親鸞の廟所は江戸時代のはじめ、1603年ごろに今の東山五条の地に移され、«大谷本廟» として整えられました。五条坂の石段を上ると、大きな総門、仏殿、そして奥に親鸞の遺骨を納める «祖壇» があります。境内の奥には、門徒のお墓が山の斜面いっぱいに広がっています。","本廟の入口の池には、石造りのアーチ橋 «円通橋»（めがね橋）がかかっています。五条通からも見える、この橋と池の景色は昔から名所でした。すぐ近くには清水寺への参道があり、観光客でにぎわいますが、本廟の中は静かで、今も多くの門徒が先祖の墓参りに訪れます。親鸞の墓を守り続けた人びとの思いが、ここに積み重なっています。"],"tl":[["1173年","親鸞が生まれる"],["1262年","親鸞が京都で亡くなり、鳥辺野で火葬される"],["1272年","覚信尼が大谷廟堂を建てる"],["14世紀前半","覚如のころ «本願寺» と名のるようになる"],["1591年","本願寺が秀吉から京都の堀川六条に土地をもらう"],["1603年ごろ","親鸞の廟所が今の東山五条に移される"],["江戸時代","円通橋や総門・仏殿などが整えられる"]],"who":[["親鸞","浄土真宗の開祖。ここに遺骨が納められている"],["覚信尼","親鸞の末娘。大谷廟堂を建て、守り続けた"],["覚如","親鸞のひ孫。廟堂を «本願寺» として発展させた"],["蓮如","本願寺8代。教団を大きく広げた"]],"deep":["東本願寺（真宗大谷派）も東山に «大谷祖廟（東大谷）» をもっており、«西大谷»«東大谷» と呼び分けられています。","親鸞の火葬地は «延仁寺» の地とされ、東山区今熊野の近くに跡が伝わります。","覚信尼が廟堂の土地を門徒全体の共有とした（寄進した）ことが、のちの本願寺の性格に影響を与えたといわれます。","円通橋は、江戸時代の終わりごろに造られた石造のアーチ橋とされ、京都の石橋の中でも目立つ存在です。","本廟では、門徒の遺骨を親鸞の廟の近くに納める «祖壇納骨» が行われており、多くの人が «親鸞聖人のそばで眠りたい» と願ってきました。"],"look":["池にかかる石造アーチ橋 «円通橋»","総門と仏殿","親鸞の遺骨を納める祖壇（明著堂の奥）","斜面いっぱいに広がる墓地のながめ"],"q":["大谷本廟の始まりとなった «大谷廟堂» を建てた人物は？","親鸞の末娘・覚信尼です。"],"myth":"円通橋の建造年は推定を含む。","img":["親鸞","覚信尼","本願寺","浄土真宗"],"wp":"大谷本廟","rel":{"ev":["kuya","kiyomori"],"grave":[["shinran","親鸞"]]}},{"id":"26_tojiin","n":"等持院（足利将軍の木像）","yomi":"とうじいん","cat":"墓所","rank":"B","y":1341,"era":["muromachi","edo","taisho"],"sh":"","ad":"京都市北区等持院北町","st":"京福電鉄北野線 等持院・立命館大学衣笠キャンパス前駅から歩いて約10分","la":35.0318,"lo":135.7256,"hook":"ずらりと並ぶ歴代将軍の木像。幕末、その «首» が切られて河原にさらされた。","lead":"等持院は、室町幕府を開いた足利尊氏が建てた禅寺で、尊氏の墓があります。霊光殿には歴代の足利将軍の木像が並び、«足利家の菩提寺» として知られています。幕末には、この木像の首が持ち去られる事件も起きました。","story":["1341年ごろ、足利尊氏は、禅僧の夢窓疎石を開山にむかえて寺を建てました。はじめは京都の町なかにあった等持寺の別院で、北にあったので «北等持寺» と呼ばれました。1358年に尊氏が亡くなると、ここに葬られ、寺の名も «等持院» となって、足利将軍家の菩提寺になりました。","霊光殿に入ると、ずらりと並ぶ木像に目をうばわれます。初代尊氏から15代義昭まで、足利将軍の像が並んでいます（5代義量、14代義栄の像はありません）。着ている服や顔立ちには一人ひとりの個性があり、«教科書で見たあの将軍は、こんな顔?» と見比べるのも楽しみです。徳川家康の像もいっしょにまつられています。","1863年、この木像に大事件が起こります。尊王攘夷の考えをもつ浪士たちが寺にしのびこみ、尊氏・義詮・義満の三代の木像の首を持ち去って、三条河原にさらしたのです。そばには «天皇に逆らった逆賊» と非難する文が立てられました。«なぜ木像に?» 本当のねらいは、天皇をないがしろにしているとされた当時の徳川幕府への警告だったといわれます。","寺の庭園は、夢窓疎石の作と伝わる池泉回遊式の庭です。東の «心字池»、西の «芙蓉池»、そして茶室 «清漣亭» があり、四季折々の花が美しいことで知られます。とくに有楽椿やさつき、秋の紅葉が見事です。","大正時代には、日本映画の父と呼ばれる牧野省三が、寺の境内に «等持院撮影所» を開きました。時代劇の名作がここから生まれ、境内には牧野省三の銅像も立っています。南北朝の動乱、幕末の事件、そして映画の歴史 ― ひとつの寺に、いくつもの時代が重なっています。"],"tl":[["1341年ごろ","足利尊氏が夢窓疎石を開山に寺を建てる"],["1358年","尊氏が亡くなり、ここに葬られる"],["室町時代","足利将軍家の菩提寺となる"],["1863年","足利三代の木像の首が三条河原にさらされる（足利三代木像梟首事件）"],["1921年","牧野省三が等持院撮影所を開く"]],"who":[["足利尊氏","室町幕府初代将軍。寺を建て、ここに眠る"],["夢窓疎石","開山の禅僧。庭園の作者と伝わる"],["足利義満","3代将軍。木像が梟首事件で被害にあった一人"],["牧野省三","日本映画の父。境内に撮影所を開いた"]],"deep":["尊氏の墓は、境内の宝篋印塔です。ただし京都市内の等持寺跡や、鎌倉の長寿寺にも尊氏の墓とされるものがあります。","足利三代木像梟首事件では、平田派の国学を学んだ浪士らが捕らえられました。事件の背景には、尊氏を «逆賊» とする南朝正統論の広まりがありました。","木像は江戸時代の作とされるものも含まれ、すべてが将軍の生きていた時代に作られたわけではありません。","等持院は臨済宗天龍寺派の寺です。尊氏が夢窓疎石のすすめで建てた天龍寺とも深いつながりがあります。","茶室 «清漣亭» は、8代将軍義政の好みと伝わります。"],"look":["霊光殿の歴代足利将軍の木像","尊氏の墓の宝篋印塔","芙蓉池・心字池の庭園と清漣亭","境内の牧野省三の銅像"],"q":["1863年、等持院の足利将軍の木像はどんな事件にあった？","尊氏・義詮・義満の木像の首が持ち去られ、三条河原にさらされました（足利三代木像梟首事件）。"],"myth":"庭園の作者を夢窓疎石とするのは伝承。清漣亭を義政好みとするのも伝承。","img":["足利尊氏","夢窓疎石","足利三代木像梟首事件","牧野省三"],"wp":"等持院","rel":{"ev":[],"grave":[["takauji","足利尊氏"]]}},{"id":"26_suiheisha","n":"全国水平社創立の地（岡崎公会堂跡）","yomi":"ぜんこくすいへいしゃそうりつのち","cat":"近代","rank":"B","y":1922,"era":["taisho"],"sh":"","ad":"京都市左京区岡崎最勝寺町（ロームシアター京都付近）","st":"京都市営地下鉄東西線 東山駅から歩いて約10分","la":35.0138,"lo":135.7826,"hook":"«人の世に熱あれ、人間に光あれ» ― 日本で初めての人権宣言といわれる言葉が、ここで読み上げられた。","lead":"1922年3月3日、京都・岡崎の公会堂で «全国水平社» の創立大会が開かれました。いわれのない差別に苦しめられてきた被差別部落の人びとが、自らの手で差別をなくそうと立ち上がったのです。公会堂は今はなく、跡地にはロームシアター京都が建っています。","story":["江戸時代、身分制度のもとで、一部の人びとは «えた»«ひにん» などと呼ばれ、住む場所や仕事、結婚などで厳しい差別を受けていました。1871年、明治政府はこうした呼び名を廃止する布告を出します（いわゆる «解放令»）。しかし差別はなくならず、学校や職場、結婚の場で、人びとはいわれのない扱いを受け続けました。","大正時代、奈良県の柏原（今の御所市）の若者たちが声を上げました。西光万吉、阪本清一郎、駒井喜作らです。«だれかに哀れんでもらうのではなく、自分たちの力で差別をなくそう»。彼らは全国に呼びかけ、京都で大会を開くことにしました。«水平» という名には、人間はみな平らで等しい、という思いがこめられています。","1922年3月3日、岡崎公会堂には全国から2000人以上とも伝わる人びとが集まりました。壇上で読み上げられたのが «水平社宣言» です。«全国に散在する吾が特殊部落民よ団結せよ» で始まり、«人の世に熱あれ、人間に光あれ» で結ばれるこの宣言は、差別される側が自らの誇りを語った、日本で最初の人権宣言ともいわれます。会場は感動につつまれたと伝わります。","水平社の旗は、黒地に赤い «荊冠»（いばらの冠）。苦しみの中でも誇りをもって進む、という意味がこめられていました。水平社の運動は全国に広がり、差別をなくす運動の出発点となりました。その流れは、戦後の部落解放運動や、人権を守る取り組みへとつながっていきます。","岡崎公会堂は、のちに京都会館となり、2016年にロームシアター京都として生まれ変わりました。建物は変わりましたが、ここは «人間の尊厳» を求める声が上がった場所です。差別は «昔の話» ではなく、今もインターネットなどで問題になっています。«人の世に熱あれ» ― その言葉を、自分たちの問題として考えたい場所です。"],"tl":[["1871年","明治政府が身分の呼び名を廃止する布告を出す"],["1920年ごろ","奈良県柏原の青年たちが運動を始める"],["1922年3月3日","岡崎公会堂で全国水平社の創立大会。水平社宣言が読み上げられる"],["1942年","戦時体制のもとで水平社が消滅"],["1946年","部落解放全国委員会が結成される（戦後の運動へ）"],["2016年","跡地にロームシアター京都が開館"],["2022年","水平社創立100年"]],"who":[["西光万吉","水平社宣言の起草者とされる。荊冠旗を考案したともいわれる"],["阪本清一郎","柏原の創立者の一人"],["駒井喜作","創立大会で宣言を朗読したとされる"],["南梅吉","京都の運動家。水平社の初代の中心人物の一人"]],"deep":["水平社宣言は、差別する側を責めるだけでなく、差別される側が «人間の誇り» を取り戻そうと呼びかけた点が、画期的だと評価されています。","宣言の文章には、今の目から見ると差別的な表現も含まれますが、当時の人びとが自らをそう名乗って誇りを取り戻そうとした歴史的な文書として読まれています。","水平社博物館（奈良県御所市柏原）には、創立に関わる資料が展示されています。","2016年には «部落差別の解消の推進に関する法律» が施行されました。差別の問題は今も続いています。","京都市内には、創立大会の地をしのぶ説明板などがあり、人権学習の場として訪れる学校もあります。"],"look":["ロームシアター京都周辺（岡崎公会堂の跡地）","岡崎の平安神宮・京都市京セラ美術館など、近代の建物群","近くの疏水沿いの道"],"q":["水平社宣言の最後の言葉は？","«人の世に熱あれ、人間に光あれ»。"],"myth":"大会の参加人数は資料により異なる。宣言の起草・荊冠旗の考案者は西光万吉とされるが、関わった人は複数いた。","img":["水平社宣言","西光万吉","ロームシアター京都"],"wp":"全国水平社","rel":{"ev":["insei","hogen","suiheisha"],"grave":[]}},{"id":"26_funaokayama","n":"船岡山（船岡山合戦・信長を祀る建勲神社）","yomi":"ふなおかやま","cat":"古戦場","rank":"B","y":1511,"era":["heian","muromachi","meiji"],"sh":"国指定史跡","ad":"京都市北区紫野北舟岡町","st":"市バス «船岡山» または «建勲神社前» から歩いて約5分","la":35.0385,"lo":135.7432,"hook":"平安京を設計する «目印» だったかもしれない小さな山。戦国の戦場になり、やがて信長の神社になった。","lead":"船岡山は、京都市北区にある高さ約112mの小さな山です。平安京をつくるときの基準になったという説があり、清少納言も «岡は船岡» とたたえました。戦国時代には «船岡山合戦» の舞台となり、明治には織田信長をまつる建勲神社が建てられました。","story":["船岡山は、船をふせたような形から名がついたといわれます。平安京の中心を南北に走る朱雀大路をまっすぐ北にのばすと、ちょうどこの山のあたりにぶつかります。«都の設計の目印にしたのでは?» という説があり、風水でいう «玄武»（北を守る神）にあたる山と考える人もいます（諸説あり）。","平安時代、船岡山は貴族たちが野遊びを楽しむ場所でした。清少納言は『枕草子』で、«岡は船岡» と、数ある岡の中でいちばんに名を挙げています。一方で、近くには葬送の地もあり、都の北の «境目» のような場所でもありました。","戦国時代、京都は争いの舞台になります。1511年、将軍の座をめぐって、足利義尹（のちの義稙）を立てる大内義興・細川高国の軍と、足利義澄を立てる細川澄元の軍が戦いました。澄元方の軍が船岡山に陣を置いたところを、大内・細川高国の軍が攻め、激しい戦いの末に大内方が勝ちます。これが «船岡山合戦» です。応仁の乱のときにも、西軍がこの山に陣を構えたといわれます。","時は流れて明治時代。明治天皇は、戦国の世を終わらせ天下統一への道を開いた織田信長の功績をたたえ、1869年に信長をまつる神社をつくるよう命じました。これが «建勲（たけいさお）神社» で、1880年に船岡山の山頂近くに社殿が移されました。«なぜ船岡山に?» 秀吉が信長の菩提寺を建てようとした場所の近くで、ゆかりのある土地だったといわれます。","今、建勲神社の石段を上がると、信長が好んだとされる «人間五十年、下天のうちをくらぶれば…» の «敦盛» の一節を刻んだ碑があります。山頂からは、京都市内と、遠く大文字の送り火の山々が見わたせます。平安の目印、戦国の戦場、明治の神社 ― 小さな山に、京都の長い歴史が重なっています。"],"tl":[["794年","平安京に遷都。船岡山が都の北の目印になったという説がある"],["平安時代","貴族の遊覧地となり、清少納言が «岡は船岡» と記す"],["1467年〜","応仁の乱で西軍が陣を置いたといわれる"],["1511年","船岡山合戦。大内義興・細川高国の軍が勝つ"],["1869年","明治天皇が信長をまつる神社の創建を命じる"],["1880年","建勲神社が船岡山に移される"],["1968年","船岡山が国の史跡に指定される"]],"who":[["織田信長","建勲神社の祭神。天下統一への道を開いた"],["大内義興","周防の大名。船岡山合戦で勝利した"],["細川高国","義興とともに戦い、合戦後に管領として力をもった"],["細川澄元","船岡山合戦で敗れた側の大将"],["清少納言","『枕草子』で船岡山をたたえた"]],"deep":["平安京が船岡山を基準に設計されたという説はよく知られていますが、確かな史料による裏付けは乏しく、諸説の一つです。","船岡山合戦の結果、足利義稙が将軍に復帰し、大内義興は約10年京都にとどまって政治に関わりました。","建勲神社の «建勲» は «たけいさお» と読むのが正式ですが、«けんくん» とも呼ばれます。","建勲神社には、信長が桶狭間の戦いで今川義元から奪ったと伝わる名刀 «義元左文字»（重要文化財）が伝わっています。","山には応仁の乱や戦国の城（船岡山城）の跡とされる堀切や土塁の名残があるといわれます。"],"look":["建勲神社の本殿と «敦盛» の碑","山頂から見る京都市街と大文字山","公園に残る地形の起伏（城の跡とされる）","ふもとの大徳寺（信長の葬儀が行われた寺）"],"q":["清少納言が『枕草子』で «岡は〇〇» と書いた、〇〇に入る岡の名は？","«船岡»。船岡山のことです。"],"koji":[{"w":"人間五十年、下天のうちをくらぶれば夢幻のごとくなり","m":"幸若舞 «敦盛» の一節。信長が好んで舞ったと伝わる"}],"myth":"平安京の基準・玄武とする説、応仁の乱の陣、城の遺構の評価には諸説がある。","img":["建勲神社","船岡山合戦","織田信長","枕草子"],"wp":"船岡山","rel":{"ev":[],"grave":[]}},{"id":"26_iwakura","n":"岩倉具視幽棲旧宅","yomi":"いわくらともみゆうせいきゅうたく","cat":"幕末","rank":"B","y":1864,"era":["edo","meiji"],"sh":"国指定史跡","ad":"京都市左京区岩倉上蔵町","st":"京都バス «岩倉実相院» から歩いて約3分／叡山電鉄 岩倉駅から歩いて約20分","la":35.0804,"lo":135.7832,"hook":"都を追われた公家が、田舎の小さな家で «王政復古» の筋書きを練っていた。","lead":"岩倉具視幽棲旧宅は、幕末の公家・岩倉具視が京都から追放されていた時期に住んだ家です。5年ほど、洛北の岩倉村でひっそり暮らしながら、坂本龍馬の仲間の中岡慎太郎や、薩摩の大久保利通らと会い、新しい政府づくりの準備を進めました。国の史跡です。","story":["岩倉具視は、下級の公家の家に生まれながら、頭の良さと行動力で朝廷の中で頭角をあらわしました。幕府と朝廷の仲を取り持つ «公武合体» をすすめ、孝明天皇の妹・和宮を14代将軍・徳川家茂に嫁がせる話を実現させます。ところが、これが «幕府にこびる裏切り者» と尊王攘夷派の激しい怒りを買いました。","1862年、岩倉は命をねらわれる危険の中で官職を辞し、頭を丸めて都を追われます。いくつかの場所を転々としたあと、1864年から洛北の岩倉村のこの家に住みました。大工の家を買い取ったといわれる、質素な家です。«もう政治の表舞台には戻れないのか»。そんな思いもあったでしょう。","しかし岩倉はあきらめませんでした。この家には、しだいにさまざまな人が訪れます。土佐の中岡慎太郎、薩摩の大久保利通や小松帯刀らです。人目をしのんで語り合ったのは、幕府をどうするか、朝廷を中心とした新しい国をどうつくるか ― という話でした。岩倉は «叢裡鳴虫»（くさむらで鳴く虫）などの意見書を書き、朝廷の政治の改革を訴えました。","1867年、岩倉は許されて都に戻ります。そして同じ年の12月9日、薩摩藩などと手を組み、«王政復古の大号令» を実現させました。幕府は廃止され、天皇を中心とした新政府が誕生します。岩倉村の小さな家で練られた構想が、ついに実を結んだのです。","その後、岩倉は新政府の中心人物となり、1871年からは «岩倉使節団» を率いて欧米を回りました。旧宅には、主屋などの建物が残り、敷地内の «対岳文庫» では岩倉ゆかりの資料が展示されています。近くには門跡寺院の実相院もあり、静かな岩倉の里を歩くと、幕末の隠れ家の雰囲気が伝わってきます。"],"tl":[["1825年","岩倉具視が生まれる"],["1861年","和宮が将軍・家茂のもとへ嫁ぐ（降嫁）"],["1862年","岩倉が尊攘派に非難され、官職を辞して都を追われる"],["1864年","岩倉村のこの家に移り住む"],["1867年","許されて都に戻る。12月、王政復古の大号令"],["1871年","岩倉使節団を率いて欧米へ出発"],["1883年","岩倉具視が亡くなる"],["1932年","旧宅が国の史跡に指定される"]],"who":[["岩倉具視","公家。追放中にこの家に住み、王政復古を準備した"],["中岡慎太郎","土佐の志士。ここを訪れ、岩倉と薩長をつないだ"],["大久保利通","薩摩藩士。岩倉と手を組み、新政府を築いた"],["和宮","孝明天皇の妹。岩倉がすすめた将軍家への降嫁で知られる"]],"deep":["岩倉は尊攘派から、和宮降嫁を進めた «四奸二嬪» の一人として非難されました。","旧宅の敷地の «対岳文庫» は、昭和のはじめに岩倉の遺品などを収めるために建てられた建物で、今は資料の展示に使われています。","中岡慎太郎は岩倉を高く評価し、薩摩の人びとに岩倉を紹介したと伝わります。","岩倉は500円札（旧紙幣）の肖像にもなりました。","旧宅の庭からは比叡山が見え、«対岳» という名前はその山を望むことに由来するといわれます。"],"look":["岩倉が住んだ主屋（質素な造り）","対岳文庫の展示資料","庭から望む比叡山","近くの実相院の «床もみじ»（公開時期に注意）"],"q":["岩倉具視が岩倉村で準備を進め、1867年12月に実現させた出来事は？","«王政復古の大号令»。幕府を廃止し、天皇中心の新政府をつくると宣言しました。"],"myth":"大工の家を買い取った話、対岳文庫の名前の由来には諸説がある。","img":["岩倉具視","王政復古 (日本)","和宮親子内親王","岩倉使節団"],"wp":"岩倉具視幽棲旧宅","rel":{"ev":[],"grave":[]}},{"id":"26_div16","n":"旧陸軍第十六師団司令部（深草・聖母女学院）","yomi":"きゅうりくぐんだいじゅうろくしだんしれいぶ","cat":"昭和","rank":"B","y":1908,"era":["meiji","showa"],"sh":"国の登録有形文化財","ad":"京都市伏見区深草田谷町（聖母女学院 本館）","st":"京阪本線 藤森駅から歩いて約3分（学校の敷地のため、ふだんは中に入れない）","la":34.9503,"lo":135.7712,"hook":"女子校の白い洋館は、かつて京都の兵隊たちを戦場へ送り出した «師団司令部» だった。","lead":"伏見区深草にある聖母女学院の本館は、明治時代に建てられた旧陸軍第十六師団の司令部の建物です。京都を拠点としたこの師団は、日中戦争や太平洋戦争で各地の戦場に送られました。戦後、学校として生まれ変わった建物は、戦争と平和の両方の記憶を伝えています。","story":["日露戦争のころ、陸軍は兵隊の数を増やすために新しい師団をつくりました。そのうちの一つが第十六師団です。1908年ごろ、師団は京都の深草に置かれ、司令部の建物が建てられました。れんが造りの二階建てで、正面に玄関のある洋風の建物です。深草から伏見にかけては、兵舎や練兵場、陸軍の施設が次々とつくられ、«軍都» と呼ばれる町になりました。","«なぜ深草に?» 京都の町に近く、広い土地があり、鉄道も通っていたからです。今も残る «師団街道» という道の名前は、ここと京都の町を結ぶ道だったことから来ています。兵隊を相手にした商店が並び、町は大きく変わりました。","第十六師団には、京都や滋賀、奈良、三重などの若者が入隊しました。1937年、日中戦争が始まると師団は中国へ送られ、南京攻略戦に加わりました。このときの戦いでは、多くの中国の兵士や一般の人びとが犠牲になりました（南京事件。犠牲者の数については諸説があります）。この歴史も、この場所の記憶の一部です。","太平洋戦争が始まると、師団はフィリピンへ送られました。1944年、アメリカ軍がレイテ島に上陸すると、第十六師団はその正面で戦い、ほぼ全滅しました。帰ってこられた人はほんのわずかでした。京都のたくさんの家庭が、家族を戦場で失ったのです。","戦争が終わると、師団はなくなりました。司令部の建物は、1949年ごろからカトリックの学校・聖母女学院の校舎として使われるようになります。兵隊に命令を出していた建物で、子どもたちが学ぶ ― そのことに、平和のありがたさを感じずにはいられません。建物は国の登録有形文化財になり、年に何度か公開されることもあります。周りの龍谷大学や京都教育大学の土地も、もとは陸軍の施設でした。"],"tl":[["1905年","日露戦争中に第十六師団が編成される"],["1908年ごろ","師団が京都・深草に置かれ、司令部庁舎が完成"],["1937年","日中戦争が始まり、師団が中国へ送られる。南京攻略戦に参加"],["1941年","太平洋戦争が始まり、フィリピンへ"],["1944年","レイテ島の戦いで師団がほぼ全滅"],["1945年","終戦。師団が解体される"],["1949年ごろ","聖母女学院が建物を使い始める"]],"who":[["第十六師団の将兵","京都などから入隊し、多くが戦場で亡くなった"],["戦争の犠牲者","中国やフィリピンなどで、戦争に巻き込まれた人びと"],["聖母女学院","戦後、司令部の建物を校舎として受け継いだ学校"]],"deep":["«師団» とは、約1万〜2万人の兵隊をまとめた陸軍の大きな単位です。司令部は、その師団に命令を出す中心でした。","«師団街道» のほか、深草には «第一軍道»«第二軍道» など、陸軍にちなむ道の名前も残っています。","レイテ島の戦いでの第十六師団の戦死者は非常に多く、師団は事実上消滅しました。正確な人数は資料によって違いがあります。","司令部の建物は、明治の陸軍の建物の特徴をよく残しており、近代建築として貴重だとされています。","伏見区の深草・藤森周辺には、陸軍の兵器庫や練兵場の跡が、大学のキャンパスや公園として今も使われています。"],"look":["聖母女学院本館の外観（門の外から。中は公開日のみ）","«師団街道» の道標","藤森神社（すぐ近く、菖蒲の節句の武者行列でも知られる）","龍谷大学深草キャンパス（旧陸軍の施設跡）"],"q":["深草にある «師団街道» という道の名前は、何に由来する？","陸軍の第十六師団が置かれ、京都の町と結ぶ道だったことに由来します。"],"myth":"南京事件の犠牲者数、レイテ島での戦死者数には諸説・資料による違いがある。","img":["レイテ島の戦い","聖母女学院","師団街道"],"wp":"第16師団 (日本軍)","rel":{"ev":[],"grave":[]}},{"id":"26_katsuryuji","n":"勝竜寺城（細川ガラシャ輿入れの城）","yomi":"しょうりゅうじじょう","cat":"城","rank":"B","y":1578,"era":["muromachi","azuchi"],"sh":"","ad":"長岡京市勝竜寺","st":"JR京都線 長岡京駅から歩いて約10分","la":34.9275,"lo":135.698,"hook":"16歳の花嫁・玉がこの城に嫁いだ4年後、父・明智光秀は本能寺の変を起こした。","lead":"勝竜寺城は、今の長岡京市にあった城です。細川藤孝（幽斎）が城主のとき、明智光秀の娘・玉（のちの細川ガラシャ）が、息子の忠興のもとに嫁いできました。本能寺の変のあとの山崎の戦いでは、光秀がこの城に入り、最後の夜を迎えました。今は公園として整備されています。","story":["勝竜寺城は、南北朝時代の1339年に細川頼春が築いたと伝わります。京都から西国へ向かう道と、桂川・淀川の水運をおさえる大事な場所でした。戦国時代、1571年に織田信長から一帯をまかされた細川藤孝が、城を大きく改修し、石垣や瓦をもつ «新しい城» に造り替えました。","1578年、この城に16歳の花嫁がやって来ます。明智光秀の娘・玉です。夫は同じく16歳の細川忠興。信長のすすめによる結婚で、二人は仲のよい夫婦だったといわれます。玉は美しく、かしこい女性として知られ、のちにキリスト教の洗礼を受けて «ガラシャ» と名乗りました。","しかし幸せは長く続きません。1582年6月、父・光秀が本能寺の変を起こしたのです。光秀は細川家に味方になるよう頼みましたが、藤孝と忠興はこれを断り、玉は «謀反人の娘» として丹後の山奥・味土野（みどの）に幽閉されました。«なぜ父は…» 玉の苦しみはここから始まります。","6月13日、光秀は羽柴秀吉と山崎で戦いました。勝竜寺城は、その光秀軍の拠点の一つとなり、敗れた光秀はいったんこの城に逃げこみます。しかし城は守りきれるものではありませんでした。夜、光秀はひそかに城を抜け出し、近江の坂本城をめざしましたが、途中の小栗栖で命を落としました。娘が嫁いできた城が、父の最後の城になったのです。","その後、城は使われなくなり、跡は田畑になりました。1992年、発掘調査をもとに «勝竜寺城公園» として整備され、隅櫓風の建物や堀、石垣がつくられました。発掘では、信長の時代の古い石垣や瓦も見つかっています。毎年秋には、玉の輿入れ行列を再現する «長岡京ガラシャ祭» が行われ、町の人びとが玉と忠興の物語をしのびます。"],"tl":[["1339年","細川頼春が築城したと伝わる"],["1571年","細川藤孝が城主となり、城を改修"],["1578年","明智光秀の娘・玉が細川忠興に嫁ぐ"],["1582年6月","本能寺の変。玉は丹後の味土野に幽閉される"],["1582年6月13日","山崎の戦い。敗れた光秀が勝竜寺城に入り、夜に脱出"],["1600年","ガラシャが大坂の細川屋敷で亡くなる"],["1992年","勝竜寺城公園として整備される"]],"who":[["細川ガラシャ（玉）","明智光秀の娘。この城で細川忠興と結婚した"],["細川忠興","ガラシャの夫。のちの豊前小倉・肥後熊本藩細川家のもとを築いた"],["細川藤孝（幽斎）","忠興の父。城を改修した城主"],["明智光秀","玉の父。山崎の戦いで敗れ、この城から落ちのびた"]],"deep":["勝竜寺城の石垣は、信長の時代の城として早い時期の石垣の例とされ、転用石（石仏など）も見つかっています。","1339年の頼春による築城は伝承で、はっきりした史料での確認は難しいとされます。","玉が幽閉された味土野は、今の京丹後市弥栄町にあり、«ガラシャ隠棲地» の碑が立っています。","1600年、ガラシャは石田三成から人質になるよう求められましたが、これを拒み、家臣の手を借りて命を絶ちました。キリスト教では自殺が禁じられていたためといわれます。","«散りぬべき時知りてこそ世の中の花も花なれ人も人なれ» は、ガラシャの辞世として伝わる歌です。"],"look":["勝竜寺城公園の隅櫓風の建物と堀","発掘で見つかった石垣の展示","公園内のガラシャと忠興の像","近くの細川家ゆかりの «神足神社» の土塁"],"q":["細川ガラシャの結婚前の名前は？","«玉（たま）»。明智光秀の娘です。"],"myth":"頼春による築城、辞世の歌などは伝承を含む。夫婦仲の評価も諸説ある。","img":["細川ガラシャ","細川忠興","細川幽斎","山崎の戦い"],"wp":"勝竜寺城","rel":{"ev":["nagaoka"],"grave":[]}},{"id":"26_uji_ryo","n":"宇治陵（藤原氏の墓所・木幡）","yomi":"うじりょう","cat":"墓所","rank":"B","y":1005,"era":["heian"],"sh":"","ad":"宇治市木幡（こわた）一帯","st":"京阪宇治線 木幡駅から歩いて約10分（総拝所）","la":34.9225,"lo":135.801,"hook":"住宅地の間に点々と残る小さな森。そこは、平安の都を動かした藤原一族が眠る «一族の墓地» だった。","lead":"宇治市の木幡の丘には、藤原氏の人々、とくに天皇のきさきや母となった女性たちのお墓がたくさんあります。宮内庁はこれをまとめて «宇治陵» とよび、30か所をこえる塚を管理しています。藤原道長もここに眠るといわれます。","story":["京都から宇治へ向かう道の途中、京阪電車の木幡駅のまわりを歩くと、家と家のすきまに、柵で囲まれた小さな森がいくつも見つかります。石の標識には «宇治陵» と番号。じつはここ、平安時代に «摂関政治» で権力をにぎった藤原北家の人々の墓地だったのです。なぜ都の中ではなく、宇治の手前の丘だったのでしょう?","平安時代の貴族は、死をけがれとして都から遠ざけました。そこで郊外に一族の «墓所» を決め、代々そこに葬ったのです。藤原氏がえらんだのが、都から宇治へ抜ける道ぞいの木幡。見晴らしのよい丘で、藤原基経のころから一族の墓がつくられるようになったといわれます。","ところが平安の人々は、遺体を葬ったあとはお墓をあまり大事にしませんでした。魂は寺でとむらうもので、墓は «からっぽの場所» と考えたからです。若いころの藤原道長が木幡をおとずれたとき、先祖の墓が草にうもれ、だれのものかもわからないありさまだったと伝わります。«このままでは申しわけない» ――そう思った道長は、ここに寺を建てると心に決めました。","1005年、道長は木幡に «浄妙寺» を建て、三昧堂で一族の成仏をいのる法華三昧をおこなわせました。のちには多宝塔も建ちます。権力の頂点に立った道長が、なぜ墓参りの寺にこだわったのか。栄華のかげで、一族の死者と向き合う気持ちがあったのかもしれません。道長自身も1027年に亡くなると、遺骨は木幡におさめられたといわれます。","時代がたつと浄妙寺はすたれ、どの塚がだれの墓なのかも、ほとんどわからなくなりました。明治になって宮内庁が、天皇のきさきや母になった女性たちの墓として、塚をまとめて «宇治陵» に定めます。いまは総拝所で手を合わせることができ、住宅地の森は、千年前の一族の祈りを静かに伝えています。"],"tl":[["9世紀後半","藤原基経のころ、木幡が藤原北家の墓所になっていったといわれる"],["1005年","藤原道長が木幡に浄妙寺を建て、三昧堂を供養"],["1027年","藤原道長が亡くなり、遺骨が木幡におさめられたと伝わる"],["平安時代後期","藤原氏出身のきさきたちが次々と木幡に葬られる"],["明治時代","宮内庁（当時の宮内省）が塚をまとめて «宇治陵» として管理"],["1990年代","浄妙寺跡の発掘調査で、寺の遺構が確認される"]],"who":[["藤原道長","浄妙寺を建てて一族の墓所を整えた。自身も木幡に眠るといわれる"],["藤原基経","最初の関白。木幡の墓所の始まりにかかわるとされる"],["藤原彰子（上東門院）","道長の娘で一条天皇の中宮。宇治陵に葬られた女性の一人とされる"],["藤原頼通","道長の子。宇治に平等院をひらき、宇治を藤原氏の聖地にした"]],"deep":["宇治陵は «一つの陵» ではなく、木幡から宇治にかけて散らばる番号つきの塚の総称です。宮内庁は1号から37号までの塚を管理しているとされ、総拝所は1号陵の近くにあります。","どの塚がだれの墓かはほとんど確定できません。明治の治定は伝承や地名をたよりにしたもので、考古学的に被葬者がわかったものではない点に注意が必要です。","浄妙寺跡は、いまの宇治市立木幡小学校のあたりで発掘され、三昧堂や多宝塔の跡とみられる遺構が見つかっています。道長の «墓寺» の実在を裏づける発見でした。","平安貴族は火葬が多く、遺骨を墓所におさめたあとは、年忌も寺で営むのがふつうでした。 «墓参り» の習慣が広まるのはもっと後の時代で、道長の浄妙寺はその早い例ともいえます。","木幡は宇治への入口です。道長の子・頼通が1052年に別荘を寺にしたのが平等院。つまり木幡の墓所と平等院は、藤原氏が «宇治» を一族の特別な土地にしていった流れの中にあります。","道長の日記『御堂関白記』には、浄妙寺にかかわる記事が見られます。自筆の日記が国宝として残っているため、寺づくりへの熱意を本人の言葉でたどれるのが貴重です。"],"look":["総拝所（京阪木幡駅の東側）","住宅地の中に点在する番号つきの塚と石標","浄妙寺跡の説明板（木幡小学校付近）","足をのばして平等院へ。墓所から聖地へつながる藤原氏の «宇治»"],"q":["藤原道長が一族の墓所の近くに建てた寺の名前は?","«浄妙寺»。1005年に三昧堂が供養され、一族の成仏をいのりました。いまは跡だけが残ります。"],"myth":"道長が荒れた墓を見て寺を建てようと決めた話は伝承的な要素をふくむ。個々の塚の被葬者は明治の治定で、学問的には未確定。","img":["藤原道長","浄妙寺 (宇治市)","平等院"],"wp":"宇治陵","rel":{"ev":[],"grave":[]}},{"id":"26_makishimajo","n":"槇島城跡（室町幕府滅亡の地）","yomi":"まきしまじょうあと","cat":"城","rank":"B","y":1573,"era":["muromachi","azuchi"],"sh":"","ad":"宇治市槇島町（まきしまちょう）","st":"京阪宇治線・JR奈良線の宇治駅から歩いて約30分、またはバス。石碑は住宅地の中","la":34.905,"lo":135.789,"hook":"いまは住宅地の中の石碑ひとつ。でも、240年近く続いた室町幕府が終わりを迎えたのは、この場所だった。","lead":"槇島城は、宇治川と巨椋池（おぐらいけ）にかこまれた、水に浮かぶような城でした。1573年、15代将軍・足利義昭はここで織田信長に最後の戦いをいどみ、敗れて京都を追われます。これが «室町幕府のおわり» とされる出来事です。城は残っておらず、石碑が立つだけです。","story":["1573年の夏。京都の二条の御所を出た将軍・足利義昭は、南の宇治へと向かいました。めざしたのは槇島城。まわりを宇治川の流れと巨大な池・巨椋池にかこまれ、攻めにくい «水の城» です。«ここなら信長もかんたんには手が出せまい» ――義昭はそう考えたのかもしれません。","義昭は、もともと信長に助けられて将軍になった人でした。ところが、しだいに信長が政治の実権をにぎり、義昭の行動をしばるようになります。義昭は武田信玄や浅井・朝倉、本願寺などに手紙を送り、信長をかこむ包囲網をつくろうとしました。けれども頼みの信玄はこの年の春に亡くなってしまいます。","信長の動きは速いものでした。大軍が宇治川に着くと、水かさが増した川を前に、家臣たちはためらったといいます。そこで信長みずから渡河を命じ、軍勢は二手に分かれて川を押し渡ったと伝わります。城は取りかこまれ、数日のうちに勝負はつきました。","義昭は降参し、幼い息子を人質に差し出して城を出ました。信長は将軍の命まではとらず、京都から追い出すだけにします。なぜ殺さなかったのでしょう? «将軍殺し» の悪名を避けたかった、とも考えられています。義昭はその後も備後の鞆（とも）などで将軍を名のり続けましたが、京都にもどることはありませんでした。","城のまわりの景色は、その後大きく変わります。豊臣秀吉は伏見城を築くとき宇治川の流れを変え、昭和の初めには巨椋池も干拓されて田畑になりました。水にかこまれた城のすがたは、もう想像するしかありません。住宅地の石碑の前で、足もとがかつて水辺だったことを思いうかべてみてください。"],"tl":[["室町時代","宇治川の中州・槇島に真木島（槇島）氏が城を構える"],["1568年","足利義昭が織田信長に奉じられて上洛、15代将軍に"],["1573年4月","武田信玄が亡くなる"],["1573年7月","義昭が槇島城で挙兵。信長の大軍に囲まれ降伏、京都から追放される"],["1573年7月","元号が «天正» に改められる"],["1594年ごろ","豊臣秀吉が伏見城築城にあわせて宇治川の流れを付け替える"],["1933〜1941年","巨椋池の干拓工事。城のまわりの水辺が消える"]],"who":[["足利義昭","室町幕府15代将軍。槇島城で信長に敗れ、京都を追われた"],["織田信長","義昭を将軍にした後に対立し、槇島城を攻め落とした"],["真木島昭光","槇島城の城主で義昭の側近。義昭の流浪にも付き従ったとされる"],["豊臣秀吉","のちに宇治川の流れを変え、城のまわりの地形を一変させた"]],"deep":["«室町幕府の滅亡» は1573年とするのが一般的ですが、義昭は追放後も将軍職を朝廷に返しておらず、鞆で «鞆幕府» ともよばれる活動を続けました。滅亡の年をいつとみるかには諸説あります。","信長は義昭追放の直後、朝廷に働きかけて元号を «元亀» から «天正» に改めさせました。新しい時代の始まりを、元号でも示したといえます。","巨椋池は周囲約16kmともいわれた京都盆地最大の池でした。昭和の干拓で農地になり、いまは «巨椋池干拓地» として広い田んぼが広がっています。","槇島城の正確な位置や規模ははっきりしていません。宇治川の流路が大きく変わったため、遺構は見つかっておらず、石碑は伝承地に立てられています。","信長の家臣が書いた『信長公記』には、槇島城攻めの様子が記されています。宇治川を渡る場面は、同じ宇治川で源平時代に «先陣争い» があったことを思わせる名場面として語られてきました。"],"look":["住宅地に立つ «槇島城跡» の石碑と説明板","周囲の平らな地形（かつての巨椋池と宇治川の水辺）","宇治川の堤防から見る川の流れ","宇治市歴史資料館で地域の歴史をあわせて学ぶ"],"q":["槇島城で信長に敗れた室町幕府の将軍はだれ?","15代将軍・足利義昭。1573年に降伏して京都を追われ、室町幕府の終わりとされます。"],"koji":[{"w":"天下布武","m":"武の力で天下を治めるという信長の印の言葉。将軍を追放したのちの信長の歩みを象徴する"}],"myth":"信長が自ら渡河を命じた場面の細部は軍記による。城の正確な位置は未確定で、石碑は伝承地。","img":["足利義昭","巨椋池","織田信長"],"wp":"槇島城","rel":{"ev":[],"grave":[]}},{"id":"26_ikkyuji","n":"酬恩庵 一休寺（京田辺）","yomi":"しゅうおんあん いっきゅうじ","cat":"墓所","rank":"B","y":1456,"era":["muromachi","edo"],"sh":"本堂・方丈など国の重要文化財／方丈庭園は国の名勝","ad":"京田辺市薪里ノ内（たきぎさとのうち）","st":"JR京田辺駅・近鉄新田辺駅から歩いて約20〜25分、または京阪バス «一休寺道» から歩いて約5分","la":34.8285,"lo":135.756,"hook":"«このはしわたるべからず» のとんちで有名な一休さん。本物の一休が晩年を過ごし、いまも眠るのがこの寺だ。","lead":"酬恩庵は、室町時代のお坊さん・一休宗純が再建し、晩年をすごした禅寺です。 «一休寺» の名で親しまれています。一休はここで88歳で亡くなり、境内のお墓は «天皇の子» として宮内庁が管理しています。","story":["アニメの «一休さん» は、かわいい小僧さんがとんちで大人をやりこめるお話。でも本物の一休宗純は、もっとはげしく、自由で、ちょっと型破りなお坊さんでした。ぼろぼろの衣で町を歩き、お酒も飲み、えらいお坊さんたちのうわべだけの修行をきびしく批判したといいます。","この寺のもとは、鎌倉時代に大応国師（南浦紹明）がひらいた «妙勝寺» でした。一休にとって大応は、あこがれの師の、そのまた師にあたる人です。戦乱で荒れはてたこの寺を、一休は1456年ごろに建て直しました。«師の恩にむくいる» という意味で、名前を «酬恩庵» とつけたのです。","一休は60代からの晩年の多くをここで過ごしました。80歳をこえて大徳寺の住職に選ばれたときも、住まいはこの庵にあったと伝わります。戦で焼けた大徳寺を建て直すため、堺の商人たちに協力をよびかけたのも、このころのことです。","«門松は冥土の旅の一里塚 めでたくもありめでたくもなし»。お正月に骸骨をつけた杖をついて町を歩いた、という話が伝わります。なぜそんなことを? 年をとることは死に近づくことでもある、と人々に気づかせたかったのでしょう。ただし、この歌が本当に一休の作かどうかははっきりしません。","1481年、一休はこの地で亡くなりました。88歳でした。一休は後小松天皇の子だったといわれ、お墓は «宗純王廟» として宮内庁が管理しています。門の菊の紋の向こうに、自由に生きたお坊さんの眠る場所があります。静かな方丈の庭に座ると、あのとんち話とはまたちがう、一休の素顔にふれられる気がします。"],"tl":[["鎌倉時代","大応国師（南浦紹明）が «妙勝寺» をひらく"],["1333年ごろ","元弘の乱の戦火で荒れたと伝わる"],["1456年ごろ","一休宗純が再興し «酬恩庵» と名づける"],["1474年","一休が大徳寺の住職（住持）となる"],["1481年","一休が酬恩庵で亡くなる（88歳）"],["1650年","加賀藩主・前田利常の援助で方丈などが再建される"],["1975年","テレビアニメ «一休さん» 放送開始。とんちの一休が全国に広まる"]],"who":[["一休宗純","室町時代の臨済宗の僧。酬恩庵を再興し、晩年を過ごして葬られた"],["南浦紹明（大応国師）","鎌倉時代の禅僧。この寺のもとになった妙勝寺をひらいた"],["後小松天皇","一休の父といわれる天皇"],["森女（しんにょ）","一休が晩年に深く愛した盲目の女性。一休の詩集『狂雲集』に登場する"],["前田利常","加賀藩主。江戸時代に方丈などの再建を援助した"]],"deep":["一休が後小松天皇の子とする説は、弟子たちがまとめた『一休和尚年譜』などに記されています。宮内庁が墓を管理しているのはこの説によるもので、母は南朝方の貴族の娘ともいわれます。","とんち話の多くは、江戸時代に出版された『一休咄』などの読み物で広まったものです。 «このはし渡るべからず» も、実在の一休の逸話として史料で確かめられるものではありません。","一休の漢詩集『狂雲集』は、仏教の教えから恋、社会への怒りまでを大胆に詠んだ作品として知られます。晩年の森女への思いをつづった詩は、禅僧の作品としては異例の率直さです。","方丈庭園は、江戸時代初めの文化人・松花堂昭乗、石川丈山、佐川田喜六の合作と伝わります。南・東・北の三方に趣のちがう庭があり、国の名勝に指定されています。","寺では «一休寺納豆» がつくられています。一休が中国から伝わった製法を広めたとされる、味噌のような色と塩気の強い «寺納豆» で、糸を引く納豆とはまったく別物です。","本堂は室町時代、足利義教の寄進で建てられたと伝わり、山城・大和地方に残る室町の唐様（禅宗様）仏堂として重要文化財です。"],"look":["宗純王廟（一休の墓。菊の紋の門ごしに拝む）","方丈と三方の庭園（国の名勝）","一休の木像（方丈に安置。年に一度の開帳など公開時期に注意）","室町時代の本堂（重要文化財）","名物の一休寺納豆"],"q":["一休が寺の名を «酬恩庵» とした意味は?","«師の恩にむくいる» という意味。この寺をひらいた大応国師の恩にこたえるためと伝わります。"],"koji":[{"w":"門松は冥土の旅の一里塚","m":"正月を迎えるたびに死に一歩近づく、という意味。一休作とされるが確証はない"}],"myth":"後小松天皇の子とする説、とんち話、«門松は冥土の» の歌の作者はいずれも伝承・後世の読み物をふくむ。","img":["一休宗純","南浦紹明","狂雲集"],"wp":"酬恩庵","rel":{"ev":[],"grave":[]}},{"id":"26_kuzukawa","n":"久津川車塚古墳（城陽）","yomi":"くつかわくるまづかこふん","cat":"遺跡","rank":"B","y":450,"era":["kofun"],"sh":"国指定史跡","ad":"城陽市平川（ひらかわ）","st":"近鉄京都線 久津川駅から歩いて約10分","la":34.864,"lo":135.779,"hook":"南山城でいちばん大きな古墳。明治の鉄道工事で、豪華な石棺と甲冑がとつぜん姿をあらわした。","lead":"久津川車塚古墳は、5世紀につくられた長さ約180mの前方後円墳で、京都府南部（南山城）で最大です。明治時代に線路をつくる工事で石棺が見つかり、鏡やよろいなどがたくさん出てきました。この地方をおさめた «王» の墓と考えられています。","story":["明治時代の終わり近く、奈良と京都を結ぶ鉄道の工事が、城陽の丘にさしかかりました。土を掘りくずしていた作業員たちの前に、とつぜん大きな石の箱があらわれます。ふたを開けると、中には銅の鏡や鉄のよろい、たくさんの玉。«これはただの墓ではない» ――村はおおさわぎになったといいます。","それが久津川車塚古墳の石棺でした。長持形石棺とよばれる、組み合わせ式の立派な石の棺です。この形の石棺は、大王（のちの天皇）の墓がある大阪の古市・百舌鳥の古墳群などに多く、特別な人だけが使えたと考えられています。つまり、ここに葬られた人は、ヤマトの大王と深いつながりをもっていたのです。","なぜこの場所に、こんな大きな古墳がつくられたのでしょう? 城陽は、木津川ぞいに奈良と京都・近江を結ぶ交通の要所です。川の水運や道をおさえた有力者が、大王の政権と手を結んでいた。その力を見せつけるように、丘の上に巨大な墓を築いたと考えられます。","古墳のまわりには、水をたたえた堀がめぐっていました。発掘調査では、周濠が二重にめぐっていたことや、埴輪が並べられていたことがわかってきています。近くには芭蕉塚古墳や丸塚古墳などもあり、このあたりは «久津川古墳群» とよばれる古墳の集まりになっています。","いま古墳は、住宅地と線路にはさまれた緑の丘です。線路は墳丘のすぐそばを走り、電車の窓からもその高まりが見えます。千五百年以上前の王の眠りをさまたげた鉄道が、いまは毎日そのわきを通りすぎていく――ちょっと不思議な風景です。"],"tl":[["5世紀前半〜中ごろ","久津川車塚古墳がつくられる（推定）"],["1894年","鉄道工事で長持形石棺が見つかり、鏡・甲冑・玉などが出土"],["昭和時代","国の史跡に指定される"],["2010年代","城陽市による発掘調査が進み、周濠や埴輪の様子が明らかに"],["現在","史跡の整備が進められている"]],"who":[["南山城の首長（被葬者）","名前は伝わらない。木津川流域をおさめ、ヤマト政権と結びついた有力者と考えられる"],["明治の鉄道工事の人々","偶然石棺を掘りあて、古墳の重要さが知られるきっかけをつくった"],["梅原末治","京都大学の考古学者。久津川古墳群の出土品を研究した一人"]],"deep":["墳丘の長さは約180m。京都府内の前方後円墳では、丹後の網野銚子山古墳や神明山古墳とならぶ大型で、南山城では最大です。","長持形石棺は、短辺・長辺・底・ふたの石を組み合わせた棺で、古墳時代中期の大王墓級の古墳に多く見られます。 «王者の棺» ともよばれます。","出土品には、銅鏡、甲冑（よろい・かぶと）、刀剣、勾玉などの玉類があり、一部は東京国立博物館などにおさめられています。","古墳の名前の «車塚» は、前方後円墳の形が車（牛車）に見えたことからつけられたと考えられ、各地に同じ名前の古墳があります。","近くの芭蕉塚古墳も全長100mをこえる前方後円墳です。久津川古墳群は、5世紀を中心に首長の墓が次々とつくられた場所で、有力な一族が何代も続いていたことを物語ります。"],"look":["墳丘の大きさ（線路ぞいから全体の長さを実感）","前方部と後円部の高さのちがい","周濠の名残（田畑や低地の形）","近くの芭蕉塚古墳・丸塚古墳","城陽市歴史民俗資料館（通称 «五里ごり館»）の展示"],"q":["久津川車塚古墳の石棺が見つかったきっかけは?","明治時代の鉄道工事。線路を通すために土を掘ったところ、長持形石棺があらわれました。"],"myth":"被葬者は不明。築造年代は5世紀前半〜中ごろとする見方が多いが、研究者により幅がある。","img":["久津川古墳群","長持形石棺","前方後円墳"],"wp":"久津川車塚古墳","rel":{"ev":[],"grave":[]}},{"id":"26_horagatoge","n":"洞ヶ峠（日和見の筒井順慶）","yomi":"ほらがとうげ","cat":"古戦場","rank":"B","y":1582,"era":["azuchi"],"sh":"","ad":"八幡市八幡南山付近（大阪府枚方市との境）","st":"京阪本線 樟葉駅から京阪バスで «洞ヶ峠» 下車","la":34.8435,"lo":135.69,"hook":"«洞ヶ峠を決め込む» ――有利な方につこうと様子見すること。でも本当に峠で待っていたのは、あの武将のほうだった。","lead":"洞ヶ峠は、京都府八幡市と大阪府枚方市の境にある峠です。1582年の山崎の戦いの前、大和の武将・筒井順慶がここで明智光秀と羽柴秀吉のどちらが勝つか様子を見ていた、という話から «洞ヶ峠を決め込む» ということわざが生まれました。けれども史実は少しちがうようです。","story":["1582年6月2日、本能寺の変。織田信長を討った明智光秀は、急いで味方を集めようとしました。たよりにしたのが、大和の国（奈良県）をおさめる筒井順慶です。順慶は光秀の世話で信長に仕えた人で、光秀にとっては «きっと味方してくれる» はずの相手でした。","ところが順慶の返事ははっきりしません。そのころ、中国地方で戦っていた羽柴秀吉は、信じられない速さで京都へ引き返してきていました。光秀か、秀吉か。どちらにつくかで、筒井家の運命が決まります。","のちの物語では、順慶は兵をひきいて洞ヶ峠まで出てきて、山崎の戦いのなりゆきを高みから見物し、秀吉が勝ちそうだとわかってから秀吉についた、と語られます。ここから、どっちつかずで様子見することを «洞ヶ峠を決め込む» とか «日和見（ひよりみ）» とよぶようになりました。","でも、本当はどうだったのでしょう? 当時の記録を調べると、洞ヶ峠まで出陣したのは、じつは光秀のほうでした。光秀は順慶の参陣を待って峠に陣を置いたものの、順慶は大和の郡山城にこもって動かず、ついに来なかったといいます。 «待ちぼうけ» をくったのは光秀だったのです。","峠の名前だけが、ちょっと気の毒な意味で日本語に残りました。順慶は迷ったのか、最初から動かないと決めていたのか――。峠の茶屋あとあたりに立つと、北に京都の町、南に大阪平野が見わたせます。ここで返事を待ち続けた光秀の胸のうちを想像してみてください。"],"tl":[["1582年6月2日","本能寺の変。明智光秀が織田信長を討つ"],["1582年6月上旬","光秀が筒井順慶の参陣を待って洞ヶ峠に出陣したとされる"],["1582年6月13日","山崎の戦い。羽柴秀吉が光秀を破る"],["1582年6月","順慶は秀吉に従う姿勢を示す"],["1584年","筒井順慶が亡くなる"],["江戸時代","軍記物などで «順慶が洞ヶ峠で日和見した» という話が広まる"]],"who":[["筒井順慶","大和の武将。本能寺の変のあと態度をはっきりさせず、 «日和見» の代名詞にされた"],["明智光秀","順慶の参陣を待って洞ヶ峠に陣を置いたとされる"],["羽柴秀吉","中国大返しで戻り、山崎の戦いで光秀を破った"],["織田信長","本能寺の変で討たれた。順慶・光秀の主君"]],"deep":["«洞ヶ峠を決め込む» の話の根拠は、江戸時代の軍記物です。一方、奈良・興福寺の僧の日記『多聞院日記』などからは、順慶が郡山城を動かず、光秀が洞ヶ峠で待っていたと読みとれるとされます。","順慶は一時、光秀のもとに兵を送る動きも見せたものの、途中で引き返させたともいわれます。家臣の間で意見が割れていた可能性も指摘されています。","«日和見» はもとは空模様を見て天気を占うこと。そこから «形勢をうかがってどちらにもつかないこと» の意味に広がり、洞ヶ峠の話と結びつきました。","洞ヶ峠は京都と大阪（河内）を結ぶ東高野街道の峠で、いまは国道1号が通る交通の要所です。山崎の戦場（大山崎町）は、ここから淀川をはさんだ北西の方向にあたります。","峠には、かつて茶屋があり «洞ヶ峠茶屋» として親しまれていました。国道ぞいに筒井順慶ゆかりをしめす碑や説明板があります。"],"look":["国道1号ぞいの洞ヶ峠の碑・説明板","峠から北西にひらける京都側の眺め（山崎方面）","八幡市側の東高野街道の道すじ","足をのばして石清水八幡宮（男山）"],"q":["洞ヶ峠に出陣して、来ない味方を待っていたのはだれといわれる?","明智光秀。筒井順慶は大和の郡山城から動かなかったと考えられています。"],"koji":[{"w":"洞ヶ峠を決め込む","m":"有利な方につこうと、形勢をうかがってどっちつかずの態度をとること"},{"w":"日和見","m":"なりゆきを見て態度を決めないこと"}],"myth":"順慶が洞ヶ峠で様子見したという話は江戸時代の軍記物由来で、史実とは考えにくい。","img":["筒井順慶","山崎の戦い","明智光秀"],"wp":"洞ヶ峠","rel":{"ev":[],"grave":[]}},{"id":"26_izumo_daijingu","n":"出雲大神宮（丹波国一之宮）","yomi":"いずもだいじんぐう","cat":"寺社","rank":"B","y":1345,"era":["nara","heian","muromachi"],"sh":"本殿は国の重要文化財","ad":"亀岡市千歳町出雲（ちとせちょういずも）","st":"JR嵯峨野線 亀岡駅から京阪京都交通バスで «出雲神社前» 下車すぐ","la":35.066,"lo":135.6075,"hook":"«出雲大社のふるさとはここ» ――そんな言い伝えをもつ、丹波の山すその古い古いお宮。","lead":"出雲大神宮は、丹波国でいちばん格の高い «一之宮» とされた神社です。大国主命をまつり、うしろの御蔭山（みかげやま）そのものを神さまとしてあがめてきました。島根の出雲大社はここから分かれた、という «元出雲» の伝えがあります。","story":["亀岡の町から北東へ。田んぼの向こうに、おわんをふせたような形のなだらかな山が見えてきます。これが御蔭山。出雲大神宮は、この山のふもとに鎮まっています。むかしの人は、形の美しい山には神さまが宿ると考え、山そのものを拝みました。本殿ができるずっと前から、ここは祈りの場所だったのです。","この神社には «元出雲» というふしぎな言い伝えがあります。島根の出雲大社は、奈良時代のはじめに、ここから大国主命の神霊を分けてまつったものだ、というのです。本当でしょうか? はっきりした証拠はありませんが、丹波と出雲をむすぶ古い交流の記憶が、こうした伝えになったのかもしれません。","平安時代の『延喜式』には «出雲神社» の名があり、とくに重んじられる «名神大社» とされています。都に近い丹波の国で、いちばん大切な神社として、国司たちもお参りしました。","いまの本殿は、南北朝時代の1345年に足利尊氏が修理させたと伝わる建物で、国の重要文化財です。尊氏は、丹波の篠村で兵をあげて京都の六波羅を攻めたことがあり、丹波とは縁の深い人でした。","この神社は、『徒然草』のおもしろい話の舞台としても知られます。聖海上人（しょうかいしょうにん）という僧がお参りしたとき、狛犬が背中合わせに置かれているのを見て «これはきっと深いわけがあるにちがいない» と涙を流して感動しました。ところが神官に聞くと «子どもたちのいたずらです» と、あっさり元にもどされてしまった――。思いこみで感動することのおかしさを、兼好法師はここで描いたのです。"],"tl":[["709年","社伝では、この年に社殿がととのえられたとされる"],["927年","『延喜式』に «出雲神社» として名神大社に列せられる"],["平安時代","丹波国一之宮として国司の崇敬を受ける"],["1330年代","『徒然草』第236段に、丹波の出雲の話が書かれる"],["1345年","足利尊氏が本殿を修造したと伝わる"],["明治時代","社名を «出雲神社» から現在の «出雲大神宮» に"]],"who":[["大国主命","主祭神。国づくりの神で、縁結びの神としても信仰される"],["三穂津姫命","大国主命の妻とされる神。ともにまつられる"],["足利尊氏","1345年に本殿を修造させたと伝わる"],["兼好法師","『徒然草』でこの社の狛犬の話を書いた"]],"deep":["『徒然草』第236段は «丹波に出雲といふ所あり。大社をうつして、めでたく造れり» と始まります。鎌倉時代末には、すでに «出雲大社を移した» という理解があったことがわかります。","本殿は三間社流造で、室町時代初めの様式をよく残すとして重要文化財に指定されています。修造の年代は社の記録によるもので、細部には後の修理も入っています。","神体山の御蔭山は禁足地で、一般の人は入れません。山の中には磐座（いわくら）とよばれる祭祀の岩があるとされます。","境内の裏手には古墳や «真名井の水» とよばれる湧き水があり、名水として水をくみに来る人も多くいます。","«元出雲» の伝承は、江戸時代の地誌などにも見えますが、史料で確かめることはできません。出雲大社側にはこの説はなく、あくまで当社の伝えです。"],"look":["室町時代の本殿（重要文化財）","御蔭山の山容（遠くからも形がよくわかる）","真名井の水","境内の磐座や古墳（立入できる範囲で）","狛犬（『徒然草』の話を思い出して）"],"q":["『徒然草』でこの神社の狛犬はどうなっていた?","背中合わせに置かれていました。僧は深い意味があると感動しましたが、子どものいたずらでした。"],"koji":[{"w":"先達はあらまほしきことなり","m":"何事にも案内役・指導者がいてほしいもの。『徒然草』の別の段（石清水の話）の言葉"}],"myth":"«元出雲» の伝承、709年の社殿創建、尊氏による修造年は社伝による。","img":["徒然草","大国主","丹波国"],"wp":"出雲大神宮","rel":{"ev":[],"grave":[]}},{"id":"26_oinosaka","n":"老ノ坂（光秀の «敵は本能寺» への道）","yomi":"おいのさか","cat":"街道","rank":"B","y":1582,"era":["heian","kamakura","azuchi"],"sh":"","ad":"京都市西京区大枝沓掛町〜亀岡市篠町の境","st":"阪急桂駅・JR桂川駅方面から京阪京都交通バス（亀岡方面）で峠付近へ。国道9号は歩道がせまいので注意","la":34.9935,"lo":135.6435,"hook":"1582年6月、真夜中。1万数千の兵が、この峠を越えて京都へ下った。行き先を知る者は、まだほとんどいなかった。","lead":"老ノ坂は、京都と丹波（亀岡）の境にある山陰道の峠です。1582年、明智光秀はここを越えて本能寺の織田信長を討ちに向かいました。鬼の酒呑童子の首を埋めたという «首塚大明神» もあり、歴史と伝説がまじりあう峠です。","story":["1582年6月1日の夜。丹波の亀山城（いまの亀岡）を出た明智光秀の軍勢は、東へ進んでいました。表向きの目的は «中国地方で戦う羽柴秀吉を助けに行く»。それなら西へ向かうはずなのに、軍は京都へ向かう老ノ坂の山道をのぼっていきます。兵たちは «徳川家康どのを接待するため、信長さまに軍勢をお見せするのだろう» と思っていたともいわれます。","峠を越え、沓掛のあたりで光秀は兵に休息をとらせ、ここで重臣たちに本心を打ち明けたと伝わります。そして桂川を渡ったところで、全軍に進むべき先が告げられました。 «敵は本能寺にあり»――この名せりふは、じつは江戸時代以降の軍記物や歴史書で広まった言葉です。それでも、多くの人がこの峠と結びつけて思い出します。","老ノ坂は、光秀より前にも歴史の舞台になりました。1333年、足利尊氏は丹波の篠村八幡宮で鎌倉幕府に背く兵をあげ、この峠を越えて京都の六波羅探題を攻めおとしました。京都をねらう軍勢にとって、丹波からの入口はここだったのです。","峠には、もうひとつの顔があります。源頼光たちが大江山の鬼・酒呑童子を退治して、その首を都へ運ぼうとしたとき、この峠で首が急に重くなり動かなくなった、という伝説です。 «けがれた首を都に入れてはならぬ»――そう告げられて、首はここに埋められたといいます。いまも «首塚大明神» があり、首から上の病気にご利益があるとされています。","ではなぜ «大江山» の鬼の首がここに? じつは «大江山» は丹後の大江山ではなく、この峠のある «大枝山（おおえやま）» だった、という説もあるのです。軍勢も鬼も越えた峠。いまはトンネルと国道が通り、車があっという間に走りぬけていきます。"],"tl":[["平安時代","山陰道の峠として «大枝（おおえ）» の名で知られる"],["1333年","足利尊氏が篠村で挙兵し、この峠を越えて六波羅探題を攻める"],["1582年6月1日夜","明智光秀の軍勢が亀山城を出て老ノ坂を越える"],["1582年6月2日早朝","本能寺の変"],["江戸時代","山陰街道の宿場・峠道として人や物が行き交う"],["1964年","国道9号の老ノ坂トンネルが開通"]],"who":[["明智光秀","亀山城から老ノ坂を越えて本能寺へ向かった"],["足利尊氏","1333年、この峠を越えて六波羅探題を攻めた"],["源頼光","酒呑童子を退治したと伝わる武将。首塚の伝説に登場"],["酒呑童子","大江山に住んだという鬼の頭領。首がこの峠に埋められたと伝わる"],["小式部内侍","«大江山いく野の道の遠ければ» の歌をよんだ平安の歌人"]],"deep":["«敵は本能寺にあり» は同時代の史料には見えず、江戸時代の軍記や頼山陽の『日本外史』などを通じて広まった表現とされます。","光秀の軍が本能寺へ向かった道すじには、老ノ坂を越える山陰道説のほかに、北の唐櫃越（からとごえ）を通った説もあり、道すじには諸説あります。","百人一首の小式部内侍の歌 «大江山いく野の道の遠ければ まだふみもみず天の橋立» の «大江山» は、丹後へ向かう途中の、この大枝山を指すと考えられています。","首塚大明神の境内には酒呑童子の首を埋めたとされる塚があります。酒呑童子の本拠地を丹後の大江山とする話と、老ノ坂の大枝山とする話の両方が伝わっています。","老ノ坂の地名は、坂の名前として «老いの坂» の字があてられたもので、もとは «大枝（おおえ）の坂» が変化したという説があります。","峠の京都側の «沓掛» は古くからの宿場で、旅人がすりきれた沓（くつ）を掛けたことに由来する地名といわれます。"],"look":["首塚大明神（峠の京都側）","旧山陰道の峠道の雰囲気","国道9号・老ノ坂トンネル付近から見る地形","亀岡側の篠村八幡宮（尊氏挙兵の地）もあわせて"],"q":["老ノ坂の近くに首が埋められたと伝わる鬼の名前は?","«酒呑童子»。源頼光に退治され、首を運ぶ途中この峠で動かなくなったと伝わります。"],"koji":[{"w":"敵は本能寺にあり","m":"本当のねらいは別のところにある、というたとえ。光秀の言葉とされるが後世の表現"}],"myth":"«敵は本能寺にあり» は後世の創作的表現。光秀の進路、酒呑童子の首塚は諸説・伝承。","img":["本能寺の変","酒呑童子","篠村八幡宮"],"wp":"大枝山","rel":{"ev":[],"grave":[]}},{"id":"26_tanba_kokubunji","n":"丹波国分寺跡","yomi":"たんばこくぶんじあと","cat":"遺跡","rank":"B","y":741,"era":["nara","heian"],"sh":"国指定史跡","ad":"亀岡市千歳町国分（ちとせちょうこくぶ）","st":"JR嵯峨野線 亀岡駅から京阪京都交通バスで «国分» 付近下車、歩いて数分","la":35.056,"lo":135.6,"hook":"田んぼの中の小さなお寺。その境内に、1300年前の塔の礎石が、いまも同じ場所にならんでいる。","lead":"丹波国分寺跡は、奈良時代に聖武天皇の命令で国ごとに建てられた «国分寺» の一つ、丹波国の国分寺の跡です。いまの国分寺（浄土宗）の境内に、七重塔や金堂の礎石が残り、国の史跡になっています。","story":["741年、聖武天皇は «国ごとに寺を建てよ» という命令を出しました。そのころの日本は、ききんや病気のはやり、反乱などが続き、人々は不安な日々を送っていました。天皇は、仏の力で国を守ろうと考えたのです。こうして全国に国分寺と国分尼寺がつくられ、丹波国の国分寺はこの亀岡の地に建てられました。","国分寺には、七重塔をそなえることが定められていました。高さは数十メートルあったと考えられ、平らな亀岡盆地のどこからでも見えたはずです。 «都から来たお寺はなんて大きいんだろう»。はじめて塔を見上げた村人たちの驚きが目にうかびます。","境内には、その塔の心柱や柱を支えた礎石が、ほぼもとの位置のまま残っています。石の上には、柱をすえるための丸いくぼみ。ここに太い柱が立ち、その上に七つの屋根が重なっていたのです。発掘調査では、金堂や講堂、回廊などの跡も確かめられ、寺の配置がわかってきました。","平安時代以降、国の役所の力が弱まると、国分寺もしだいにさびれていきます。戦国時代には戦火にかかったと伝わり、江戸時代に小さなお寺として再興されました。いまの本堂は江戸時代のものです。","近くには、国分尼寺の跡と考えられる遺跡もあり、あわせて保存されています。平凡な田園風景のなかに、奈良の都と同じ時代の «国家プロジェクト» の跡が眠っている。塔の礎石に手をかざして、失われた七重塔の高さを想像してみましょう。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["8世紀中ごろ","丹波国分寺が建てられる（推定）"],["平安時代以降","国の制度のゆるみとともに衰える"],["戦国時代","戦火で荒れたと伝わる"],["江戸時代","現在の国分寺が再興され、本堂が建てられる"],["1928年","国の史跡に指定される"],["平成時代","発掘調査が進み、国分尼寺跡とみられる遺跡も史跡に加えられる"]],"who":[["聖武天皇","国分寺建立の詔を出し、全国に国分寺を建てさせた"],["光明皇后","聖武天皇の皇后。国分寺・国分尼寺の建立を進めたといわれる"],["丹波国司","国分寺の造営と維持をになった国の役人"]],"deep":["塔跡には礎石がよく残り、全国の国分寺跡のなかでも塔の規模がつかみやすい例とされます。礎石の配置から、一辺約10m前後の塔と推定されています。","国分寺の正式名は «金光明四天王護国之寺»、国分尼寺は «法華滅罪之寺» といいます。丹波国分寺の近くの «御上人林（おしょうにんばやし）廃寺» は国分尼寺跡と考えられています。","発掘調査では、金堂・講堂・中門・回廊などの位置が確かめられ、東大寺などと同じように、中心の伽藍を回廊でかこむ配置だったとみられています。","丹波国の役所である国府の位置は、亀岡市内にあったと考えられていますが、場所は確定していません。国分寺は国府の近くに置かれるのがふつうでした。","明智光秀による丹波攻めのときに焼かれた、とする伝えがありますが、確かな記録はありません。"],"look":["塔跡の礎石群（心礎と四天柱・側柱）","金堂跡の説明板","江戸時代の本堂","周囲の田園と、北東にそびえる御蔭山","近くの出雲大神宮とあわせた散策"],"q":["国分寺を国ごとに建てるように命じた天皇はだれ?","聖武天皇。741年に詔を出し、仏の力で国の平安をいのりました。"],"myth":"光秀の丹波攻めでの焼失は伝承。塔の規模は礎石からの推定。","img":["国分寺","聖武天皇","丹波国"],"wp":"丹波国分寺","rel":{"ev":[],"grave":[]}},{"id":"26_yagijo","n":"八木城跡（内藤如安の山城）","yomi":"やぎじょうあと","cat":"城","rank":"B","y":1560,"era":["muromachi","azuchi"],"sh":"","ad":"南丹市八木町八木・本郷ほか（城山）","st":"JR嵯峨野線 八木駅から登山口まで歩いて約20分、さらに山頂まで登山約40分〜1時間","la":35.079,"lo":135.531,"hook":"信仰をつらぬき、日本を追われてマニラで亡くなった武将――内藤如安。そのふるさとの城が、この山の上にあった。","lead":"八木城は、丹波の守護代・内藤氏がきずいた山城で、丹波でも有数の大きな城でした。キリシタン武将として知られる内藤如安（ジョアン）の城です。建物はなく、山の上に曲輪や石垣の跡が残っています。","story":["亀岡から北西へ、嵯峨野線の電車が八木駅に近づくと、北側に木におおわれた城山が見えます。標高は300mあまり。ここに戦国時代、丹波の中心の一つだった八木城がありました。山の尾根にそって、たくさんの曲輪（平らにけずった場所）がつくられた大きな城です。","城主の内藤氏は、丹波の守護代をつとめた家です。戦国時代の半ば、松永久秀の弟・松永長頼が内藤家に入り、 «内藤宗勝» と名のって丹波を治めました。その子が内藤如安です。如安は、若いころにキリスト教の洗礼を受け、 «ジョアン» という洗礼名をもっていました。","如安は、将軍・足利義昭を支える側に立ちましたが、義昭が信長に追放されると内藤家も力を失います。そして明智光秀の丹波攻めで、八木城も落ちたと伝わります。落城の時期や様子については、はっきりしないことも多いのです。","城を失った如安は、キリシタン大名の小西行長に仕えました。朝鮮出兵のときには、明（中国）との講和交渉の使者として北京まで出向いたといわれます。のちに加藤清正の家臣を経て、加賀の前田家に身を寄せました。けれども1614年、江戸幕府のキリスト教禁止によって、高山右近らとともに国外へ追放されてしまいます。","«信仰は捨てられない»。如安は船でフィリピンのマニラへ渡り、そこで一生を終えました。山頂の本丸跡に立つと、亀岡盆地と南丹の山々が見わたせます。この景色を、遠い南の国で如安は思い出したでしょうか。"],"tl":[["室町時代","丹波守護代の内藤氏が八木を拠点とする"],["1550年代","松永長頼が内藤家に入り «内藤宗勝» として丹波で勢力をふるう"],["1565年","内藤宗勝が戦死したとされる"],["1570年代","明智光秀の丹波攻めで八木城が落ちたと伝わる"],["1592〜1596年","内藤如安が小西行長のもとで明との講和交渉にあたる"],["1614年","キリシタン追放令により、如安が高山右近らとマニラへ追放"],["1626年","如安がマニラで亡くなったとされる"]],"who":[["内藤如安（ジョアン）","八木城主の家に生まれたキリシタン武将。マニラへ追放された"],["内藤宗勝（松永長頼）","松永久秀の弟。内藤家を継いで丹波で活躍した如安の父"],["明智光秀","丹波攻めで八木城を攻めたとされる"],["小西行長","如安が仕えたキリシタン大名"],["高山右近","ともにマニラへ追放されたキリシタン大名"]],"deep":["八木城は尾根上に大小の曲輪が連なる連郭式の山城で、本丸周辺には石垣の一部が残ります。石垣は光秀の時代以降に手が加えられた可能性もあり、築かれた時期は研究課題です。","如安の名前は «内藤忠俊» などとも伝わり、 «如安» は洗礼名ジョアンに漢字をあてたものです。 «小西飛騨守» と名のった時期もあります。","明との講和交渉では、如安は行長の使者として北京に入り、明の皇帝側と交渉したとされます。この交渉はうまくいかず、のちの慶長の役につながりました。","八木城の落城年には諸説あり、光秀の丹波攻めの過程（1570年代後半）とする見方が多いものの、確かな一次史料は少ないとされます。","マニラには、高山右近の像がありますが、如安も同じくマニラの人々に迎えられ、その地で亡くなったと宣教師の記録に残っています。"],"look":["本丸跡からの亀岡盆地の眺め","尾根に連なる曲輪の跡","本丸付近の石垣の残り","登山口の説明板（登山道は整備されているが山道なので装備を）"],"q":["内藤如安が1614年に追放されて渡った場所は?","フィリピンのマニラ。高山右近らとともに追放され、その地で生涯を終えました。"],"myth":"八木城の落城時期・経緯、如安の生年などは諸説ある。","img":["内藤如安","松永長頼","高山右近"],"wp":"八木城 (丹波国)","rel":{"ev":[],"grave":[]}},{"id":"26_sonobejo","n":"園部城（最後に築かれた城）","yomi":"そのべじょう","cat":"城","rank":"B","y":1869,"era":["edo","meiji"],"sh":"","ad":"南丹市園部町小桜町（京都府立園部高校付近）","st":"JR嵯峨野線 園部駅から歩いて約20分","la":35.108,"lo":135.47,"hook":"明治に入ってから櫓（やぐら）と門を築いた――日本の城の歴史の «最後のページ» は、丹波の小さな町で書かれた。","lead":"園部城は、江戸時代の園部藩・小出氏の陣屋を、明治のはじめに城としてととのえたものです。日本で最後に築かれた城といわれます。いまは櫓門などが残り、府立園部高校の入口になっています。","story":["江戸時代のはじめ、1619年に小出吉親という大名が園部にやってきました。石高は2万6千石あまり。小さな藩だったので、立派な天守のある城ではなく、 «陣屋» とよばれる役所と屋敷をかねた建物で政治をおこないました。小出家は、明治まで約250年、ここを治めます。","幕末、世の中が大きくゆれました。1868年、鳥羽・伏見の戦いがおこり、新政府と旧幕府の戦いが始まります。 «もし京都が戦場になったら、天皇をどこへお移しすればよいか»。そんな心配の中で、京都に近い園部を守りの拠点にしようという考えがうまれたといわれます。","そこで園部藩は、新政府のゆるしを得て、陣屋を城へつくりかえる工事を始めました。堀や石垣を整え、櫓や櫓門を建てます。完成したのは明治2年（1869年）ごろ。ところが、すでに戦の主な舞台は東へ移り、園部城が戦に使われることはありませんでした。","そして1871年の廃藩置県で藩はなくなり、城もまもなく取りこわされていきます。 «築いてすぐに役目を終えた城»――それが園部城でした。櫓門と巽櫓などは残され、とくに櫓門はいまも府立園部高校の門として使われています。高校生たちが毎日くぐる門が、 «日本最後の城門» なのです。","近くには、天守風の建物をもつ «南丹市国際交流会館» があり、城の雰囲気を伝えています。城の歴史の終わりを見とどけたこの小さな城から、明治という新しい時代の始まりを感じてみてください。"],"tl":[["1619年","小出吉親が園部に入り、園部藩が成立。陣屋を築く"],["1868年","鳥羽・伏見の戦い。園部陣屋の城郭化が計画される"],["1869年ごろ","櫓や櫓門などが完成し、園部城となる"],["1871年","廃藩置県で園部藩が廃止される"],["明治時代","城の多くの建物が取りこわされる"],["1990年代","城跡の近くに天守風の国際交流会館が建てられる"]],"who":[["小出吉親","園部藩の初代藩主。陣屋を築いた"],["小出英尚","園部藩最後の藩主。明治の城の整備にかかわった"],["明治新政府","園部城の築城（城郭化）を認めた"]],"deep":["«日本最後の城» とよばれる理由は、明治に入ってから櫓と門が新たに築かれたためです。北海道の五稜郭や松前城なども幕末の築城ですが、園部城はさらに後の明治初年の完成です。","城郭化の理由については、京都が戦乱にまきこまれた際の天皇の避難先として考えられた、という説が語られますが、はっきりした史料は少ないといわれます。","現存する櫓門は園部高校の正門として使われており、京都府の文化財にもなっています。学校の敷地なので、見学は外からか、授業のじゃまにならないよう配慮が必要です。","園部藩は2万6千石あまりで、城主格の大名としてはかなり小さな藩でした。小藩が明治になって城を築いたこと自体が異例のできごとです。","南丹市立文化博物館が城跡の近くにあり、園部藩や地域の歴史資料を展示しています。"],"look":["櫓門（園部高校の正門。外から見学を）","巽櫓などの遺構","堀や石垣の名残","南丹市立文化博物館","天守風の南丹市国際交流会館"],"q":["園部城が «日本最後の城» とよばれるのはなぜ?","明治に入ってから（1869年ごろ）櫓や門が築かれたから。廃藩置県で役目をすぐに終えました。"],"myth":"城郭化の目的（天皇の避難先説）は伝承的要素をふくむ。","img":["園部藩","小出吉親","陣屋"],"wp":"園部城","rel":{"ev":[],"grave":[]}},{"id":"26_miyama","n":"美山かやぶきの里（北集落）","yomi":"みやまかやぶきのさと","cat":"町","rank":"B","y":1800,"era":["edo","meiji","heisei"],"sh":"国の重要伝統的建造物群保存地区","ad":"南丹市美山町北（きた）","st":"JR山陰本線 日吉駅から南丹市営バスで約50分 «北» 下車。車が便利","la":35.3095,"lo":135.623,"hook":"山あいの斜面に、茅葺き屋根がいくつも肩を寄せ合う。 «日本の原風景» は、住む人たちの手で守られてきた。","lead":"美山町北の集落は、茅葺き屋根の民家が40棟ほどまとまって残る山里です。1993年に国の重要伝統的建造物群保存地区に選ばれました。いまも人が暮らしながら、屋根の葺き替えや防火の工夫で景観を守っています。","story":["京都の町から北へ車で1時間半ほど。由良川の上流、山にかこまれた谷あいに «かやぶきの里» があります。緑の田んぼの向こうに、三角の大きな茅葺き屋根がいくつも並ぶ光景。はじめて見た人の多くが «昔話の世界に来たみたい» と声をあげます。","この家々の多くは、江戸時代の中ごろから明治時代にかけて建てられました。屋根は急な角度の入母屋づくりで、雪がすべり落ちやすくなっています。美山は冬に雪の多い土地。屋根裏は広く、かつては養蚕に使われたり、薪や道具をしまったりしていました。","でも、茅葺き屋根はずっとそのままでいられるわけではありません。二、三十年ごとにススキなどの茅を葺き替える必要があります。昔は集落のみんなで茅を刈り、力を合わせて屋根を葺きました。 «結（ゆい）» とよばれる助け合いのしくみです。人が減った今は、職人の力も借りながら、茅場を守り、技を受けついでいます。","茅葺きの里のいちばんの敵は火事です。そこで集落には、茅葺き屋根にむけて水をかける放水銃がいくつもそなえられています。春と秋には点検をかねて一斉に放水し、屋根の上に水のアーチがいっせいに立ちのぼります。その光景を見るために、たくさんの人が訪れるようになりました。","ここは «見せるための村» ではなく、人が暮らす村です。洗濯物がゆれ、畑では野菜が育っています。訪れる人は、家の中をのぞいたり、私有地に入ったりしないのがマナー。 «美山民俗資料館» や «かやぶき美術館» では、家の中のようすも見学できます。守り続ける人たちへの感謝の気持ちで歩きたい里です。"],"tl":[["江戸時代中期〜","現在残る茅葺き民家の古いものが建てられ始める"],["明治時代","養蚕などに使うため屋根裏を広くとった家が建てられる"],["1993年","国の重要伝統的建造物群保存地区に選定"],["2000年","民俗資料館が火災で焼失（のちに再建）"],["2006年","美山町が合併して南丹市となる"],["現在","春・秋の一斉放水が行われ、多くの人が見学に訪れる"]],"who":[["北集落の住民","茅葺き民家に暮らしながら景観を守り続ける人々"],["茅葺き職人","屋根の葺き替えの技を伝える。地元で育成も行われている"],["美山町の人々","景観保存と観光のバランスをとる取り組みを続けてきた"]],"deep":["北集落の茅葺き民家は、入母屋造で急勾配の屋根をもつ «北山型» とよばれる形式が多いとされます。棟の上に千木のような «ウマノリ» をのせるのが特徴です。","重要伝統的建造物群保存地区は、町並みや集落を面として守る制度で、美山町北は茅葺きの山村集落としての価値が評価されました。","放水銃は60基あまりが設置されているとされ、年に2回の一斉放水は «美山の風物詩» になっています。実施日は年によってちがうので、事前に確認が必要です。","美山は、若狭と京都を結ぶ道の途中にあり、昔から人や物の往来がありました。山の木材や炭を京都へ運ぶなど、都とのつながりも深い土地です。","2000年に美山民俗資料館が火災で焼けたことは、防火の大切さを改めて知らせる出来事になりました。その後、資料館は再建され、防火設備の充実も進められました。"],"look":["集落全体を見わたす高台からの眺め","茅葺き屋根の形と棟の飾り","放水銃の格納庫（赤い小屋）","美山民俗資料館（家の中の見学）","かやぶき美術館・郷土資料館"],"q":["茅葺きの里で春と秋に行われる、屋根に水をかける行事は?","放水銃の一斉放水。火事にそなえた点検をかねて行われ、水のアーチが立ちのぼります。"],"myth":"","img":["茅葺","重要伝統的建造物群保存地区"],"wp":"美山町","rel":{"ev":[],"grave":[]}},{"id":"26_ankokuji","n":"安国寺（足利尊氏誕生伝承・綾部）","yomi":"あんこくじ","cat":"寺社","rank":"B","y":1305,"era":["kamakura","muromachi"],"sh":"本尊の釈迦三尊像などが国の重要文化財","ad":"綾部市安国寺町（あんこくじちょう）","st":"JR舞鶴線 梅迫駅から歩いて約15分","la":35.287,"lo":135.33,"hook":"室町幕府をひらいた足利尊氏は、じつはこの丹波の山里で生まれた――そんな言い伝えをもつ寺がある。","lead":"綾部市の安国寺は、足利尊氏の母・上杉清子の実家ゆかりの地にある禅寺です。尊氏はここで生まれたという言い伝えがあり、尊氏と母、妻のお墓とされる石塔が並んでいます。尊氏が全国に建てた «安国寺» のなかでも特別な寺とされます。","story":["綾部の東、梅迫の駅から田んぼの道を歩くと、山すそに茅葺き屋根の仏殿をもつお寺が見えてきます。安国寺です。このあたりは鎌倉時代、上杉家の «上杉荘» という領地でした。足利尊氏の母・上杉清子は、この上杉家の娘です。","寺の言い伝えでは、1305年、清子は実家のあるこの地で尊氏を産んだといいます。境内には «産湯の井戸» とよばれる井戸もあります。 «のちに天下を動かす子が、この井戸の水で産湯をつかった» ――そう聞くと、ふつうの井戸がちがって見えてきます。","でも、本当に尊氏はここで生まれたのでしょうか? 多くの歴史家は、足利家の本拠地・鎌倉などで生まれたと考えています。綾部の誕生説は、母の実家との深い縁から生まれた言い伝え、という見方が有力です。それでも、尊氏がこの寺を大切にしたことはまちがいありません。","尊氏と弟の直義は、南北朝の戦いで亡くなった人々をとむらうため、全国の国ごとに «安国寺» と «利生塔» をもうけました。そのなかで、丹波の安国寺は、母の実家ゆかりの寺として特に重んじられたと伝わります。","境内の奥には、尊氏、母の清子、妻の登子のものとされる三つの宝篋印塔が静かに並んでいます。秋には境内のもみじが真っ赤に色づき、茅葺きの仏殿と見事な景色をつくります。戦乱の時代を生きた一族が、ふるさとの静けさの中で眠っているようです。"],"tl":[["鎌倉時代","上杉荘の地に寺（光福寺）があったと伝わる"],["1305年","足利尊氏がこの地で生まれたという伝承がある"],["1338年","尊氏が征夷大将軍となる"],["1340年代","尊氏・直義が全国に安国寺を定め、この寺も丹波国の安国寺とされる"],["1358年","尊氏が亡くなる。のちに境内に墓とされる宝篋印塔が建てられる"],["江戸時代","仏殿などが再建される"]],"who":[["足利尊氏","室町幕府初代将軍。この地で生まれたという伝承がある"],["上杉清子","尊氏の母。上杉荘ゆかりの上杉家の出身"],["赤橋登子","尊氏の妻。墓とされる石塔が境内にある"],["足利直義","尊氏の弟。安国寺・利生塔の設置を進めた"],["夢窓疎石","安国寺・利生塔の設置をすすめた禅僧"]],"deep":["全国の安国寺と利生塔は、夢窓疎石のすすめで、元弘の乱以来の戦死者の霊をとむらうために設けられました。既存の寺を指定する例も多く、この寺も前身の寺を改めたものといわれます。","尊氏の誕生地については、鎌倉説・足利荘（栃木県）説・丹波の上杉荘説などがあります。上杉荘説は寺伝が中心で、決め手となる同時代史料はありません。","本尊の釈迦如来と文殊・普賢菩薩の釈迦三尊像は重要文化財です。仏殿は茅葺き屋根の珍しい姿で、禅寺の仏殿として印象に残ります。","境内の三基の宝篋印塔は、尊氏・清子・登子の墓と伝えられています。尊氏の墓とされるものは京都の等持院などほかにもあり、ここは供養塔の性格をもつと考えられます。","上杉家はもともと京都の公家・勧修寺家の流れで、丹波の上杉荘を名字の地としたといわれます。のちに関東管領として東国で大きな力をもつ上杉氏のルーツが、じつは丹波にあるというのはおもしろいつながりです。"],"look":["茅葺き屋根の仏殿","尊氏・清子・登子の墓とされる三基の宝篋印塔","産湯の井戸","秋のもみじ（見ごろは11月中旬〜下旬ごろ）"],"q":["足利尊氏の母・上杉清子の実家の上杉家は、どこの地名からその名がついたといわれる?","丹波国の «上杉荘»（いまの綾部市）。のちの関東管領・上杉氏のルーツとされます。"],"myth":"尊氏の綾部誕生説は寺伝で、鎌倉・足利荘説など諸説ある。石塔の被葬者も伝承。","img":["足利尊氏","上杉清子","安国寺利生塔"],"wp":"安国寺 (綾部市)","rel":{"ev":[],"grave":[]}},{"id":"26_omoto","n":"大本事件の地（綾部・亀岡の大本聖地）","yomi":"おおもとじけんのち","cat":"昭和","rank":"B","y":1935,"era":["meiji","taisho","showa"],"sh":"","ad":"綾部市本宮町（梅松苑）・亀岡市荒塚町（天恩郷）","st":"綾部の梅松苑はJR綾部駅から歩いて約15分。亀岡の天恩郷はJR亀岡駅から歩いて約10分","la":35.3005,"lo":135.252,"hook":"一人の貧しい女性の «お筆先» から始まった教えは、やがて国家に «危険» とみなされ、神殿はダイナマイトで跡形もなく壊された。","lead":"大本は、明治時代に綾部の出口なおと、のちの出口王仁三郎がひらいた宗教です。大正時代から昭和の初めにかけて多くの信者を集めましたが、1921年と1935年の二度、国によってきびしく弾圧されました。これが «大本事件» で、戦前の日本の宗教弾圧を代表する出来事です。","story":["1892年、綾部に暮らす出口なおという女性が、神がかりの状態になったといいます。なおは夫を亡くし、糸引きやぼろ買いをして子どもたちを育てた、とても貧しい人でした。字を習ったことのないなおが、やがて紙に書きつけるようになった言葉は «お筆先» とよばれ、 «世の立て替え立て直し» を説くものでした。","そこへやってきたのが、京都・亀岡出身の上田喜三郎、のちの出口王仁三郎です。王仁三郎はなおの娘と結婚し、教えをまとめ、組織を大きくしていきました。新聞社を買いとり、全国に教えを広め、大正時代には知識人や軍人の中にも信者があらわれます。","しかし、急に大きくなった宗教を、国は警戒しました。1921年、不敬罪などの疑いで幹部が逮捕されます（第一次大本事件）。さらに1935年12月、治安維持法違反などの疑いで、王仁三郎をはじめ多くの信者が一斉に検挙されました（第二次大本事件）。綾部と亀岡の神殿や建物は、当局の手でダイナマイトなどを使って徹底的に破壊されました。","取り調べはとてもきびしく、その中で命を落とした人もいたと伝えられます。信者たちは長いあいだ、信仰を表に出すことができませんでした。なぜ国はここまで徹底したのでしょう? 天皇中心の国家のしくみとちがう «世直し» の考えや、大きな組織力を、国がおそれたためと考えられています。","1942年、王仁三郎は保釈されます。そして戦後の1945年、治安維持法違反については無罪が確定しました。いま、綾部の «梅松苑» と亀岡の «天恩郷» は大本の聖地として再建され、ひろく平和や芸術の活動が行われています。ここは、信教の自由がどれほど大切かを考えさせてくれる場所です。"],"tl":[["1892年","出口なおが綾部で神がかりとなり、大本の始まりとされる"],["1898年","上田喜三郎（出口王仁三郎）がなおのもとを訪れる"],["1918年","出口なおが亡くなる"],["1921年","第一次大本事件。幹部が不敬罪などで検挙され、本宮山の神殿が破壊される"],["1935年12月","第二次大本事件。治安維持法違反などで大規模な検挙、施設が破壊される"],["1942年","出口王仁三郎が保釈される"],["1945年","治安維持法違反について無罪が確定"],["1948年","出口王仁三郎が亡くなる"]],"who":[["出口なお","大本の開祖。綾部で «お筆先» を書きしるした"],["出口王仁三郎","聖師とよばれ、教えを広めた。二度の弾圧で検挙された"],["出口すみ","なおの娘で王仁三郎の妻。二代教主"],["当時の信者たち","弾圧のなかで検挙され、苦難を受けた人々"]],"deep":["第二次大本事件は、戦前の国家による宗教弾圧の中でもとくに大規模なもので、検挙者は数百人から千人規模にのぼったとされます（数字は資料により異なります）。","治安維持法はもともと共産主義などを取りしまる法律でしたが、この事件では宗教団体に適用されたことが大きな特徴です。のちの宗教団体への弾圧の先例にもなりました。","亀岡の天恩郷は、明智光秀がきずいた丹波亀山城の跡です。王仁三郎が城跡を買いとって聖地としたため、城の石垣の一部が境内に残っています。","第一次事件では、綾部の本宮山に建てられていた神殿が «伊勢神宮に似せている» などとされ、取りこわしを命じられました。","王仁三郎は書画や陶芸にもすぐれ、とくに晩年の «耀盌（ようわん）» とよばれる色あざやかな茶碗は、戦後に高く評価されました。","大本は、国際語エスペラントの普及や、ほかの宗教との対話にも早くから取り組んだことで知られます。"],"look":["綾部・梅松苑の境内と、なおゆかりの場所（見学は受付で確認を）","亀岡・天恩郷の丹波亀山城の石垣（見学は受付で案内を受ける）","再建された神殿と、破壊の歴史を伝える記録","信仰の場なので、静かにマナーを守って"],"q":["第二次大本事件で、大本の関係者が問われた主な法律は?","治安維持法（と不敬罪）。1945年に治安維持法違反は無罪が確定しました。"],"myth":"検挙者数・犠牲者数は資料により差がある。«お筆先» の成立の事情は教団の伝えによる。","img":["大本","出口王仁三郎","出口なお"],"wp":"大本事件","rel":{"ev":[],"grave":[]}},{"id":"26_gunze","n":"グンゼ発祥の地（綾部の製糸業）","yomi":"ぐんぜはっしょうのち","cat":"産業","rank":"B","y":1896,"era":["meiji","taisho","showa"],"sh":"","ad":"綾部市青野町（グンゼ博物苑）","st":"JR山陰本線・舞鶴線 綾部駅から歩いて約10分","la":35.3045,"lo":135.263,"hook":"«郡是（ぐんぜ）»――郡の方針。下着でおなじみの会社の名前は、ふるさとを豊かにするという誓いの言葉だった。","lead":"グンゼは、1896年に綾部で生まれた製糸会社 «郡是製絲» が始まりです。創業者の波多野鶴吉は、地元の養蚕と生糸づくりをさかんにして、貧しい村を豊かにしようとしました。綾部には «グンゼ博物苑» があり、そのあゆみを知ることができます。","story":["明治のはじめ、綾部のあたりの何鹿（いかるが）郡は、山がちで米のとれにくい、貧しい地域でした。そんな中で注目されたのが、蚕を育てて繭をとり、糸をつむぐ «養蚕と製糸»。日本の生糸は外国に高く売れ、国をささえる大切な輸出品だったのです。","ところが、丹波の生糸は品質がそろわず、よい値がつきませんでした。 «このままでは郡のみんなが豊かになれない»。そう考えたのが、波多野鶴吉です。鶴吉は若いころ京都で学問をこころざしたものの挫折し、ふるさとにもどって地域のために働く道を選んだ人でした。","1896年、鶴吉は地元の人たちに株主になってもらい、 «郡是製絲株式会社» をつくります。 «郡是» とは、国の方針を «国是» というように、 «郡の方針» という意味。地域全体で良い繭を育て、良い糸をつくろうという、ふるさとの将来をかけた会社の名前だったのです。","鶴吉はキリスト教の信仰をもち、働く女性たちの教育にも力を入れました。 «よい人がよい糸をつくる» という考えで、工場に学びの場をもうけたといいます。郡是の生糸は品質がよいと評判になり、アメリカにも輸出されました。","やがて生糸の時代は終わり、会社は靴下や肌着などへと仕事を広げていきます。1967年には社名をカタカナの «グンゼ» に。いまも本社の登記は綾部にあり、ゆかりの地には «グンゼ博物苑» がつくられています。レンガの繭蔵を歩くと、ふるさとを思う一人の人の志が、世界的な会社を生んだことが伝わってきます。"],"tl":[["1858年","波多野鶴吉が何鹿郡に生まれる"],["1896年","郡是製絲株式会社を綾部に設立"],["明治後期〜大正","良質な生糸で評価を高め、アメリカなどへ輸出"],["1918年","波多野鶴吉が亡くなる"],["昭和初期","靴下などの製造にも進出"],["1967年","社名をグンゼ株式会社に変更"],["1996年","創業100周年を記念してグンゼ博物苑がひらかれる"]],"who":[["波多野鶴吉","郡是製絲の創業者。地域を豊かにするために製糸会社をつくった"],["前田正名","明治の官僚。地方産業の振興をうったえ、 «郡是» の考えを広めた"],["波多野はな","鶴吉の妻。事業と工女の教育をささえたといわれる"],["工女たち","工場で糸をつむいだ若い女性たち。郡是の品質をささえた"]],"deep":["«郡是» という言葉は、明治の官僚・前田正名が地方の産業振興のために説いた «国是・県是・郡是・町村是» の考えから来ています。鶴吉は前田の講演に感銘を受けたといわれます。","郡是製絲は、地元の養蚕農家に株主になってもらい、繭の品質を上げる指導もおこなうなど、地域ぐるみの会社づくりをめざしました。","グンゼ博物苑には、繭を保管したレンガ造りの «繭蔵» などが残り、製糸の道具や会社のあゆみを伝える展示があります。","綾部には、グンゼの創業にかかわる古い建物がいくつか残っており、近代化の歩みを伝える遺産として注目されています。","鶴吉はキリスト教の信仰をもち、工場での教育や人格形成を重んじました。 «人間尊重» の社是につながったといわれます。"],"look":["グンゼ博物苑の繭蔵（レンガ造り）","製糸の機械や道具の展示","創業当時の資料・写真","グンゼ記念館などの近代建築（公開状況は事前に確認）"],"q":["社名 «グンゼ» のもとになった «郡是» の意味は?","«郡の方針»。国の方針を «国是» というように、地域全体で目指すべき目標を表した言葉です。"],"myth":"","img":["波多野鶴吉","製糸業"],"wp":"グンゼ","rel":{"ev":[],"grave":[]}},{"id":"26_kotaijinja","n":"元伊勢内宮 皇大神社（福知山）","yomi":"もといせないくう こうたいじんじゃ","cat":"伝承","rank":"B","y":300,"era":["kofun"],"sh":"","ad":"福知山市大江町内宮（うちみや）","st":"京都丹後鉄道 宮福線 大江山口内宮駅から歩いて約20分","la":35.434,"lo":135.176,"hook":"伊勢神宮にしずまる天照大神は、伊勢に落ちつく前、日本中を旅していた――その旅の宿のひとつが、ここだったと伝わる。","lead":"皇大神社は、天照大神が伊勢に移る前にしばらくまつられた場所だという «元伊勢» の伝承をもつ神社です。近くには外宮にあたる豊受大神社や、ピラミッドのような形の日室ヶ嶽（ひむろがたけ）があり、神話の世界を感じられる場所です。","story":["伊勢神宮にまつられている天照大神は、はじめは天皇の住む宮殿の中でまつられていたと伝わります。ところが崇神天皇の時代、 «神さまのお力があまりに強く、同じ御殿にいるのはおそれ多い» として、宮殿の外にお移りいただくことになりました。こうして、ふさわしい場所を探す長い旅が始まった――というのが、神話の世界の話です。","その旅で、天照大神がしばらく足をとめた場所は «元伊勢» とよばれます。この大江町の皇大神社も、そのひとつだと伝えられています。 «丹波の吉佐宮（よさのみや）» で4年間まつられた、という古い書物の記事があり、この神社がその場所だというのです。","参道の石段をのぼると、杉の大木にかこまれた静かな境内にたどりつきます。ここには、皮をむかない丸太でつくった «黒木の鳥居» があります。飾りのない素朴な姿は、神話の時代のお宮のすがたを思わせます。","近くには、まるでピラミッドのような三角形の山、日室ヶ嶽があります。神さまの宿る山として、人が入ってはいけない «禁足地» とされ、遥拝所から拝むことになっています。夏至のころには、この山の頂上に夕日が沈んでいくといわれ、太陽の神・天照大神とのふしぎなつながりを感じさせます。","«元伊勢» を名のる神社は各地にあり、丹後の籠神社も «吉佐宮» の伝承をもっています。どこが本当なのかは、もうわかりません。大切なのは、神話を信じ、ここで祈りをつなぎ続けてきた人々がいることかもしれません。"],"tl":[["崇神天皇の時代（伝承）","天照大神が宮中から外へ移され、各地をめぐる旅が始まったと伝わる"],["同（伝承）","丹波の «吉佐宮» に4年間まつられたとされる"],["垂仁天皇の時代（伝承）","倭姫命が天照大神を伊勢の地にまつったとされる"],["平安時代以降","各地で «元伊勢» の信仰がうまれる"],["現在","内宮・外宮・天岩戸神社とあわせて «元伊勢三社» として参拝される"]],"who":[["天照大神","太陽の女神。伊勢神宮の内宮にまつられる。ここにしばらく鎮まったと伝わる"],["豊鍬入姫命","崇神天皇の娘。天照大神を奉じて各地をめぐったと伝わる"],["倭姫命","垂仁天皇の娘。天照大神を伊勢にまつったと伝わる"],["崇神天皇","天照大神を宮中の外でまつらせたと伝わる天皇"]],"deep":["天照大神の旅の話は、『日本書紀』のほか、鎌倉時代ごろに成立した伊勢神道の書『倭姫命世記』にくわしく書かれています。 «吉佐宮» の名は『倭姫命世記』などに見え、その比定地には諸説あります。","«元伊勢» を名のる場所は、丹後の籠神社、この皇大神社をはじめ、奈良・三重・岐阜などにもあります。どれも伝承で、考古学的に確かめられたものではありません。","境内には、伊勢神宮の別宮と同じ名前の小さなお社が数多くまつられていて、 «伊勢の縮図» のような構成になっています。","黒木の鳥居は、樹皮がついたままの丸太を使った古い形式の鳥居で、京都・嵯峨の野宮神社のものが有名です。","日室ヶ嶽は、山の形が整った «神奈備（かんなび）» 型の山として、古くから信仰の対象だったと考えられています。登山は禁じられています。","大江町は酒呑童子の伝説で知られる大江山のふもとでもあり、 «鬼» と «神» の伝承が同じ地域に重なっているのもおもしろい点です。"],"look":["黒木の鳥居","杉の巨木に囲まれた本殿","境内の多数の摂社・末社","日室ヶ嶽の遥拝所（山への立ち入りは禁止）","あわせて天岩戸神社・豊受大神社（外宮）"],"q":["皇大神社の近くにある、ピラミッドのような形の禁足地の山の名前は?","«日室ヶ嶽»（岩戸山）。遥拝所から拝みます。夏至のころ頂上に夕日が沈むといわれます。"],"myth":"«元伊勢»・«吉佐宮» はすべて伝承。比定地には籠神社など複数の説がある。年代は神話上のもので、y・eraは便宜的な推定。","img":["元伊勢","倭姫命","豊受大神社 (福知山市)"],"wp":"皇大神社 (福知山市)","rel":{"ev":[],"grave":[]}},{"id":"26_hamazume","n":"浜詰遺跡（丹後の縄文貝塚）","yomi":"はまづめいせき","cat":"遺跡","rank":"B","y":-3000,"era":["jomon"],"sh":"","ad":"京丹後市網野町浜詰（はまづめ）","st":"京都丹後鉄道 夕日ヶ浦木津温泉駅から車で約5分。遺跡そのものは見学施設がなく、説明板などで場所を知る程度","la":35.6775,"lo":135.048,"hook":"日本海のそばの砂丘の下から、縄文人の «ごみ捨て場» が見つかった。そこには海とともに生きた暮らしがつまっていた。","lead":"浜詰遺跡は、京丹後市網野町の夕日ヶ浦に近い砂丘にある縄文時代の遺跡です。貝がらや魚の骨、土器などがまとまって見つかる貝塚があり、日本海側ではめずらしい縄文の貝塚として知られています。","story":["夕日がきれいなことで知られる京丹後の «夕日ヶ浦»。その近く、浜詰の砂丘の中に、数千年前の縄文人の暮らしのあとが眠っています。見つかったのは、たくさんの貝がらや魚の骨がつみ重なった «貝塚»。縄文人たちが食べたあとの貝や骨を捨てた場所です。","«ごみ捨て場なんて、何がおもしろいの?» と思うかもしれません。でも、考古学者にとって貝塚は宝の山です。どんな貝を食べていたか、どんな魚をとっていたか、どの季節に暮らしていたか。ごみを調べると、縄文人の毎日の食卓が見えてくるのです。","貝塚というと、関東など太平洋側の海辺にたくさんあることで有名です。日本海側では、海の満ち引きが小さく、干潟が広がりにくいこともあって、大きな貝塚はあまり多くありません。だからこそ、浜詰の貝塚は、日本海側の縄文人がどんなふうに海の恵みを利用していたかを知る、大切な手がかりになっています。","砂丘は、風で砂が動きやすい場所です。縄文人の暮らしのあとも、長い時間のあいだに砂におおわれ、守られてきました。近くの久美浜の函石浜など、丹後の海岸の砂丘には、同じように古い時代の遺跡がいくつも眠っています。","いま、遺跡の上には家や畑が広がり、発掘のあとを目で見ることはほとんどできません。それでも、砂浜に立って日本海をながめると、丸木舟で漁に出て、浜で貝を拾い、火をかこんで食事をした縄文人たちのすがたが、少しだけ想像できる気がします。"],"tl":[["縄文時代","砂丘の上で人々が暮らし、貝塚がつくられる（推定）"],["昭和時代","貝塚や土器が見つかり、調査が行われる"],["現在","丹後の縄文時代を知る遺跡として知られる"]],"who":[["縄文時代の浜詰の人々","海で漁をし、貝を集めて暮らした人々。名前は伝わらない"],["発掘にあたった研究者たち","貝塚を調べ、日本海側の縄文の暮らしを明らかにしようとした"]],"deep":["日本の貝塚の多くは東京湾沿岸など太平洋側に集中しています。日本海側の貝塚は数が少なく、浜詰遺跡のような例は地域の縄文文化を知るうえで貴重です。","貝塚からは、貝がらのほかに魚や動物の骨、土器や石器などが見つかるのがふつうです。貝がらのカルシウムが土を中和するため、骨が残りやすいのも貝塚の特徴です。","砂丘上の遺跡は、砂の移動によって何度も埋もれたり、あらわれたりします。そのため、出土品の層の順番を読みとるのがむずかしいこともあります。","京丹後市の海岸には、函石浜遺物包含地（国指定史跡）をはじめ、砂丘に営まれた先史時代の遺跡が多く、丹後の海岸が古くから人の暮らしの場だったことがわかります。","出土品のくわしい内容や年代は、京丹後市の文化財担当や資料館の展示・報告書で確かめるのがおすすめです。"],"look":["夕日ヶ浦の砂浜と砂丘の地形","遺跡周辺の説明板（あれば）","京丹後市内の資料館での出土品展示（公開状況は事前確認）","近くの函石浜遺跡とのくらべ歩き"],"q":["貝塚とはどんな場所?","縄文人などが食べた貝がらや骨を捨てた場所。当時の食生活や暮らしを知る手がかりになります。"],"myth":"発見・調査の年、遺跡の正確な時期（縄文のどの段階か）は確認できていないため記載をひかえた。","img":["貝塚","縄文時代","夕日ヶ浦温泉"],"wp":"浜詰遺跡","rel":{"ev":[],"grave":[]}},{"id":"26_kanmurijima","n":"冠島（老人嶋神社の聖なる島）","yomi":"かんむりじま","cat":"島","rank":"B","y":701,"era":["asuka","taisho"],"sh":"国の天然記念物（オオミズナギドリ繁殖地）","ad":"舞鶴市（若狭湾の沖合）","st":"無人島で、一般の上陸は原則できない。舞鶴や若狭の海岸・船の上から遠くに眺める","la":35.676,"lo":135.423,"hook":"若狭湾の沖に浮かぶ、冠のかたちの無人島。漁師たちが «おいとしまさん» と手を合わせる、海の聖地だ。","lead":"冠島は、舞鶴市の北の沖合、若狭湾に浮かぶ無人島です。島には老人嶋（おいとしま）神社がまつられ、海で働く人々の信仰を集めてきました。海鳥オオミズナギドリの大きな繁殖地で、国の天然記念物に指定されています。","story":["舞鶴の港を出て北へ。若狭湾の青い海の向こうに、ぽつんと島が見えてきます。遠くから見ると、王さまのかんむりのような形。これが冠島です。すぐそばには、もっと小さな «沓島（くつじま）» があり、ふたつ合わせて «冠と沓（くつ）» なのだといわれます。","島には人は住んでいません。でも、ここはただの無人島ではありません。島には «老人嶋神社» があり、若狭湾の漁師たちは、この島を «おいとしまさん» とよんで大切にしてきました。海の安全と豊漁を守る神さまのいる島なのです。","毎年6月ごろには、舞鶴の大浦半島などの漁師たちが、船をかざって島へわたり、神社にお参りする «雄島参り（おしままいり）» の行事が伝えられています。大漁旗をなびかせた船が沖へ向かう光景は、海とともに生きる人々の祈りそのものです。","この島には、ふしぎな伝説もあります。ずっと昔、大きな地震で «凡海郷（おおしあまのごう）» という土地が海にしずみ、その山のいただきだけが残ったのが冠島と沓島だ――というのです。本当でしょうか? 地質学的な証拠はなく、伝説と考えられています。それでも、海にしずんだ村の話は、人々の心に強く残ってきました。","春から秋にかけて、島はオオミズナギドリの大群でにぎわいます。夕方、海から帰ってきた鳥たちは、地面に掘った巣穴へもぐりこみます。鳥たちを守るため、島へは許可なく上陸することができません。遠くから静かに眺めることが、この聖なる島を守ることにつながっています。"],"tl":[["701年（伝承）","大地震で凡海郷がしずみ、冠島・沓島が残ったと伝わる"],["古くから","老人嶋神社がまつられ、漁師たちの信仰を集める"],["1924年","オオミズナギドリ繁殖地として国の天然記念物に指定"],["現在","漁師たちによる «雄島参り» が伝えられている"]],"who":[["若狭湾の漁師たち","冠島を «おいとしまさん» とよび、雄島参りを続けてきた"],["老人嶋神社の神々","航海の安全と豊漁を守る神としてまつられる"],["オオミズナギドリ","島で子育てをする海鳥。京都府の «府の鳥» でもある"]],"deep":["オオミズナギドリは京都府の «府の鳥» に選ばれています。冠島は国内有数の繁殖地で、巣穴を地面に掘ってひなを育てます。","凡海郷がしずんだという話は、大宝元年（701年）の地震と結びつけて語られますが、根拠とされる書物には後世に書かれたものがふくまれ、史実とは考えにくいとされています。","«おいとしま» という読みは、 «大島（おおしま）» や «雄島（おしま）» との関係も指摘されますが、語源ははっきりしていません。","冠島は京都府でも数少ない沖合の島で、周辺は好漁場として知られます。島への上陸は天然記念物の保護のため制限されています。","となりの沓島もまた海鳥の繁殖地で、ふたつの島はセットで信仰と自然の両面から大切にされてきました。"],"look":["冠島の島影（大浦半島や舞鶴の沿岸から）","となりの沓島とあわせた景観","雄島参りの行事（見学できる機会は限られる）","舞鶴の漁港の風景"],"q":["冠島で子育てをする、京都府の «府の鳥» はなに?","オオミズナギドリ。冠島は国の天然記念物に指定された繁殖地です。"],"myth":"凡海郷の沈没伝説は伝承で史実とは考えにくい。老人嶋神社の祭神・雄島参りの日程は資料で確認を。","img":["オオミズナギドリ","沓島"],"wp":"冠島","rel":{"ev":[],"grave":[]}},{"id":"26_miyazujo","n":"宮津城跡","yomi":"みやづじょうあと","cat":"城","rank":"B","y":1580,"era":["azuchi","edo"],"sh":"","ad":"宮津市鶴賀（つるが）付近","st":"京都丹後鉄道 宮津駅から歩いて約5〜10分","la":35.5405,"lo":135.2,"hook":"天橋立の入り江に面した海の城。若き日の細川ガラシャが、夫とともに暮らした場所でもあった。","lead":"宮津城は、宮津湾に面して築かれた «海城» です。1580年ごろに細川藤孝・忠興父子が築き、江戸時代には宮津藩の城として使われました。明治に取りこわされ、いまは石垣の一部などがわずかに残るだけです。","story":["1580年、織田信長の命令で丹後を任された細川藤孝（幽斎）と息子の忠興は、宮津の海辺に城を築きました。目の前は宮津湾、北には天橋立。船で人や物が行き来する、海と一体になった城です。","忠興の妻は、明智光秀の娘・玉、のちの細川ガラシャです。若い二人はこの宮津で暮らし、子どもにもめぐまれました。ところが1582年、玉の父・光秀が本能寺の変をおこします。 «反逆者の娘» となった玉は、丹後の山奥の味土野（みどの）に隠され、つらい日々を送ることになりました。","1600年、関ヶ原の戦いの前。細川家は徳川家康に味方し、忠興は兵をひきいて東へ向かいます。留守をあずかる藤孝は、宮津城では守りきれないと考え、城に火を放って舞鶴の田辺城にこもりました。そのころ大坂では、人質になるのをこばんだガラシャが、屋敷で命を落としていました。","戦のあと、丹後には京極高知が入り、その後、京極家の宮津藩が城を大きく造りなおしました。石垣や堀をめぐらし、城下町もととのえられていきます。江戸時代の半ばからは本庄松平家が治め、明治まで続きました。","明治になると、城は取りこわされ、堀もうめられていきました。いま宮津の町を歩いても、城のすがたを見つけるのはむずかしいほどです。それでも、大手川ぞいに残る石垣の一部や、城下町の道すじが、かつての海城の記憶を伝えています。"],"tl":[["1580年","細川藤孝・忠興が丹後に入り、宮津城を築く"],["1582年","本能寺の変。忠興の妻・玉（ガラシャ）が味土野に隠される"],["1600年","関ヶ原の戦いの前に、藤孝が宮津城を焼いて田辺城にこもる"],["1601年","京極高知が丹後に入る"],["1620年代","京極家の宮津藩が城を大きく改修"],["1758年","本庄松平家が宮津藩主となり、明治まで続く"],["明治時代","城が取りこわされる"]],"who":[["細川藤孝（幽斎）","宮津城を築いた武将。関ヶ原の前に城を焼き、田辺城で籠城した"],["細川忠興","藤孝の子。宮津城主として丹後を治めた"],["細川ガラシャ（玉）","明智光秀の娘で忠興の妻。宮津で暮らした"],["京極高知","関ヶ原の後に丹後に入った大名"],["京極高広","宮津藩主として城を大改修した"]],"deep":["宮津城は宮津湾に面した海城で、船が直接出入りできる構造だったと考えられています。天橋立をのぞむ位置は、水運の拠点としても重要でした。","細川時代の宮津城と、京極氏が築き直した江戸時代の宮津城は、場所や規模が必ずしも同じではないと考えられています。いま城跡とされるのは主に江戸時代の城です。","1600年、藤孝が籠城した田辺城（舞鶴）には朝廷から勅使が送られ、古今伝授を受けていた藤孝の命が惜しまれて開城となった話が有名です。","宮津藩は京極家の改易後、永井・阿部・奥平・青山などの家が入れかわり、1758年に本庄松平家が入って明治まで続きました。","城跡の遺構はごくわずかで、大手川ぞいの石垣のほか、市内には城の門が移築されたと伝わるものもあります。"],"look":["大手川ぞいの石垣の残り","城下町の町割り（宮津駅周辺）","宮津湾と天橋立の方向の眺め","近くのカトリック宮津教会（明治の教会建築）"],"q":["宮津城に住んだ細川ガラシャは、だれの娘?","明智光秀の娘。本能寺の変のあと、丹後の味土野に隠されました。"],"myth":"細川時代と江戸時代の城の位置関係、移築門の伝えには不確かな点がある。","img":["細川ガラシャ","細川藤孝","宮津藩"],"wp":"宮津城","rel":{"ev":[],"grave":[]}},{"id":"26_tango_kokubunji","n":"丹後国分寺跡","yomi":"たんごこくぶんじあと","cat":"遺跡","rank":"B","y":1334,"era":["nara","kamakura","muromachi"],"sh":"国指定史跡","ad":"宮津市国分（こくぶ）","st":"京都丹後鉄道 天橋立駅から路線バスで «丹後郷土資料館» 付近下車、または天橋立を渡って府中地区から歩く","la":35.5835,"lo":135.186,"hook":"雪舟が描いた国宝 «天橋立図» 。その絵の中に、この国分寺が塔とともに描きこまれている。","lead":"丹後国分寺跡は、天橋立の北側、宮津市の府中地区にある国分寺の跡です。奈良時代に建てられ、鎌倉時代の終わりに建て直されました。いまは金堂などの礎石が並び、国の史跡になっています。","story":["天橋立を北へ渡りきると、そこは «府中» とよばれる地区です。 «府中» とは、国の役所・国府があった場所という意味。つまりこのあたりは、むかし丹後国の中心だったのです。丹後国分寺も、その近く、天橋立と阿蘇海を見おろす丘に建てられました。","奈良時代、聖武天皇の命令で全国に国分寺がつくられ、丹後にも寺が建てられました。けれども、時代がたつにつれて寺は荒れていきます。そこで鎌倉時代の終わり、寺の人々は再建にとりかかりました。そして1334年、新しい金堂の完成を祝う大きな法要がひらかれたと、寺の記録に書かれています。","この記録が残っているのが、とても大切な点です。 «何年に、だれが、どのように建て直したか» がくわしくわかる国分寺は、全国でもめずらしいのです。記録は重要文化財として、いまも伝えられています。","時代は室町へ。画僧の雪舟は、天橋立を描いた «天橋立図» という絵を残しました。のちに国宝となるこの絵の中に、丹後国分寺が描かれていて、塔のすがたも見えます。雪舟が見たとき、寺はまだ立派な姿をとどめていたのでしょう。","その後、寺はふたたび衰え、いまは金堂の礎石などがきれいに並ぶ史跡として残っています。すぐとなりには京都府立丹後郷土資料館があります。礎石の上に立ち、天橋立の松並木をながめれば、雪舟と同じ景色を見ていることに気づくはずです。"],"tl":[["8世紀中ごろ","聖武天皇の命令により丹後国分寺が建てられる（推定）"],["平安〜鎌倉時代","しだいに衰える"],["1334年","再建された金堂の供養が行われる（寺の記録による）"],["16世紀初めごろ","雪舟が «天橋立図» を描き、国分寺の姿が描かれる"],["昭和時代","国の史跡に指定される"],["1970年","となりに京都府立丹後郷土資料館がひらかれる"]],"who":[["聖武天皇","国分寺建立の詔を出した天皇"],["雪舟","室町時代の画僧。 «天橋立図» に国分寺を描いた"],["再興にかかわった僧たち","鎌倉時代末に国分寺の再建を進め、記録を残した"]],"deep":["再建の記録は «丹後国分寺建武再興縁起» とよばれ、建武元年（1334年）の金堂供養のようすがくわしく書かれています。重要文化財に指定されています。","現在の礎石は、奈良時代の創建時のものではなく、鎌倉時代末の再建金堂のものと考えられています。 «中世に再建された国分寺» の姿がわかる点で貴重です。","雪舟の «天橋立図» は京都国立博物館が所蔵する国宝で、雪舟の晩年の作とされます。丹後国分寺のほか、成相寺や籠神社なども描かれています。","丹後国府の正確な位置はまだ確定していませんが、 «府中» の地名や国分寺・一宮の籠神社の位置から、このあたりにあったと考えられています。","京都府立丹後郷土資料館は、丹後の考古・歴史・民俗の資料を展示しており、国分寺跡とあわせて見学すると理解が深まります。"],"look":["金堂跡の礎石群","礎石越しに見る天橋立と阿蘇海","京都府立丹後郷土資料館の展示","近くの籠神社（丹後国一之宮）"],"q":["丹後国分寺が描かれている、雪舟の国宝の絵の名前は?","«天橋立図»。天橋立の景色とともに、国分寺や籠神社などが描かれています。"],"myth":"創建年は推定。 «天橋立図» の制作年には諸説ある。","img":["天橋立図","雪舟","丹後国"],"wp":"丹後国分寺","rel":{"ev":[],"grave":[]}},{"id":"26_ebisuyama","n":"蛭子山古墳（与謝野町・丹後王国）","yomi":"えびすやまこふん","cat":"遺跡","rank":"B","y":350,"era":["kofun"],"sh":"国指定史跡","ad":"与謝郡与謝野町明石（あけし）","st":"京都丹後鉄道 与謝野駅から車で約15分、または路線バス利用。古墳公園として整備","la":35.5105,"lo":135.086,"hook":"丹後の山あいに、全長約145mの巨大な前方後円墳。頂上には、1600年以上前の石の棺がいまも置かれている。","lead":"蛭子山古墳は、与謝野町にある4世紀ごろの前方後円墳で、長さは約145mあります。丹後三大古墳のひとつで、墳丘の頂上には花こう岩でできた舟形の石棺が残っています。 «丹後王国» という言葉を生んだ遺跡のひとつです。","story":["与謝野町の加悦谷（かやだに）。まわりを山にかこまれた平野を見おろす丘の上に、大きな前方後円墳があります。蛭子山古墳です。いまは «古墳公園» として整備され、階段をのぼって墳丘の上まで行くことができます。","頂上に着くと、屋根の下に置かれた大きな石の棺が目に入ります。舟のような形をした «舟形石棺» で、かたい花こう岩をくりぬいてつくられています。重い石を山から切り出し、ここまで運んで、きれいにけずり上げる――どれほどの人と時間がかかったのでしょう。","丹後には、この蛭子山古墳のほかに、網野銚子山古墳と神明山古墳という巨大な前方後円墳があり、 «丹後三大古墳» とよばれています。どれも、日本海側では最大級の古墳です。なぜ、こんなに大きな古墳が丹後に集まっているのでしょう?","丹後は、日本海をへだてて朝鮮半島や大陸とつながる海の玄関口でした。鉄や玉づくりの技術が早くから入り、海の交易で力をたくわえた有力者がいたと考えられています。そこで、ヤマトの大王とならぶほどの力をもつ «丹後王国» があったのではないか、という説がうまれました。","«丹後王国» が本当に独立した国だったのかは、研究者のあいだでも意見が分かれています。でも、この巨大な古墳を前にすると、日本海の海の道を支配した王の力を感じずにはいられません。すぐとなりには、形のちがう古墳がならぶ作山古墳群もあり、古墳の見くらべができます。"],"tl":[["4世紀中ごろ〜後半","蛭子山古墳がつくられる（推定）"],["4〜5世紀","網野銚子山古墳・神明山古墳など丹後の大型古墳がつくられる"],["昭和初期","蛭子山古墳・作山古墳が国の史跡に指定される"],["1980年代","«丹後王国» 論が提唱され、丹後の古墳に注目が集まる"],["平成時代","古墳公園として整備され、墳丘の復元や資料館がととのう"]],"who":[["蛭子山古墳の被葬者","名前は伝わらない。加悦谷を中心に丹後の一部を治めた首長と考えられる"],["門脇禎二","古代史家。 «丹後王国論» を唱えた"],["古墳をつくった人々","石棺を運び、墳丘を築いた多くの人々"]],"deep":["蛭子山古墳の全長は約145mで、網野銚子山古墳（約198m）、神明山古墳（約190m）とともに丹後三大古墳とよばれます。","墳頂の舟形石棺は花こう岩製で、墳丘上に露出して保存されています。石棺が古墳の上で見られる例は多くありません。","«丹後王国論» は、古代史家の門脇禎二が1980年代に唱えた説で、丹後にヤマト政権とは別の地域国家があったとするものです。これに対しては、ヤマト政権と結びついた有力な地方首長とみる考えもあり、議論が続いています。","となりの作山古墳群には、円墳・方墳・前方後円墳などいろいろな形の古墳が集まっていて、古墳の形のちがいを見くらべることができます。","古墳公園内の «はにわ資料館» では、蛭子山古墳や作山古墳群から出土した埴輪などを展示しています。"],"look":["墳頂の舟形石棺","墳丘上から見る加悦谷の眺め","となりの作山古墳群","古墳公園はにわ資料館"],"q":["丹後三大古墳とよばれる3つの古墳は?","蛭子山古墳、網野銚子山古墳、神明山古墳。いずれも日本海側で最大級の前方後円墳です。"],"myth":"«丹後王国» は学説で、評価は分かれる。築造年代は推定。","img":["作山古墳","網野銚子山古墳","神明山古墳 (京丹後市)"],"wp":"蛭子山古墳","rel":{"ev":[],"grave":[]}},{"id":"26_urashima","n":"浦嶋神社（浦島伝説の本家）","yomi":"うらしまじんじゃ","cat":"伝承","rank":"B","y":825,"era":["nara","heian","muromachi"],"sh":"«浦嶋明神縁起» の絵巻が国の重要文化財","ad":"与謝郡伊根町本庄浜（ほんじょうはま）","st":"京都丹後鉄道 天橋立駅から丹後海陸交通バスで約1時間 «浦嶋神社前» 下車すぐ","la":35.72,"lo":135.256,"hook":"亀を助けた浦島太郎――その話のいちばん古い記録は、奈良時代の丹後で書かれていた。主人公をまつる神社が、いまも海辺にある。","lead":"浦嶋神社（宇良神社）は、浦島太郎のモデルとされる «浦嶋子（うらのしまこ）» をまつる神社です。奈良時代の『丹後国風土記』や『日本書紀』に、丹後の浦嶋子が海の向こうの不思議な国へ行った話が書かれています。神社には室町時代の絵巻や «玉手箱» と伝わる箱が伝わっています。","story":["«むかしむかし、浦島太郎は助けた亀に連れられて竜宮城へ……»。だれもが知るこの昔話には、じつはとても古い «元の話» があります。舞台は、丹後半島の筒川（つつかわ）というところ。いまの伊根町本庄のあたりです。","奈良時代にまとめられた『丹後国風土記』（いまは一部だけが他の本に引用されて残る）には、こんな話が出てきます。筒川に住む嶼子（しまこ）という若者が、小舟で釣りをしていると、五色の亀がかかりました。うとうとしている間に、亀は美しい女性に姿を変えます。女性にさそわれた嶼子は、海の上の不思議な国・蓬莱山（とこよのくに）へ旅立ちました。","そこで嶼子は夢のような日々を過ごします。でも、三年ほどたつとふるさとが恋しくなりました。別れぎわ、女性は «もう一度会いたいなら、決してこの箱を開けてはいけません» と玉匣（たまくしげ）をわたします。ところがふるさとに帰ると、村はすっかり変わり、自分が出かけてから三百年もたっていたのです。","悲しみのあまり、嶼子は約束をやぶって箱を開けてしまいました。すると……。昔話では、太郎はおじいさんになります。けれども風土記の話では、若々しい姿が雲とともに空へ飛び去った、と書かれているのです。亀も竜宮城も乙姫も出てこない、少し大人っぽい、切ない恋の物語でした。","浦嶋神社は、この嶼子を «浦嶋子» としてまつる神社です。社伝によると、825年に淳和天皇の命で社がつくられたといいます。境内の宝物館には、室町時代に描かれた «浦嶋明神縁起» の絵巻や、 «玉手箱» と伝わる化粧箱が伝えられています。海辺の小さなお宮で、日本最古級のファンタジーに思いをはせてみてください。"],"tl":[["478年（伝承）","『日本書紀』雄略天皇22年条に、丹波国余社郡の浦嶋子が蓬莱山へ行ったと記される"],["8世紀前半","『丹後国風土記』に筒川の嶼子の話が書かれる"],["825年","社伝によれば、この年に浦嶋子をまつる社がつくられる"],["室町時代","«浦嶋明神縁起» の絵巻がつくられる"],["江戸時代","御伽草子などを通じて «浦島太郎» の話が広まる"],["明治時代","国定教科書や唱歌で浦島太郎が全国の子どもに親しまれる"]],"who":[["浦嶋子（嶼子）","浦島太郎のモデル。筒川の若者で、蓬莱山へ行ったと伝わる"],["亀比売（かめひめ）","風土記で亀から姿を変えた女性。のちの乙姫のもとになった"],["淳和天皇","社伝で浦嶋神社の創建を命じたとされる天皇"],["伊預部馬養","浦嶋子の話を書き残したと『丹後国風土記』にある人物"]],"deep":["浦嶋子の話は、『日本書紀』雄略天皇22年条、『丹後国風土記』逸文、『万葉集』の高橋虫麻呂の長歌の三つに見えます。万葉集では舞台が «墨吉（すみのえ）» とされ、住吉との関係も論じられています。","『丹後国風土記』逸文には、この話がもともと伊預部馬養（いよべのうまかい）の記録にもとづくと書かれています。馬養は大宝律令の編さんにも加わった官人です。","昔話の «竜宮城» や «乙姫» 、 «助けた亀の恩返し» といった要素は、室町時代の御伽草子などで加わったもので、古い話には見られません。","神社の «玉手箱» とされるものは、室町時代ごろの化粧箱と考えられており、重要文化財の «浦嶋明神縁起» 絵巻とともに宝物として伝えられています。","«浦島伝説» の地は、ほかにも香川県の荘内半島や神奈川県横浜市など各地にあります。そのなかで伊根町は、最古の文献の舞台として «本家» を名のっています。"],"look":["海辺に建つ本殿","宝物館の «浦嶋明神縁起» 絵巻（複製展示の場合あり）と玉手箱","筒川の流れと本庄浜の海","伊根町内の浦島伝説ゆかりの場所"],"q":["『丹後国風土記』の浦嶋子の話で、箱を開けた嶼子はどうなった?","昔話のようにおじいさんになるのではなく、若々しい姿が雲とともに空へ飛び去ったと書かれています。"],"koji":[{"w":"浦島太郎","m":"長く留守にしている間に世の中がすっかり変わってしまい、とまどう人のたとえ"}],"myth":"社伝の825年創建は神社の伝え。 «玉手箱» とされる品は伝承。","img":["浦島太郎","丹後国風土記","宇良神社"],"wp":"浦嶋神社","rel":{"ev":[],"grave":[]}},{"id":"26_ine","n":"伊根の舟屋","yomi":"いねのふなや","cat":"町","rank":"B","y":1800,"era":["edo","meiji","heisei"],"sh":"国の重要伝統的建造物群保存地区","ad":"与謝郡伊根町平田・亀島ほか","st":"京都丹後鉄道 天橋立駅から丹後海陸交通バスで約1時間 «伊根» 付近下車","la":35.677,"lo":135.286,"hook":"家の1階が、そのまま海につながる «船のガレージ» 。静かな入り江を、230軒ほどの舟屋がぐるりと囲む。","lead":"伊根の舟屋は、伊根湾にそって建ちならぶ、1階に船をしまう独特の家です。約230軒の舟屋が海にせりだすように並び、2005年には漁村として全国で初めて重要伝統的建造物群保存地区に選ばれました。","story":["丹後半島の東のはし、伊根湾。波がおだやかな入り江にそって、海の上に浮かんでいるかのような家が、ずらりと並んでいます。これが舟屋です。のぞいてみると、1階には海から船がそのまま入りこみ、2階が部屋になっています。 «家に船のガレージがある!» ――はじめて見た人はびっくりします。","なぜ、こんな家がつくられたのでしょう? ひみつは伊根湾の地形にあります。入り江は南に開いていますが、湾の入り口に青島という島があって、外海の荒波をさえぎってくれます。しかも、潮の満ち引きの差がとても小さいのです。だから、海のすぐそばに家を建てても、波にさらわれにくかったのです。","舟屋の1階は、船をしまったり、網を干したり、漁の道具を手入れしたりする作業場でした。むかしは2階も物置や網の干し場に使われることが多く、人々は道の反対側の母屋に住んでいました。道をはさんで、海側に舟屋、山側に母屋。そのセットが、伊根の暮らしの形だったのです。","伊根の人々は、ブリなどの漁で生きてきました。江戸時代には、湾に入ってきたクジラをとる漁も行われていたといいます。舟屋のならぶ湾は、漁の基地であると同時に、家族の生活の場でもありました。","いま、舟屋は遊覧船や海からの眺めで人気の観光地になりました。けれども、ここは今も人が住み、漁をしている町です。家の中をのぞいたり、私有地に入ったりしないようにしましょう。夕方、舟屋の窓に明かりがともるころ、湾の水面にうつる光景は、ここにしかない美しさです。"],"tl":[["江戸時代","伊根浦で漁業がさかんになり、舟屋が建てられる"],["江戸〜明治時代","湾に入るクジラをとる伊根浦の捕鯨が行われる"],["昭和時代","舟屋の多くが現在のような2階建ての形に建てかえられる"],["2005年","漁村として全国で初めて国の重要伝統的建造物群保存地区に選定"],["現在","舟屋を改装した宿やカフェも登場し、景観と暮らしの両立が課題に"]],"who":[["伊根浦の漁師たち","舟屋を建て、湾を基地に漁をしてきた人々"],["舟屋に暮らす人々","海とともにある暮らしと景観を守る住民"],["伊根町の人々","重要伝統的建造物群保存地区として舟屋群の保存に取り組む"]],"deep":["伊根湾の潮位差は小さく、年間を通じても数十センチ程度とされます。これが、海面すれすれに建つ舟屋が成り立つ大きな理由です。","湾の入り口にある青島が防波堤のような役割をはたし、日本海の荒波が湾内に入りにくくなっています。","舟屋の多くは、昔は平屋で、茅葺きのものもありました。いま見られる2階建ての舟屋の多くは、昭和時代以降に建てかえられたものです。","伊根浦ではかつて、湾内に入ってきたクジラを網などでとる漁が行われていました。捕鯨の記録や道具は、地域の歴史を伝える資料になっています。","重要伝統的建造物群保存地区としては、舟屋だけでなく、道をはさんだ母屋や土蔵、背後の山の緑までふくめて、 «漁村の景観» 全体が守られています。"],"look":["伊根湾めぐりの遊覧船から見る舟屋群","道の駅 «舟屋の里伊根» の高台からの眺め","舟屋と母屋のセット（道の両側）","湾口の青島","夕方の水面にうつる舟屋の明かり"],"q":["伊根で海のすぐそばに舟屋が建てられた大きな理由は?","湾が波の静かな入り江で、潮の満ち引きの差がとても小さいから。湾口の青島が荒波をふせいでいます。"],"myth":"","img":["伊根町","舟屋","伊根湾"],"wp":"伊根の舟屋","rel":{"ev":[],"grave":[]}},{"id":"26_chirimen","n":"丹後ちりめん（加悦の縮緬街道）","yomi":"たんごちりめん","cat":"産業","rank":"B","y":1722,"era":["edo","meiji","showa"],"sh":"国の重要伝統的建造物群保存地区（加悦）","ad":"与謝郡与謝野町加悦（かや）","st":"京都丹後鉄道 与謝野駅から丹後海陸交通バスで «加悦» 付近下車","la":35.498,"lo":135.085,"hook":"ガチャン、ガチャン――機織りの音が町にひびくと «ガチャマン» 景気。丹後の絹が、京の着物を支えてきた。","lead":"丹後ちりめんは、表面に細かな «しぼ» (でこぼこ)のある絹織物で、日本の着物の生地の多くをつくってきました。江戸時代の中ごろ、京都の西陣から技術が伝わったのが始まりです。与謝野町加悦の «ちりめん街道» には、機屋や商家の町並みが残っています。","story":["丹後は、冬にくもりや雪の日が多く、しっとりと湿った土地です。この湿気が、絹糸を織るのにちょうどよいのだといわれます。むかしから丹後では絹織物がつくられていましたが、江戸時代の半ばになると、京都の西陣で生まれた新しい織物 «ちりめん» の人気におされ、売れなくなってしまいました。","«なんとか、ちりめんの技を身につけたい»。そう考えた峰山の絹屋佐平治という人が、西陣に入りこんで技術を学び、1720年ごろ故郷にもどってちりめんを織りはじめたと伝わります。つづいて加悦でも、手米屋小右衛門、木綿屋六右衛門といった人々が西陣で技を学び、1722年ごろに加悦谷へ伝えたといいます。","ちりめんのひみつは、強くよりをかけた糸にあります。織ったあとで布をお湯で練ると、糸がもとにもどろうとして縮み、表面に細かなでこぼこ «しぼ» ができます。これが、しなやかで、しわになりにくく、色がきれいに染まる生地になるのです。","丹後ちりめんはやがて日本一の産地となり、昭和の中ごろには «ガチャン» と一回織れば «万» もうかる、という意味の «ガチャマン景気» とよばれるほどのにぎわいを見せました。加悦には、ちりめんを運ぶための加悦鉄道も走っていました。","いま、加悦の «ちりめん街道» を歩くと、旧尾藤家住宅などの商家や、洋風の旧加悦町役場庁舎、機屋の建物が並んでいます。どこからか機の音が聞こえてくることもあります。着物を着る人が減った今も、丹後の人々はちりめんの技を新しい製品にいかそうと工夫を続けています。"],"tl":[["1720年ごろ","峰山の絹屋佐平治が西陣でちりめんの技術を学び、丹後で織りはじめる"],["1722年ごろ","加悦谷にもちりめんの技術が伝わる"],["江戸時代後期","丹後ちりめんが京都へ大量に送られる"],["1926年","加悦鉄道が開業し、ちりめんなどを運ぶ"],["1929年","旧加悦町役場庁舎が建てられる"],["1960年代","«ガチャマン景気» で丹後ちりめんの生産が最盛期に"],["2005年","加悦の町並みが国の重要伝統的建造物群保存地区に選ばれる"]],"who":[["絹屋佐平治（森田治郎兵衛）","峰山の人。西陣でちりめんの技術を学び、丹後に伝えたとされる"],["手米屋小右衛門","加悦の人。加悦谷にちりめんを伝えたとされる"],["木綿屋六右衛門","加悦の人。小右衛門とともに技術を伝えたとされる"],["尾藤家","加悦の生糸・ちりめん商人。屋敷が残る"]],"deep":["ちりめんは、よこ糸に1メートルあたり3000回前後の強いよりをかけるのが特徴とされます。この «強撚糸» が、精練のあとに縮んで «しぼ» をつくります。","丹後ちりめんは、国内の絹織物（白生地）の生産の大きな割合をしめてきた最大の産地です。着物の多くは丹後で織られた白生地を京都で染めて仕立てたものです。","旧尾藤家住宅は、ちりめん商人の屋敷で、和風の主屋に洋風の部屋を組みこんだ建物として知られ、京都府の指定文化財になっています。","加悦鉄道は1926年に開業し、ちりめんのほか、大江山のニッケル鉱石の輸送にも使われました。1985年に廃止され、車両は一部保存されています。","絹屋佐平治が西陣で技術を学んだ方法については、 «身分をかくして機屋に奉公した» など物語的な伝えが多く、細部ははっきりしません。"],"look":["ちりめん街道の町並み","旧尾藤家住宅（ちりめん商人の屋敷）","旧加悦町役場庁舎（昭和初期の洋風建築）","機屋の建物と機織りの音","ちりめん製品の店や体験施設"],"q":["丹後ちりめんの表面にある、細かなでこぼこを何という?","«しぼ»。強くよりをかけた糸が、織ったあとで縮むことでできます。"],"koji":[{"w":"ガチャマン景気","m":"機を «ガチャン» と一回織れば «万» のお金がもうかる、といわれた織物業の好景気"}],"myth":"絹屋佐平治らの技術導入の年や経緯は伝承的な要素をふくむ。","img":["加悦鉄道","旧尾藤家住宅"],"wp":"丹後ちりめん","rel":{"ev":[],"grave":[]}},{"id":"26_hakoishihama","n":"函石浜遺跡（旧石器〜の砂丘遺跡）","yomi":"はこいしはまいせき","cat":"遺跡","rank":"B","y":0,"era":["jomon","yayoi","kofun"],"sh":"国指定史跡（函石浜遺物包含地）","ad":"京丹後市久美浜町湊宮（みなとみや）付近","st":"京都丹後鉄道 久美浜駅から車で約15分。砂丘の松林の中","la":35.645,"lo":134.915,"hook":"風で動く砂の下から、2000年前の中国のお金が出てきた。日本海の砂丘は、海の向こうとつながっていた。","lead":"函石浜遺跡（函石浜遺物包含地）は、京丹後市久美浜町の海岸の砂丘にある遺跡です。縄文時代から古墳時代ごろまでの土器や石器が見つかり、中国の «新» という国のお金 «貨泉» も出土しました。大正時代に国の史跡になった、古くから知られた遺跡です。","story":["久美浜湾と日本海のあいだには、細長い砂の帯がのびています。 «小天橋» とよばれるこの砂州の近く、松林におおわれた砂丘に、函石浜遺跡があります。風が強く吹くと砂が動き、その下から土器のかけらや石器が顔を出す――そんな場所として、むかしから知られていました。","ここでは、いろいろな時代の遺物が見つかっています。縄文時代の土器、弥生時代の土器、石のやじりや石斧、さらに古墳時代ごろのものまで。長いあいだ、たくさんの人がこの浜で暮らしたり、行き来したりしていたことがわかります。","なかでも人々をおどろかせたのが、 «貨泉» という銅のお金です。これは、中国で紀元1世紀のはじめに «新» という国を建てた王莽がつくらせたお金でした。 «なぜ中国のお金が、丹後の砂浜に?» 。それは、日本海を渡って大陸や朝鮮半島と人や物が行き来していた証拠だと考えられています。","函石浜の遺跡は、1921年、国の史跡に指定されました。史跡の制度ができてまもないころで、京都府内でもとても早い指定のひとつです。それだけ、この砂丘から出るたくさんの遺物が注目されていたのです。","いま遺跡は松林におおわれ、石碑が立っています。砂を持ち帰ったり、遺物を拾ったりすることはできません。砂丘の上に立って日本海を見わたすと、この海が、遠い国とつながる «道» だったことを実感できます。"],"tl":[["縄文時代","砂丘周辺で人々が活動をはじめる（推定）"],["弥生時代","土器や石器が残される。貨泉もこのころ持ちこまれたと考えられる"],["1世紀前半","中国・新の王莽が貨泉を発行"],["明治時代","砂丘から遺物が多く見つかり、注目される"],["1921年","«函石浜遺物包含地» として国の史跡に指定"],["現在","松林の中に石碑があり、保存されている"]],"who":[["王莽","中国の «新» を建てた皇帝。貨泉を発行させた"],["函石浜で暮らした人々","縄文〜古墳時代にこの浜で生活や交易をした人々"],["遺物を調べた研究者たち","明治〜大正にこの遺跡を学界に紹介した"]],"deep":["«遺物包含地» は、建物跡などよりも、土器や石器などの遺物がまとまって見つかる場所をさす言い方です。函石浜は、その名前で指定された珍しい史跡です。","貨泉は、中国の新（8〜23年）の王莽が14年ごろに発行した銅銭とされます。日本では九州から日本海側にかけて出土例があり、弥生時代の年代を考える手がかりにもなります。","遺跡名の «旧石器» については、旧石器時代の石器とされるものが見つかったという報告がありますが、評価は定まっていません。","砂丘遺跡は、風で砂が動くたびに遺物があらわれたり埋まったりするため、出土した層の順番がくずれやすく、年代の決め方がむずかしいとされます。","久美浜湾の «小天橋» の砂州は、宮津の天橋立と同じように、海流が運んだ砂がつくった地形です。"],"look":["松林の中の史跡の石碑","砂丘の地形と日本海の眺め","近くの小天橋の砂州と久美浜湾","京丹後市内の資料館での出土品の展示（公開状況は事前確認）"],"q":["函石浜遺跡で見つかった、中国の «新» の時代のお金の名前は?","«貨泉»。王莽の時代に発行された銅銭で、日本海を通じた交流の証拠と考えられています。"],"myth":"旧石器時代の遺物の評価は定まっていない。貨泉がもたらされた時期・経路は推定。","img":["貨泉","王莽","久美浜湾"],"wp":"函石浜遺物包含地","rel":{"ev":[],"grave":[]}},{"id":"26_kitatango","n":"北丹後地震の震災記念（郷村断層）","yomi":"きたたんごじしん（ごうむらだんそう）","cat":"昭和","rank":"B","y":1927,"era":["showa"],"sh":"郷村断層は国の天然記念物","ad":"京丹後市網野町郷（ごう）・生野内ほか","st":"京都丹後鉄道 網野駅から車で約10分。断層の保存地点に説明板あり","la":35.656,"lo":135.042,"hook":"1927年3月7日の夕方。夕食のしたくの時間に大地がゆれ、丹後の町は炎につつまれた。大地にはずれた «きず» が今も残る。","lead":"北丹後地震は、1927年に丹後半島をおそったマグニチュード7.3の大地震です。峰山や網野などで家がたおれ、火事が広がり、約2900人の方が亡くなりました。このとき地表にあらわれた «郷村断層» が、国の天然記念物として保存されています。","story":["1927年（昭和2年）3月7日、午後6時半ごろ。丹後の町では、ちょうど夕食のしたくのころでした。かまどや火ばちには火がついています。そのとき、ドーンという音とともに、はげしいゆれがおそいました。北丹後地震です。","とくに被害が大きかったのは、峰山や網野などの町でした。木造の家がつぎつぎとたおれ、たおれた家から火が出て、町は炎につつまれました。雪が残る寒い季節で、多くの人が家の下じきになったり、火に追われたりして命を落としました。亡くなった方は約2900人にのぼります。","この地震のあと、人々は地面に奇妙なものを見つけました。田んぼや道が、一本の線にそって横にずれ、段差ができていたのです。長さはおよそ18km。これが «郷村断層» です。地震は、地下の断層が急にずれることでおこる――そのことを、目に見える形で示した断層でした。","郷村断層は、地震のしくみを研究するうえでとても大切な資料となり、1929年に国の天然記念物に指定されました。いまも網野町の郷などに、ずれた地面が保存されていて、説明板とともに見ることができます。ずれの向きや大きさを自分の目で確かめられる、全国でもめずらしい場所です。","丹後の人々は、深い悲しみの中から町を立て直していきました。地震のあと、学校や役場は燃えにくい建物で建て直され、町の道も広げられました。断層の前に立つとき、ここで亡くなった多くの人々のことを思い、そして «地震はまたやってくる» ことを忘れないでいたいものです。"],"tl":[["1927年3月7日","北丹後地震が発生（マグニチュード7.3）"],["1927年3月","峰山・網野などで家屋倒壊と火災。約2900人が亡くなる"],["1927〜1928年","地震学者たちが郷村断層・山田断層を調査"],["1929年","郷村断層が国の天然記念物に指定される"],["昭和初期","震災からの復興で、燃えにくい建物や広い道がつくられる"],["現在","断層保存地点や記念碑で、震災の記憶が伝えられている"]],"who":[["北丹後地震で亡くなった人々","約2900人。多くが家の倒壊や火災の犠牲となった"],["震災を生きのびた丹後の人々","悲しみの中で町を立て直した"],["地震学者たち","郷村断層などを調べ、地震と断層の関係を明らかにした"]],"deep":["郷村断層は、主に左横ずれの動きを示し、ずれの大きさは最大で3m近くあったとされます。同時に、これとほぼ直角に山田断層も動きました。","北丹後地震は、地震と地表の断層の関係がくわしく調べられた初期の例のひとつで、断層研究の歴史の中で重要な地震とされています。","被害が大きくなった理由として、夕食時で火を使っていたこと、木造家屋が密集していたこと、軟らかい地盤の上に町があったことなどがあげられます。","峰山では、地震からの復興の記念として «丹後震災記念館» が建てられました。震災の記憶を伝える建物として残されています。","郷村断層の天然記念物は、網野町の複数の地点が保存地点になっています。見学の際は、農地や私有地に入らないよう気をつけましょう。"],"look":["郷村断層の保存地点（ずれた地面と説明板）","断層に沿った地形の段差","峰山の丹後震災記念館（公開状況は事前確認）","町の中の慰霊碑・記念碑"],"q":["北丹後地震のときに地表にあらわれ、国の天然記念物になった断層の名前は?","«郷村断層»。長さ約18kmにわたって地面が横にずれました。"],"myth":"","img":["郷村断層","丹後震災記念館","峰山町"],"wp":"北丹後地震","rel":{"ev":[],"grave":[]}}];
